INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37622, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "対戦相手を表し、「祖父に負けて」と自然に続く。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す助詞で、「祖父から負けて」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す助詞で、「祖父より負けて」は文にならない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の助詞で、「祖父の負けて」は文にならない。"}], "correct_answer": "に", "explanations": {"に": "対戦相手を表し、「祖父に負けて」と自然に続く。", "から": "起点を表す助詞で、「祖父から負けて」は意味が通らない。", "より": "比較を表す助詞で、「祖父より負けて」は文にならない。", "の": "連体修飾の助詞で、「祖父の負けて」は文にならない。"}, "error_tags": {"から": "起点", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "勝つ", "is_correct": true, "explanation": "勝負の結果で「負ける」と反対の意味を表す対義語。"}, {"text": "届ける", "is_correct": false, "explanation": "物を相手に渡す動作で、勝負とは関係ない。"}, {"text": "叫ぶ", "is_correct": false, "explanation": "大きな声を出す動作で、勝敗とは関係ない。"}, {"text": "眠る", "is_correct": false, "explanation": "体を休める動作で、勝敗とは関係ない。"}], "correct_answer": "勝つ", "explanations": {"勝つ": "勝負の結果で「負ける」と反対の意味を表す対義語。", "届ける": "物を相手に渡す動作で、勝負とは関係ない。", "叫ぶ": "大きな声を出す動作で、勝敗とは関係ない。", "眠る": "体を休める動作で、勝敗とは関係ない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37622, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "まけるは、たたかって、かてないことです。", "primary_collocate": null, "pronunciation": "まける", "ipa": "makeɾɯ", "syllable_count": 3, "sentences": [{"text": "きのうの試合で、私たちのチームは三対一で負けた。", "target_word": "負けた", "complexity_tier": "T3", "furigana": "きのうの試合[しあい]で、私[わたし]たちのチームは三対一[さんたいいち]で負[ま]けた。", "sentence_source": "generated"}, {"text": "じゃんけんに負けた人が、ジュースを買いに行く。", "target_word": "負けた", "complexity_tier": "T3", "furigana": "じゃんけんに負[ま]けた人[ひと]が、ジュースを買[か]いに行[い]く。", "sentence_source": "generated"}, {"text": "弟とカードゲームをしたが、また負けてしまった。", "target_word": "負けて", "complexity_tier": "T3", "furigana": "弟[おとうと]とカードゲームをしたが、また負[ま]けてしまった。", "sentence_source": "generated"}, {"text": "負けても泣かないで、次はがんばろうと思った。", "target_word": "負けても", "complexity_tier": "T3", "furigana": "負[ま]けても泣[な]かないで、次[つぎ]はがんばろうと思[おも]った。", "sentence_source": "generated"}, {"text": "相手が強すぎて、この試合は負けるかもしれない。", "target_word": "負ける", "complexity_tier": "T3", "furigana": "相手[あいて]が強[つよ]すぎて、この試合[しあい]は負[ま]けるかもしれない。", "sentence_source": "generated"}, {"text": "兄は走るのが速いので、競走ではいつも負ける。", "target_word": "負ける", "complexity_tier": "T3", "furigana": "兄[あに]は走[はし]るのが速[はや]いので、競走[きょうそう]ではいつも負[ま]ける。", "sentence_source": "generated"}, {"text": "最後まで走ったが、あと少しのところで負けた。", "target_word": "負けた", "complexity_tier": "T3", "furigana": "最後[さいご]まで走[はし]ったが、あと少[すこ]しのところで負[ま]けた。", "sentence_source": "generated"}, {"text": "将棋で祖父に負けて、悔しくてもう一回やった。", "target_word": "負けて", "complexity_tier": "T3", "furigana": "将棋[しょうぎ]で祖父[そふ]に負[ま]けて、悔[くや]しくてもう一回[いっかい]やった。", "sentence_source": "generated"}, {"text": "練習を休んだので、大会の一回戦で負けた。", "target_word": "負けた", "complexity_tier": "T3", "furigana": "練習[れんしゅう]を休[やす]んだので、大会[たいかい]の一回戦[いっかいせん]で負[ま]けた。", "sentence_source": "generated"}, {"text": "負けたチームの選手たちは、くやしそうに下を向いていた。", "target_word": "負けた", "complexity_tier": "T3", "furigana": "負[ま]けたチームの選手[せんしゅ]たちは、くやしそうに下[した]を向[む]いていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "負ける", "label": "基本形"}, {"form": "負けた", "label": "過去形"}, {"form": "負けない", "label": "否定形"}, {"form": "負けて", "label": "て形"}, {"form": "負けます", "label": "丁寧形"}, {"form": "負ければ", "label": "仮定形"}], "register": "平易な日常語（常体）", "sense_fingerprint": "試合や勝負で相手に勝てないこと（やさしい説明）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0e12dd3-c77b-4d9e-9498-0161804d2652') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37622, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "負けた", "is_correct": true, "explanation": "過去形で、きのうの試合の結果を言い切る形。この空欄に入る。"}, {"text": "負けたら", "is_correct": false, "explanation": "条件の形なので、文を言い切れない。"}, {"text": "負けろ", "is_correct": false, "explanation": "命令形なので、試合の結果を報告する文に合わない。"}, {"text": "負けます", "is_correct": false, "explanation": "丁寧体なので、この文の常体（だ・た）と合わない。"}], "explanations": {"負けた": "過去形で、きのうの試合の結果を言い切る形。この空欄に入る。", "負けたら": "条件の形なので、文を言い切れない。", "負けろ": "命令形なので、試合の結果を報告する文に合わない。", "負けます": "丁寧体なので、この文の常体（だ・た）と合わない。"}, "sentence_index": 0, "correct_answer": "負けた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大事な財布を負けてしまった。", "explanation": "ここは〈なくす〉の意味。物をなくすことは〈負ける〉ではなく〈なくす〉で表す。"}, {"text": "試合は三対三のまま終わり、負けた。", "explanation": "ここは〈引き分けた〉の意味。同点で終わったのに〈負けた〉とは言わず、〈引き分ける〉を使う。"}, {"text": "入試に負けたので、来年もう一度受けることにした。", "explanation": "ここは〈落ちた〉の意味。不合格になることは〈負ける〉ではなく〈落ちる〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37622, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "負けた", "is_correct": true, "explanation": "過去形で、あと少しのところで敗れたという結果を言い切る形。"}, {"text": "負けて", "is_correct": false, "explanation": "て形なので、文を言い切れない。"}, {"text": "負けるなら", "is_correct": false, "explanation": "条件の形なので、文が途中で終わってしまう。"}, {"text": "負けよう", "is_correct": false, "explanation": "意向形で、過去の結末を述べる文に合わない。"}], "explanations": {"負けた": "過去形で、あと少しのところで敗れたという結果を言い切る形。", "負けて": "て形なので、文を言い切れない。", "負けるなら": "条件の形なので、文が途中で終わってしまう。", "負けよう": "意向形で、過去の結末を述べる文に合わない。"}, "sentence_index": 6, "correct_answer": "負けた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大事なチャンスを負けて、悔しかった。", "explanation": "ここは〈逃す〉の意味。機会を取り逃がすことは〈負ける〉ではなく〈逃す〉で表す。"}, {"text": "寝坊して、朝の授業に負けてしまった。", "explanation": "ここは〈遅れる〉の意味。授業の時間に間に合わないことは〈負ける〉ではなく〈遅れる〉で表す。"}, {"text": "スマホの電池が負けた。", "explanation": "ここは〈切れる〉の意味。電池が尽きることは〈負ける〉ではなく〈切れる〉で表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37622, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女はテニスで友人を負けた。", "corrected_sentence": "彼女はテニスで友人に負けた。", "error_description": "「負ける」は勝負の相手を「〜に負ける」で表す。「を」は誤りで、正しくは「に」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "負けた", "is_correct": true, "explanation": "過去形で、じゃんけんの負けた人を修飾している。"}, {"text": "負けろ", "is_correct": false, "explanation": "命令形なので、連体修飾できず「人」に続かない。"}, {"text": "負けて", "is_correct": false, "explanation": "て形なので、名詞「人」を修飾できず文が成り立たない。"}, {"text": "負ければ", "is_correct": false, "explanation": "仮定形で、「負けたら」という仮の話になり事実を述べる文に合わない。"}], "correct_form": "負けた", "base_form": "負ける", "form_label": "過去形", "sentence_index": 1, "explanations": {"負けた": "過去形で、じゃんけんの負けた人を修飾している。", "負けろ": "命令形なので、連体修飾できず「人」に続かない。", "負けて": "て形なので、名詞「人」を修飾できず文が成り立たない。", "負ければ": "仮定形で、「負けたら」という仮の話になり事実を述べる文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37622, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨日の決勝で、相手に負けない。", "corrected_sentence": "昨日の決勝で、相手に負けた。", "error_description": "「昨日」の出来事なので過去形「負けた」が必要。「負けない」は現在の否定で時制が合わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "負けて", "is_correct": true, "explanation": "て形で、後ろの「悔しくて」へ続けている。"}, {"text": "負けよう", "is_correct": false, "explanation": "意向形で、過去の出来事を述べる文に合わない。"}, {"text": "負けます", "is_correct": false, "explanation": "丁寧体なので、後ろの文へ続かない。"}, {"text": "負けろ", "is_correct": false, "explanation": "命令形なので、過去の出来事を述べる文に合わない。"}], "correct_form": "負けて", "base_form": "負ける", "form_label": "て形", "sentence_index": 7, "explanations": {"負けて": "て形で、後ろの「悔しくて」へ続けている。", "負けよう": "意向形で、過去の出来事を述べる文に合わない。", "負けます": "丁寧体なので、後ろの文へ続かない。", "負けろ": "命令形なので、過去の出来事を述べる文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37623, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "誘惑という原因を表し、「誘惑に負けて」と自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "「負ける」は目的語を取らないので、「誘惑を負けて」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "共同を表す助詞で、「誘惑と負けて」は文にならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す助詞で、「誘惑から負けて」は原因の意味にならない。"}], "correct_answer": "に", "explanations": {"に": "誘惑という原因を表し、「誘惑に負けて」と自然に続く。", "を": "「負ける」は目的語を取らないので、「誘惑を負けて」は不自然。", "と": "共同を表す助詞で、「誘惑と負けて」は文にならない。", "から": "起点を表す助詞で、「誘惑から負けて」は原因の意味にならない。"}, "error_tags": {"を": "目的語", "と": "共同", "から": "起点"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "勝つ", "is_correct": true, "explanation": "誘惑や暑さに打ち勝つ意味で、「負ける」の対義語。"}, {"text": "咲く", "is_correct": false, "explanation": "花が開く動作を表し、対義語ではない。"}, {"text": "遊ぶ", "is_correct": false, "explanation": "楽しむ行為を表し、勝ち負けの対義語ではない。"}, {"text": "届く", "is_correct": false, "explanation": "物や知らせが到着することを表し、対義語ではない。"}], "correct_answer": "勝つ", "explanations": {"勝つ": "誘惑や暑さに打ち勝つ意味で、「負ける」の対義語。", "咲く": "花が開く動作を表し、対義語ではない。", "遊ぶ": "楽しむ行為を表し、勝ち負けの対義語ではない。", "届く": "物や知らせが到着することを表し、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37623, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "対戦相手を表し、「先輩に負けてしまった」と自然に続く。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、「先輩へ負けて」は対戦の意味にならない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す助詞で、「先輩より負けて」は文にならない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の助詞で、「先輩の負けてしまった」は文にならない。"}], "correct_answer": "に", "explanations": {"に": "対戦相手を表し、「先輩に負けてしまった」と自然に続く。", "へ": "方向を表す助詞で、「先輩へ負けて」は対戦の意味にならない。", "より": "比較を表す助詞で、「先輩より負けて」は文にならない。", "の": "連体修飾の助詞で、「先輩の負けてしまった」は文にならない。"}, "error_tags": {"へ": "方向", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "勝つ", "is_correct": true, "explanation": "裁判や勝負で勝つことを表し、「負ける」の対義語。"}, {"text": "叫ぶ", "is_correct": false, "explanation": "大きな声を出す動作で、勝敗とは関係ない。"}, {"text": "眠る", "is_correct": false, "explanation": "体を休める動作で、勝敗とは関係ない。"}, {"text": "転ぶ", "is_correct": false, "explanation": "体が倒れる動作で、勝敗の対義語ではない。"}], "correct_answer": "勝つ", "explanations": {"勝つ": "裁判や勝負で勝つことを表し、「負ける」の対義語。", "叫ぶ": "大きな声を出す動作で、勝敗とは関係ない。", "眠る": "体を休める動作で、勝敗とは関係ない。", "転ぶ": "体が倒れる動作で、勝敗の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37623, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "競争や戦いで、相手に勝てずに敗れること。また、力や影響に耐えきれずに屈すること。", "primary_collocate": null, "pronunciation": "まける", "ipa": "makeɾɯ", "syllable_count": 3, "sentences": [{"text": "決勝で惜しくも相手に負け、準優勝に終わった。", "target_word": "負け", "complexity_tier": "T3", "furigana": "決勝[けっしょう]で惜[お]しくも相手[あいて]に負[ま]け、準優勝[じゅんゆうしょう]に終[お]わった。", "sentence_source": "generated"}, {"text": "誘惑に負けて、夜中にお菓子を食べてしまった。", "target_word": "負けて", "complexity_tier": "T3", "furigana": "誘惑[ゆうわく]に負[ま]けて、夜中[よなか]にお菓子[かし]を食[た]べてしまった。", "sentence_source": "generated"}, {"text": "彼は強い批判にも負けず、計画を最後までやり通した。", "target_word": "負けず", "complexity_tier": "T3", "furigana": "彼[かれ]は強[つよ]い批判[ひはん]にも負[ま]けず、計画[けいかく]を最後[さいご]までやり通[とお]した。", "sentence_source": "generated"}, {"text": "暑さに負けて、午後は仕事に集中できなかった。", "target_word": "負けて", "complexity_tier": "T3", "furigana": "暑[あつ]さに負[ま]けて、午後[ごご]は仕事[しごと]に集中[しゅうちゅう]できなかった。", "sentence_source": "generated"}, {"text": "選挙で現職の候補者に負けたが、得票は僅差だった。", "target_word": "負けた", "complexity_tier": "T3", "furigana": "選挙[せんきょ]で現職[げんしょく]の候補者[こうほしゃ]に負[ま]けたが、得票[とくひょう]は僅差[きんさ]だった。", "sentence_source": "generated"}, {"text": "眠気に負けそうになりながら、試験勉強を続けた。", "target_word": "負けそう", "complexity_tier": "T3", "furigana": "眠気[ねむけ]に負[ま]けそうになりながら、試験[しけん]勉強[べんきょう]を続[つづ]けた。", "sentence_source": "generated"}, {"text": "彼女は病気に負けない強い心を持っている。", "target_word": "負けない", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は病気[びょうき]に負[ま]けない強[つよ]い心[こころ]を持[も]っている。", "sentence_source": "generated"}, {"text": "経験の差で、新人は先輩に負けてしまった。", "target_word": "負けて", "complexity_tier": "T3", "furigana": "経験[けいけん]の差[さ]で、新人[しんじん]は先輩[せんぱい]に負[ま]けてしまった。", "sentence_source": "generated"}, {"text": "相手の勢いに負けて、つい要求を受け入れた。", "target_word": "負けて", "complexity_tier": "T3", "furigana": "相手[あいて]の勢[いきお]いに負[ま]けて、つい要求[ようきゅう]を受[う]け入[い]れた。", "sentence_source": "generated"}, {"text": "裁判で負けた会社は、賠償金を支払うことになった。", "target_word": "負けた", "complexity_tier": "T3", "furigana": "裁判[さいばん]で負[ま]けた会社[かいしゃ]は、賠償金[ばいしょうきん]を支払[しはら]うことになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "負ける", "label": "基本形"}, {"form": "負けた", "label": "過去形"}, {"form": "負けない", "label": "否定形"}, {"form": "負けて", "label": "て形"}, {"form": "負けず", "label": "否定連用形"}, {"form": "負けそう", "label": "様態形"}], "register": "一般的な書き言葉（常体）", "sense_fingerprint": "勝負で敗れる／誘惑・暑さ・圧力などに耐えきれず屈する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0e12dd3-c77b-4d9e-9498-0161804d2652') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37623, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "負け", "is_correct": true, "explanation": "中止形で、後ろの「準優勝に終わった」へ続けている。"}, {"text": "負けよう", "is_correct": false, "explanation": "意向形で、結果を述べる文に合わない。"}, {"text": "負けます", "is_correct": false, "explanation": "丁寧体なので、後ろの文へ続かない。"}, {"text": "負けろ", "is_correct": false, "explanation": "命令形なので、結果を述べる文の流れに合わない。"}], "explanations": {"負け": "中止形で、後ろの「準優勝に終わった」へ続けている。", "負けよう": "意向形で、結果を述べる文に合わない。", "負けます": "丁寧体なので、後ろの文へ続かない。", "負けろ": "命令形なので、結果を述べる文の流れに合わない。"}, "sentence_index": 0, "correct_answer": "負け"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "原材料が高くなったのに、店はお菓子の値段を負けてくれた。", "explanation": "ここは〈値引きする〉の意味。値段を下げることは〈負ける〉で言うが、勝負で敗れる意味ではない。"}, {"text": "寝坊して、大事な会議に負けてしまった。", "explanation": "ここは〈遅れる〉の意味。会議に間に合わないことは〈負ける〉ではなく〈遅れる〉で表す。"}, {"text": "試験に負けて、もう一年勉強することになった。", "explanation": "ここは〈落第する〉の意味。試験で不合格になることは〈負ける〉ではなく〈落ちる〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37623, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "負けない", "is_correct": true, "explanation": "否定の連体形で、「病気に負けない強い心」と自然に修飾している。"}, {"text": "負けた", "is_correct": false, "explanation": "過去形で「病気に負けた強い心」となり、意味が通らない。"}, {"text": "負けたい", "is_correct": false, "explanation": "願望形で「負けたい強い心」となり、意味が通らない。"}, {"text": "負けるな", "is_correct": false, "explanation": "禁止の命令形で、「強い心」を修飾できない。"}], "explanations": {"負けない": "否定の連体形で、「病気に負けない強い心」と自然に修飾している。", "負けた": "過去形で「病気に負けた強い心」となり、意味が通らない。", "負けたい": "願望形で「負けたい強い心」となり、意味が通らない。", "負けるな": "禁止の命令形で、「強い心」を修飾できない。"}, "sentence_index": 6, "correct_answer": "負けない"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "道に負けて、約束の時間に大きく遅れてしまった。", "explanation": "ここは〈迷う〉の意味。道に迷うことは〈負ける〉ではなく〈迷う〉で表す。"}, {"text": "相談して、二人で行き先に負けた。", "explanation": "ここは〈決める〉の意味。行き先を選ぶことは〈負ける〉ではなく〈決める〉で表す。"}, {"text": "寝坊して、朝のバスに負けた。", "explanation": "ここは〈乗り遅れる〉の意味。バスに間に合わないことは〈負ける〉ではなく〈乗り遅れる〉で表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37623, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先輩の強い言葉を負けて、言い返せなかった。", "corrected_sentence": "先輩の強い言葉に負けて、言い返せなかった。", "error_description": "「負ける」は相手を「〜に負ける」で表す。「を」は誤りで、正しくは「に」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "負けて", "is_correct": true, "explanation": "て形で、「お菓子を食べてしまった」へ原因を続けている。"}, {"text": "負けない", "is_correct": false, "explanation": "否定形で、屈しなかったという意味になり文の流れと合わない。"}, {"text": "負けろ", "is_correct": false, "explanation": "命令形なので、過去の出来事を述べる文に合わない。"}, {"text": "負ければ", "is_correct": false, "explanation": "仮定形で、仮の話になり事実を述べる文に合わない。"}], "correct_form": "負けて", "base_form": "負ける", "form_label": "て形", "sentence_index": 1, "explanations": {"負けて": "て形で、「お菓子を食べてしまった」へ原因を続けている。", "負けない": "否定形で、屈しなかったという意味になり文の流れと合わない。", "負けろ": "命令形なので、過去の出来事を述べる文に合わない。", "負ければ": "仮定形で、仮の話になり事実を述べる文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37623, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨日の暑さに、彼はまったく負けない。", "corrected_sentence": "昨日の暑さに、彼はまったく負けなかった。", "error_description": "「昨日」の出来事なので過去形「負けなかった」が必要。「負けない」は現在形で時制が合わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "負けて", "is_correct": true, "explanation": "て形で、「負けてしまった」と続けている。"}, {"text": "負けます", "is_correct": false, "explanation": "丁寧体なので、過去の出来事を述べる常体の文と合わない。"}, {"text": "負けろ", "is_correct": false, "explanation": "命令形なので、過去の出来事を述べる文に合わない。"}, {"text": "負けず", "is_correct": false, "explanation": "否定連用形で、屈しないという意味になり文の内容と合わない。"}], "correct_form": "負けて", "base_form": "負ける", "form_label": "て形", "sentence_index": 7, "explanations": {"負けて": "て形で、「負けてしまった」と続けている。", "負けます": "丁寧体なので、過去の出来事を述べる常体の文と合わない。", "負けろ": "命令形なので、過去の出来事を述べる文に合わない。", "負けず": "否定連用形で、屈しないという意味になり文の内容と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37624, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不安定", "is_correct": true, "explanation": "安定の対義語で、揺れて落ち着かない状態を表す。"}, {"text": "振動", "is_correct": false, "explanation": "揺れること自体は表すが、安定の対義語ではない。"}, {"text": "混雑", "is_correct": false, "explanation": "人や物が込み合う状態を表し、安定の対義語ではない。"}, {"text": "遅延", "is_correct": false, "explanation": "予定より遅れることを表し、安定の対義語ではない。"}], "correct_answer": "不安定", "explanations": {"不安定": "安定の対義語で、揺れて落ち着かない状態を表す。", "振動": "揺れること自体は表すが、安定の対義語ではない。", "混雑": "人や物が込み合う状態を表し、安定の対義語ではない。", "遅延": "予定より遅れることを表し、安定の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37624, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不安定", "is_correct": true, "explanation": "安定の対義語で、揺れて落ち着かない状態を表す。"}, {"text": "雑踏", "is_correct": false, "explanation": "人が入り乱れる様子を表し、対義語ではない。"}, {"text": "会議", "is_correct": false, "explanation": "話し合いの場を指し、対義語ではない。"}, {"text": "花火", "is_correct": false, "explanation": "夜空に上がる火の現象で、対義語ではない。"}], "correct_answer": "不安定", "explanations": {"不安定": "安定の対義語で、揺れて落ち着かない状態を表す。", "雑踏": "人が入り乱れる様子を表し、対義語ではない。", "会議": "話し合いの場を指し、対義語ではない。", "花火": "夜空に上がる火の現象で、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37624, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "動かないように、しっかりしていること。", "primary_collocate": null, "pronunciation": "あんてい", "ipa": "a̠nte̞i", "syllable_count": 4, "sentences": [{"text": "このいすは足が広いので、とても安定しています。", "target_word": "安定", "complexity_tier": "T3", "furigana": "このいすは足[あし]が広[ひろ]いので、とても安定[あんてい]しています。", "sentence_source": "generated"}, {"text": "船が大きく揺れて、体の安定を保てなかった。", "target_word": "安定", "complexity_tier": "T3", "furigana": "船[ふね]が大[おお]きく揺[ゆ]れて、体[からだ]の安定[あんてい]を保[たも]てなかった。", "sentence_source": "generated"}, {"text": "台風の後、天気がやっと安定した。", "target_word": "安定", "complexity_tier": "T3", "furigana": "台風[たいふう]の後[あと]、天気[てんき]がやっと安定[あんてい]した。", "sentence_source": "generated"}, {"text": "三脚を使うと、カメラが安定して、きれいな写真が撮れる。", "target_word": "安定", "complexity_tier": "T3", "furigana": "三脚[さんきゃく]を使[つか]うと、カメラが安定[あんてい]して、きれいな写真[しゃしん]が撮[と]れる。", "sentence_source": "generated"}, {"text": "安定した仕事に就きたいので、公務員を目指している。", "target_word": "安定", "complexity_tier": "T3", "furigana": "安定[あんてい]した仕事[しごと]に就[つ]きたいので、公務員[こうむいん]を目指[めざ]している。", "sentence_source": "generated"}, {"text": "物価が安定しているので、生活しやすい。", "target_word": "安定", "complexity_tier": "T3", "furigana": "物価[ぶっか]が安定[あんてい]しているので、生活[せいかつ]しやすい。", "sentence_source": "generated"}, {"text": "彼は気持ちが安定していて、いつも落ち着いている。", "target_word": "安定", "complexity_tier": "T3", "furigana": "彼[かれ]は気持[きも]ちが安定[あんてい]していて、いつも落[お]ち着[つ]いている。", "sentence_source": "generated"}, {"text": "荷物を低い所に置くと、棚の安定がよくなる。", "target_word": "安定", "complexity_tier": "T3", "furigana": "荷物[にもつ]を低[ひく]い所[ところ]に置[お]くと、棚[たな]の安定[あんてい]がよくなる。", "sentence_source": "generated"}, {"text": "自転車は速く走るほど安定する。", "target_word": "安定", "complexity_tier": "T3", "furigana": "自転車[じてんしゃ]は速[はや]く走[はし]るほど安定[あんてい]する。", "sentence_source": "generated"}, {"text": "病気の父の容体はやっと安定した。", "target_word": "安定", "complexity_tier": "T3", "furigana": "病気[びょうき]の父[ちち]の容体[ようだい]はやっと安定[あんてい]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "安定", "label": "基本形（名詞）"}, {"form": "安定する", "label": "する動詞"}, {"form": "安定した", "label": "過去・連体形"}, {"form": "安定している", "label": "継続"}], "register": "中立", "sense_fingerprint": "ぐらつかず、しっかり落ち着いて変わらない状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90fa4bdf-c71d-489f-bb70-e9e1151b79b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37624, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安定", "is_correct": true, "explanation": "足が広くて動かない状態を表し、「とても〜しています」の空欄に入る。"}, {"text": "海岸", "is_correct": false, "explanation": "海岸は場所の名で、いすの様子を表せない。"}, {"text": "教室", "is_correct": false, "explanation": "教室は部屋の名で、いすの状態には使えない。"}, {"text": "名刺", "is_correct": false, "explanation": "名刺は名前を書いた紙で、いすの状態を表さない。"}], "explanations": {"安定": "足が広くて動かない状態を表し、「とても〜しています」の空欄に入る。", "海岸": "海岸は場所の名で、いすの様子を表せない。", "教室": "教室は部屋の名で、いすの状態には使えない。", "名刺": "名刺は名前を書いた紙で、いすの状態を表さない。"}, "sentence_index": 0, "correct_answer": "安定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医者に、しばらく安定にしているよう言われた。", "explanation": "ここは〈安静〉の意味（体を休めて動かさないこと）。安定は揺れず変わらない状態を指すので、体を休める意味では使えない。"}, {"text": "彼は突然のできごとにも、安定を装っていた。", "explanation": "ここは〈平静〉の意味（動じず落ち着いていること）。安定は状態が変わらないことで、感情を隠す振る舞いは表せない。"}, {"text": "授業中は、先生の話に安定していた。", "explanation": "ここは〈集中〉の意味（一つのことに心を向けること）。安定は落ち着いて変わらない状態で、心を一点に向ける意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37624, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "安定", "is_correct": true, "explanation": "気持ちが揺れず落ち着いている状態を表し、空欄に入る。"}, {"text": "天井", "is_correct": false, "explanation": "部屋の上の面を指し、気持ちの状態には使えない。"}, {"text": "切符", "is_correct": false, "explanation": "乗車などに使う券で、気持ちの様子は表せない。"}, {"text": "博物館", "is_correct": false, "explanation": "展示施設の名で、気持ちの状態には合わない。"}], "explanations": {"安定": "気持ちが揺れず落ち着いている状態を表し、空欄に入る。", "天井": "部屋の上の面を指し、気持ちの状態には使えない。", "切符": "乗車などに使う券で、気持ちの様子は表せない。", "博物館": "展示施設の名で、気持ちの状態には合わない。"}, "sentence_index": 6, "correct_answer": "安定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試合で、チームは安定を収めた。", "explanation": "ここは〈勝利〉の意味。収めるのは勝利や成功で、安定は収める結果ではない。"}, {"text": "暑い日、彼は額に安定をかいた。", "explanation": "ここは〈汗〉の意味。額にかくのは汗で、安定は状態を表すので合わない。"}, {"text": "作業員は現場で、常に安定を払っている。", "explanation": "ここは〈注意〉の意味。払うのは注意で、安定は払う対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37624, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大きな波で、船の安定に保てなかった。", "corrected_sentence": "大きな波で、船の安定を保てなかった。", "error_description": "「保つ」は「〜を保つ」と目的語に「を」を取る。「に」は誤りで、「安定を保つ」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37624, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "台風の後、ようやく地盤が安定させた。", "corrected_sentence": "台風の後、ようやく地盤が安定した。", "error_description": "「安定させる」は動作主が目的語を安定させる使役で、主語の地盤は動かせない。自動詞の「安定した」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
