INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37626, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "食べ物や飲み物の味がとてもよいこと。", "primary_collocate": null, "pronunciation": "うまい", "ipa": "ɯmai", "syllable_count": 3, "sentences": [{"text": "この店のラーメンは、スープが濃くてとても旨い。", "target_word": "旨い", "complexity_tier": "T3", "furigana": "この店[みせ]のラーメンは、スープが濃[こ]くてとても旨[うま]い。", "sentence_source": "generated"}, {"text": "仕事のあとに飲む冷たいビールは、格別に旨い。", "target_word": "旨い", "complexity_tier": "T3", "furigana": "仕事[しごと]のあとに飲[の]む冷[つめ]たいビールは、格別[かくべつ]に旨[うま]い。", "sentence_source": "generated"}, {"text": "獲れたての魚は、刺身で食べると旨かった。", "target_word": "旨かった", "complexity_tier": "T3", "furigana": "獲[と]れたての魚[さかな]は、刺身[さしみ]で食[た]べると旨[うま]かった。", "sentence_source": "generated"}, {"text": "母が作った煮物は、どこの店よりも旨いと思う。", "target_word": "旨い", "complexity_tier": "T3", "furigana": "母[はは]が作[つく]った煮物[にもの]は、どこの店[みせ]よりも旨[うま]いと思[おも]う。", "sentence_source": "generated"}, {"text": "このパンは焼きたてで、外はかりかり、中はふわふわで旨い。", "target_word": "旨い", "complexity_tier": "T3", "furigana": "このパンは焼[や]きたてで、外[そと]はかりかり、中[なか]はふわふわで旨[うま]い。", "sentence_source": "generated"}, {"text": "山の水で淹れたお茶が、びっくりするほど旨かった。", "target_word": "旨かった", "complexity_tier": "T3", "furigana": "山[やま]の水[みず]で淹[い]れたお茶[ちゃ]が、びっくりするほど旨[うま]かった。", "sentence_source": "generated"}, {"text": "旨いものを食べに、わざわざ遠くの町まで出かけた。", "target_word": "旨い", "complexity_tier": "T3", "furigana": "旨[うま]いものを食[た]べに、わざわざ遠[とお]くの町[まち]まで出[で]かけた。", "sentence_source": "generated"}, {"text": "腹が減っていたから、何を食べても旨く感じた。", "target_word": "旨く", "complexity_tier": "T3", "furigana": "腹[はら]が減[へ]っていたから、何[なに]を食[た]べても旨[うま]く感[かん]じた。", "sentence_source": "generated"}, {"text": "新米は、おかずがなくても旨いご飯だ。", "target_word": "旨い", "complexity_tier": "T3", "furigana": "新米[しんまい]は、おかずがなくても旨[うま]いご飯[はん]だ。", "sentence_source": "generated"}, {"text": "この店の餃子は旨くて、三皿もおかわりした。", "target_word": "旨くて", "complexity_tier": "T3", "furigana": "この店[みせ]の餃子[ぎょうざ]は旨[うま]くて、三皿[みさら]もおかわりした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "旨い", "label": "基本形"}, {"form": "旨かった", "label": "過去形"}, {"form": "旨くない", "label": "否定形"}, {"form": "旨くて", "label": "て形"}, {"form": "旨ければ", "label": "仮定形"}, {"form": "旨そう", "label": "様態形"}], "register": "くだけた口語（常体）", "sense_fingerprint": "食べ物や飲み物の味がとてもよい（おいしい）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0e12dd3-c77b-4d9e-9498-0161804d2652') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37626, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "旨い", "is_correct": true, "explanation": "基本形で、スープの濃さに対する評価を言い切る形。"}, {"text": "旨く", "is_correct": false, "explanation": "連用形なので、文を言い切れない。"}, {"text": "旨ければ", "is_correct": false, "explanation": "仮定形なので、文が途中で終わってしまう。"}, {"text": "旨くて", "is_correct": false, "explanation": "て形なので、文を言い切れない。"}], "explanations": {"旨い": "基本形で、スープの濃さに対する評価を言い切る形。", "旨く": "連用形なので、文を言い切れない。", "旨ければ": "仮定形なので、文が途中で終わってしまう。", "旨くて": "て形なので、文を言い切れない。"}, "sentence_index": 0, "correct_answer": "旨い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議の進め方がうまくて、予定より早く終わった。", "explanation": "ここは〈上手だ〉の意味。やり方の巧みさは味の旨さではなく別の語義。"}, {"text": "この机は重さが旨くて、一人では持ち上げられない。", "explanation": "ここは〈重い〉の意味。重さは〈旨い〉ではなく〈重い〉で表す。"}, {"text": "駅までの道のりが旨くて、すぐ着いた。", "explanation": "ここは〈近い〉の意味。道のりの近さは〈旨い〉ではなく〈近い〉で表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37626, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "旨い", "is_correct": true, "explanation": "「旨いもの」と名詞を修飾し、味の良い食べ物を指している。"}, {"text": "旨そう", "is_correct": false, "explanation": "様態形で「旨そうなもの」となり、この文の意味と合わない。"}, {"text": "旨がって", "is_correct": false, "explanation": "動詞「旨がる」のて形で、名詞を修飾できない。"}, {"text": "旨かったら", "is_correct": false, "explanation": "条件の形で、「旨かったらものを食べに」は文にならない。"}], "explanations": {"旨い": "「旨いもの」と名詞を修飾し、味の良い食べ物を指している。", "旨そう": "様態形で「旨そうなもの」となり、この文の意味と合わない。", "旨がって": "動詞「旨がる」のて形で、名詞を修飾できない。", "旨かったら": "条件の形で、「旨かったらものを食べに」は文にならない。"}, "sentence_index": 6, "correct_answer": "旨い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店は値段が旨くて、なかなか入れない。", "explanation": "ここは〈高い〉の意味。値段の高さは〈旨い〉ではなく〈高い〉で表す。"}, {"text": "この服は生地が旨くて、暑くて着られない。", "explanation": "ここは〈厚い〉の意味。生地の厚さは〈旨い〉ではなく〈厚い〉で表す。"}, {"text": "この車は旨くて、遅刻せずに済んだ。", "explanation": "ここは〈速い〉の意味。走る速さは〈旨い〉ではなく〈速い〉で表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37626, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒い夜に、熱いスープを旨い飲んだ。", "corrected_sentence": "寒い夜に、熱いスープを旨く飲んだ。", "error_description": "動詞「飲んだ」を修飾するには連用形「旨く」が必要。「旨い」のままでは誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "旨い", "is_correct": true, "explanation": "基本形で、文末で「格別に旨い」と言い切っている。"}, {"text": "旨かった", "is_correct": false, "explanation": "過去形で、現在の評価を述べる文と時制が合わない。"}, {"text": "旨くない", "is_correct": false, "explanation": "否定形で、味がよくないという意味になり文の内容と合わない。"}, {"text": "旨くて", "is_correct": false, "explanation": "て形なので、文を言い切れない。"}], "correct_form": "旨い", "base_form": "旨い", "form_label": "基本形", "sentence_index": 1, "explanations": {"旨い": "基本形で、文末で「格別に旨い」と言い切っている。", "旨かった": "過去形で、現在の評価を述べる文と時制が合わない。", "旨くない": "否定形で、味がよくないという意味になり文の内容と合わない。", "旨くて": "て形なので、文を言い切れない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37626, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨日食べた寿司は、とても旨いだった。", "corrected_sentence": "昨日食べた寿司は、とても旨かった。", "error_description": "形容詞の過去形は「旨かった」。「旨いだった」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "旨く", "is_correct": true, "explanation": "連用形で、動詞「感じた」を修飾している。"}, {"text": "旨い", "is_correct": false, "explanation": "基本形なので、動詞「感じた」を修飾できない。"}, {"text": "旨ければ", "is_correct": false, "explanation": "仮定形で、仮の話になり事実を述べる文に合わない。"}, {"text": "旨そう", "is_correct": false, "explanation": "様態形で、見た目の印象を表し、この文の意味と合わない。"}], "correct_form": "旨く", "base_form": "旨い", "form_label": "連用形", "sentence_index": 7, "explanations": {"旨く": "連用形で、動詞「感じた」を修飾している。", "旨い": "基本形なので、動詞「感じた」を修飾できない。", "旨ければ": "仮定形で、仮の話になり事実を述べる文に合わない。", "旨そう": "様態形で、見た目の印象を表し、この文の意味と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37628, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "危険", "is_correct": true, "explanation": "正解。「安全」の対義語で、けがや危なさがある状態を表す。"}, {"text": "簡単", "is_correct": false, "explanation": "「簡単」は易しさを表す語で、「安全」の対義語ではない。"}, {"text": "快適", "is_correct": false, "explanation": "「快適」は心地よさを表す語で、「安全」の対義語ではない。"}, {"text": "不便", "is_correct": false, "explanation": "「不便」は使いにくさを表す語で、「安全」の対義語ではない。"}], "correct_answer": "危険", "explanations": {"危険": "正解。「安全」の対義語で、けがや危なさがある状態を表す。", "簡単": "「簡単」は易しさを表す語で、「安全」の対義語ではない。", "快適": "「快適」は心地よさを表す語で、「安全」の対義語ではない。", "不便": "「不便」は使いにくさを表す語で、「安全」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37628, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "危険", "is_correct": true, "explanation": "正解。「安全」の対義語で、危なさがある状態を表す。"}, {"text": "手軽", "is_correct": false, "explanation": "「手軽」は簡単で負担が少ない様子を表す語で、「安全」の対義語ではない。"}, {"text": "豪華", "is_correct": false, "explanation": "「豪華」は派手で立派な様子を表す語で、「安全」の対義語ではない。"}, {"text": "贅沢", "is_correct": false, "explanation": "「贅沢」はお金をかけた楽しみを表す語で、「安全」の対義語ではない。"}], "correct_answer": "危険", "explanations": {"危険": "正解。「安全」の対義語で、危なさがある状態を表す。", "手軽": "「手軽」は簡単で負担が少ない様子を表す語で、「安全」の対義語ではない。", "豪華": "「豪華」は派手で立派な様子を表す語で、「安全」の対義語ではない。", "贅沢": "「贅沢」はお金をかけた楽しみを表す語で、「安全」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37628, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "けがやこわいことがないこと。", "primary_collocate": null, "pronunciation": "あんぜん", "ipa": "aɲzeɴ", "syllable_count": 4, "sentences": [{"text": "柵があるので、この公園は小さな子供が遊んでも安全だ。", "target_word": "安全", "complexity_tier": "T3", "furigana": "柵[さく]があるので、この公園[こうえん]は小[ちい]さな子供[こども]が遊[あそ]んでも安全[あんぜん]だ。", "sentence_source": "generated"}, {"text": "安全な場所に着くまで、手をはなしてはいけない。", "target_word": "安全", "complexity_tier": "T3", "furigana": "安全[あんぜん]な場所[ばしょ]に着[つ]くまで、手[て]をはなしてはいけない。", "sentence_source": "generated"}, {"text": "川で泳ぐときは、安全のために必ず浅いところを選ぶ。", "target_word": "安全", "complexity_tier": "T3", "furigana": "川[かわ]で泳[およ]ぐときは、安全[あんぜん]のために必[かなら]ず浅[あさ]いところを選[えら]ぶ。", "sentence_source": "generated"}, {"text": "地震のとき、机の下は安全だと先生に教わった。", "target_word": "安全", "complexity_tier": "T3", "furigana": "地震[じしん]のとき、机[つくえ]の下[した]は安全[あんぜん]だと先生[せんせい]に教[おそ]わった。", "sentence_source": "generated"}, {"text": "自転車に乗る前に、ヘルメットをつけて安全を確かめる。", "target_word": "安全", "complexity_tier": "T3", "furigana": "自転車[じてんしゃ]に乗[の]る前[まえ]に、ヘルメットをつけて安全[あんぜん]を確[たし]かめる。", "sentence_source": "generated"}, {"text": "犬がつながれているから、近くを通っても安全だ。", "target_word": "安全", "complexity_tier": "T3", "furigana": "犬[いぬ]がつながれているから、近[ちか]くを通[とお]っても安全[あんぜん]だ。", "sentence_source": "generated"}, {"text": "夜道は暗くて怖いが、友達と一緒なら安全に帰れる。", "target_word": "安全", "complexity_tier": "T3", "furigana": "夜道[よみち]は暗[くら]くて怖[こわ]いが、友達[ともだち]と一緒[いっしょ]なら安全[あんぜん]に帰[かえ]れる。", "sentence_source": "generated"}, {"text": "この遊具は低くて、落ちてもけがをしにくく安全だ。", "target_word": "安全", "complexity_tier": "T3", "furigana": "この遊具[ゆうぐ]は低[ひく]くて、落[お]ちてもけがをしにくく安全[あんぜん]だ。", "sentence_source": "generated"}, {"text": "山に登るときは、天気を調べて安全を第一に考える。", "target_word": "安全", "complexity_tier": "T3", "furigana": "山[やま]に登[のぼ]るときは、天気[てんき]を調[しら]べて安全[あんぜん]を第一[だいいち]に考[かんが]える。", "sentence_source": "generated"}, {"text": "嵐の夜、娘が帰ってきて、母はようやく家の中が安全だと感じた。", "target_word": "安全", "complexity_tier": "T3", "furigana": "嵐[あらし]の夜[よる]、娘[むすめ]が帰[かえ]ってきて、母[はは]はようやく家[いえ]の中[なか]が安全[あんぜん]だと感じた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "安全", "label": "語幹"}, {"form": "安全だ", "label": "終止形"}, {"form": "安全な", "label": "連体形"}, {"form": "安全に", "label": "連用形"}, {"form": "安全を", "label": "名詞用法（を）"}], "register": "標準語・中立（普通体）", "sense_fingerprint": "けがや怖い思いをする心配がない身近な状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T1: 3 words above tier T1 (max 2): 夜道 (Zipf 2.95), 暗く (Zipf 3.91), 帰れる (Zipf 3.79)']::text[], '636da3c2-221b-40c9-84b6-330f2c60b543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37628, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安全", "is_correct": true, "explanation": "正解。「遊んでも安全だ」は、けがをする心配がないことを表す。"}, {"text": "唐突", "is_correct": false, "explanation": "「遊んでも唐突だ」は意味が通らない。唐突は出来事の様子を表す語。"}, {"text": "無口", "is_correct": false, "explanation": "「遊んでも無口だ」は成り立たない。人の性格を表す語。"}, {"text": "不明", "is_correct": false, "explanation": "「遊んでも不明だ」は不自然で、公園の状態を表す語として合わない。"}], "explanations": {"安全": "正解。「遊んでも安全だ」は、けがをする心配がないことを表す。", "唐突": "「遊んでも唐突だ」は意味が通らない。唐突は出来事の様子を表す語。", "無口": "「遊んでも無口だ」は成り立たない。人の性格を表す語。", "不明": "「遊んでも不明だ」は不自然で、公園の状態を表す語として合わない。"}, "sentence_index": 0, "correct_answer": "安全"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この計算は安全で、間違いがない。", "explanation": "「安全」を「正確」の意味で使っている。「安全」は危険がないことを表す語で、計算の正しさは表さない。"}, {"text": "彼女は安全な人なので、すぐ怒り出す。", "explanation": "「穏やか」の意味で使っている。「安全」は危険がないことで、人柄の穏やかさは表さない。"}, {"text": "この魚は安全な味がして、とてもおいしい。", "explanation": "「安全」を「うまい」の意味で使っている。「安全」は危険がないことを表す語で、味の良さは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37628, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "安全", "is_correct": true, "explanation": "正解。「一緒なら安全に帰れる」は、けがや危険の心配なく帰れることを表す。"}, {"text": "無断", "is_correct": false, "explanation": "「一緒なら無断に帰れる」は意味が通らない。無断は許可のないことを表す語。"}, {"text": "不器用", "is_correct": false, "explanation": "「一緒なら不器用に帰れる」は成り立たない。人の性質を表す語。"}, {"text": "無関係", "is_correct": false, "explanation": "「一緒なら無関係に帰れる」は意味が通らない。文の状況に合わない。"}], "explanations": {"安全": "正解。「一緒なら安全に帰れる」は、けがや危険の心配なく帰れることを表す。", "無断": "「一緒なら無断に帰れる」は意味が通らない。無断は許可のないことを表す語。", "不器用": "「一緒なら不器用に帰れる」は成り立たない。人の性質を表す語。", "無関係": "「一緒なら無関係に帰れる」は意味が通らない。文の状況に合わない。"}, "sentence_index": 6, "correct_answer": "安全"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この夏の暑さは、もう安全だ。", "explanation": "「平気」の意味で使っている。「安全」は危険がないことで、暑さに耐えられる度合いは表さない。"}, {"text": "父は安全な頭で、難しい問題をすぐに解いた。", "explanation": "「安全」を「賢い」の意味で使っている。「安全」は危険がないことを表す語で、頭の良さは表さない。"}, {"text": "その絵は安全な色で、とても美しい。", "explanation": "「安全」を「鮮やか」の意味で使っている。「安全」は危険がないことを表す語で、色の鮮やかさは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37628, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "柵があるので、この広場は小さな子供が遊んでも安全の。", "corrected_sentence": "柵があるので、この広場は小さな子供が遊んでも安全だ。", "error_description": "「安全」は形状詞なので、文末の述語には「だ」が必要。「の」は名詞に続く形で、文末では使えない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "安全", "is_correct": true, "explanation": "正解。語幹の形で、語の基本となる部分。"}, {"text": "安全だ", "is_correct": false, "explanation": "終止形で文を言い切る形。名詞「場所」の前には置けない。"}, {"text": "安全に", "is_correct": false, "explanation": "連用形で、動詞や形容詞に続く形。「場所」を修飾する形ではない。"}, {"text": "安全を", "is_correct": false, "explanation": "名詞用法で助詞「を」を伴う形。ここでは「場所」を修飾できない。"}], "correct_form": "安全", "base_form": "安全", "form_label": "語幹", "sentence_index": 1, "explanations": {"安全": "正解。語幹の形で、語の基本となる部分。", "安全だ": "終止形で文を言い切る形。名詞「場所」の前には置けない。", "安全に": "連用形で、動詞や形容詞に続く形。「場所」を修飾する形ではない。", "安全を": "名詞用法で助詞「を」を伴う形。ここでは「場所」を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37628, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜道は暗くて怖いが、友達と一緒なら安全を家へ帰れる。", "corrected_sentence": "夜道は暗くて怖いが、友達と一緒なら安全に家へ帰れる。", "error_description": "「安全」は後ろの「帰れる」を修飾するので「に」が必要。「を」は目的語を示すため、ここでは合わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "安全", "is_correct": true, "explanation": "正解。語幹の形で、語の基本となる部分。"}, {"text": "安全な", "is_correct": false, "explanation": "連体形で名詞の前に置く形。文末の述語にはなれない。"}, {"text": "安全で", "is_correct": false, "explanation": "「で」で続ける中止の形。文を言い切る位置には置けず、ここでは述語として成り立たない。"}, {"text": "安全だった", "is_correct": false, "explanation": "過去の形。今の遊具の状態を述べる文では時制が合わない。"}], "correct_form": "安全", "base_form": "安全", "form_label": "語幹", "sentence_index": 7, "explanations": {"安全": "正解。語幹の形で、語の基本となる部分。", "安全な": "連体形で名詞の前に置く形。文末の述語にはなれない。", "安全で": "「で」で続ける中止の形。文を言い切る位置には置けず、ここでは述語として成り立たない。", "安全だった": "過去の形。今の遊具の状態を述べる文では時制が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37629, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "危険", "is_correct": true, "explanation": "正解。「安全」の対義語で、けがや危なさがある状態を表す。"}, {"text": "簡単", "is_correct": false, "explanation": "「簡単」は易しさを表す語で、「安全」の対義語ではない。"}, {"text": "快適", "is_correct": false, "explanation": "「快適」は心地よさを表す語で、「安全」の対義語ではない。"}, {"text": "不便", "is_correct": false, "explanation": "「不便」は使いにくさを表す語で、「安全」の対義語ではない。"}], "correct_answer": "危険", "explanations": {"危険": "正解。「安全」の対義語で、けがや危なさがある状態を表す。", "簡単": "「簡単」は易しさを表す語で、「安全」の対義語ではない。", "快適": "「快適」は心地よさを表す語で、「安全」の対義語ではない。", "不便": "「不便」は使いにくさを表す語で、「安全」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37629, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "危険", "is_correct": true, "explanation": "正解。「安全」の対義語で、危なさがある状態を表す。"}, {"text": "豪華", "is_correct": false, "explanation": "「豪華」は派手で立派な様子を表す語で、「安全」の対義語ではない。"}, {"text": "不規則", "is_correct": false, "explanation": "「不規則」は決まりがない様子を表す語で、「安全」の対義語ではない。"}, {"text": "手軽", "is_correct": false, "explanation": "「手軽」は簡単で負担が少ない様子を表す語で、「安全」の対義語ではない。"}], "correct_answer": "危険", "explanations": {"危険": "正解。「安全」の対義語で、危なさがある状態を表す。", "豪華": "「豪華」は派手で立派な様子を表す語で、「安全」の対義語ではない。", "不規則": "「不規則」は決まりがない様子を表す語で、「安全」の対義語ではない。", "手軽": "「手軽」は簡単で負担が少ない様子を表す語で、「安全」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37629, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "危険がなく、安心できること。また、そのさま。", "primary_collocate": null, "pronunciation": "あんぜん", "ipa": "aɲzeɴ", "syllable_count": 4, "sentences": [{"text": "彼がこれらを大切に育てる理由は、地域の子供たちに安全な給食を安定的に提供するためだ。", "target_word": "安全", "complexity_tier": "T3", "furigana": "彼[かれ]がこれらを大切[たいせつ]に育[そだ]てる理由[りゆう]は、地域[ちいき]の子供[こども]たちに安全[あんぜん]な給食[きゅうしょく]を安定的[あんていてき]に提供[ていきょう]するためだ。", "sentence_source": "mined"}, {"text": "この道は車が少なく、子供が歩いても安全だ。", "target_word": "安全", "complexity_tier": "T3", "furigana": "この道[みち]は車[くるま]が少[すく]なく、子供[こども]が歩[ある]いても安全[あんぜん]だ。", "sentence_source": "generated"}, {"text": "安全な水を飲めない地域では、病気にかかる人が多い。", "target_word": "安全", "complexity_tier": "T3", "furigana": "安全[あんぜん]な水[みず]を飲[の]めない地域[ちいき]では、病気[びょうき]にかかる人[ひと]が多[おお]い。", "sentence_source": "generated"}, {"text": "工事の間、作業員は安全に働けるようにヘルメットをかぶる。", "target_word": "安全", "complexity_tier": "T3", "furigana": "工事[こうじ]の間[あいだ]、作業員[さぎょういん]は安全[あんぜん]に働[はたら]けるようにヘルメットをかぶる。", "sentence_source": "generated"}, {"text": "台風が近づいているので、安全な場所に避難したほうがいい。", "target_word": "安全", "complexity_tier": "T3", "furigana": "台風[たいふう]が近[ちか]づいているので、安全[あんぜん]な場所[ばしょ]に避難[ひなん]したほうがいい。", "sentence_source": "generated"}, {"text": "農薬を使わないので、この野菜は安全で、小さい子にも食べさせられる。", "target_word": "安全", "complexity_tier": "T3", "furigana": "農薬[のうやく]を使[つか]わないので、この野菜[やさい]は安全[あんぜん]で、小[ちい]さい子[こ]にも食[た]べさせられる。", "sentence_source": "generated"}, {"text": "専門家が点検して、この橋は安全だと確認された。", "target_word": "安全", "complexity_tier": "T3", "furigana": "専門家[せんもんか]が点検[てんけん]して、この橋[はし]は安全[あんぜん]だと確認[かくにん]された。", "sentence_source": "generated"}, {"text": "夜は暗い道より、明るい道を選んだほうが安全だ。", "target_word": "安全", "complexity_tier": "T3", "furigana": "夜[よる]は暗[くら]い道[みち]より、明[あか]るい道[みち]を選[えら]んだほうが安全[あんぜん]だ。", "sentence_source": "generated"}, {"text": "この薬は医師の指示を守れば、安全に使うことができる。", "target_word": "安全", "complexity_tier": "T3", "furigana": "この薬[くすり]は医師[いし]の指示[しじ]を守[まも]れば、安全[あんぜん]に使[つか]うことができる。", "sentence_source": "generated"}, {"text": "食品工場では、安全な製品を届けるために毎日検査をする。", "target_word": "安全", "complexity_tier": "T3", "furigana": "食品[しょくひん]工場[こうじょう]では、安全[あんぜん]な製品[せいひん]を届[とど]けるために毎日[まいにち]検査[けんさ]をする。", "sentence_source": "generated"}], "morphological_forms": [{"form": "安全", "label": "語幹"}, {"form": "安全だ", "label": "終止形"}, {"form": "安全な", "label": "連体形"}, {"form": "安全に", "label": "連用形"}, {"form": "安全で", "label": "連用形（で）"}], "register": "標準語・中立（普通体）", "sense_fingerprint": "危険がなく安心して利用・生活できる状態（食品・道・薬など）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T1: 3 words above tier T1 (max 2): 働ける (Zipf 3.58), ヘルメット (Zipf 3.97), かぶる (Zipf 3.49)']::text[], '636da3c2-221b-40c9-84b6-330f2c60b543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37629, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安全", "is_correct": true, "explanation": "正解。「安全な給食」は危険や不安がない給食を指す。"}, {"text": "無関係", "is_correct": false, "explanation": "「無関係な給食」は意味が通らない。給食と無関係という語は文の目的に合わない。"}, {"text": "無断", "is_correct": false, "explanation": "「無断な給食」は成り立たない。無断は許可のないことを表す語。"}, {"text": "不明", "is_correct": false, "explanation": "「不明な給食」は不自然。給食の性質を表す語として合わない。"}], "explanations": {"安全": "正解。「安全な給食」は危険や不安がない給食を指す。", "無関係": "「無関係な給食」は意味が通らない。給食と無関係という語は文の目的に合わない。", "無断": "「無断な給食」は成り立たない。無断は許可のないことを表す語。", "不明": "「不明な給食」は不自然。給食の性質を表す語として合わない。"}, "sentence_index": 0, "correct_answer": "安全"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "あの選手は安全な勢いで、いつもゴールを決める。", "explanation": "「安全」を「鋭い」の意味で使っている。「安全」は危険がないことを表す語で、勢いの鋭さは表さない。"}, {"text": "この店の値段は安全だ。", "explanation": "「安い」の意味で使っている。「安全」は危険がないことなので、値段の高低は表さない。"}, {"text": "彼は安全な声で、子供に話しかけた。", "explanation": "「安全」を「優しい」の意味で使っている。「安全」は危険がないことを表す語で、声の優しさは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37629, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "安全", "is_correct": true, "explanation": "正解。「この橋は安全だと確認された」は、危険がないと確かめられたことを表す。"}, {"text": "唐突", "is_correct": false, "explanation": "「この橋は唐突だと確認された」は意味が通らない。唐突は出来事の様子を表す語。"}, {"text": "不器用", "is_correct": false, "explanation": "「この橋は不器用だと確認された」は成り立たない。人の性質を表す語。"}, {"text": "無口", "is_correct": false, "explanation": "「この橋は無口だと確認された」は不自然。人の性格を表す語。"}], "explanations": {"安全": "正解。「この橋は安全だと確認された」は、危険がないと確かめられたことを表す。", "唐突": "「この橋は唐突だと確認された」は意味が通らない。唐突は出来事の様子を表す語。", "不器用": "「この橋は不器用だと確認された」は成り立たない。人の性質を表す語。", "無口": "「この橋は無口だと確認された」は不自然。人の性格を表す語。"}, "sentence_index": 6, "correct_answer": "安全"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この問題は安全なので、誰でも解ける。", "explanation": "「安全」を「簡単」の意味で使っている。「安全」は危険がないことを表す語で、問題の易しさは表さない。"}, {"text": "彼女は安全な性格で、いつも遅刻する。", "explanation": "「安全」を「真面目」の意味で使っている。「安全」は危険がないことを表す語で、人柄の誠実さは表さない。"}, {"text": "この布は安全な長さで、何度洗っても短くならない。", "explanation": "「安全」を「縮みにくい」の意味で使っている。「安全」は危険がないことを表す語で、布の縮みにくさは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37629, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この通りは車が少なく、子供が歩いても安全な。", "corrected_sentence": "この通りは車が少なく、子供が歩いても安全だ。", "error_description": "「安全」は形状詞なので、文末では「だ」が必要。「な」は後ろに名詞が続くときの形なので、ここでは合わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "安全", "is_correct": true, "explanation": "語幹で、文中の「安全だ」の「安全」の部分と一致する。"}, {"text": "安全な", "is_correct": false, "explanation": "連体形で、後ろに名詞が続くときの形。文末の「だ」の前には入らない。"}, {"text": "安全に", "is_correct": false, "explanation": "連用形で、動詞を修飾する副詞の形。文末の「だ」の前には入らない。"}, {"text": "安全で", "is_correct": false, "explanation": "連用形（で）で、文を続ける形。文末の「だ」の前には入らない。"}], "correct_form": "安全", "base_form": "安全", "form_label": "語幹", "sentence_index": 1, "explanations": {"安全": "語幹で、文中の「安全だ」の「安全」の部分と一致する。", "安全な": "連体形で、後ろに名詞が続くときの形。文末の「だ」の前には入らない。", "安全に": "連用形で、動詞を修飾する副詞の形。文末の「だ」の前には入らない。", "安全で": "連用形（で）で、文を続ける形。文末の「だ」の前には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37629, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "食品工場では、安全だ製品を届けるために毎日検査を行っている。", "corrected_sentence": "食品工場では、安全な製品を届けるために毎日検査を行っている。", "error_description": "「安全」は形状詞で、名詞「製品」の前では「な」が必要。「だ」は文末の形なので、名詞の前には使えない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "安全", "is_correct": true, "explanation": "語幹で、文中の「安全だ」の「安全」の部分と一致する。"}, {"text": "安全だった", "is_correct": false, "explanation": "過去の形で、今の一般的な判断を述べる文と合わない。"}, {"text": "安全ではない", "is_correct": false, "explanation": "否定の形で、明るい道のほうが安全だという文の内容と逆になる。"}, {"text": "安全であれば", "is_correct": false, "explanation": "仮定の形で、「選んだほうが安全だ」と言い切る文に合わない。"}], "correct_form": "安全", "base_form": "安全", "form_label": "語幹", "sentence_index": 7, "explanations": {"安全": "語幹で、文中の「安全だ」の「安全」の部分と一致する。", "安全だった": "過去の形で、今の一般的な判断を述べる文と合わない。", "安全ではない": "否定の形で、明るい道のほうが安全だという文の内容と逆になる。", "安全であれば": "仮定の形で、「選んだほうが安全だ」と言い切る文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37630, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「試験の段階」で、試験と段階をつなぎ、名詞句を作る。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」は、名詞どうしをつなぐこの位置には入らない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は位置や相手を示すため、「試験に段階」では意味が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すため、名詞の段階をつなぐ位置には合わない。"}], "correct_answer": "の", "explanations": {"の": "「試験の段階」で、試験と段階をつなぎ、名詞句を作る。", "が": "主語を示す「が」は、名詞どうしをつなぐこの位置には入らない。", "に": "「に」は位置や相手を示すため、「試験に段階」では意味が成り立たない。", "で": "「で」は場所や手段を示すため、名詞の段階をつなぐ位置には合わない。"}, "error_tags": {"の": "連体修飾", "が": "主格", "に": "位置・相手", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37630, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37630, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かがうまくいくかどうかを、ためしにやってみること。", "primary_collocate": null, "pronunciation": "しけん", "ipa": "ɕikeɴ", "syllable_count": 3, "sentences": [{"text": "新しい信号機の試験が、来週から駅前の道路で始まります。", "target_word": "試験", "complexity_tier": "T3", "furigana": "新[あたら]しい信号機[しんごうき]の試験[しけん]が、来週[らいしゅう]から駅前[えきまえ]の道路[どうろ]で始[はじ]まります。", "sentence_source": "generated"}, {"text": "この機械はまだ試験の段階なので、売ることはできません。", "target_word": "試験", "complexity_tier": "T3", "furigana": "この機械[きかい]はまだ試験[しけん]の段階[だんかい]なので、売[う]ることはできません。", "sentence_source": "generated"}, {"text": "会社は新しい薬の試験を、何年も続けています。", "target_word": "試験", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は新[あたら]しい薬[くすり]の試験[しけん]を、何年[なんねん]も続[つづ]けています。", "sentence_source": "generated"}, {"text": "試験の結果がよければ、このやり方を全部の店に広げます。", "target_word": "試験", "complexity_tier": "T3", "furigana": "試験[しけん]の結果[けっか]がよければ、このやり方[かた]を全部[ぜんぶ]の店[みせ]に広[ひろ]げます。", "sentence_source": "generated"}, {"text": "この町の一部で、無人バスの試験が行われています。", "target_word": "試験", "complexity_tier": "T3", "furigana": "この町[まち]の一部[いちぶ]で、無人[むじん]バスの試験[しけん]が行[おこな]われています。", "sentence_source": "generated"}, {"text": "新しい肥料が本当に効くか、畑の一角で試験をしてみました。", "target_word": "試験", "complexity_tier": "T3", "furigana": "新[あたら]しい肥料[ひりょう]が本当[ほんとう]に効[き]くか、畑[はたけ]の一角[いっかく]で試験[しけん]をしてみました。", "sentence_source": "generated"}, {"text": "試験をしないで、いきなり本番に使うのは危ないです。", "target_word": "試験", "complexity_tier": "T3", "furigana": "試験[しけん]をしないで、いきなり本番[ほんばん]に使[つか]うのは危[あぶ]ないです。", "sentence_source": "generated"}, {"text": "ロケットのエンジンは、打ち上げの前に何度も試験されます。", "target_word": "試験", "complexity_tier": "T3", "furigana": "ロケットのエンジンは、打[う]ち上[あ]げの前[まえ]に何度[なんど]も試験[しけん]されます。", "sentence_source": "generated"}, {"text": "市は、ごみの分け方を変える試験を、三か月間おこないます。", "target_word": "試験", "complexity_tier": "T3", "furigana": "市[し]は、ごみの分[わ]け方[かた]を変[か]える試験[しけん]を、三[さん]か月間[げつかん]おこないます。", "sentence_source": "generated"}, {"text": "まだ試験ですから、うまくいかなくても気にしないでください。", "target_word": "試験", "complexity_tier": "T3", "furigana": "まだ試験[しけん]ですから、うまくいかなくても気[き]にしないでください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "試験", "label": "基本形（名詞）"}, {"form": "試験する", "label": "サ変動詞・辞書形"}, {"form": "試験した", "label": "サ変動詞・過去形"}, {"form": "試験して", "label": "サ変動詞・て形"}, {"form": "試験される", "label": "サ変動詞・受身形"}], "register": "標準的な丁寧体（です・ます）", "sense_fingerprint": "新しい方法や機械がうまくいくかを、本番の前にためしにやってみる試行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac89fc-2658-479e-8f76-fbc5a3afbfe1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37630, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "試験", "is_correct": true, "explanation": "「試験」は、新しいものを本番の前にためしてみる意味で、新しい信号機の試しの段階に合う。"}, {"text": "色", "is_correct": false, "explanation": "「信号機の色が来週から始まる」は成り立たず、文の流れに合わない。"}, {"text": "電池", "is_correct": false, "explanation": "「信号機の電池が始まる」という内容は不自然で、道路で始まる話としても意味が通らない。"}, {"text": "寝息", "is_correct": false, "explanation": "「信号機の寝息」は意味をなさず、「始まります」とも結びつかない。"}], "explanations": {"試験": "「試験」は、新しいものを本番の前にためしてみる意味で、新しい信号機の試しの段階に合う。", "色": "「信号機の色が来週から始まる」は成り立たず、文の流れに合わない。", "電池": "「信号機の電池が始まる」という内容は不自然で、道路で始まる話としても意味が通らない。", "寝息": "「信号機の寝息」は意味をなさず、「始まります」とも結びつかない。"}, "sentence_index": 0, "correct_answer": "試験"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今日の試験で、うちのチームは三対一で勝ちました。", "explanation": "ここは〈試合〉の意味。勝ち負けを競う場面なので、試験は合わない。"}, {"text": "毎年の健康診断で、胃の試験を受けています。", "explanation": "ここは〈検査〉の意味。体の状態を調べる場面では検査と言い、試験は新しいものが働くかをためす場合に使う。"}, {"text": "学校の試験に合格するため、毎晩遅くまで勉強しました。", "explanation": "ここは〈学力試験〉の意味。知識を問う場面で、本番前にためしてみる行為とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37630, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "試験", "is_correct": true, "explanation": "「試験をしないで、いきなり本番に使う」は、本番の前にためすという意味で、試験の意味に合う。"}, {"text": "日焼け", "is_correct": false, "explanation": "「日焼けをしないで本番に使う」は意味が通らず、文の論理に合わない。"}, {"text": "発送", "is_correct": false, "explanation": "「発送をしないで本番に使う」は成り立たず、ためす行為の説明にもならない。"}, {"text": "失恋", "is_correct": false, "explanation": "「失恋をしないで」という文脈は意味が通らない。"}], "explanations": {"試験": "「試験をしないで、いきなり本番に使う」は、本番の前にためすという意味で、試験の意味に合う。", "日焼け": "「日焼けをしないで本番に使う」は意味が通らず、文の論理に合わない。", "発送": "「発送をしないで本番に使う」は成り立たず、ためす行為の説明にもならない。", "失恋": "「失恋をしないで」という文脈は意味が通らない。"}, "sentence_index": 6, "correct_answer": "試験"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来週の試験に向けて、毎晩勉強しています。", "explanation": "ここは〈学力試験〉の意味。学習の場面で、本番前にためしに行う試行とは違う。"}, {"text": "夜空の星を、試験しています。", "explanation": "ここは〈観測〉の意味。星を観察して記録する場面で、試験は新しいものが働くかをためす意味に合わない。"}, {"text": "服を買う前に、体の試験をしてもらいました。", "explanation": "ここは〈採寸〉の意味。体の寸法を測る場面なので、試験は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37630, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しいバスの試験を、来月から市内の道路で始まります。", "corrected_sentence": "新しいバスの試験が、来月から市内の道路で始まります。", "error_description": "誤: 試験を／正: 試験が。「始まる」は自動詞で、主語（試験）に「が」を取るため、ここでの「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37630, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい機械の試験を務めました。", "corrected_sentence": "新しい機械の試験を行いました。", "error_description": "誤: 務めました／正: 行いました。「務める」は役割を果たす意味で、試験とは組み合わない。試験には「行う」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37631, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "手段を表し、「試験で確かめる」という自然な表現になる。"}, {"text": "の", "is_correct": false, "explanation": "「試験の確かめました」では動詞につながらず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すため、「試験へ確かめました」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「試験と確かめました」は並列の形にならず、文が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "手段を表し、「試験で確かめる」という自然な表現になる。", "の": "「試験の確かめました」では動詞につながらず、文が成り立たない。", "へ": "方向を表すため、「試験へ確かめました」は意味が通らない。", "と": "「試験と確かめました」は並列の形にならず、文が成り立たない。"}, "error_tags": {"で": "手段・道具", "の": "連体修飾", "へ": "方向", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37631, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "手段を表し、「試験で調べます」は自然な表現になる。"}, {"text": "に", "is_correct": false, "explanation": "「試験に調べます」は動作の相手として成り立たず、文が不自然になる。"}, {"text": "が", "is_correct": false, "explanation": "「試験が調べます」は試験が人のように調べる主体になり、不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す「より」は、「試験より調べます」では意味が通らない。"}], "correct_answer": "で", "explanations": {"で": "手段を表し、「試験で調べます」は自然な表現になる。", "に": "「試験に調べます」は動作の相手として成り立たず、文が不自然になる。", "が": "「試験が調べます」は試験が人のように調べる主体になり、不自然。", "より": "比較を表す「より」は、「試験より調べます」では意味が通らない。"}, "error_tags": {"で": "手段・道具", "に": "対象・相手", "が": "主格", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37631, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事の性質や能力を確かめるために、実際に試してみること。", "primary_collocate": null, "pronunciation": "しけん", "ipa": "ɕikeɴ", "syllable_count": 3, "sentences": [{"text": "橋に使う鉄の強さを調べるために、工場で試験をしました。", "target_word": "試験", "complexity_tier": "T3", "furigana": "橋[はし]に使[つか]う鉄[てつ]の強[つよ]さを調[しら]べるために、工場[こうじょう]で試験[しけん]をしました。", "sentence_source": "generated"}, {"text": "この材料は火に強いかどうか、試験で確かめました。", "target_word": "試験", "complexity_tier": "T3", "furigana": "この材料[ざいりょう]は火[ひ]に強[つよ]いかどうか、試験[しけん]で確[たし]かめました。", "sentence_source": "generated"}, {"text": "新しい車は、ぶつかったときの安全性を確かめる試験に合格しました。", "target_word": "試験", "complexity_tier": "T3", "furigana": "新[あたら]しい車[くるま]は、ぶつかったときの安全性[あんぜんせい]を確[たし]かめる試験[しけん]に合格[ごうかく]しました。", "sentence_source": "generated"}, {"text": "試験の結果、この布は水を通さないとわかりました。", "target_word": "試験", "complexity_tier": "T3", "furigana": "試験[しけん]の結果[けっか]、この布[ぬの]は水[みず]を通[とお]さないとわかりました。", "sentence_source": "generated"}, {"text": "研究者は、薬が体にどう働くかを、動物を使って試験しています。", "target_word": "試験", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、薬[くすり]が体[からだ]にどう働[はたら]くかを、動物[どうぶつ]を使[つか]って試験[しけん]しています。", "sentence_source": "generated"}, {"text": "完成した製品は、出荷の前に必ず試験を受けます。", "target_word": "試験", "complexity_tier": "T3", "furigana": "完成[かんせい]した製品[せいひん]は、出荷[しゅっか]の前[まえ]に必[かなら]ず試験[しけん]を受[う]けます。", "sentence_source": "generated"}, {"text": "水道の水がきれいかどうか、毎月試験をしています。", "target_word": "試験", "complexity_tier": "T3", "furigana": "水道[すいどう]の水[みず]がきれいかどうか、毎月[まいつき]試験[しけん]をしています。", "sentence_source": "generated"}, {"text": "この電池が何時間もつか、試験で調べます。", "target_word": "試験", "complexity_tier": "T3", "furigana": "この電池[でんち]が何時間[なんじかん]もつか、試験[しけん]で調[しら]べます。", "sentence_source": "generated"}, {"text": "厳しい試験を通った部品だけが、飛行機に使われます。", "target_word": "試験", "complexity_tier": "T3", "furigana": "厳[きび]しい試験[しけん]を通[とお]った部品[ぶひん]だけが、飛行機[ひこうき]に使[つか]われます。", "sentence_source": "generated"}, {"text": "試験のやり方を変えたら、前とは違う数字が出ました。", "target_word": "試験", "complexity_tier": "T3", "furigana": "試験[しけん]のやり方[かた]を変[か]えたら、前[まえ]とは違[ちが]う数字[すうじ]が出[で]ました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "試験", "label": "基本形（名詞）"}, {"form": "試験する", "label": "サ変動詞・辞書形"}, {"form": "試験した", "label": "サ変動詞・過去形"}, {"form": "試験して", "label": "サ変動詞・て形"}, {"form": "試験される", "label": "サ変動詞・受身形"}], "register": "標準的な丁寧体（です・ます）", "sense_fingerprint": "材料や製品などの強さ・性能・性質を、実際に調べて確かめる検査", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac89fc-2658-479e-8f76-fbc5a3afbfe1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37631, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "試験", "is_correct": true, "explanation": "「工場で試験をしました」は、鉄の強さを実際に調べる意味で、文脈に合う。"}, {"text": "受験", "is_correct": false, "explanation": "「工場で受験をしました」は、試験を受ける意味になり、工場で強さを調べる文脈に合わない。"}, {"text": "落下", "is_correct": false, "explanation": "「工場で落下をしました」は文に合わず、鉄の強さを調べる行為にもならない。"}, {"text": "停電", "is_correct": false, "explanation": "「工場で停電をしました」は意味が通らず、強さを調べる文脈に合わない。"}], "explanations": {"試験": "「工場で試験をしました」は、鉄の強さを実際に調べる意味で、文脈に合う。", "受験": "「工場で受験をしました」は、試験を受ける意味になり、工場で強さを調べる文脈に合わない。", "落下": "「工場で落下をしました」は文に合わず、鉄の強さを調べる行為にもならない。", "停電": "「工場で停電をしました」は意味が通らず、強さを調べる文脈に合わない。"}, "sentence_index": 0, "correct_answer": "試験"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "決勝の試験で、うちのチームが優勝しました。", "explanation": "ここは〈試合〉の意味。勝ち負けを競う場面なので、試験は合わない。"}, {"text": "来月の試験のために、教科書を何度も読みました。", "explanation": "ここは〈学力試験〉の意味。知識を問う場面で、材料や製品の性質を確かめる意味とは違う。"}, {"text": "毎朝、血圧を試験しています。", "explanation": "ここは〈測定〉の意味。血圧は数値を量るもので、性質をためす試験とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37631, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "試験", "is_correct": true, "explanation": "「水道の水がきれいかどうか、毎月試験をしています」は、水質を実際に調べる意味で文脈に合う。"}, {"text": "脱線", "is_correct": false, "explanation": "「毎月脱線をしています」は水質を調べる行為として成り立たない。"}, {"text": "停車", "is_correct": false, "explanation": "「毎月停車をしています」は水道の水の文脈に合わず、意味が通らない。"}, {"text": "発熱", "is_correct": false, "explanation": "「毎月発熱をしています」は水質の文脈に合わず、「をする」とも続かない。"}], "explanations": {"試験": "「水道の水がきれいかどうか、毎月試験をしています」は、水質を実際に調べる意味で文脈に合う。", "脱線": "「毎月脱線をしています」は水質を調べる行為として成り立たない。", "停車": "「毎月停車をしています」は水道の水の文脈に合わず、意味が通らない。", "発熱": "「毎月発熱をしています」は水質の文脈に合わず、「をする」とも続かない。"}, "sentence_index": 6, "correct_answer": "試験"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎朝、庭の花の様子を試験しています。", "explanation": "ここは〈観察〉の意味。花の様子を見て記録する場面で、試験は性質を試してみる意味に合わない。"}, {"text": "土地の面積を、専門の人が試験しました。", "explanation": "ここは〈測量〉の意味。面積を距離や角度から測る作業で、試験とは言わない。"}, {"text": "審判が、ゴールの試験をしました。", "explanation": "ここは〈判定〉の意味。ゴールの成否を決める場面なので、試験は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37631, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この部品は熱に強いかどうか、試験に調べます。", "corrected_sentence": "この部品は熱に強いかどうか、試験で調べます。", "error_description": "誤: 試験に／正: 試験で。「調べる」は手段を「で」で示すため、「試験に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37631, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい車は、衝突の試験を務めて安全性を確かめました。", "corrected_sentence": "新しい車は、衝突の試験を受けて安全性を確かめました。", "error_description": "誤: 務めて／正: 受けて。試験には「受ける」を使う。「務める」は役割を果たす意味で、試験とは組み合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37632, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "場所を表す助詞で、「部屋で行われた」と場所を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表す助詞で、「部屋を行われた」は受身の文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、「部屋へ行われた」は場所の表し方として合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の助詞で、「部屋の行われた」は文が成立しない。"}], "correct_answer": "で", "explanations": {"で": "場所を表す助詞で、「部屋で行われた」と場所を示す。", "を": "目的語を表す助詞で、「部屋を行われた」は受身の文として成り立たない。", "へ": "方向を表す助詞で、「部屋へ行われた」は場所の表し方として合わない。", "の": "連体修飾の助詞で、「部屋の行われた」は文が成立しない。"}, "error_tags": {"を": "対象", "へ": "方向", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37632, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「投票を行った」で、投票が目的語になる。"}, {"text": "が", "is_correct": false, "explanation": "「投票が行った」では主語になり、「行う」の目的語にならない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表す助詞で、「投票で行った」は目的語を示せない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す助詞で、「投票から行った」は文が成立しない。"}], "correct_answer": "を", "explanations": {"を": "「投票を行った」で、投票が目的語になる。", "が": "「投票が行った」では主語になり、「行う」の目的語にならない。", "で": "場所や手段を表す助詞で、「投票で行った」は目的語を示せない。", "から": "起点を表す助詞で、「投票から行った」は文が成立しない。"}, "error_tags": {"が": "主語", "で": "場所", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37632, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "行事・作業・調査などを、計画に従って実行する。", "primary_collocate": null, "pronunciation": "おこなう", "ipa": "okonaɯ", "syllable_count": 4, "sentences": [{"text": "来週、学校で避難訓練を行う。", "target_word": "行う", "complexity_tier": "T3", "furigana": "来週[らいしゅう]、学校[がっこう]で避難[ひなん]訓練[くんれん]を行[おこな]う。", "sentence_source": "generated"}, {"text": "会議は三階の大きな部屋で行われた。", "target_word": "行われた", "complexity_tier": "T3", "furigana": "会議[かいぎ]は三階[さんがい]の大[おお]きな部屋[へや]で行[おこな]われた。", "sentence_source": "generated"}, {"text": "先生は、毎朝、ラジオ体操を行うように言った。", "target_word": "行う", "complexity_tier": "T3", "furigana": "先生[せんせい]は、毎朝[まいあさ]、ラジオ体操[たいそう]を行[おこな]うように言[い]った。", "sentence_source": "generated"}, {"text": "実験を行う前に、必ず手を洗う。", "target_word": "行う", "complexity_tier": "T3", "furigana": "実験[じっけん]を行[おこな]う前[まえ]に、必[かなら]ず手[て]を洗[あら]う。", "sentence_source": "generated"}, {"text": "雨が降ったので、運動会は体育館で行った。", "target_word": "行った", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ったので、運動会[うんどうかい]は体育館[たいいくかん]で行[おこな]った。", "sentence_source": "generated"}, {"text": "新しい薬の調査は、三年間行われている。", "target_word": "行われている", "complexity_tier": "T3", "furigana": "新[あたら]しい薬[くすり]の調査[ちょうさ]は、三年間[さんねんかん]行[おこな]われている。", "sentence_source": "generated"}, {"text": "この町では、毎年夏に大きな祭りが行われる。", "target_word": "行われる", "complexity_tier": "T3", "furigana": "この町[まち]では、毎年[まいとし]夏[なつ]に大[おお]きな祭[まつ]りが行[おこな]われる。", "sentence_source": "generated"}, {"text": "私たちは、先月、クラスで投票を行った。", "target_word": "行った", "complexity_tier": "T3", "furigana": "私[わたし]たちは、先月[せんげつ]、クラスで投票[とうひょう]を行[おこな]った。", "sentence_source": "generated"}, {"text": "工事は夜に行うので、昼は静かだ。", "target_word": "行う", "complexity_tier": "T3", "furigana": "工事[こうじ]は夜[よる]に行[おこな]うので、昼[ひる]は静[しず]かだ。", "sentence_source": "generated"}, {"text": "結果を発表する式は、十時に行う。", "target_word": "行う", "complexity_tier": "T3", "furigana": "結果[けっか]を発表[はっぴょう]する式[しき]は、十時[じゅうじ]に行[おこな]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "行う", "label": "終止形"}, {"form": "行います", "label": "丁寧形"}, {"form": "行った", "label": "過去形"}, {"form": "行って", "label": "て形"}, {"form": "行わ", "label": "未然形"}, {"form": "行い", "label": "連用形"}, {"form": "行われる", "label": "受身形"}], "register": "普通体（やや改まった表現）", "sense_fingerprint": "行事・作業・調査などを計画に従って実行する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd744feb5-cce0-45db-a3b7-f31e2c301cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37632, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行う", "is_correct": true, "explanation": "行事や訓練を計画どおりに実行する意味で、「避難訓練を行う」に合う。"}, {"text": "食べる", "is_correct": false, "explanation": "飲食を表す動詞で、「避難訓練を食べる」は意味をなさない。"}, {"text": "眠る", "is_correct": false, "explanation": "睡眠を表す動詞で、「避難訓練を眠る」は成り立たない。"}, {"text": "歌う", "is_correct": false, "explanation": "歌唱を表す動詞で、「避難訓練を歌う」は意味をなさない。"}], "explanations": {"行う": "行事や訓練を計画どおりに実行する意味で、「避難訓練を行う」に合う。", "食べる": "飲食を表す動詞で、「避難訓練を食べる」は意味をなさない。", "眠る": "睡眠を表す動詞で、「避難訓練を眠る」は成り立たない。", "歌う": "歌唱を表す動詞で、「避難訓練を歌う」は意味をなさない。"}, "sentence_index": 0, "correct_answer": "行う"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明日、おじの家へ行う。", "explanation": "ここは〈行く〉の意味。場所へ移動する意味は〈行く〉で表し、〈行う〉は何かを実行する語なので合わない。"}, {"text": "彼は、大きな責任を行う。", "explanation": "ここは〈担う〉の意味。責任を引き受けて負う場合は〈担う〉で、〈行う〉は作業や行事の実行に使う。"}, {"text": "庭の花に水を行う。", "explanation": "ここは〈やる・与える〉の意味。植物に水をあげる場合は〈やる〉で、〈行う〉とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37632, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行われる", "is_correct": true, "explanation": "行事が催されるという意味で、「大きな祭りが行われる」に合う。"}, {"text": "飲まれる", "is_correct": false, "explanation": "飲む行為の受身で、「大きな祭りが飲まれる」は意味をなさない。"}, {"text": "噛まれる", "is_correct": false, "explanation": "噛む行為の受身で、「大きな祭りが噛まれる」は成り立たない。"}, {"text": "洗われる", "is_correct": false, "explanation": "洗う行為の受身で、「大きな祭りが洗われる」は意味をなさない。"}], "explanations": {"行われる": "行事が催されるという意味で、「大きな祭りが行われる」に合う。", "飲まれる": "飲む行為の受身で、「大きな祭りが飲まれる」は意味をなさない。", "噛まれる": "噛む行為の受身で、「大きな祭りが噛まれる」は成り立たない。", "洗われる": "洗う行為の受身で、「大きな祭りが洗われる」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "行われる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は、リーダーとしての役目を行った。", "explanation": "ここは〈果たす〉の意味。役目を成し遂げる場合は〈果たす〉で、〈行う〉は作業や行事の実行に使う。"}, {"text": "父は毎朝、車を行って会社へ通う。", "explanation": "ここは〈運転する〉の意味。車を操作する場合は〈運転する〉で、〈行う〉とは言わない。"}, {"text": "彼女は、友人に感謝の気持ちを行った。", "explanation": "ここは〈伝える〉の意味。気持ちを相手に届ける場合は〈伝える〉で、〈行う〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37632, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町の会館で、来月、祭りを行わ予定だ。", "corrected_sentence": "町の会館で、来月、祭りを行う予定だ。", "error_description": "「予定だ」の前は連体形の「行う」が必要。未然形「行わ」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "行われた", "is_correct": true, "explanation": "「行われる」の過去形で、会議が開かれたという文に合う。"}, {"text": "行い", "is_correct": false, "explanation": "連用形で、文末に置けず、「部屋で行い」では文が成立しない。"}, {"text": "行わ", "is_correct": false, "explanation": "未然形で、単独では文末にならず、過去の「た」も続いていない。"}, {"text": "行って", "is_correct": false, "explanation": "て形で、文末に置けず、「部屋で行って」では文が完結しない。"}], "correct_form": "行われた", "base_form": "行う", "form_label": "受身の過去形", "sentence_index": 1, "explanations": {"行われた": "「行われる」の過去形で、会議が開かれたという文に合う。", "行い": "連用形で、文末に置けず、「部屋で行い」では文が成立しない。", "行わ": "未然形で、単独では文末にならず、過去の「た」も続いていない。", "行って": "て形で、文末に置けず、「部屋で行って」では文が完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37632, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校の体育館で、来週、運動会を行うで予定だ。", "corrected_sentence": "学校の体育館で、来週、運動会を行う予定だ。", "error_description": "「行う」の直後に助詞「で」が付いている。「行う予定だ」と、連体形で「予定」に直接続けるのが正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "行った", "is_correct": true, "explanation": "「行う」の過去形で、投票を実施したという文に合う。"}, {"text": "行わせ", "is_correct": false, "explanation": "使役の語幹で、文末に置けず「投票を行わせ。」は文として成り立たない。"}, {"text": "行えず", "is_correct": false, "explanation": "可能形の否定の連用形で、文末に置けず「投票を行えず。」は文が完結しない。"}, {"text": "行いませた", "is_correct": false, "explanation": "丁寧形の語幹に過去の「た」を付けた不正な形で、文として成り立たない。"}], "correct_form": "行った", "base_form": "行う", "form_label": "過去形（普通体）", "sentence_index": 7, "explanations": {"行った": "「行う」の過去形で、投票を実施したという文に合う。", "行わせ": "使役の語幹で、文末に置けず「投票を行わせ。」は文として成り立たない。", "行えず": "可能形の否定の連用形で、文末に置けず「投票を行えず。」は文が完結しない。", "行いませた": "丁寧形の語幹に過去の「た」を付けた不正な形で、文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37634, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "立場を示す「で」で、子どもの視点という立場で町を歩く意味になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」だが、歩くの目的語はすでにあり、ここでは不自然。"}, {"text": "に", "is_correct": false, "explanation": "場所を示す「に」だが、「視点に町を歩く」とは結びつかず文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列を示す「と」で、視点と一緒に町を歩くという意味になり文意が合わない。"}], "correct_answer": "で", "explanations": {"で": "立場を示す「で」で、子どもの視点という立場で町を歩く意味になる。", "を": "目的語の「を」だが、歩くの目的語はすでにあり、ここでは不自然。", "に": "場所を示す「に」だが、「視点に町を歩く」とは結びつかず文が成り立たない。", "と": "並列を示す「と」で、視点と一緒に町を歩くという意味になり文意が合わない。"}, "error_tags": {"を": "目的語", "に": "場所", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37634, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37634, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を見るときの、どこから見るかという立場のこと。", "primary_collocate": null, "pronunciation": "してん", "ipa": "ɕite̞ɴ", "syllable_count": 3, "sentences": [{"text": "この写真は、低い視点から撮られている。", "target_word": "視点", "complexity_tier": "T3", "furigana": "この写真[しゃしん]は、低[ひく]い視点[してん]から撮[と]られている。", "sentence_source": "generated"}, {"text": "子どもの視点で町を歩くと、新しい発見がある。", "target_word": "視点", "complexity_tier": "T3", "furigana": "子[こ]どもの視点[してん]で町[まち]を歩[ある]くと、新[あたら]しい発見[はっけん]がある。", "sentence_source": "generated"}, {"text": "先生と生徒では、視点が違うのは当然だ。", "target_word": "視点", "complexity_tier": "T3", "furigana": "先生[せんせい]と生徒[せいと]では、視点[してん]が違[ちが]うのは当然[とうぜん]だ。", "sentence_source": "generated"}, {"text": "彼の意見は、お客さんの視点に立った考えだった。", "target_word": "視点", "complexity_tier": "T3", "furigana": "彼[かれ]の意見[いけん]は、お客[きゃく]さんの視点[してん]に立[た]った考[かんが]えだった。", "sentence_source": "generated"}, {"text": "この小説は、猫の視点で書かれている。", "target_word": "視点", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]は、猫[ねこ]の視点[してん]で書[か]かれている。", "sentence_source": "generated"}, {"text": "高い所に登ると、町を見る視点が変わる。", "target_word": "視点", "complexity_tier": "T3", "furigana": "高[たか]い所[ところ]に登[のぼ]ると、町[まち]を見[み]る視点[してん]が変[か]わる。", "sentence_source": "generated"}, {"text": "別の視点から見れば、その問題も違って見える。", "target_word": "視点", "complexity_tier": "T3", "furigana": "別[べつ]の視点[してん]から見[み]れば、その問題[もんだい]も違[ちが]って見[み]える。", "sentence_source": "generated"}, {"text": "絵を描くときは、視点を決めることが大切だ。", "target_word": "視点", "complexity_tier": "T3", "furigana": "絵[え]を描[か]くときは、視点[してん]を決[き]めることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "母の視点では、私はまだ子どもなのだろう。", "target_word": "視点", "complexity_tier": "T3", "furigana": "母[はは]の視点[してん]では、私[わたし]はまだ子[こ]どもなのだろう。", "sentence_source": "generated"}, {"text": "車いすの人の視点で、駅の中を調べてみた。", "target_word": "視点", "complexity_tier": "T3", "furigana": "車[くるま]いすの人[ひと]の視点[してん]で、駅[えき]の中[なか]を調[しら]べてみた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "視点", "label": "基本形（名詞）"}, {"form": "視点の", "label": "連体形"}, {"form": "視点を変える", "label": "よく使う形"}], "register": "中立", "sense_fingerprint": "物事をどの位置・立場から見るかという見る側の位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90fa4bdf-c71d-489f-bb70-e9e1151b79b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37634, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "視点", "is_correct": true, "explanation": "写真を撮る位置や立場を表し、低い位置から撮ったことに合う。"}, {"text": "色", "is_correct": false, "explanation": "写真の色味を表すが、撮る位置は表せない。"}, {"text": "紙", "is_correct": false, "explanation": "写真を印刷する紙を指し、撮る位置には合わない。"}, {"text": "音楽", "is_correct": false, "explanation": "聞くものを指し、写真の撮り方には関係しない。"}], "explanations": {"視点": "写真を撮る位置や立場を表し、低い位置から撮ったことに合う。", "色": "写真の色味を表すが、撮る位置は表せない。", "紙": "写真を印刷する紙を指し、撮る位置には合わない。", "音楽": "聞くものを指し、写真の撮り方には関係しない。"}, "sentence_index": 0, "correct_answer": "視点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試合の終わりに、彼女は一人で視点を三つ稼いだ。", "explanation": "ここは〈得点〉の意味（試合で取る点数）。視点は見る立場を指すので、点数の代わりにはならない。"}, {"text": "二時間話し合って、ようやく視点に達した。", "explanation": "ここは〈結論〉の意味。話し合いの末に達するのは結論で、見る立場の視点は到達点にならない。"}, {"text": "彼は三回目の試験で、ついに視点に合格した。", "explanation": "ここは〈合格〉の意味。合格の対象は答案や基準で、視点は合否の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37634, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "視点", "is_correct": true, "explanation": "別の立場から見るという意味で、空欄に入る。"}, {"text": "包丁", "is_correct": false, "explanation": "台所の道具で、見る立場には使えない。"}, {"text": "祭り", "is_correct": false, "explanation": "地域の行事で、見る立場とは合わない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠くなる感覚で、見る立場を表せない。"}], "explanations": {"視点": "別の立場から見るという意味で、空欄に入る。", "包丁": "台所の道具で、見る立場には使えない。", "祭り": "地域の行事で、見る立場とは合わない。", "眠気": "眠くなる感覚で、見る立場を表せない。"}, "sentence_index": 6, "correct_answer": "視点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "霧で視点が悪く、車を止めた。", "explanation": "ここは〈視界〉の意味（見通せる範囲）。視点は見る立場を指すので、見通しの良し悪しは表せない。"}, {"text": "朝、看護師は患者の視点を測った。", "explanation": "ここは〈体温〉の意味。測るのは体温などの数値で、視点は測る対象にならない。"}, {"text": "駅で、彼は窓口で視点を切った。", "explanation": "ここは〈切符〉の意味。切るのは切符で、視点は切れるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37634, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生の視点を見ると、この問題は難しい。", "corrected_sentence": "先生の視点から見ると、この問題は難しい。", "error_description": "立場を表す「から」が正しい。「視点を見る」は「を」が不自然で、見る立場の表し方を誤っている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37634, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもの視点から立つと、町は広く感じられる。", "corrected_sentence": "子どもの視点に立つと、町は広く感じられる。", "error_description": "「視点に立つ」は「に」で立つ場所・立場を示す。「から」は誤りで、「視点に立つ」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37635, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「経済の視点」を、論じる立場の起点として示すので「から」が入る。"}, {"text": "に", "is_correct": false, "explanation": "「視点に論じている」は論じる先を示す形になり、立場の意味として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」では「視点へ論じている」が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「視点が論じている」では視点が主語になり、論じる主体と文が合わない。"}], "correct_answer": "から", "explanations": {"から": "「経済の視点」を、論じる立場の起点として示すので「から」が入る。", "に": "「視点に論じている」は論じる先を示す形になり、立場の意味として不自然。", "へ": "方向を示す「へ」では「視点へ論じている」が成り立たない。", "が": "「視点が論じている」では視点が主語になり、論じる主体と文が合わない。"}, "error_tags": {"に": "帰着点", "へ": "方向", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37635, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "専門家という立場から説明する意味を表すので「から」が入る。"}, {"text": "と", "is_correct": false, "explanation": "「視点と説明してもらった」では並列にならず、文として続かない。"}, {"text": "の", "is_correct": false, "explanation": "「視点の、」と切れると文が続かず、立場を示す形にもならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の語で、「視点より説明してもらった」では立場を示せない。"}], "correct_answer": "から", "explanations": {"から": "専門家という立場から説明する意味を表すので「から」が入る。", "と": "「視点と説明してもらった」では並列にならず、文として続かない。", "の": "「視点の、」と切れると文が続かず、立場を示す形にもならない。", "より": "「より」は比較の語で、「視点より説明してもらった」では立場を示せない。"}, "error_tags": {"と": "並列", "の": "所属", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37635, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を観察したり考えたりするときの、その人の立場や角度。", "primary_collocate": null, "pronunciation": "してん", "ipa": "ɕite̞ɴ", "syllable_count": 3, "sentences": [{"text": "新しい視点を持つと、考えが広がる。", "target_word": "視点", "complexity_tier": "T3", "furigana": "新[あたら]しい視点[してん]を持[も]つと、考[かんが]えが広[ひろ]がる。", "sentence_source": "generated"}, {"text": "この記事は、環境問題を経済の視点から論じている。", "target_word": "視点", "complexity_tier": "T3", "furigana": "この記事[きじ]は、環境問題[かんきょうもんだい]を経済[けいざい]の視点[してん]から論[ろん]じている。", "sentence_source": "generated"}, {"text": "研究では、さまざまな視点で結果を調べることが大切だ。", "target_word": "視点", "complexity_tier": "T3", "furigana": "研究[けんきゅう]では、さまざまな視点[してん]で結果[けっか]を調[しら]べることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "彼女の視点はするどく、みんなが驚いた。", "target_word": "視点", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の視点[してん]はするどく、みんなが驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "話し合いでは、相手の視点も考えてみよう。", "target_word": "視点", "complexity_tier": "T3", "furigana": "話[はな]し合[あ]いでは、相手[あいて]の視点[してん]も考[かんが]えてみよう。", "sentence_source": "generated"}, {"text": "同じ事件でも、新聞によって視点が違う。", "target_word": "視点", "complexity_tier": "T3", "furigana": "同[おな]じ事件[じけん]でも、新聞[しんぶん]によって視点[してん]が違[ちが]う。", "sentence_source": "generated"}, {"text": "視点を変えて考えたら、いい案が出てきた。", "target_word": "視点", "complexity_tier": "T3", "furigana": "視点[してん]を変[か]えて考[かんが]えたら、いい案[あん]が出[で]てきた。", "sentence_source": "generated"}, {"text": "専門家の視点から、この計画の問題点を説明してもらった。", "target_word": "視点", "complexity_tier": "T3", "furigana": "専門家[せんもんか]の視点[してん]から、この計画[けいかく]の問題点[もんだいてん]を説明[せつめい]してもらった。", "sentence_source": "generated"}, {"text": "会議で、若い人の視点が足りないと言われた。", "target_word": "視点", "complexity_tier": "T3", "furigana": "会議[かいぎ]で、若[わか]い人[ひと]の視点[してん]が足[た]りないと言[い]われた。", "sentence_source": "generated"}, {"text": "この本は、歴史を庶民の視点で描いている。", "target_word": "視点", "complexity_tier": "T3", "furigana": "この本[ほん]は、歴史[れきし]を庶民[しょみん]の視点[してん]で描[えが]いている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "視点", "label": "基本形（名詞）"}, {"form": "視点の", "label": "名詞＋の（連体修飾）"}, {"form": "視点を変える", "label": "よく使う形"}], "register": "中立", "sense_fingerprint": "物事を考え、判断するときの人それぞれの立場や角度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: するどく (Zipf 1.74)']::text[], '90fa4bdf-c71d-489f-bb70-e9e1151b79b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37635, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "視点", "is_correct": true, "explanation": "「見方・立場」の意味で、「新しい視点を持つ」と自然につながる。"}, {"text": "時差", "is_correct": false, "explanation": "時間帯のずれを表す語で、「新しい時差を持つ」とは言わない。"}, {"text": "体重", "is_correct": false, "explanation": "体の重さを表す語で、考えが広がることとは結びつかない。"}, {"text": "年齢", "is_correct": false, "explanation": "人の年数を表す語で、「新しい年齢を持つ」は不自然。"}], "explanations": {"視点": "「見方・立場」の意味で、「新しい視点を持つ」と自然につながる。", "時差": "時間帯のずれを表す語で、「新しい時差を持つ」とは言わない。", "体重": "体の重さを表す語で、考えが広がることとは結びつかない。", "年齢": "人の年数を表す語で、「新しい年齢を持つ」は不自然。"}, "sentence_index": 0, "correct_answer": "視点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父は視点が落ちて、新聞の小さな字が読みにくくなった。", "explanation": "「視点」は見方の立場を表す語で、目の見える度合いには使わない。視力が落ちると言う。"}, {"text": "このバス路線の視点は、駅の北口になっている。", "explanation": "「視点」は見方の立場を表す語で、路線の出発地には使わない。起点と言う。"}, {"text": "この道路は、事故の多い視点として知られている。", "explanation": "「視点」は見方の立場を表す語で、場所の一点には使わない。地点と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37635, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "視点", "is_correct": true, "explanation": "「視点を変える」で、見方や立場を変えるという意味になる。"}, {"text": "声量", "is_correct": false, "explanation": "声の大きさを表す語で、考えを変える文脈に合わない。"}, {"text": "体温", "is_correct": false, "explanation": "体の温度を表す語で、「視点を変えて考える」には使えない。"}, {"text": "寿命", "is_correct": false, "explanation": "存続する期間を表す語で、考える行為の対象にならない。"}], "explanations": {"視点": "「視点を変える」で、見方や立場を変えるという意味になる。", "声量": "声の大きさを表す語で、考えを変える文脈に合わない。", "体温": "体の温度を表す語で、「視点を変えて考える」には使えない。", "寿命": "存続する期間を表す語で、考える行為の対象にならない。"}, "sentence_index": 6, "correct_answer": "視点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "霧が出て、視点が悪いので車を止めた。", "explanation": "「視点」は見方の立場を表す語で、見通せる範囲には使わない。視界と言う。"}, {"text": "放物線の視点は、原点の真上にある。", "explanation": "「視点」は見方の立場を表す語で、曲線の一番高い所には使わない。頂点と言う。"}, {"text": "彼のテストの視点は九十点で、クラスで一番だった。", "explanation": "「視点」は見方の立場を表す語で、得点には使わない。点数と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37635, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この研究は、教育問題を社会学の視点に論じている。", "corrected_sentence": "この研究は、教育問題を社会学の視点から論じている。", "error_description": "「視点から論じる」が正しい。「視点」を論じる立場の起点として示す「から」が必要で、「に」では論じる先を示すことになり不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37635, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は視点を変わって、いい案を思いついた。", "corrected_sentence": "彼は視点を変えて、いい案を思いついた。", "error_description": "「視点を変える」が正しい。「視点」を目的語に取る他動詞「変える」が必要で、「変わる」は自動詞なので「を」と組み合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37636, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「相互に」は「互いに」の意味で、後ろの「訪問する」を修飾する正しい形。"}, {"text": "を", "is_correct": false, "explanation": "「相互を訪問する」は目的語の形が崩れ、互いに行き来する意味にならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表すが、「相互で訪問する」とは言わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」は、「相互から訪問する」では意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「相互に」は「互いに」の意味で、後ろの「訪問する」を修飾する正しい形。", "を": "「相互を訪問する」は目的語の形が崩れ、互いに行き来する意味にならない。", "で": "「で」は手段や場所を表すが、「相互で訪問する」とは言わない。", "から": "起点を表す「から」は、「相互から訪問する」では意味が通らない。"}, "error_tags": {"を": "目的語", "で": "手段", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37636, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「相互に」は「互いに」の意味で、後ろの「学び合う」を修飾する正しい形。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は、学び合う相手を示す形としては合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は比べる対象を示すので、学び合う関係を述べるここでは合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を結ぶ助詞で、動詞「学び合う」の前には置けない。"}], "correct_answer": "に", "explanations": {"に": "「相互に」は「互いに」の意味で、後ろの「学び合う」を修飾する正しい形。", "へ": "方向を表す「へ」は、学び合う相手を示す形としては合わない。", "より": "比較の「より」は比べる対象を示すので、学び合う関係を述べるここでは合わない。", "の": "「の」は名詞を結ぶ助詞で、動詞「学び合う」の前には置けない。"}, "error_tags": {"へ": "方向", "より": "比較", "の": "連体"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37636, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つ以上のものが、おたがいに影響し合うこと。", "primary_collocate": null, "pronunciation": "そうご", "ipa": "soːɡo", "syllable_count": 3, "sentences": [{"text": "夫婦は相互に支え合って、長い年月を過ごした。", "target_word": "相互", "complexity_tier": "T3", "furigana": "夫婦[ふうふ]は相互[そうご]に支[ささ]え合[あ]って、長[なが]い年月[ねんげつ]を過[す]ごした。", "sentence_source": "generated"}, {"text": "両国の学生が相互に訪問する計画が始まった。", "target_word": "相互", "complexity_tier": "T4", "furigana": "両国[りょうこく]の学生[がくせい]が相互[そうご]に訪問[ほうもん]する計画[けいかく]が始[はじ]まった。", "sentence_source": "generated"}, {"text": "クラスでは、相互に意見を言い合う時間がある。", "target_word": "相互", "complexity_tier": "T3", "furigana": "クラスでは、相互[そうご]に意見[いけん]を言[い]い合[あ]う時間[じかん]がある。", "sentence_source": "generated"}, {"text": "相互の誤解を解くために、二人は長く話し合った。", "target_word": "相互", "complexity_tier": "T4", "furigana": "相互[そうご]の誤解[ごかい]を解[と]くために、二人[ふたり]は長[なが]く話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "先生と生徒の相互の気持ちが通じて、教室は明るくなった。", "target_word": "相互", "complexity_tier": "T3", "furigana": "先生[せんせい]と生徒[せいと]の相互[そうご]の気持[きも]ちが通[つう]じて、教室[きょうしつ]は明[あか]るくなった。", "sentence_source": "generated"}, {"text": "この店とあの店は、相互にポイントが使える。", "target_word": "相互", "complexity_tier": "T3", "furigana": "この店[みせ]とあの店[みせ]は、相互[そうご]にポイントが使[つか]える。", "sentence_source": "generated"}, {"text": "動物と植物は相互に関わりながら生きている。", "target_word": "相互", "complexity_tier": "T3", "furigana": "動物[どうぶつ]と植物[しょくぶつ]は相互[そうご]に関[かか]わりながら生[い]きている。", "sentence_source": "generated"}, {"text": "隣の国と相互に学び合うことが大切だ。", "target_word": "相互", "complexity_tier": "T3", "furigana": "隣[となり]の国[くに]と相互[そうご]に学[まな]び合[あ]うことが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "二人は相互に理解を深めて、仲良くなった。", "target_word": "相互", "complexity_tier": "T3", "furigana": "二人[ふたり]は相互[そうご]に理解[りかい]を深[ふか]めて、仲良[なかよ]くなった。", "sentence_source": "generated"}, {"text": "ユーザーが相互にメッセージを送り合えるアプリを作った。", "target_word": "相互", "complexity_tier": "T4", "furigana": "ユーザーが相互[そうご]にメッセージを送[おく]り合[あ]えるアプリを作[つく]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "相互", "label": "基本形"}, {"form": "相互に", "label": "連用形(に)"}, {"form": "相互の", "label": "連体形(の)"}], "register": "formal", "sense_fingerprint": "二つ以上のものがおたがいに働きかけ合うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13b24d15-9ff0-4e3d-8f40-83d3e5a40e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37636, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相互", "is_correct": true, "explanation": "「相互に支え合う」は互いに支え合うという意味で、夫婦の関係を述べる文に合う。"}, {"text": "不意", "is_correct": false, "explanation": "「不意に」は出し抜けにという意味で、長年続けて支え合った様子と合わない。"}, {"text": "無断", "is_correct": false, "explanation": "「無断に」は許可を得ずにという意味で、支え合う関係を表さないため合わない。"}, {"text": "突然", "is_correct": false, "explanation": "「突然に」は急に起きる様子を表し、長い年月を過ごした文脈と合わない。"}], "explanations": {"相互": "「相互に支え合う」は互いに支え合うという意味で、夫婦の関係を述べる文に合う。", "不意": "「不意に」は出し抜けにという意味で、長年続けて支え合った様子と合わない。", "無断": "「無断に」は許可を得ずにという意味で、支え合う関係を表さないため合わない。", "突然": "「突然に」は急に起きる様子を表し、長い年月を過ごした文脈と合わない。"}, "sentence_index": 0, "correct_answer": "相互"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二人は相互に出発した。", "explanation": "ここは〈同時〉（一緒に）の意味。相互は互いに働きかけ合う意味で、同じ時刻に動く様子は表さない。"}, {"text": "彼女は相互に登山した。", "explanation": "ここは〈単独〉（一人で）の意味。相互は互いに働き合う意味で、一人での行動とは逆になる。"}, {"text": "子どもたちは相互に滑り台を使った。", "explanation": "ここは〈順番〉（交代で次々と）の意味。相互は互いに働きかけ合うことで、交代で使う様子は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37636, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相互", "is_correct": true, "explanation": "「相互に関わる」は互いに関わり合うという意味で、生物どうしの関係を述べる文に合う。"}, {"text": "無関係", "is_correct": false, "explanation": "「無関係に」は関係なくという意味で、関わり合う様子と矛盾する。"}, {"text": "夢中", "is_correct": false, "explanation": "「夢中に」は熱中しての意味で、生物どうしの関わりを述べる文には合わない。"}, {"text": "一時", "is_correct": false, "explanation": "「一時に」は一度にという意味で、長く続く関わりを表す文と合わない。"}], "explanations": {"相互": "「相互に関わる」は互いに関わり合うという意味で、生物どうしの関係を述べる文に合う。", "無関係": "「無関係に」は関係なくという意味で、関わり合う様子と矛盾する。", "夢中": "「夢中に」は熱中しての意味で、生物どうしの関わりを述べる文には合わない。", "一時": "「一時に」は一度にという意味で、長く続く関わりを表す文と合わない。"}, "sentence_index": 6, "correct_answer": "相互"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は相互に一人きりで旅に出た。", "explanation": "ここは〈単独〉（一人で）の意味。相互は互いに働きかけ合う意味で、一人きりの行動とは逆になる。"}, {"text": "部長が相互に部下へ指示した。", "explanation": "ここは〈一方的〉（片方だけ）の意味。相互は互いに働きかけ合うことで、片方だけが指示する場合には使えない。"}, {"text": "二人は相互に別の道を歩いた。", "explanation": "ここは〈別々〉（それぞれ別に）の意味。相互は互いに働きかけ合う意味で、それぞれ離れて進む様子とは逆になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37636, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先輩と後輩は相互の教え合って、技術を高め合った。", "corrected_sentence": "先輩と後輩は相互に教え合って、技術を高め合った。", "error_description": "誤: 相互の（助詞「の」）。正: 相互に（助詞「に」）。「教え合う」を副詞的に修飾する形なので「に」が必要で、「の」は後ろの動詞句にかからない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37636, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三人は相互で励まし合い、試合に勝った。", "corrected_sentence": "三人は相互に励まし合い、試合に勝った。", "error_description": "誤: 相互で（助詞「で」）。正: 相互に（助詞「に」）。「相互に励まし合う」の形で、相互は励まし合う様子を表す副詞的な用法なので、手段を示す「で」は付かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
