INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37638, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "作用の相手を示し、「油汚れに作用して」が自然になる。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表すため、「油汚れで作用して」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すため、「油汚れより作用して」は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表すため、「油汚れから作用して」は不自然で、対象を示せない。"}], "correct_answer": "に", "explanations": {"に": "作用の相手を示し、「油汚れに作用して」が自然になる。", "で": "場所や手段を表すため、「油汚れで作用して」は意味が通らない。", "より": "比較を表すため、「油汚れより作用して」は成り立たない。", "から": "起点を表すため、「油汚れから作用して」は不自然で、対象を示せない。"}, "error_tags": {"に": "対象", "で": "場所・手段", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37638, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かが、ほかのものに、はたらきかけること。", "primary_collocate": null, "pronunciation": "さよう", "ipa": "sajoː", "syllable_count": 3, "sentences": [{"text": "この薬は、胃の動きを助ける作用があります。", "target_word": "作用", "complexity_tier": "T3", "furigana": "この薬[くすり]は、胃[い]の動[うご]きを助[たす]ける作用[さよう]があります。", "sentence_source": "generated"}, {"text": "熱が加わると、金属の形が変わる作用が起こります。", "target_word": "作用", "complexity_tier": "T3", "furigana": "熱[ねつ]が加[くわ]わると、金属[きんぞく]の形[かたち]が変[か]わる作用[さよう]が起[お]こります。", "sentence_source": "generated"}, {"text": "塩には、食べ物をくさりにくくする作用があります。", "target_word": "作用", "complexity_tier": "T3", "furigana": "塩[しお]には、食[た]べ物[もの]をくさりにくくする作用[さよう]があります。", "sentence_source": "generated"}, {"text": "月の引力は、海の水に作用して潮の満ち引きを生みます。", "target_word": "作用", "complexity_tier": "T3", "furigana": "月[つき]の引力[いんりょく]は、海[うみ]の水[みず]に作用[さよう]して潮[しお]の満[み]ち引[ひ]きを生[う]みます。", "sentence_source": "generated"}, {"text": "二つの薬を一緒に飲むと、互いに作用し合うことがあります。", "target_word": "作用", "complexity_tier": "T3", "furigana": "二[ふた]つの薬[くすり]を一緒[いっしょ]に飲[の]むと、互[たが]いに作用[さよう]し合[あ]うことがあります。", "sentence_source": "generated"}, {"text": "お茶に含まれる成分には、気持ちを落ち着かせる作用があります。", "target_word": "作用", "complexity_tier": "T3", "furigana": "お茶[ちゃ]に含[ふく]まれる成分[せいぶん]には、気持[きも]ちを落[お]ち着[つ]かせる作用[さよう]があります。", "sentence_source": "generated"}, {"text": "風が長い間岩に作用して、不思議な形をつくりました。", "target_word": "作用", "complexity_tier": "T3", "furigana": "風[かぜ]が長[なが]い間[あいだ]岩[いわ]に作用[さよう]して、不思議[ふしぎ]な形[かたち]をつくりました。", "sentence_source": "generated"}, {"text": "洗剤は油汚れに作用して、水で流しやすくします。", "target_word": "作用", "complexity_tier": "T3", "furigana": "洗剤[せんざい]は油汚[あぶらよご]れに作用[さよう]して、水[みず]で流[なが]しやすくします。", "sentence_source": "generated"}, {"text": "光が葉に作用すると、植物は栄養をつくります。", "target_word": "作用", "complexity_tier": "T3", "furigana": "光[ひかり]が葉[は]に作用[さよう]すると、植物[しょくぶつ]は栄養[えいよう]をつくります。", "sentence_source": "generated"}, {"text": "この薬は強い作用があるので、飲む量を守ってください。", "target_word": "作用", "complexity_tier": "T3", "furigana": "この薬[くすり]は強[つよ]い作用[さよう]があるので、飲[の]む量[りょう]を守[まも]ってください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "作用", "label": "基本形（名詞）"}, {"form": "作用する", "label": "サ変動詞・辞書形"}, {"form": "作用した", "label": "サ変動詞・過去形"}, {"form": "作用して", "label": "サ変動詞・て形"}, {"form": "作用し合う", "label": "複合動詞・辞書形"}], "register": "標準的な丁寧体（です・ます）", "sense_fingerprint": "薬・熱・力などが別のものに働きかけて、変化や効果を生むこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: くさり (Zipf 2.26)']::text[], 'd5ac89fc-2658-479e-8f76-fbc5a3afbfe1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37638, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作用", "is_correct": true, "explanation": "「胃の動きを助ける作用」は薬の効き目を指し、文の意味に合う。"}, {"text": "包装", "is_correct": false, "explanation": "「胃の動きを助ける包装がある」は成り立たず、薬の働きの説明にならない。"}, {"text": "渋滞", "is_correct": false, "explanation": "渋滞は交通の混み具合を指し、薬の働きには合わない。"}, {"text": "運賃", "is_correct": false, "explanation": "運賃は料金のことで、薬の効き目を説明する文脈には合わない。"}], "explanations": {"作用": "「胃の動きを助ける作用」は薬の効き目を指し、文の意味に合う。", "包装": "「胃の動きを助ける包装がある」は成り立たず、薬の働きの説明にならない。", "渋滞": "渋滞は交通の混み具合を指し、薬の働きには合わない。", "運賃": "運賃は料金のことで、薬の効き目を説明する文脈には合わない。"}, "sentence_index": 0, "correct_answer": "作用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工場で部品の作用をしています。", "explanation": "ここは〈作業〉の意味。部品を組み立てる手仕事なので、作用とは言わない。"}, {"text": "新しい資料の作用を始めました。", "explanation": "ここは〈作成〉の意味。資料を新しく作る場面で、作用は物事がほかに働きかける意味になり合わない。"}, {"text": "お茶の席では、作用を守ります。", "explanation": "ここは〈作法〉の意味。礼儀や決まりを指すので、作用は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37638, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作用", "is_correct": true, "explanation": "「岩に作用して形をつくった」は、風が岩に働きかける意味で、文脈に合う。"}, {"text": "撮影", "is_correct": false, "explanation": "「風が岩を撮影して」は成り立たず、形をつくる働きに合わない。"}, {"text": "解説", "is_correct": false, "explanation": "「風が岩に解説して」は意味が通らない。"}, {"text": "注意", "is_correct": false, "explanation": "「風が岩に注意して」は文脈に合わず、形をつくる説明にならない。"}], "explanations": {"作用": "「岩に作用して形をつくった」は、風が岩に働きかける意味で、文脈に合う。", "撮影": "「風が岩を撮影して」は成り立たず、形をつくる働きに合わない。", "解説": "「風が岩に解説して」は意味が通らない。", "注意": "「風が岩に注意して」は文脈に合わず、形をつくる説明にならない。"}, "sentence_index": 6, "correct_answer": "作用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏休みに、木で作用をしました。", "explanation": "ここは〈工作〉の意味。手を使って物を作る場面なので、作用は合わない。"}, {"text": "映画の作用を担当しました。", "explanation": "ここは〈演出〉の意味。映像や俳優の表現を決める仕事なので、作用は合わない。"}, {"text": "将来は作用になりたいです。", "explanation": "ここは〈作家〉の意味。文章を書く人を指すので、作用は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37638, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この薬は、胃の動きを作用して、痛みを和らげます。", "corrected_sentence": "この薬は、胃の動きに作用して、痛みを和らげます。", "error_description": "誤: 動きを／正: 動きに。「作用する」は対象に「に」を使って「〜に作用する」と言うため、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37638, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この薬は胃の粘膜に作用し合って、炎症を抑えます。", "corrected_sentence": "この薬は胃の粘膜に作用して、炎症を抑えます。", "error_description": "誤: 作用し合って／正: 作用して。「作用し合う」は互いに働きかけ合う意味で、薬が一方的に粘膜へ働く場面には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37640, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "存在する物を示す「が」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「物体をある」は文法的に誤り。"}, {"text": "に", "is_correct": false, "explanation": "「丸い物体にある」では存在の主語が示されず誤り。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので「物体へある」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "存在する物を示す「が」が正しい。", "を": "「物体をある」は文法的に誤り。", "に": "「丸い物体にある」では存在の主語が示されず誤り。", "へ": "「へ」は方向を表すので「物体へある」は成り立たない。"}, "error_tags": {"を": "object", "に": "location", "へ": "direction"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37640, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「動いた」の主語を示す「が」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「物体を動いた」は自動詞に「を」が付き誤り。"}, {"text": "か", "is_correct": false, "explanation": "「物体か動いたので」は「か」で並べる相手がなく、文として成り立たない。"}, {"text": "や", "is_correct": false, "explanation": "「や」は名詞を並べる助詞で、「物体や動いた」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「動いた」の主語を示す「が」が正しい。", "を": "「物体を動いた」は自動詞に「を」が付き誤り。", "か": "「物体か動いたので」は「か」で並べる相手がなく、文として成り立たない。", "や": "「や」は名詞を並べる助詞で、「物体や動いた」は成り立たない。"}, "error_tags": {"を": "object", "か": "alternative", "や": "listing"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37640, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "見たり触ったりできる、かたちがあるもの。", "primary_collocate": null, "pronunciation": "ぶったい", "ipa": "buttai", "syllable_count": 4, "sentences": [{"text": "机の上に丸い物体がある。", "target_word": "物体", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]に丸[まる]い物体[ぶったい]がある。", "sentence_source": "generated"}, {"text": "物体に触る。", "target_word": "物体", "complexity_tier": "T1", "furigana": "物体[ぶったい]に触[さわ]る。", "sentence_source": "generated"}, {"text": "この物体は何ですか。", "target_word": "物体", "complexity_tier": "T2", "furigana": "この物体[ぶったい]は何[なん]ですか。", "sentence_source": "generated"}, {"text": "小さな物体が落ちてきた。", "target_word": "物体", "complexity_tier": "T3", "furigana": "小[ちい]さな物体[ぶったい]が落[お]ちてきた。", "sentence_source": "generated"}, {"text": "物体の色は赤でした。", "target_word": "物体", "complexity_tier": "T2", "furigana": "物体[ぶったい]の色[いろ]は赤[あか]でした。", "sentence_source": "generated"}, {"text": "見たことのない物体を見つけた。", "target_word": "物体", "complexity_tier": "T3", "furigana": "見[み]たことのない物体[ぶったい]を見[み]つけた。", "sentence_source": "generated"}, {"text": "物体を箱に入れます。", "target_word": "物体", "complexity_tier": "T2", "furigana": "物体[ぶったい]を箱[はこ]に入[い]れます。", "sentence_source": "generated"}, {"text": "物体が動いたので、びっくりした。", "target_word": "物体", "complexity_tier": "T3", "furigana": "物体[ぶったい]が動[うご]いたので、びっくりした。", "sentence_source": "generated"}, {"text": "暗い中では物体の形が見えにくい。", "target_word": "物体", "complexity_tier": "T3", "furigana": "暗[くら]い中[なか]では物体[ぶったい]の形[かたち]が見[み]えにくい。", "sentence_source": "generated"}, {"text": "物体を持つと、思ったより軽かった。", "target_word": "物体", "complexity_tier": "T4", "furigana": "物体[ぶったい]を持[も]つと、思[おも]ったより軽[かる]かった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "飛行物体", "label": "派生"}, {"form": "未確認物体", "label": "派生"}, {"form": "移動物体", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 見たり触ったりできる形のあるもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a6e59f-ea65-43a2-8a55-7ec9fc7d85ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37640, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "物体", "is_correct": true, "explanation": "机の上にある丸い形のものは「物体」である。"}, {"text": "理由", "is_correct": false, "explanation": "形は合うが、「丸い理由が机の上にある」は意味が合わない。"}, {"text": "約束", "is_correct": false, "explanation": "形は合うが、「約束」は机の上に置けず意味が合わない。"}, {"text": "習慣", "is_correct": false, "explanation": "形は合うが、「習慣」は机の上にあるものではなく意味が合わない。"}], "explanations": {"物体": "机の上にある丸い形のものは「物体」である。", "理由": "形は合うが、「丸い理由が机の上にある」は意味が合わない。", "約束": "形は合うが、「約束」は机の上に置けず意味が合わない。", "習慣": "形は合うが、「習慣」は机の上にあるものではなく意味が合わない。"}, "sentence_index": 0, "correct_answer": "物体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "物体を書くために、新しいペンを買った。", "explanation": "「物体」は文章や作品ではないので、「書く」の対象にならない。"}, {"text": "あの物体は私の母で、先生をしている。", "explanation": "「物体」は人を指さないので、母のことを言えない。"}, {"text": "この物体は午後三時から始まる。", "explanation": "「物体」は行事ではなく、時刻に「始まる」ものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
