INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37641, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "形をもって空間に存在するもの。物理的な実体を持つもの。", "primary_collocate": null, "pronunciation": "ぶったい", "ipa": "buttai", "syllable_count": 4, "sentences": [{"text": "結果として、建築は静的な物体ではなく、見る者によって絶えず意味が更新される開かれた場として再定義されるのです。", "target_word": "物体", "complexity_tier": "T6", "furigana": "結果[けっか]として、建築[けんちく]は静的[せいてき]な物体[ぶったい]ではなく、見[み]る者[もの]によって絶[た]えず意味[いみ]が更新[こうしん]される開[ひら]かれた場[ば]として再定義[さいていぎ]されるのです。", "sentence_source": "mined"}, {"text": "空に不思議な物体が見えた。", "target_word": "物体", "complexity_tier": "T3", "furigana": "空[そら]に不思議[ふしぎ]な物体[ぶったい]が見[み]えた。", "sentence_source": "generated"}, {"text": "物体には重さがある。", "target_word": "物体", "complexity_tier": "T3", "furigana": "物体[ぶったい]には重[おも]さがある。", "sentence_source": "generated"}, {"text": "動いている物体を目で追った。", "target_word": "物体", "complexity_tier": "T3", "furigana": "動[うご]いている物体[ぶったい]を目[め]で追[お]った。", "sentence_source": "generated"}, {"text": "宇宙には多くの物体が浮かんでいる。", "target_word": "物体", "complexity_tier": "T3", "furigana": "宇宙[うちゅう]には多[おお]くの物体[ぶったい]が浮[う]かんでいる。", "sentence_source": "generated"}, {"text": "物体を持ち上げるには力が必要だ。", "target_word": "物体", "complexity_tier": "T3", "furigana": "物体[ぶったい]を持[も]ち上[あ]げるには力[ちから]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "水に落ちた物体は、ゆっくり沈んだ。", "target_word": "物体", "complexity_tier": "T3", "furigana": "水[みず]に落[お]ちた物体[ぶったい]は、ゆっくり沈[しず]んだ。", "sentence_source": "generated"}, {"text": "光は物体に当たって反射する。", "target_word": "物体", "complexity_tier": "T3", "furigana": "光[ひかり]は物体[ぶったい]に当[あ]たって反射[はんしゃ]する。", "sentence_source": "generated"}, {"text": "物体の形や色を調べます。", "target_word": "物体", "complexity_tier": "T2", "furigana": "物体[ぶったい]の形[かたち]や色[いろ]を調[しら]べます。", "sentence_source": "generated"}, {"text": "重い物体を運ぶときは注意が必要だ。", "target_word": "物体", "complexity_tier": "T3", "furigana": "重[おも]い物体[ぶったい]を運[はこ]ぶときは注意[ちゅうい]が必要[ひつよう]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "飛行物体", "label": "派生"}, {"form": "未確認物体", "label": "派生"}, {"form": "移動物体", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 形があり存在する物理的な実体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a6e59f-ea65-43a2-8a55-7ec9fc7d85ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37641, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "物体", "is_correct": true, "explanation": "「静的な物体」で、形ある実体としての建築を否定する文脈に合う。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、建築を「天気」とする意味が合わない。"}, {"text": "約束", "is_correct": false, "explanation": "形は合うが、建築を「約束」とする意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、建築を「季節」とする意味が合わない。"}], "explanations": {"物体": "「静的な物体」で、形ある実体としての建築を否定する文脈に合う。", "天気": "形は合うが、建築を「天気」とする意味が合わない。", "約束": "形は合うが、建築を「約束」とする意味が合わない。", "季節": "形は合うが、建築を「季節」とする意味が合わない。"}, "sentence_index": 0, "correct_answer": "物体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "物体が来週の会議で話す予定だ。", "explanation": "「物体」は人ではないので、会議で話す主体として使うのは誤り。"}, {"text": "彼の優しい物体に、みんなが感動した。", "explanation": "「物体」は人の心や人柄を表さないので、「優しい物体」は誤用。"}, {"text": "兄は物体で、毎朝六時に起きる。", "explanation": "「物体」は物理的な実体で、人の属性や職業の意味はなく、兄を指せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37641, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "物体", "is_correct": true, "explanation": "水に落ちてゆっくり沈むのは「物体」である。"}, {"text": "予定", "is_correct": false, "explanation": "形は合うが、「予定」が水に落ちて沈むという意味が合わない。"}, {"text": "約束", "is_correct": false, "explanation": "形は合うが、「約束」が水に沈むという意味が合わない。"}, {"text": "気分", "is_correct": false, "explanation": "形は合うが、「気分」が水に落ちて沈むという意味が合わない。"}], "explanations": {"物体": "水に落ちてゆっくり沈むのは「物体」である。", "予定": "形は合うが、「予定」が水に落ちて沈むという意味が合わない。", "約束": "形は合うが、「約束」が水に沈むという意味が合わない。", "気分": "形は合うが、「気分」が水に落ちて沈むという意味が合わない。"}, "sentence_index": 6, "correct_answer": "物体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は物体を大きな声で歌った。", "explanation": "「物体」は歌や曲ではないので、「歌う」の対象にならない。"}, {"text": "私の物体は去年、病気で亡くなった。", "explanation": "「物体」は家族や人を指さないので、「亡くなった」と合わない。"}, {"text": "彼女の物体は、とても親切だ。", "explanation": "「物体」は性格を表さないので、「親切だ」と結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37641, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "宇宙には多くの物体が泣いている。", "corrected_sentence": "宇宙には多くの物体が浮かんでいる。", "error_description": "「物体」は感情を持たないので「泣いている」は不適切。「浮かんでいる」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
