INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37642, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "何かが持っている、特別な性質や様子。", "primary_collocate": null, "pronunciation": "とくせい", "ipa": "tokɯseː", "syllable_count": 4, "sentences": [{"text": "この木材は、水に強いという特性があります。", "target_word": "特性", "complexity_tier": "T3", "furigana": "この木材[もくざい]は、水[みず]に強[つよ]いという特性[とくせい]があります。", "sentence_source": "generated"}, {"text": "動物ごとの特性を知ってから、えさを選びます。", "target_word": "特性", "complexity_tier": "T3", "furigana": "動物[どうぶつ]ごとの特性[とくせい]を知[し]ってから、えさを選[えら]びます。", "sentence_source": "generated"}, {"text": "猫は、高い所が好きだという特性を持っています。", "target_word": "特性", "complexity_tier": "T3", "furigana": "猫[ねこ]は、高[たか]い所[ところ]が好[す]きだという特性[とくせい]を持[も]っています。", "sentence_source": "generated"}, {"text": "新しい素材の特性を生かして、軽いかばんを作りました。", "target_word": "特性", "complexity_tier": "T3", "furigana": "新[あたら]しい素材[そざい]の特性[とくせい]を生[い]かして、軽[かる]いかばんを作[つく]りました。", "sentence_source": "generated"}, {"text": "金属には、電気を通す特性があります。", "target_word": "特性", "complexity_tier": "T3", "furigana": "金属[きんぞく]には、電気[でんき]を通[とお]す特性[とくせい]があります。", "sentence_source": "generated"}, {"text": "製品の特性を説明書でよく読んでから、使い始めてください。", "target_word": "特性", "complexity_tier": "T3", "furigana": "製品[せいひん]の特性[とくせい]を説明書[せつめいしょ]でよく読[よ]んでから、使[つか]い始[はじ]めてください。", "sentence_source": "generated"}, {"text": "米は種類によって、味や粘りなどの特性が違います。", "target_word": "特性", "complexity_tier": "T3", "furigana": "米[こめ]は種類[しゅるい]によって、味[あじ]や粘[ねば]りなどの特性[とくせい]が違[ちが]います。", "sentence_source": "generated"}, {"text": "この犬は人によくなつくという特性があるので、家庭で飼いやすいです。", "target_word": "特性", "complexity_tier": "T3", "furigana": "この犬[いぬ]は人[ひと]によくなつくという特性[とくせい]があるので、家庭[かてい]で飼[か]いやすいです。", "sentence_source": "generated"}, {"text": "砂漠の植物は、水をためる特性によって乾燥に耐えます。", "target_word": "特性", "complexity_tier": "T3", "furigana": "砂漠[さばく]の植物[しょくぶつ]は、水[みず]をためる特性[とくせい]によって乾燥[かんそう]に耐[た]えます。", "sentence_source": "generated"}, {"text": "子どもの特性に合わせて、教え方を変えています。", "target_word": "特性", "complexity_tier": "T3", "furigana": "子[こ]どもの特性[とくせい]に合[あ]わせて、教[おし]え方[かた]を変[か]えています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "特性", "label": "基本形（名詞）"}, {"form": "特性の", "label": "連体修飾（名詞＋の）"}, {"form": "特性を", "label": "目的語形（名詞＋を）"}], "register": "標準的な丁寧体（です・ます）", "sense_fingerprint": "物・生き物・材料などがもともと持っている、ほかと違う特別な性質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac89fc-2658-479e-8f76-fbc5a3afbfe1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37642, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "特性", "is_correct": true, "explanation": "「水に強いという特性」は、木材がもともと持つ性質を指し、文の意味に合う。"}, {"text": "予算", "is_correct": false, "explanation": "「水に強いという予算がある」は成り立たず、木材の性質の説明にならない。"}, {"text": "手順", "is_correct": false, "explanation": "「水に強いという手順がある」は意味が通らず、木材の説明に合わない。"}, {"text": "順番", "is_correct": false, "explanation": "「水に強いという順番がある」とは言えず、文脈に合わない。"}], "explanations": {"特性": "「水に強いという特性」は、木材がもともと持つ性質を指し、文の意味に合う。", "予算": "「水に強いという予算がある」は成り立たず、木材の性質の説明にならない。", "手順": "「水に強いという手順がある」は意味が通らず、木材の説明に合わない。", "順番": "「水に強いという順番がある」とは言えず、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "特性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "スーパーで特性をしています。", "explanation": "ここは〈特売〉の意味。安くして売る場面なので、特性は合わない。"}, {"text": "特性に乗って、大阪へ行きました。", "explanation": "ここは〈特急〉の意味。列車の種類を指すので、特性は合わない。"}, {"text": "新しい技術の特性を取りました。", "explanation": "ここは〈特許〉の意味。権利を得る手続きを指すので、特性とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37642, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "特性", "is_correct": true, "explanation": "「米は種類によって、味や粘りなどの特性が違います」は、種類ごとの性質の違いを指し、文脈に合う。"}, {"text": "眠気", "is_correct": false, "explanation": "「味や粘りなどの眠気が違う」は意味が通らず、米の性質の説明にならない。"}, {"text": "遠慮", "is_correct": false, "explanation": "「味や粘りなどの遠慮が違う」は成り立たず、文脈に合わない。"}, {"text": "雨", "is_correct": false, "explanation": "「味や粘りなどの雨が違う」は意味をなさず、米の説明にならない。"}], "explanations": {"特性": "「米は種類によって、味や粘りなどの特性が違います」は、種類ごとの性質の違いを指し、文脈に合う。", "眠気": "「味や粘りなどの眠気が違う」は意味が通らず、米の性質の説明にならない。", "遠慮": "「味や粘りなどの遠慮が違う」は成り立たず、文脈に合わない。", "雨": "「味や粘りなどの雨が違う」は意味をなさず、米の説明にならない。"}, "sentence_index": 6, "correct_answer": "特性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この映画は、特性の場面が多いです。", "explanation": "ここは〈特撮〉の意味。映像の特殊効果を指すので、特性は合わない。"}, {"text": "彼女は特性のピアノで、みんなを驚かせました。", "explanation": "ここは〈特技〉の意味。身につけた技能を指すので、特性は合わない。"}, {"text": "この店の特性ハンバーグを食べました。", "explanation": "ここは〈特製〉の意味。店が特別に作った料理を指すので、特性は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37642, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この布は、水をはじく特性に持っています。", "corrected_sentence": "この布は、水をはじく特性を持っています。", "error_description": "誤: 特性に／正: 特性を。「持つ」は目的語に「を」を取るため、ここでの「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37642, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この魚は、暗い場所を好むという特性を売っています。", "corrected_sentence": "この魚は、暗い場所を好むという特性を持っています。", "error_description": "誤: 売っています／正: 持っています。「特性を持つ」が正しく、「売る」は商品や物に使う動詞なので、特性とは組み合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
