INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37644, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「調べる」の目的語を示す。主翼を調べる、という文に合う。"}, {"text": "が", "is_correct": false, "explanation": "「調べる」の主体は「点検の人」で、主翼は調べられる対象。「が」を付けると主翼が主語になり文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や方向を示すので、調べる対象を表す「を」の代わりにはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、調べる動作の対象には合わない。"}], "correct_answer": "を", "explanations": {"を": "「調べる」の目的語を示す。主翼を調べる、という文に合う。", "が": "「調べる」の主体は「点検の人」で、主翼は調べられる対象。「が」を付けると主翼が主語になり文が成り立たない。", "に": "「に」は相手や方向を示すので、調べる対象を表す「を」の代わりにはならない。", "へ": "「へ」は方向を示すので、調べる動作の対象には合わない。"}, "error_tags": {"が": "主語（主体は点検の人）", "に": "相手・方向", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37644, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "飛行機の、大きな翼のことです。", "primary_collocate": null, "pronunciation": "しゅよく", "ipa": "ɕɯjokɯ", "syllable_count": 3, "sentences": [{"text": "飛行機の主翼が、窓の外に大きく見えます。", "target_word": "主翼", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]の主翼[しゅよく]が、窓[まど]の外[そと]に大[おお]きく見[み]えます。", "sentence_source": "generated"}, {"text": "主翼には、燃料を入れる場所があります。", "target_word": "主翼", "complexity_tier": "T3", "furigana": "主翼[しゅよく]には、燃料[ねんりょう]を入[い]れる場所[ばしょ]があります。", "sentence_source": "generated"}, {"text": "雪の日は、飛行機の主翼についた氷を取り除きます。", "target_word": "主翼", "complexity_tier": "T3", "furigana": "雪[ゆき]の日[ひ]は、飛行機[ひこうき]の主翼[しゅよく]についた氷[こおり]を取[と]り除[のぞ]きます。", "sentence_source": "generated"}, {"text": "この模型飛行機は、主翼が長いので、よく飛びます。", "target_word": "主翼", "complexity_tier": "T3", "furigana": "この模型飛行機[もけいひこうき]は、主翼[しゅよく]が長[なが]いので、よく飛[と]びます。", "sentence_source": "generated"}, {"text": "離陸のとき、主翼が空気を受けて機体が浮き上がります。", "target_word": "主翼", "complexity_tier": "T3", "furigana": "離陸[りりく]のとき、主翼[しゅよく]が空気[くうき]を受[う]けて機体[きたい]が浮[う]き上[あ]がります。", "sentence_source": "generated"}, {"text": "鳥の翼をまねて、主翼の形が考えられました。", "target_word": "主翼", "complexity_tier": "T3", "furigana": "鳥[とり]の翼[つばさ]をまねて、主翼[しゅよく]の形[かたち]が考[かんが]えられました。", "sentence_source": "generated"}, {"text": "主翼の下に、エンジンが二つついています。", "target_word": "主翼", "complexity_tier": "T3", "furigana": "主翼[しゅよく]の下[した]に、エンジンが二[ふた]つついています。", "sentence_source": "generated"}, {"text": "点検の人が、主翼を一つずつ調べています。", "target_word": "主翼", "complexity_tier": "T3", "furigana": "点検[てんけん]の人[ひと]が、主翼[しゅよく]を一[ひと]つずつ調[しら]べています。", "sentence_source": "generated"}, {"text": "大きな旅客機の主翼は、先が少し上に曲がっています。", "target_word": "主翼", "complexity_tier": "T3", "furigana": "大[おお]きな旅客機[りょかくき]の主翼[しゅよく]は、先[さき]が少[すこ]し上[うえ]に曲[ま]がっています。", "sentence_source": "generated"}, {"text": "私は主翼のそばの席で、外の景色を楽しみました。", "target_word": "主翼", "complexity_tier": "T3", "furigana": "私[わたし]は主翼[しゅよく]のそばの席[せき]で、外[そと]の景色[けしき]を楽[たの]しみました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "主翼", "label": "基本形（名詞）"}, {"form": "主翼の", "label": "連体修飾（名詞＋の）"}, {"form": "主翼が", "label": "主語形（名詞＋が）"}], "register": "標準的な丁寧体（です・ます）", "sense_fingerprint": "飛行機の胴体の左右についている、いちばん大きな翼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac89fc-2658-479e-8f76-fbc5a3afbfe1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37644, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主翼", "is_correct": true, "explanation": "飛行機の左右についている大きな翼のこと。窓の外から大きく見える部分なので文に合う。"}, {"text": "客室", "is_correct": false, "explanation": "機内で乗客が過ごす空間のことで、窓の外からは見えない。外の景色の文には合わない。"}, {"text": "座席", "is_correct": false, "explanation": "機内の席のことで、窓の外に大きく見えるものではない。"}, {"text": "操縦桿", "is_correct": false, "explanation": "操縦室にある操作レバーで、機体の外からは見えない。"}], "explanations": {"主翼": "飛行機の左右についている大きな翼のこと。窓の外から大きく見える部分なので文に合う。", "客室": "機内で乗客が過ごす空間のことで、窓の外からは見えない。外の景色の文には合わない。", "座席": "機内の席のことで、窓の外に大きく見えるものではない。", "操縦桿": "操縦室にある操作レバーで、機体の外からは見えない。"}, "sentence_index": 0, "correct_answer": "主翼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "機長は、主翼を踏み込んで機首を右へ向けた。", "explanation": "ここは〈方向舵〉の意味。足で踏んで機首の向きを変えるのは方向舵で、主翼は踏んで操作するものではないので合わない。"}, {"text": "ボートの主翼で水をかくと、船が前へ進む。", "explanation": "ここは〈櫂〉の意味。櫂は水をかいて船を進めるもので、飛行機の主翼は水をかかないので合わない。"}, {"text": "鳥は、主翼をたたんで枝にとまった。", "explanation": "ここは〈羽〉の意味。主翼は飛行機の大きな翼を指すので、鳥の羽には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37644, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主翼", "is_correct": true, "explanation": "飛行機の大きな翼のこと。翼の下にエンジンが付く、という文に合う。"}, {"text": "乗降口", "is_correct": false, "explanation": "機体の出入り口で、エンジンが付く部分ではないので、その下にエンジンがあるという文とはつながらない。"}, {"text": "滑走路", "is_correct": false, "explanation": "地上の離着陸路で、機体の一部ではない。その下にエンジンが付くことはない。"}, {"text": "車輪", "is_correct": false, "explanation": "着陸のための脚についている部品で、その下にエンジンが付くという文脈には合わない。"}], "explanations": {"主翼": "飛行機の大きな翼のこと。翼の下にエンジンが付く、という文に合う。", "乗降口": "機体の出入り口で、エンジンが付く部分ではないので、その下にエンジンがあるという文とはつながらない。", "滑走路": "地上の離着陸路で、機体の一部ではない。その下にエンジンが付くことはない。", "車輪": "着陸のための脚についている部品で、その下にエンジンが付くという文脈には合わない。"}, "sentence_index": 6, "correct_answer": "主翼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私は窓側の主翼で、外の景色を楽しみました。", "explanation": "ここは〈座席〉の意味。主翼は人が座る場所ではないので合わない。"}, {"text": "私は主翼を開けて、外の景色を楽しみました。", "explanation": "ここは〈窓〉の意味。窓は開けて外を見るためのものだが、主翼は開けられないので合わない。"}, {"text": "私は主翼を深くかぶって、日差しを避けた。", "explanation": "ここは〈帽子〉の意味。帽子はかぶるものだが、主翼はかぶれないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37644, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "晴れた日は、飛行機の主翼をきれいに見えます。", "corrected_sentence": "晴れた日は、飛行機の主翼がきれいに見えます。", "error_description": "「見える」は「〜が見える」の形で主語に「が」を取るので、主翼には「が」が正しい。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37644, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨の日は、主翼で上に水がたまりやすい。", "corrected_sentence": "雨の日は、主翼の上に水がたまりやすい。", "error_description": "場所を示すには「の上に」が正しい。「で」は動作の場所を表すので「水がたまる」には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37645, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37645, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「主翼の形」と、主翼を修飾する名詞句を作る。文の内容に合う。"}, {"text": "を", "is_correct": false, "explanation": "「形を変える」の「を」は「形」に付くもの。主翼に「を」を付けると「主翼を形を」となり不自然。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到達点を示すので、主翼を形の場所に置くことになり文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「主翼へ形を変える」は意味がつながらない。"}], "correct_answer": "の", "explanations": {"の": "「主翼の形」と、主翼を修飾する名詞句を作る。文の内容に合う。", "を": "「形を変える」の「を」は「形」に付くもの。主翼に「を」を付けると「主翼を形を」となり不自然。", "に": "「に」は到達点を示すので、主翼を形の場所に置くことになり文が成り立たない。", "へ": "「へ」は方向を示すが、「主翼へ形を変える」は意味がつながらない。"}, "error_tags": {"を": "目的語の重複", "に": "到達点", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37645, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "飛行機の主要な翼で、揚力を発生させて機体を支える重要な部分。", "primary_collocate": null, "pronunciation": "しゅよく", "ipa": "ɕɯjokɯ", "syllable_count": 3, "sentences": [{"text": "主翼は、揚力を生んで機体を空中に支えます。", "target_word": "主翼", "complexity_tier": "T3", "furigana": "主翼[しゅよく]は、揚力[ようりょく]を生[う]んで機体[きたい]を空中[くうちゅう]に支[ささ]えます。", "sentence_source": "generated"}, {"text": "主翼の断面の形が、揚力の大きさを決めます。", "target_word": "主翼", "complexity_tier": "T3", "furigana": "主翼[しゅよく]の断面[だんめん]の形[かたち]が、揚力[ようりょく]の大[おお]きさを決[き]めます。", "sentence_source": "generated"}, {"text": "主翼が傷つくと、飛行機は安全に飛べません。", "target_word": "主翼", "complexity_tier": "T3", "furigana": "主翼[しゅよく]が傷[きず]つくと、飛行機[ひこうき]は安全[あんぜん]に飛[と]べません。", "sentence_source": "generated"}, {"text": "設計者は、機体の重さに合わせて主翼の面積を計算します。", "target_word": "主翼", "complexity_tier": "T3", "furigana": "設計者[せっけいしゃ]は、機体[きたい]の重[おも]さに合[あ]わせて主翼[しゅよく]の面積[めんせき]を計算[けいさん]します。", "sentence_source": "generated"}, {"text": "速く飛ぶ飛行機ほど、主翼を細く薄くすることがあります。", "target_word": "主翼", "complexity_tier": "T3", "furigana": "速[はや]く飛[と]ぶ飛行機[ひこうき]ほど、主翼[しゅよく]を細[ほそ]く薄[うす]くすることがあります。", "sentence_source": "generated"}, {"text": "主翼の根元には、とても大きな力がかかります。", "target_word": "主翼", "complexity_tier": "T3", "furigana": "主翼[しゅよく]の根元[ねもと]には、とても大[おお]きな力[ちから]がかかります。", "sentence_source": "generated"}, {"text": "主翼で作られる揚力が、機体の重さとつり合っています。", "target_word": "主翼", "complexity_tier": "T3", "furigana": "主翼[しゅよく]で作[つく]られる揚力[ようりょく]が、機体[きたい]の重[おも]さとつり合[あ]っています。", "sentence_source": "generated"}, {"text": "主翼の形を変えると、飛行機の性能が変わります。", "target_word": "主翼", "complexity_tier": "T3", "furigana": "主翼[しゅよく]の形[かたち]を変[か]えると、飛行機[ひこうき]の性能[せいのう]が変[か]わります。", "sentence_source": "generated"}, {"text": "風洞の中で、主翼にあたる空気の流れを調べました。", "target_word": "主翼", "complexity_tier": "T3", "furigana": "風洞[ふうどう]の中[なか]で、主翼[しゅよく]にあたる空気[くうき]の流[なが]れを調[しら]べました。", "sentence_source": "generated"}, {"text": "主翼が折れないように、強い材料で作られています。", "target_word": "主翼", "complexity_tier": "T3", "furigana": "主翼[しゅよく]が折[お]れないように、強[つよ]い材料[ざいりょう]で作[つく]られています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "主翼", "label": "基本形（名詞）"}, {"form": "主翼の", "label": "連体修飾（名詞＋の）"}, {"form": "主翼が", "label": "主語形（名詞＋が）"}], "register": "標準的な丁寧体（です・ます）", "sense_fingerprint": "揚力を生んで機体全体を空中で支える、飛行機の主要な構造部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac89fc-2658-479e-8f76-fbc5a3afbfe1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37645, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主翼", "is_correct": true, "explanation": "飛行機の翼のことで、揚力を生んで機体を空中に支える部分。文の内容に合う。"}, {"text": "車輪", "is_correct": false, "explanation": "着陸や地上の移動を担う部品で、揚力は生まない。"}, {"text": "燃料タンク", "is_correct": false, "explanation": "燃料を蓄える場所で、揚力を生んで機体を支える働きはない。"}, {"text": "客室", "is_correct": false, "explanation": "乗客が乗る空間で、揚力を生む役割はない。"}], "explanations": {"主翼": "飛行機の翼のことで、揚力を生んで機体を空中に支える部分。文の内容に合う。", "車輪": "着陸や地上の移動を担う部品で、揚力は生まない。", "燃料タンク": "燃料を蓄える場所で、揚力を生んで機体を支える働きはない。", "客室": "乗客が乗る空間で、揚力を生む役割はない。"}, "sentence_index": 0, "correct_answer": "主翼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "風を受けて、主翼が船を前へ進める。", "explanation": "ここは〈帆〉の働き。帆は風を受けて船を進めるもので、主翼は飛行機の翼なので船には使わない。"}, {"text": "扇風機の主翼が速く回って、涼しい風を送る。", "explanation": "ここは〈羽根〉の意味。扇風機の羽根は回って風を送るが、飛行機の主翼は回らず揚力を生むので合わない。"}, {"text": "雨の日は、主翼をさして歩く。", "explanation": "ここは〈傘〉の使い方。主翼は人が手に持つものではないので、さして歩くことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37645, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主翼", "is_correct": true, "explanation": "飛行機の翼のことで、翼によって揚力が作られるという文に合う。"}, {"text": "滑走路", "is_correct": false, "explanation": "地上の離着陸路で、揚力を作る場所ではない。"}, {"text": "座席", "is_correct": false, "explanation": "機内の席で、揚力を作る部分ではない。"}, {"text": "操縦室", "is_correct": false, "explanation": "パイロットがいる部屋で、揚力を作る部品ではない。"}], "explanations": {"主翼": "飛行機の翼のことで、翼によって揚力が作られるという文に合う。", "滑走路": "地上の離着陸路で、揚力を作る場所ではない。", "座席": "機内の席で、揚力を作る部分ではない。", "操縦室": "パイロットがいる部屋で、揚力を作る部品ではない。"}, "sentence_index": 6, "correct_answer": "主翼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鳥は主翼で枝をつかんでとまる。", "explanation": "ここは〈足〉の働き。枝をつかむのは足の役目で、主翼でつかむことはできないので合わない。"}, {"text": "料理では、主翼で野菜を煮ます。", "explanation": "ここは〈鍋〉の役割。鍋は料理の道具だが、主翼は調理器具ではないので合わない。"}, {"text": "私は主翼をしっかりはいて、山道を歩いた。", "explanation": "ここは〈靴〉の意味。靴ははくものだが、主翼ははくことができないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37645, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "主翼を生む揚力は、機体の重さを支えます。", "corrected_sentence": "主翼が生む揚力は、機体の重さを支えます。", "error_description": "「生む」の主語は「主翼」なので「が」が正しい。「を」だと主翼を生み出すことになり誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37645, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "強い風が主翼を当たると、揚力が大きくなります。", "corrected_sentence": "強い風が主翼に当たると、揚力が大きくなります。", "error_description": "「当たる」は「〜に当たる」の形で場所に「に」を取るので、主翼には「に」が正しい。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
