INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37646, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "物の外側の形。", "primary_collocate": null, "pronunciation": "けいじょう", "ipa": "ke̞ːd͡ʑo̞ː", "syllable_count": 4, "sentences": [{"text": "この石は、ふしぎな形状をしている。", "target_word": "形状", "complexity_tier": "T3", "furigana": "この石[いし]は、ふしぎな形状[けいじょう]をしている。", "sentence_source": "generated"}, {"text": "花びらの形状は、花によってちがう。", "target_word": "形状", "complexity_tier": "T3", "furigana": "花[はな]びらの形状[けいじょう]は、花[はな]によってちがう。", "sentence_source": "generated"}, {"text": "部品の形状が合わなくて、取り付けられなかった。", "target_word": "形状", "complexity_tier": "T3", "furigana": "部品[ぶひん]の形状[けいじょう]が合[あ]わなくて、取[と]り付[つ]けられなかった。", "sentence_source": "generated"}, {"text": "氷の形状は、とけるにつれて変わっていった。", "target_word": "形状", "complexity_tier": "T3", "furigana": "氷[こおり]の形状[けいじょう]は、とけるにつれて変[か]わっていった。", "sentence_source": "generated"}, {"text": "店には、さまざまな形状のコップが並んでいる。", "target_word": "形状", "complexity_tier": "T3", "furigana": "店[みせ]には、さまざまな形状[けいじょう]のコップが並[なら]んでいる。", "sentence_source": "generated"}, {"text": "あの雲の形状は、まるで動物のようだ。", "target_word": "形状", "complexity_tier": "T3", "furigana": "あの雲[くも]の形状[けいじょう]は、まるで動物[どうぶつ]のようだ。", "sentence_source": "generated"}, {"text": "新しい車は、風を受けにくい形状になっている。", "target_word": "形状", "complexity_tier": "T3", "furigana": "新[あたら]しい車[くるま]は、風[かぜ]を受[う]けにくい形状[けいじょう]になっている。", "sentence_source": "generated"}, {"text": "箱の形状を見て、中身を想像してみた。", "target_word": "形状", "complexity_tier": "T3", "furigana": "箱[はこ]の形状[けいじょう]を見[み]て、中身[なかみ]を想像[そうぞう]してみた。", "sentence_source": "generated"}, {"text": "このパンは、細長い形状が特徴だ。", "target_word": "形状", "complexity_tier": "T3", "furigana": "このパンは、細長[ほそなが]い形状[けいじょう]が特徴[とくちょう]だ。", "sentence_source": "generated"}, {"text": "部屋の形状に合わせて、棚を作ってもらった。", "target_word": "形状", "complexity_tier": "T3", "furigana": "部屋[へや]の形状[けいじょう]に合[あ]わせて、棚[たな]を作[つく]ってもらった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "形状", "label": "基本形（名詞）"}, {"form": "形状の", "label": "名詞＋の（連体修飾）"}, {"form": "形状が", "label": "主語の形"}], "register": "やや硬い", "sense_fingerprint": "物の外側から見た形そのもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90fa4bdf-c71d-489f-bb70-e9e1151b79b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37646, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "形状", "is_correct": true, "explanation": "外から見た形を指すので、「ふしぎな形状をしている」と自然に入る。"}, {"text": "体温", "is_correct": false, "explanation": "体の温度を表す語で、石の見た目の形を表せない。"}, {"text": "寿命", "is_correct": false, "explanation": "存続期間を表す語で、石の形の説明にならない。"}, {"text": "時給", "is_correct": false, "explanation": "働いて得る賃金を表す語で、物の形には使えない。"}], "explanations": {"形状": "外から見た形を指すので、「ふしぎな形状をしている」と自然に入る。", "体温": "体の温度を表す語で、石の見た目の形を表せない。", "寿命": "存続期間を表す語で、石の形の説明にならない。", "時給": "働いて得る賃金を表す語で、物の形には使えない。"}, "sentence_index": 0, "correct_answer": "形状"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店の形状は、夜になるとにぎやかになる。", "explanation": "「形状」は物の外側の形を表す語で、店の雰囲気には使わない。雰囲気と言う。"}, {"text": "このレポートの形状は、決まった書式に従っている。", "explanation": "「形状」は物の外側の形を表す語で、書き方の決まりには使わない。形式と言う。"}, {"text": "彼の形状は、背筋が伸びて美しい。", "explanation": "「形状」は物の外側の形を表す語で、人の立ち姿には使わない。姿と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37646, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "形状", "is_correct": true, "explanation": "車の外形を指し、「風を受けにくい形状になっている」と合う。"}, {"text": "声量", "is_correct": false, "explanation": "声の大きさを表す語で、車の形の説明にならない。"}, {"text": "年齢", "is_correct": false, "explanation": "人や物の年数を表す語で、「風を受けにくい年齢になっている」とは言えない。"}, {"text": "投票数", "is_correct": false, "explanation": "票の数を表す語で、車の形には使えない。"}], "explanations": {"形状": "車の外形を指し、「風を受けにくい形状になっている」と合う。", "声量": "声の大きさを表す語で、車の形の説明にならない。", "年齢": "人や物の年数を表す語で、「風を受けにくい年齢になっている」とは言えない。", "投票数": "票の数を表す語で、車の形には使えない。"}, "sentence_index": 6, "correct_answer": "形状"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この花は、形状が鮮やかで、部屋が明るく見える。", "explanation": "「形状」は物の外側の形を表す語で、色の鮮やかさには使わない。色と言う。"}, {"text": "ボールは、形状を重くすると、遠くまで飛ぶ。", "explanation": "「形状」は物の外側の形を表す語で、重さの大きさには使わない。重さと言う。"}, {"text": "この店は、形状が丈夫な木でできていて、百年持つ。", "explanation": "「形状」は物の外側の形を表す語で、素材の性質には使わない。材質と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37646, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この道具は、持ちやすい形状がしている。", "corrected_sentence": "この道具は、持ちやすい形状をしている。", "error_description": "「形状をしている」が正しい。「形状」は「する」の目的語になるので「を」が必要で、「が」では文として成立しない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37646, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "うすい板を曲げて、新しい形状を作られた。", "corrected_sentence": "うすい板を曲げて、新しい形状を作った。", "error_description": "「作った」が正しい。「作る」は他動詞で、目的語の「形状」を取って能動で使う。「作られた」は受け身なので、目的語の「を」と組み合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
