INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37647, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "物体や図形の、外から見た形や様子。", "primary_collocate": null, "pronunciation": "けいじょう", "ipa": "ke̞ːd͡ʑo̞ː", "syllable_count": 4, "sentences": [{"text": "数学の授業で、図形の形状について学んだ。", "target_word": "形状", "complexity_tier": "T3", "furigana": "数学[すうがく]の授業[じゅぎょう]で、図形[ずけい]の形状[けいじょう]について学[まな]んだ。", "sentence_source": "generated"}, {"text": "機械の形状は、使う目的によって決まる。", "target_word": "形状", "complexity_tier": "T3", "furigana": "機械[きかい]の形状[けいじょう]は、使[つか]う目的[もくてき]によって決[き]まる。", "sentence_source": "generated"}, {"text": "顕微鏡で見ると、細かい粒の形状がよくわかる。", "target_word": "形状", "complexity_tier": "T3", "furigana": "顕微鏡[けんびきょう]で見[み]ると、細[こま]かい粒[つぶ]の形状[けいじょう]がよくわかる。", "sentence_source": "generated"}, {"text": "この道具は、手に持ちやすい形状に作られている。", "target_word": "形状", "complexity_tier": "T3", "furigana": "この道具[どうぐ]は、手[て]に持[も]ちやすい形状[けいじょう]に作[つく]られている。", "sentence_source": "generated"}, {"text": "地図で湖の形状を調べた。", "target_word": "形状", "complexity_tier": "T3", "furigana": "地図[ちず]で湖[みずうみ]の形状[けいじょう]を調[しら]べた。", "sentence_source": "generated"}, {"text": "物体の形状が変わっても、重さは同じだ。", "target_word": "形状", "complexity_tier": "T3", "furigana": "物体[ぶったい]の形状[けいじょう]が変[か]わっても、重[おも]さは同[おな]じだ。", "sentence_source": "generated"}, {"text": "工場では、製品の形状を機械で確認している。", "target_word": "形状", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、製品[せいひん]の形状[けいじょう]を機械[きかい]で確認[かくにん]している。", "sentence_source": "generated"}, {"text": "同じ量の水でも、容器の形状によって高さが変わる。", "target_word": "形状", "complexity_tier": "T3", "furigana": "同[おな]じ量[りょう]の水[みず]でも、容器[ようき]の形状[けいじょう]によって高[たか]さが変[か]わる。", "sentence_source": "generated"}, {"text": "彼は粘土で、さまざまな形状を作って遊んでいた。", "target_word": "形状", "complexity_tier": "T3", "furigana": "彼[かれ]は粘土[ねんど]で、さまざまな形状[けいじょう]を作[つく]って遊[あそ]んでいた。", "sentence_source": "generated"}, {"text": "図形の形状を言葉で説明するのは難しい。", "target_word": "形状", "complexity_tier": "T3", "furigana": "図形[ずけい]の形状[けいじょう]を言葉[ことば]で説明[せつめい]するのは難[むずか]しい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "形状", "label": "基本形（名詞）"}, {"form": "形状の", "label": "名詞＋の（連体修飾）"}, {"form": "形状が", "label": "主語の形"}], "register": "やや硬い", "sense_fingerprint": "物体や図形を外から見たときの形や様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90fa4bdf-c71d-489f-bb70-e9e1151b79b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37647, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "形状", "is_correct": true, "explanation": "図形の外形を指すので、「図形の形状について学んだ」と合う。"}, {"text": "年齢", "is_correct": false, "explanation": "人や物の齢を表す語で、図形の学習内容にならない。"}, {"text": "時差", "is_correct": false, "explanation": "時間帯のずれを表す語で、図形とは関係がない。"}, {"text": "体重", "is_correct": false, "explanation": "物の重さを表す語で、図形の学習内容とは合わない。"}], "explanations": {"形状": "図形の外形を指すので、「図形の形状について学んだ」と合う。", "年齢": "人や物の齢を表す語で、図形の学習内容にならない。", "時差": "時間帯のずれを表す語で、図形とは関係がない。", "体重": "物の重さを表す語で、図形の学習内容とは合わない。"}, "sentence_index": 0, "correct_answer": "形状"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この道具は、形状の使い方を覚えれば、誰にでも扱える。", "explanation": "「形状」は物の外側の形を表す語で、操作の仕方には使わない。使い方と言う。"}, {"text": "この道具は、形状が安くて、誰でも買える。", "explanation": "「形状」は物の外側の形を表す語で、代金には使わない。値段と言う。"}, {"text": "この道具は、形状が多く、いろいろな作業に使える。", "explanation": "「形状」は物の外側の形を表す語で、できることには使わない。機能と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37647, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "形状", "is_correct": true, "explanation": "製品の外形を指し、機械で確認する対象として自然。"}, {"text": "声量", "is_correct": false, "explanation": "声の大きさを表す語で、製品の検査対象にならない。"}, {"text": "語数", "is_correct": false, "explanation": "文字や言葉の数を表す語で、製品の検査には使わない。"}, {"text": "歌詞", "is_correct": false, "explanation": "歌の言葉を表す語で、製品には当てはまらない。"}], "explanations": {"形状": "製品の外形を指し、機械で確認する対象として自然。", "声量": "声の大きさを表す語で、製品の検査対象にならない。", "語数": "文字や言葉の数を表す語で、製品の検査には使わない。", "歌詞": "歌の言葉を表す語で、製品には当てはまらない。"}, "sentence_index": 6, "correct_answer": "形状"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このスープは、形状が濃くて、家族に人気だ。", "explanation": "「形状」は物の外側の形を表す語で、食べたときの風味には使わない。味と言う。"}, {"text": "この車は、形状が速くて、まだ誰も追いつけない。", "explanation": "「形状」は物の外側の形を表す語で、進む速度には使わない。速さと言う。"}, {"text": "この絵は、形状が鮮やかで、見る人を明るい気持ちにする。", "explanation": "「形状」は物の外側の形を表す語で、色の鮮やかさには使わない。色と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37647, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この模型は、本物の機械と同じ形状が再現している。", "corrected_sentence": "この模型は、本物の機械と同じ形状を再現している。", "error_description": "「形状を再現している」が正しい。「再現する」は他動詞で、目的語の「形状」に「を」が必要。「が」では文として成立しない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37647, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工場の機械が、新しい形状を作られた。", "corrected_sentence": "工場の機械が、新しい形状を作った。", "error_description": "「作った」が正しい。目的語の「形状」を取る他動詞「作る」は能動で使う。「作られた」は受け身なので、目的語の「を」と組み合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
