INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37648, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「海からの気流」と、海を起点とする気流を表す。文に合う。"}, {"text": "が", "is_correct": false, "explanation": "「海から」の後に「が」は続かず、「海から」と「気流」が結びつかない。"}, {"text": "を", "is_correct": false, "explanation": "「海から」の後に「を」は続かず、気流を修飾する関係が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「海からに」は続かず、「気流」と結びつかない。"}], "correct_answer": "の", "explanations": {"の": "「海からの気流」と、海を起点とする気流を表す。文に合う。", "が": "「海から」の後に「が」は続かず、「海から」と「気流」が結びつかない。", "を": "「海から」の後に「を」は続かず、気流を修飾する関係が成り立たない。", "に": "「海からに」は続かず、「気流」と結びつかない。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "位置"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37648, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "空気が動くこと。", "primary_collocate": null, "pronunciation": "きりゅう", "ipa": "kiɾʲɯː", "syllable_count": 2, "sentences": [{"text": "山の谷間では、昼と夜で気流の向きが変わる。", "target_word": "気流", "complexity_tier": "T3", "furigana": "山[やま]の谷間[たにま]では、昼[ひる]と夜[よる]で気流[きりゅう]の向[む]きが変[か]わる。", "sentence_source": "generated"}, {"text": "窓を二つ開けると、部屋の中に気流ができて涼しくなる。", "target_word": "気流", "complexity_tier": "T3", "furigana": "窓[まど]を二[ふた]つ開[あ]けると、部屋[へや]の中[なか]に気流[きりゅう]ができて涼[すず]しくなる。", "sentence_source": "generated"}, {"text": "暖房の気流が顔に当たって、目が乾いてしまった。", "target_word": "気流", "complexity_tier": "T3", "furigana": "暖房[だんぼう]の気流[きりゅう]が顔[かお]に当[あ]たって、目[め]が乾[かわ]いてしまった。", "sentence_source": "generated"}, {"text": "鳥は気流に乗って、羽を動かさずに空高く飛んでいく。", "target_word": "気流", "complexity_tier": "T3", "furigana": "鳥[とり]は気流[きりゅう]に乗[の]って、羽[はね]を動[うご]かさずに空高[そらたか]く飛[と]んでいく。", "sentence_source": "generated"}, {"text": "気流が弱い日は、煙がまっすぐ上に立ちのぼる。", "target_word": "気流", "complexity_tier": "T3", "furigana": "気流[きりゅう]が弱[よわ]い日[ひ]は、煙[けむり]がまっすぐ上[うえ]に立[た]ちのぼる。", "sentence_source": "generated"}, {"text": "この扇風機は、やわらかい気流を部屋全体に送ってくれる。", "target_word": "気流", "complexity_tier": "T3", "furigana": "この扇風機[せんぷうき]は、やわらかい気流[きりゅう]を部屋全体[へやぜんたい]に送[おく]ってくれる。", "sentence_source": "generated"}, {"text": "気流の変化を読んで、グライダーの選手は高く上がった。", "target_word": "気流", "complexity_tier": "T3", "furigana": "気流[きりゅう]の変化[へんか]を読[よ]んで、グライダーの選手[せんしゅ]は高[たか]く上[あ]がった。", "sentence_source": "generated"}, {"text": "天気予報によると、夜は海からの気流で気温が下がるそうだ。", "target_word": "気流", "complexity_tier": "T3", "furigana": "天気予報[てんきよほう]によると、夜[よる]は海[うみ]からの気流[きりゅう]で気温[きおん]が下[さ]がるそうだ。", "sentence_source": "generated"}, {"text": "洞窟の奥から気流を感じたので、出口が近いと分かった。", "target_word": "気流", "complexity_tier": "T3", "furigana": "洞窟[どうくつ]の奥[おく]から気流[きりゅう]を感[かん]じたので、出口[でぐち]が近[ちか]いと分[わ]かった。", "sentence_source": "generated"}, {"text": "エアコンの風が強すぎて、冷たい気流が足元に集まった。", "target_word": "気流", "complexity_tier": "T3", "furigana": "エアコンの風[かぜ]が強[つよ]すぎて、冷[つめ]たい気流[きりゅう]が足元[あしもと]に集[あつ]まった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "気流", "label": "基本形"}], "register": "普通体（だ・である）", "sense_fingerprint": "空気が動くこと。天気や部屋の中などで感じる一般的な空気の動き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T4: contains vocabulary far above tier T4: 立ちのぼる (Zipf 1.21)']::text[], 'd5ac89fc-2658-479e-8f76-fbc5a3afbfe1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37648, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "気流", "is_correct": true, "explanation": "空気が動くこと。昼と夜で空気の流れの向きが変わる、という文に合う。"}, {"text": "湖", "is_correct": false, "explanation": "水をためた地形で、昼と夜で向きが変わるものではない。"}, {"text": "地面", "is_correct": false, "explanation": "土地の表面で、昼と夜で向きが変わると言うのは不自然。"}, {"text": "砂浜", "is_correct": false, "explanation": "海岸の砂の場所で、向きを持つものではない。"}], "explanations": {"気流": "空気が動くこと。昼と夜で空気の流れの向きが変わる、という文に合う。", "湖": "水をためた地形で、昼と夜で向きが変わるものではない。", "地面": "土地の表面で、昼と夜で向きが変わると言うのは不自然。", "砂浜": "海岸の砂の場所で、向きを持つものではない。"}, "sentence_index": 0, "correct_answer": "気流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "部屋の中で気流がこもって、カビが生えた。", "explanation": "ここは〈空気〉の意味。気流は流れている空気のことで、よどんでこもる様子には使わない。"}, {"text": "川の気流が速くなって、岩を削る。", "explanation": "ここは〈水流〉の意味。気流は空気の動きで、川の水の流れには使わない。"}, {"text": "気流が流れて、ランプが点いた。", "explanation": "ここは〈電流〉の意味。気流は空気の動きで、電気の流れには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37648, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "気流", "is_correct": true, "explanation": "空気の動きのこと。その変化を読んで高く上がる、という文に合う。"}, {"text": "座布団", "is_correct": false, "explanation": "床に敷く布製の品で、変化を読む対象にはならない。"}, {"text": "石段", "is_correct": false, "explanation": "建物の段のことで、変化を読むものではない。"}, {"text": "湯飲み", "is_correct": false, "explanation": "お茶を入れる器で、変化を読む対象ではない。"}], "explanations": {"気流": "空気の動きのこと。その変化を読んで高く上がる、という文に合う。", "座布団": "床に敷く布製の品で、変化を読む対象にはならない。", "石段": "建物の段のことで、変化を読むものではない。", "湯飲み": "お茶を入れる器で、変化を読む対象ではない。"}, "sentence_index": 6, "correct_answer": "気流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "気流が廊下に響いた。", "explanation": "ここは〈足音〉の意味。空気の流れは響くものではないので、文として合わない。"}, {"text": "窓から気流が差し込んで、部屋が明るくなった。", "explanation": "ここは〈日差し〉の意味。日差しは差し込んで部屋を明るくするが、空気の流れは部屋を明るくしないので合わない。"}, {"text": "気流が静かに積もった。", "explanation": "ここは〈雪〉の意味。雪は積もるが、空気の流れが積もることはないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37648, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓際では、外の気流を部屋の中へ入ってくる。", "corrected_sentence": "窓際では、外の気流が部屋の中へ入ってくる。", "error_description": "「入ってくる」の主語は「気流」なので「が」が正しい。「を」は目的語を示すので、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37648, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窓を開けたら、気流をカーテンを大きく揺らした。", "corrected_sentence": "窓を開けたら、気流がカーテンを大きく揺らした。", "error_description": "「揺らした」の主語は「気流」なので「が」が正しい。「を」だと目的語が二つになり誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
