INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37649, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "空気の流れ。特に、飛行機の翼の周りなどの空気の動き。", "primary_collocate": null, "pronunciation": "きりゅう", "ipa": "kiɾʲɯː", "syllable_count": 2, "sentences": [{"text": "飛行機の翼の上では、気流が速くなって機体を持ち上げる。", "target_word": "気流", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]の翼[つばさ]の上[うえ]では、気流[きりゅう]が速[はや]くなって機体[きたい]を持[も]ち上[あ]げる。", "sentence_source": "generated"}, {"text": "風洞実験で、車体の周りの気流を目に見えるようにした。", "target_word": "気流", "complexity_tier": "T3", "furigana": "風洞実験[ふうどうじっけん]で、車体[しゃたい]の周[まわ]りの気流[きりゅう]を目[め]に見[み]えるようにした。", "sentence_source": "generated"}, {"text": "翼の形が悪いと、気流が乱れて揚力が落ちてしまう。", "target_word": "気流", "complexity_tier": "T3", "furigana": "翼[つばさ]の形[かたち]が悪[わる]いと、気流[きりゅう]が乱[みだ]れて揚力[ようりょく]が落[お]ちてしまう。", "sentence_source": "generated"}, {"text": "機長は、気流の影響で機体が大きく揺れると放送した。", "target_word": "気流", "complexity_tier": "T3", "furigana": "機長[きちょう]は、気流[きりゅう]の影響[えいきょう]で機体[きたい]が大[おお]きく揺[ゆ]れると放送[ほうそう]した。", "sentence_source": "generated"}, {"text": "新幹線の先頭は、気流の抵抗を減らす形になっている。", "target_word": "気流", "complexity_tier": "T3", "furigana": "新幹線[しんかんせん]の先頭[せんとう]は、気流[きりゅう]の抵抗[ていこう]を減[へ]らす形[かたち]になっている。", "sentence_source": "generated"}, {"text": "パイロットは、着陸の前に気流の変化に注意している。", "target_word": "気流", "complexity_tier": "T3", "furigana": "パイロットは、着陸[ちゃくりく]の前[まえ]に気流[きりゅう]の変化[へんか]に注意[ちゅうい]している。", "sentence_source": "generated"}, {"text": "煙を流すと、翼の後ろにできる気流の渦が見える。", "target_word": "気流", "complexity_tier": "T3", "furigana": "煙[けむり]を流[なが]すと、翼[つばさ]の後[うし]ろにできる気流[きりゅう]の渦[うず]が見[み]える。", "sentence_source": "generated"}, {"text": "ドローンのプロペラが起こす気流で、紙が床に飛んだ。", "target_word": "気流", "complexity_tier": "T3", "furigana": "ドローンのプロペラが起[お]こす気流[きりゅう]で、紙[かみ]が床[ゆか]に飛[と]んだ。", "sentence_source": "generated"}, {"text": "設計者は、エンジンに入る気流をまっすぐにそろえた。", "target_word": "気流", "complexity_tier": "T3", "furigana": "設計者[せっけいしゃ]は、エンジンに入[はい]る気流[きりゅう]をまっすぐにそろえた。", "sentence_source": "generated"}, {"text": "翼から気流がはがれると、飛行機は急に浮く力を失う。", "target_word": "気流", "complexity_tier": "T3", "furigana": "翼[つばさ]から気流[きりゅう]がはがれると、飛行機[ひこうき]は急[きゅう]に浮[う]く力[ちから]を失[うしな]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "気流", "label": "基本形"}], "register": "普通体（だ・である）", "sense_fingerprint": "空気の流れ。飛行機の翼や乗り物の周りなど、空力に関わる空気の動き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac89fc-2658-479e-8f76-fbc5a3afbfe1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37649, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "気流", "is_correct": true, "explanation": "空気の流れのこと。翼の上で速くなり機体を持ち上げる、という文に合う。"}, {"text": "翼", "is_correct": false, "explanation": "機体の左右の翼そのもの。翼が速くなって機体を持ち上げるという文にはならない。"}, {"text": "燃料", "is_correct": false, "explanation": "機体に積む燃料のことで、速くなって機体を持ち上げることはない。"}, {"text": "座席", "is_correct": false, "explanation": "機内の席で、速くなる対象ではない。"}], "explanations": {"気流": "空気の流れのこと。翼の上で速くなり機体を持ち上げる、という文に合う。", "翼": "機体の左右の翼そのもの。翼が速くなって機体を持ち上げるという文にはならない。", "燃料": "機体に積む燃料のことで、速くなって機体を持ち上げることはない。", "座席": "機内の席で、速くなる対象ではない。"}, "sentence_index": 0, "correct_answer": "気流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "山の中では気流が届かず、スマホが圏外になる。", "explanation": "ここは〈電波〉の意味。圏外になるのは電波が届かないからで、空気の流れは関係しないので合わない。"}, {"text": "気流が降り始めて、空が暗くなった。", "explanation": "ここは〈雨〉の意味。雨は降るものだが、空気の流れは降らないので合わない。"}, {"text": "棚から落ちたら、気流が割れた。", "explanation": "ここは〈皿〉の意味。皿は落とすと割れるが、空気の流れは割れないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37649, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "気流", "is_correct": true, "explanation": "空気の流れのこと。翼の後ろにできる空気の流れの渦、という文に合う。"}, {"text": "歯車", "is_correct": false, "explanation": "機械の回る部品で、翼の後ろにできる渦とは関係ない。"}, {"text": "車輪", "is_correct": false, "explanation": "車両の回る部品で、翼の後ろにできる渦の対象ではない。"}, {"text": "滑走路", "is_correct": false, "explanation": "地上の離着陸路で、渦を作るものではない。"}], "explanations": {"気流": "空気の流れのこと。翼の後ろにできる空気の流れの渦、という文に合う。", "歯車": "機械の回る部品で、翼の後ろにできる渦とは関係ない。", "車輪": "車両の回る部品で、翼の後ろにできる渦の対象ではない。", "滑走路": "地上の離着陸路で、渦を作るものではない。"}, "sentence_index": 6, "correct_answer": "気流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "川の気流が速くなって、岸の砂が削られた。", "explanation": "ここは〈水流〉の意味。気流は空気の流れで、川の水には使わない。"}, {"text": "気流に座って、本を読んだ。", "explanation": "ここは〈椅子〉の意味。椅子には座れるが、空気の流れには座れないので合わない。"}, {"text": "機長の気流で、到着時刻が知らされた。", "explanation": "ここは〈放送〉の意味。時刻を知らせるのは放送であり、空気の流れでは知らせられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37649, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "翼の下面を流れる気流を、機体の動きを安定させる。", "corrected_sentence": "翼の下面を流れる気流が、機体の動きを安定させる。", "error_description": "「安定させる」の主語は「気流」なので「が」が正しい。「を」だと目的語になり誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37649, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "翼の表面で気流をはがれると、失速の危険が高まる。", "corrected_sentence": "翼の表面で気流がはがれると、失速の危険が高まる。", "error_description": "「はがれる」は自動詞で、主語は「気流」なので「が」が正しい。「を」は目的語を示すので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37650, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『速度』は『遅くする』の対象なので、格助詞『を』が正しい。"}, {"text": "に", "is_correct": false, "explanation": "『に』は位置や相手を示す。『速度に遅くする』とは続かない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は手段や場所を示す。『速度で遅くする』という形にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示す。『速度へ遅くする』とは言わない。"}], "correct_answer": "を", "explanations": {"を": "『速度』は『遅くする』の対象なので、格助詞『を』が正しい。", "に": "『に』は位置や相手を示す。『速度に遅くする』とは続かない。", "で": "『で』は手段や場所を示す。『速度で遅くする』という形にはならない。", "へ": "『へ』は方向を示す。『速度へ遅くする』とは言わない。"}, "error_tags": {"に": "target", "で": "means", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37650, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『守る』の目的語を示す『を』で、「速度を守る」と続く。"}, {"text": "が", "is_correct": false, "explanation": "『が』は主語を示すが、『守る』の主語は運転者なので「速度が守る」とはならない。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列や相手を示す。「速度と守る」とは続かない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示す。『速度へ守る』とは続かない。"}], "correct_answer": "を", "explanations": {"を": "『守る』の目的語を示す『を』で、「速度を守る」と続く。", "が": "『が』は主語を示すが、『守る』の主語は運転者なので「速度が守る」とはならない。", "と": "『と』は並列や相手を示す。「速度と守る」とは続かない。", "へ": "『へ』は方向を示す。『速度へ守る』とは続かない。"}, "error_tags": {"が": "subject", "と": "comitative", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37650, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物が動く速さのことです。", "primary_collocate": null, "pronunciation": "そくど", "ipa": "sokɯdo", "syllable_count": 3, "sentences": [{"text": "この電車は、駅に近づくと速度を落とす。", "target_word": "速度", "complexity_tier": "T3", "furigana": "この電車[でんしゃ]は、駅[えき]に近[ちか]づくと速度[そくど]を落[お]とす。", "sentence_source": "generated"}, {"text": "雨の日は、車の速度をいつもより遅くしたほうがいい。", "target_word": "速度", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、車[くるま]の速度[そくど]をいつもより遅[おそ]くしたほうがいい。", "sentence_source": "generated"}, {"text": "自転車の速度が速すぎて、ブレーキが間に合わなかった。", "target_word": "速度", "complexity_tier": "T3", "furigana": "自転車[じてんしゃ]の速度[そくど]が速[はや]すぎて、ブレーキが間[ま]に合[あ]わなかった。", "sentence_source": "generated"}, {"text": "ドローンの速度を下げて、ゆっくり着陸させた。", "target_word": "速度", "complexity_tier": "T3", "furigana": "ドローンの速度[そくど]を下[さ]げて、ゆっくり着陸[ちゃくりく]させた。", "sentence_source": "generated"}, {"text": "ジェットコースターは、坂を下るときにいちばん速度が出る。", "target_word": "速度", "complexity_tier": "T3", "furigana": "ジェットコースターは、坂[さか]を下[くだ]るときにいちばん速度[そくど]が出[で]る。", "sentence_source": "generated"}, {"text": "速度を上げるために、選手たちは毎日走る練習をしている。", "target_word": "速度", "complexity_tier": "T3", "furigana": "速度[そくど]を上[あ]げるために、選手[せんしゅ]たちは毎日[まいにち]走[はし]る練習[れんしゅう]をしている。", "sentence_source": "generated"}, {"text": "船の速度は遅いが、景色をゆっくり楽しめる。", "target_word": "速度", "complexity_tier": "T3", "furigana": "船[ふね]の速度[そくど]は遅[おそ]いが、景色[けしき]をゆっくり楽[たの]しめる。", "sentence_source": "generated"}, {"text": "高速道路では、決められた速度を守って運転してください。", "target_word": "速度", "complexity_tier": "T3", "furigana": "高速道路[こうそくどうろ]では、決[き]められた速度[そくど]を守[まも]って運転[うんてん]してください。", "sentence_source": "generated"}, {"text": "風が強くなって、船の進む速度が急に変わった。", "target_word": "速度", "complexity_tier": "T3", "furigana": "風[かぜ]が強[つよ]くなって、船[ふね]の進[すす]む速度[そくど]が急[きゅう]に変[か]わった。", "sentence_source": "generated"}, {"text": "子どもが走る速度は、大人よりずっとゆっくりだった。", "target_word": "速度", "complexity_tier": "T3", "furigana": "子[こ]どもが走[はし]る速度[そくど]は、大人[おとな]よりずっとゆっくりだった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "速度", "label": "基本形"}], "register": "中立", "sense_fingerprint": "物が動く速さ。乗り物や人の動きなど、日常で言う速さ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac89fc-2658-479e-8f76-fbc5a3afbfe1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37650, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "速度", "is_correct": true, "explanation": "電車が動く速さを表し、「速度を落とす」と自然につながる。"}, {"text": "距離", "is_correct": false, "explanation": "離れている長さのことで、動きの速さを落とすとは言わない。"}, {"text": "角度", "is_correct": false, "explanation": "傾きの大きさのことで、「角度を落とす」は電車の話では成り立たない。"}, {"text": "面積", "is_correct": false, "explanation": "広さのことで、電車が駅に近づく場面の動きには使えない。"}], "explanations": {"速度": "電車が動く速さを表し、「速度を落とす」と自然につながる。", "距離": "離れている長さのことで、動きの速さを落とすとは言わない。", "角度": "傾きの大きさのことで、「角度を落とす」は電車の話では成り立たない。", "面積": "広さのことで、電車が駅に近づく場面の動きには使えない。"}, "sentence_index": 0, "correct_answer": "速度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この部屋の速度は十二平方メートルで、一人で使うには広い。", "explanation": "ここは〈面積〉の意味。速度は物が動く速さなので、部屋の広さには使わない。"}, {"text": "この子の速度は、先月より三キロ増えた。", "explanation": "ここは〈体重〉の意味。速度は動く速さなので、重さの増減には使わない。"}, {"text": "この湖の速度は十メートルある。", "explanation": "ここは〈深さ〉の意味。速度は物が動く速さなので、水の深さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37650, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "速度", "is_correct": true, "explanation": "船が進む速さを表し、「船の速度は遅い」と自然に続く。"}, {"text": "重さ", "is_correct": false, "explanation": "重量のことで、進むのが遅いという説明にはならない。"}, {"text": "高さ", "is_correct": false, "explanation": "高低の度合いで、船の進みの遅さの説明には使えない。"}, {"text": "色", "is_correct": false, "explanation": "色合いのことで、「遅い」と結びつかない。"}], "explanations": {"速度": "船が進む速さを表し、「船の速度は遅い」と自然に続く。", "重さ": "重量のことで、進むのが遅いという説明にはならない。", "高さ": "高低の度合いで、船の進みの遅さの説明には使えない。", "色": "色合いのことで、「遅い」と結びつかない。"}, "sentence_index": 6, "correct_answer": "速度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "熱が出て、体温の速度が上がった。", "explanation": "ここは〈温度〉の意味。速度は物が動く速さなので、体の温度を表す語にはならない。"}, {"text": "祖父の速度は、今年で八十歳になった。", "explanation": "ここは〈年齢〉の意味。速度は物の動きの速さなので、人の年には使わない。"}, {"text": "この曲の速度は五分だ。", "explanation": "ここは〈演奏時間〉の意味。速度は物が動く速さなので、曲の長さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37650, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "坂道で自転車の速度に落とした。", "corrected_sentence": "坂道で自転車の速度を落とした。", "error_description": "「速度を落とす」の目的語は『を』。『速度に』は誤りで、『を』に直す必要がある。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37650, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "バスは、坂を上るときは速度を落ちる。", "corrected_sentence": "バスは、坂を上るときは速度が落ちる。", "error_description": "「落ちる」は自動詞で、主語に『が』を取る。『速度を落ちる』は誤りで、『が』に直す必要がある。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37651, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『速度の単位』と名詞をつなぐ連体修飾の『の』で、正しい。"}, {"text": "を", "is_correct": false, "explanation": "『を』は目的語を示す。『速度を単位』と名詞同士をつなぐことはできない。"}, {"text": "に", "is_correct": false, "explanation": "『に』は位置や対象を示す。『速度に単位』とはならない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示す。名詞同士を『へ』でつなぐことはない。"}], "correct_answer": "の", "explanations": {"の": "『速度の単位』と名詞をつなぐ連体修飾の『の』で、正しい。", "を": "『を』は目的語を示す。『速度を単位』と名詞同士をつなぐことはできない。", "に": "『に』は位置や対象を示す。『速度に単位』とはならない。", "へ": "『へ』は方向を示す。名詞同士を『へ』でつなぐことはない。"}, "error_tags": {"を": "object", "に": "target", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37651, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37651, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物体の動きの速さを表す量で、単位時間あたりに進む距離のこと。", "primary_collocate": null, "pronunciation": "そくど", "ipa": "sokɯdo", "syllable_count": 3, "sentences": [{"text": "物理の授業で、速度は距離を時間で割って求めると習った。", "target_word": "速度", "complexity_tier": "T3", "furigana": "物理[ぶつり]の授業[じゅぎょう]で、速度[そくど]は距離[きょり]を時間[じかん]で割[わ]って求[もと]めると習[なら]った。", "sentence_source": "generated"}, {"text": "速度の単位は、メートル毎秒で表すことが多い。", "target_word": "速度", "complexity_tier": "T3", "furigana": "速度[そくど]の単位[たんい]は、メートル毎秒[まいびょう]で表[あらわ]すことが多[おお]い。", "sentence_source": "generated"}, {"text": "物体の速度が秒速十メートルなら、二秒で二十メートル進む。", "target_word": "速度", "complexity_tier": "T3", "furigana": "物体[ぶったい]の速度[そくど]が秒速[びょうそく]十[じゅう]メートルなら、二秒[にびょう]で二十[にじゅう]メートル進[すす]む。", "sentence_source": "generated"}, {"text": "ボールの速度が一定なら、進む距離は時間に比例する。", "target_word": "速度", "complexity_tier": "T3", "furigana": "ボールの速度[そくど]が一定[いってい]なら、進[すす]む距離[きょり]は時間[じかん]に比例[ひれい]する。", "sentence_source": "generated"}, {"text": "実験では、台車の速度をセンサーで記録して、グラフにした。", "target_word": "速度", "complexity_tier": "T3", "furigana": "実験[じっけん]では、台車[だいしゃ]の速度[そくど]をセンサーで記録[きろく]して、グラフにした。", "sentence_source": "generated"}, {"text": "速度が二倍になると、同じ時間に進む距離も二倍になる。", "target_word": "速度", "complexity_tier": "T3", "furigana": "速度[そくど]が二倍[にばい]になると、同[おな]じ時間[じかん]に進[すす]む距離[きょり]も二倍[にばい]になる。", "sentence_source": "generated"}, {"text": "坂道を下る球は、時間がたつほど速度が大きくなる。", "target_word": "速度", "complexity_tier": "T3", "furigana": "坂道[さかみち]を下[くだ]る球[たま]は、時間[じかん]がたつほど速度[そくど]が大[おお]きくなる。", "sentence_source": "generated"}, {"text": "ゴールまでの距離が同じでも、速度が速いほど到着までの時間は短くなる。", "target_word": "速度", "complexity_tier": "T3", "furigana": "ゴールまでの距離[きょり]が同[おな]じでも、速度[そくど]が速[はや]いほど到着[とうちゃく]までの時間[じかん]は短[みじか]くなる。", "sentence_source": "generated"}, {"text": "地球が太陽の周りを回る速度は、秒速約三十キロメートルだ。", "target_word": "速度", "complexity_tier": "T3", "furigana": "地球[ちきゅう]が太陽[たいよう]の周[まわ]りを回[まわ]る速度[そくど]は、秒速約[びょうそくやく]三十[さんじゅう]キロメートルだ。", "sentence_source": "generated"}, {"text": "加速とは、速度が時間とともに変化することだ。", "target_word": "速度", "complexity_tier": "T3", "furigana": "加速[かそく]とは、速度[そくど]が時間[じかん]とともに変化[へんか]することだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "速度", "label": "基本形"}], "register": "中立", "sense_fingerprint": "物理量としての速度。単位時間あたりに進む距離", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac89fc-2658-479e-8f76-fbc5a3afbfe1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37651, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "速度", "is_correct": true, "explanation": "物理で、距離を時間で割って求める量として正しく続く。"}, {"text": "密度", "is_correct": false, "explanation": "単位体積あたりの質量の量で、距離を時間で割って求めるものではない。"}, {"text": "質量", "is_correct": false, "explanation": "物体に含まれる物質の量で、この求め方には合わない。"}, {"text": "電圧", "is_correct": false, "explanation": "電気の押し出す力のことで、距離と時間からは求めない。"}], "explanations": {"速度": "物理で、距離を時間で割って求める量として正しく続く。", "密度": "単位体積あたりの質量の量で、距離を時間で割って求めるものではない。", "質量": "物体に含まれる物質の量で、この求め方には合わない。", "電圧": "電気の押し出す力のことで、距離と時間からは求めない。"}, "sentence_index": 0, "correct_answer": "速度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今日の速度は朝から三十度を超えた。", "explanation": "ここは〈気温〉の意味。速度は物理量の動く速さなので、温度には使わない。"}, {"text": "健康診断で、私の速度が高いと言われた。", "explanation": "ここは〈血圧〉の意味。速度は運動の速さを表すので、血の圧力には使わない。"}, {"text": "私の速度は、先月より三キロ増えた。", "explanation": "ここは〈体重〉の意味。速度は動く速さを表す量なので、重さの増減には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37651, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "速度", "is_correct": true, "explanation": "坂道で時間とともに大きくなる量として、正しく続く。"}, {"text": "色", "is_correct": false, "explanation": "色合いのことで、速さの変化を表す文脈には合わない。"}, {"text": "味", "is_correct": false, "explanation": "食べ物の味覚のことで、物理の変化には使わない。"}, {"text": "手触り", "is_correct": false, "explanation": "触ったときの感じのことで、坂を下る球の変化には合わない。"}], "explanations": {"速度": "坂道で時間とともに大きくなる量として、正しく続く。", "色": "色合いのことで、速さの変化を表す文脈には合わない。", "味": "食べ物の味覚のことで、物理の変化には使わない。", "手触り": "触ったときの感じのことで、坂を下る球の変化には合わない。"}, "sentence_index": 6, "correct_answer": "速度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の速度は去年より百万円増えた。", "explanation": "ここは〈年収〉の意味。速度は動く速さを表すので、お金の額には使わない。"}, {"text": "この子の速度は、一年で五センチ伸びた。", "explanation": "ここは〈身長〉の意味。速度は物の動きの速さなので、背の高さには使わない。"}, {"text": "ゴールまでの速度は、十キロメートルだ。", "explanation": "ここは〈距離〉の意味。速度は単位時間に進む速さで、道のりの長さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37651, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "実験で、台車の速度を秒速二メートルだった。", "corrected_sentence": "実験で、台車の速度は秒速二メートルだった。", "error_description": "ここは主題を示す『は』が正しい。『速度を』は目的語の形になり誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37651, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ボールは、坂を転がると速度を大きくなる。", "corrected_sentence": "ボールは、坂を転がると速度が大きくなる。", "error_description": "「大きくなる」は自動詞で、主語に『が』を取る。『速度を』は誤りで、『が』に直す必要がある。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37655, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『使う』の目的語を示す『を』で、「定理を使う」と続く。"}, {"text": "が", "is_correct": false, "explanation": "『が』は主語を示す。「定理が使って」では意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列や相手を示す。「定理と使う」とは続かない。"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点や材料を示す。「定理から使う」とは言わない。"}], "correct_answer": "を", "explanations": {"を": "『使う』の目的語を示す『を』で、「定理を使う」と続く。", "が": "『が』は主語を示す。「定理が使って」では意味が通らない。", "と": "『と』は並列や相手を示す。「定理と使う」とは続かない。", "から": "『から』は起点や材料を示す。「定理から使う」とは言わない。"}, "error_tags": {"が": "subject", "と": "comitative", "から": "source"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
