INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37655, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "証明された数学や科学の基本的な規則。", "primary_collocate": null, "pronunciation": "ていり", "ipa": "teiɾi", "syllable_count": 3, "sentences": [{"text": "三角形の内角の和が百八十度になるのは、有名な定理だ。", "target_word": "定理", "complexity_tier": "T3", "furigana": "三角形[さんかっけい]の内角[ないかく]の和[わ]が百八十度[ひゃくはちじゅうど]になるのは、有名[ゆうめい]な定理[ていり]だ。", "sentence_source": "generated"}, {"text": "ピタゴラスの定理を使って、直角三角形の斜辺の長さを求めた。", "target_word": "定理", "complexity_tier": "T3", "furigana": "ピタゴラスの定理[ていり]を使[つか]って、直角三角形[ちょっかくさんかっけい]の斜辺[しゃへん]の長[なが]さを求[もと]めた。", "sentence_source": "generated"}, {"text": "数学者は、この定理を証明するのに十年かかった。", "target_word": "定理", "complexity_tier": "T3", "furigana": "数学者[すうがくしゃ]は、この定理[ていり]を証明[しょうめい]するのに十年[じゅうねん]かかった。", "sentence_source": "generated"}, {"text": "定理は、正しいと証明されてはじめてそう呼ばれる。", "target_word": "定理", "complexity_tier": "T3", "furigana": "定理[ていり]は、正[ただ]しいと証明[しょうめい]されてはじめてそう呼[よ]ばれる。", "sentence_source": "generated"}, {"text": "先生は黒板に定理を書いて、一つずつ証明を説明した。", "target_word": "定理", "complexity_tier": "T3", "furigana": "先生[せんせい]は黒板[こくばん]に定理[ていり]を書[か]いて、一[ひと]つずつ証明[しょうめい]を説明[せつめい]した。", "sentence_source": "generated"}, {"text": "試験では、授業で習った定理を使って問題を解く。", "target_word": "定理", "complexity_tier": "T3", "furigana": "試験[しけん]では、授業[じゅぎょう]で習[なら]った定理[ていり]を使[つか]って問題[もんだい]を解[と]く。", "sentence_source": "generated"}, {"text": "この定理は、円の中の角度の関係を表している。", "target_word": "定理", "complexity_tier": "T3", "furigana": "この定理[ていり]は、円[えん]の中[なか]の角度[かくど]の関係[かんけい]を表[あらわ]している。", "sentence_source": "generated"}, {"text": "新しい定理が見つかると、数学の世界が少し広がる。", "target_word": "定理", "complexity_tier": "T3", "furigana": "新[あたら]しい定理[ていり]が見[み]つかると、数学[すうがく]の世界[せかい]が少[すこ]し広[ひろ]がる。", "sentence_source": "generated"}, {"text": "彼は定理の証明に間違いがないか、何度も確かめた。", "target_word": "定理", "complexity_tier": "T3", "furigana": "彼[かれ]は定理[ていり]の証明[しょうめい]に間違[まちが]いがないか、何度[なんど]も確[たし]かめた。", "sentence_source": "generated"}, {"text": "物理学では、エネルギーに関する定理が計算の基礎になる。", "target_word": "定理", "complexity_tier": "T3", "furigana": "物理学[ぶつりがく]では、エネルギーに関[かん]する定理[ていり]が計算[けいさん]の基礎[きそ]になる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "定理", "label": "基本形"}], "register": "中立", "sense_fingerprint": "数学や科学で、証明によって正しいと確かめられた基本的な規則", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac89fc-2658-479e-8f76-fbc5a3afbfe1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37655, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "定理", "is_correct": true, "explanation": "三角形の内角の和の性質を指し、「有名な定理だ」と自然に続く。"}, {"text": "寺院", "is_correct": false, "explanation": "寺の建物のことで、数学の内容を表す文脈には合わない。"}, {"text": "砂漠", "is_correct": false, "explanation": "乾いた地形のことで、図形の性質の説明には使えない。"}, {"text": "温泉", "is_correct": false, "explanation": "湯が湧く場所のことで、数学の話には合わない。"}], "explanations": {"定理": "三角形の内角の和の性質を指し、「有名な定理だ」と自然に続く。", "寺院": "寺の建物のことで、数学の内容を表す文脈には合わない。", "砂漠": "乾いた地形のことで、図形の性質の説明には使えない。", "温泉": "湯が湧く場所のことで、数学の話には合わない。"}, "sentence_index": 0, "correct_answer": "定理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父は毎朝、定理を三杯飲んでいる。", "explanation": "ここは〈飲み物〉の意味。定理は証明された規則を指すので、飲むものには使わない。"}, {"text": "定理は証明されず、正しいとして認められた出発点だ。", "explanation": "ここは〈公理〉の意味。定理は証明されてはじめて定理と呼ばれるので、証明しないという説明は合わない。"}, {"text": "この教室の定理は三十人だ。", "explanation": "ここは〈定員〉の意味。定理は証明された規則を指すので、人数の上限には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37655, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "定理", "is_correct": true, "explanation": "角度の関係を表す数学の規則を指し、「この定理は〜を表している」と自然に続く。"}, {"text": "楽譜", "is_correct": false, "explanation": "音楽の音符を書いたもので、角度の関係は表さない。"}, {"text": "手紙", "is_correct": false, "explanation": "人に伝える文書のことで、図形の関係を表す文脈には合わない。"}, {"text": "名簿", "is_correct": false, "explanation": "人の名前を並べた一覧で、角度の関係は表さない。"}], "explanations": {"定理": "角度の関係を表す数学の規則を指し、「この定理は〜を表している」と自然に続く。", "楽譜": "音楽の音符を書いたもので、角度の関係は表さない。", "手紙": "人に伝える文書のことで、図形の関係を表す文脈には合わない。", "名簿": "人の名前を並べた一覧で、角度の関係は表さない。"}, "sentence_index": 6, "correct_answer": "定理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この定理は、空と同じ青だ。", "explanation": "ここは〈色〉の意味。定理は証明された規則を指すので、色の名前には使わない。"}, {"text": "この定理には、戦国時代の出来事が年ごとにまとめられている。", "explanation": "ここは〈年表〉の意味。定理は数学の規則なので、歴史の出来事は書かない。"}, {"text": "明日の定理は、朝九時から会議だ。", "explanation": "ここは〈予定〉の意味。定理は規則を指すので、会議の時間には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37655, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "数学者は、この定理に証明した。", "corrected_sentence": "数学者は、この定理を証明した。", "error_description": "「証明する」は目的語に『を』を取る。『定理に』は誤りで、『を』に直す必要がある。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37655, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この定理を、三角形の辺の長さの関係を表している。", "corrected_sentence": "この定理は、三角形の辺の長さの関係を表している。", "error_description": "主題を示す『は』が正しい。『定理を』と目的語にしているのが誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68cbdfa4-d8a6-4a1d-b587-d31aa3638751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
