INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37656, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "力の大きさを表す単位。記号はN。", "primary_collocate": null, "pronunciation": "にゅーとん", "ipa": "ɲɯːtoɴ", "syllable_count": 4, "sentences": [{"text": "ボールを押す力の大きさは、ニュートンで表す。", "target_word": "ニュートン", "complexity_tier": "T3", "furigana": "ボールを押[お]す力[ちから]の大[おお]きさは、ニュートンで表[あらわ]す。", "sentence_source": "generated"}, {"text": "理科の授業で、物を動かす力をニュートンという言葉で習った。", "target_word": "ニュートン", "complexity_tier": "T3", "furigana": "理科[りか]の授業[じゅぎょう]で、物[もの]を動[うご]かす力[ちから]をニュートンという言葉[ことば]で習[なら]った。", "sentence_source": "generated"}, {"text": "手で箱を押すとき、その力はニュートンで測れる。", "target_word": "ニュートン", "complexity_tier": "T3", "furigana": "手[て]で箱[はこ]を押[お]すとき、その力[ちから]はニュートンで測[はか]れる。", "sentence_source": "generated"}, {"text": "先生は、ニュートンの考え方を使ってボールの動きを説明した。", "target_word": "ニュートン", "complexity_tier": "T3", "furigana": "先生[せんせい]は、ニュートンの考[かんが]え方[かた]を使[つか]ってボールの動[うご]きを説明[せつめい]した。", "sentence_source": "generated"}, {"text": "ニュートンの考え方では、強く押すほど物は速く動く。", "target_word": "ニュートン", "complexity_tier": "T3", "furigana": "ニュートンの考[かんが]え方[かた]では、強[つよ]く押[お]すほど物[もの]は速[はや]く動[うご]く。", "sentence_source": "generated"}, {"text": "ばねばかりの目盛りは、ニュートンで読む。", "target_word": "ニュートン", "complexity_tier": "T3", "furigana": "ばねばかりの目盛[めも]りは、ニュートンで読[よ]む。", "sentence_source": "generated"}, {"text": "ボールを投げる手の力も、ニュートンで考えることができる。", "target_word": "ニュートン", "complexity_tier": "T3", "furigana": "ボールを投[な]げる手[て]の力[ちから]も、ニュートンで考[かんが]えることができる。", "sentence_source": "generated"}, {"text": "この実験では、ひもを引く力をニュートンで記録する。", "target_word": "ニュートン", "complexity_tier": "T3", "furigana": "この実験[じっけん]では、ひもを引[ひ]く力[ちから]をニュートンで記録[きろく]する。", "sentence_source": "generated"}, {"text": "力が大きいほど、ニュートンの数字も大きくなる。", "target_word": "ニュートン", "complexity_tier": "T3", "furigana": "力[ちから]が大[おお]きいほど、ニュートンの数字[すうじ]も大[おお]きくなる。", "sentence_source": "generated"}, {"text": "ニュートンという言葉は、力の大きさを表すときに使う。", "target_word": "ニュートン", "complexity_tier": "T3", "furigana": "ニュートンという言葉[ことば]は、力[ちから]の大[おお]きさを表[あらわ]すときに使[つか]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ニュートン", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物を動かす力を表す言葉としてのニュートン", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c94323-d2a7-4136-9285-064b10d13ae7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37656, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "箱", "is_correct": false, "explanation": "箱は容器で、「箱で力の大きさを表す」は意味が通らない。"}, {"text": "ニュートン", "is_correct": true, "explanation": "力の単位で、力の大きさを表す文に合う。"}, {"text": "夕方", "is_correct": false, "explanation": "夕方は時間帯で、力の大きさを表す手段にはならない。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は本で、「教科書で力の大きさを表す」とは言わない。"}], "explanations": {"箱": "箱は容器で、「箱で力の大きさを表す」は意味が通らない。", "ニュートン": "力の単位で、力の大きさを表す文に合う。", "夕方": "夕方は時間帯で、力の大きさを表す手段にはならない。", "教科書": "教科書は本で、「教科書で力の大きさを表す」とは言わない。"}, "sentence_index": 0, "correct_answer": "ニュートン"}, "level_6": {"correct_sentence_index": 2, "wrong_sentences": [{"text": "ボールの速度は、ニュートンで表す。", "explanation": "ここは〈速度〉の意味。ニュートンは力の単位で、速度は時速などで表す。"}, {"text": "タイヤの空気の圧力は、ニュートンで表す。", "explanation": "ここは〈圧力〉の意味。ニュートンは力の単位で、圧力はパスカルなどで表す。"}, {"text": "ボールが空中にある時間は、ニュートンで表す。", "explanation": "ここは〈時間〉の意味。ニュートンは力の単位で、時間は秒などで表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37656, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雨", "is_correct": false, "explanation": "雨は天気の現象で、「雨で力を考える」は意味が通らない。"}, {"text": "屋根", "is_correct": false, "explanation": "屋根は建物の一部で、考える手段にはならない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは空の景色で、「夕焼けで考える」とは言わない。"}, {"text": "ニュートン", "is_correct": true, "explanation": "力の単位で、力の大きさを考える手段として文に合う。"}], "explanations": {"雨": "雨は天気の現象で、「雨で力を考える」は意味が通らない。", "屋根": "屋根は建物の一部で、考える手段にはならない。", "夕焼け": "夕焼けは空の景色で、「夕焼けで考える」とは言わない。", "ニュートン": "力の単位で、力の大きさを考える手段として文に合う。"}, "sentence_index": 6, "correct_answer": "ニュートン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この箱の質量は、ニュートンで量った。", "explanation": "ここは〈質量〉の意味。ニュートンは力の単位で、質量はグラムやキログラムで量る。"}, {"text": "学校までの距離は、ニュートンで測る。", "explanation": "ここは〈距離〉の意味。ニュートンは力の単位で、距離はメートルなどで測る。"}, {"text": "部屋の温度は、ニュートンで表示された。", "explanation": "ここは〈温度〉の意味。ニュートンは力の単位で、温度は度で表示する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37656, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この装置は、力をニュートンを表示する。", "corrected_sentence": "この装置は、力をニュートンで表示する。", "error_description": "「表示する」の手段は「で」で示す。「を」は誤りで、「力をニュートンを」と目的語が二つになる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37656, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ボールに加わる力は、ニュートンで数える。", "corrected_sentence": "ボールに加わる力は、ニュートンで測る。", "error_description": "力の大きさは「測る」で量る。「数える」は個数を数える動詞で、力には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37658, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語の「を」。「運動を勧める」の対象を示し、ここに入る。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の「で」。勧める対象を示せないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。勧める対象は方向ではないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "相手・引用の「と」。勧める対象を直接示さないので合わない。"}], "correct_answer": "を", "explanations": {"を": "目的語の「を」。「運動を勧める」の対象を示し、ここに入る。", "で": "手段・場所の「で」。勧める対象を示せないので合わない。", "へ": "方向の「へ」。勧める対象は方向ではないので合わない。", "と": "相手・引用の「と」。勧める対象を直接示さないので合わない。"}, "error_tags": {"で": "means/place particle, not the object of 勧める", "へ": "direction particle, doesn''t fit 勧める", "と": "companion/quotation particle, doesn''t fit 勧める"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37658, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37658, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "体を動かすことです。", "primary_collocate": null, "pronunciation": "うんどう", "ipa": "ɯɴdoː", "syllable_count": 4, "sentences": [{"text": "毎朝少し運動すると、体が軽くなります。", "target_word": "運動", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]少[すこ]し運動[うんどう]すると、体[からだ]が軽[かる]くなります。", "sentence_source": "generated"}, {"text": "医者に運動を勧められて、毎日歩くことにしました。", "target_word": "運動", "complexity_tier": "T3", "furigana": "医者[いしゃ]に運動[うんどう]を勧[すす]められて、毎日[まいにち]歩[ある]くことにしました。", "sentence_source": "generated"}, {"text": "父は運動が好きで、休みの日はいつも外に出ます。", "target_word": "運動", "complexity_tier": "T3", "furigana": "父[ちち]は運動[うんどう]が好[す]きで、休[やす]みの日[ひ]はいつも外[そと]に出[で]ます。", "sentence_source": "generated"}, {"text": "運動したあとは、水をたくさん飲んだほうがいいです。", "target_word": "運動", "complexity_tier": "T3", "furigana": "運動[うんどう]したあとは、水[みず]をたくさん飲[の]んだほうがいいです。", "sentence_source": "generated"}, {"text": "雨の日は運動ができないので、家でストレッチをします。", "target_word": "運動", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は運動[うんどう]ができないので、家[いえ]でストレッチをします。", "sentence_source": "generated"}, {"text": "運動しないと、体が重く感じるようになります。", "target_word": "運動", "complexity_tier": "T3", "furigana": "運動[うんどう]しないと、体[からだ]が重[おも]く感[かん]じるようになります。", "sentence_source": "generated"}, {"text": "私は運動が苦手ですが、散歩だけは続けています。", "target_word": "運動", "complexity_tier": "T3", "furigana": "私[わたし]は運動[うんどう]が苦手[にがて]ですが、散歩[さんぽ]だけは続[つづ]けています。", "sentence_source": "generated"}, {"text": "食事に気をつけて、運動も始めたら、体重が減りました。", "target_word": "運動", "complexity_tier": "T3", "furigana": "食事[しょくじ]に気[き]をつけて、運動[うんどう]も始[はじ]めたら、体重[たいじゅう]が減[へ]りました。", "sentence_source": "generated"}, {"text": "寝る前に軽く運動すると、よく眠れます。", "target_word": "運動", "complexity_tier": "T3", "furigana": "寝[ね]る前[まえ]に軽[かる]く運動[うんどう]すると、よく眠[ねむ]れます。", "sentence_source": "generated"}, {"text": "祖母は健康のために、毎日公園で運動しています。", "target_word": "運動", "complexity_tier": "T3", "furigana": "祖母[そぼ]は健康[けんこう]のために、毎日[まいにち]公園[こうえん]で運動[うんどう]しています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "運動", "label": "辞書形"}, {"form": "運動する", "label": "動詞形"}, {"form": "運動した", "label": "過去形"}, {"form": "運動しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "健康のために体を動かすこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b294bab-d39d-44d2-ae6c-179982acd0dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37658, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "運動", "is_correct": true, "explanation": "健康のために体を動かすという意味で、体が軽くなるという結果と自然につながる。"}, {"text": "計算", "is_correct": false, "explanation": "数を求める行為なので、毎朝の体の軽さという結果とつながらず、文が成り立たない。"}, {"text": "会議", "is_correct": false, "explanation": "人が集まって話し合う場を指し、体が軽くなるという文の意味に合わない。"}, {"text": "通訳", "is_correct": false, "explanation": "言葉を別の言語に置き換える行為で、体の状態を述べる文には合わない。"}], "explanations": {"運動": "健康のために体を動かすという意味で、体が軽くなるという結果と自然につながる。", "計算": "数を求める行為なので、毎朝の体の軽さという結果とつながらず、文が成り立たない。", "会議": "人が集まって話し合う場を指し、体が軽くなるという文の意味に合わない。", "通訳": "言葉を別の言語に置き換える行為で、体の状態を述べる文には合わない。"}, "sentence_index": 0, "correct_answer": "運動"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は会社の運動を辞めて、故郷に戻りました。", "explanation": "ここは〈仕事・勤め〉の意味。勤め先を辞めることは仕事を辞めるで、運動は体を動かすことを指すので合わない。"}, {"text": "彼は毎日、ピアノの運動を続けています。", "explanation": "ここは〈練習〉の意味。ピアノの上達のための反復は練習で、運動は体を動かすことを指すので合わない。"}, {"text": "ギターの運動を聴きに、昨日コンサートへ行きました。", "explanation": "ここは〈演奏〉の意味。音楽を聴く対象は演奏で、運動は体を動かすことなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37658, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "運動", "is_correct": true, "explanation": "体を動かすことを指し、散歩を続けているという対比で「苦手」と述べるのに合う。"}, {"text": "睡眠", "is_correct": false, "explanation": "眠ることを指し、散歩との対比で「苦手ですが」と続けても意味が通らない。"}, {"text": "寄付", "is_correct": false, "explanation": "金品を差し出す行為で、散歩と対比させる文脈に合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩を入れると「散歩が苦手ですが、散歩だけは続けています」となり、同じ語で矛盾する。"}], "explanations": {"運動": "体を動かすことを指し、散歩を続けているという対比で「苦手」と述べるのに合う。", "睡眠": "眠ることを指し、散歩との対比で「苦手ですが」と続けても意味が通らない。", "寄付": "金品を差し出す行為で、散歩と対比させる文脈に合わない。", "散歩": "散歩を入れると「散歩が苦手ですが、散歩だけは続けています」となり、同じ語で矛盾する。"}, "sentence_index": 6, "correct_answer": "運動"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は毎朝、電車で学校へ運動しています。", "explanation": "ここは〈移動〉の意味。場所を移ることは移動で、運動は体を動かすことを指すので合わない。"}, {"text": "祖母は毎日、台所の運動をしています。", "explanation": "ここは〈修理〉の意味。壊れた所を直す行為は修理で、運動は体を動かすことを指すので合わない。"}, {"text": "祖母は毎日、車を運動しています。", "explanation": "ここは〈運転〉の意味。車を操作することは運転で、運動は体を動かすことなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37658, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏の朝は、公園で運動がするのが気持ちいいです。", "corrected_sentence": "夏の朝は、公園で運動をするのが気持ちいいです。", "error_description": "「運動をする」の「を」は目的語を示す。「運動が」にすると「運動がする」となり不自然で、ここは「を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37658, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨の日は運動へ休みます。", "corrected_sentence": "雨の日は運動を休みます。", "error_description": "「休む」の対象は「を」で示す。「へ」は方向を表すので、ここでは「運動を休みます」の「を」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
