INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37659, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語の「を」。「運動を避ける」の対象を示し、ここに入る。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の「で」。避ける対象を示せないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "方向・相手の「に」。避ける対象を直接示さないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "相手・引用の「と」。避ける対象には合わない。"}], "correct_answer": "を", "explanations": {"を": "目的語の「を」。「運動を避ける」の対象を示し、ここに入る。", "で": "手段・場所の「で」。避ける対象を示せないので合わない。", "に": "方向・相手の「に」。避ける対象を直接示さないので合わない。", "と": "相手・引用の「と」。避ける対象には合わない。"}, "error_tags": {"で": "means/location particle, doesn''t fit 避ける", "に": "dative target particle, doesn''t fit 避ける", "と": "companion/quotation particle, doesn''t fit 避ける"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37659, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "体や体の一部を、目的をもって動かすこと。活動や競技のために体を使うこと。", "primary_collocate": null, "pronunciation": "うんどう", "ipa": "ɯɴdoː", "syllable_count": 4, "sentences": [{"text": "試合の前に、体をほぐす運動をしました。", "target_word": "運動", "complexity_tier": "T3", "furigana": "試合[しあい]の前[まえ]に、体[からだ]をほぐす運動[うんどう]をしました。", "sentence_source": "generated"}, {"text": "水泳は全身を使う運動なので、体力がつきます。", "target_word": "運動", "complexity_tier": "T3", "furigana": "水泳[すいえい]は全身[ぜんしん]を使[つか]う運動[うんどう]なので、体力[たいりょく]がつきます。", "sentence_source": "generated"}, {"text": "運動のあとで、足が痛くなりました。", "target_word": "運動", "complexity_tier": "T3", "furigana": "運動[うんどう]のあとで、足[あし]が痛[いた]くなりました。", "sentence_source": "generated"}, {"text": "彼は体力をつけるために、毎日走って運動しています。", "target_word": "運動", "complexity_tier": "T3", "furigana": "彼[かれ]は体力[たいりょく]をつけるために、毎日[まいにち]走[はし]って運動[うんどう]しています。", "sentence_source": "generated"}, {"text": "兄は運動が得意で、どのスポーツも上手です。", "target_word": "運動", "complexity_tier": "T3", "furigana": "兄[あに]は運動[うんどう]が得意[とくい]で、どのスポーツも上手[じょうず]です。", "sentence_source": "generated"}, {"text": "激しい運動をしたので、汗がたくさん出ました。", "target_word": "運動", "complexity_tier": "T3", "furigana": "激[はげ]しい運動[うんどう]をしたので、汗[あせ]がたくさん出[で]ました。", "sentence_source": "generated"}, {"text": "運動の種類によって、使う筋肉が違います。", "target_word": "運動", "complexity_tier": "T3", "furigana": "運動[うんどう]の種類[しゅるい]によって、使[つか]う筋肉[きんにく]が違[ちが]います。", "sentence_source": "generated"}, {"text": "腰が痛いときは、無理な運動を避けてください。", "target_word": "運動", "complexity_tier": "T3", "furigana": "腰[こし]が痛[いた]いときは、無理[むり]な運動[うんどう]を避[さ]けてください。", "sentence_source": "generated"}, {"text": "放課後は、適度な運動が子どもの成長に大切です。", "target_word": "運動", "complexity_tier": "T3", "furigana": "放課後[ほうかご]は、適度[てきど]な運動[うんどう]が子ども[こども]の成長[せいちょう]に大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "運動するときは、動きやすい服を着ましょう。", "target_word": "運動", "complexity_tier": "T3", "furigana": "運動[うんどう]するときは、動[うご]きやすい服[ふく]を着[き]ましょう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "運動", "label": "辞書形"}, {"form": "運動する", "label": "動詞形"}, {"form": "運動した", "label": "過去形"}, {"form": "運動して", "label": "て形"}], "register": "neutral", "sense_fingerprint": "スポーツや活動のために体を使うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b294bab-d39d-44d2-ae6c-179982acd0dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37659, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "運動", "is_correct": true, "explanation": "体をほぐすために体を動かす活動を指し、「体をほぐす〜をしました」に合う。"}, {"text": "計算", "is_correct": false, "explanation": "数を求める行為で、「体をほぐす計算をしました」は文として成り立たない。"}, {"text": "会議", "is_correct": false, "explanation": "話し合いの場を指し、体をほぐすという行為とつながらない。"}, {"text": "通訳", "is_correct": false, "explanation": "言葉を置き換える行為で、体をほぐす行為の目的語にならない。"}], "explanations": {"運動": "体をほぐすために体を動かす活動を指し、「体をほぐす〜をしました」に合う。", "計算": "数を求める行為で、「体をほぐす計算をしました」は文として成り立たない。", "会議": "話し合いの場を指し、体をほぐすという行為とつながらない。", "通訳": "言葉を置き換える行為で、体をほぐす行為の目的語にならない。"}, "sentence_index": 0, "correct_answer": "運動"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "店の運動を辞めて、故郷に戻りました。", "explanation": "ここは〈仕事・勤め〉の意味。店を辞めることは仕事を辞めるで、運動は体を使う活動を指すので合わない。"}, {"text": "彼は毎日、ピアノの運動をしています。", "explanation": "ここは〈練習〉の意味。楽器の上達のための反復は練習で、運動は体を使う活動を指すので合わない。"}, {"text": "彼は毎日、車を運動しています。", "explanation": "ここは〈運転〉の意味。車を操作することは運転で、運動は体を使う活動なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37659, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "運動", "is_correct": true, "explanation": "体を動かす活動を指し、「運動の種類によって使う筋肉が違う」という説明に合う。"}, {"text": "睡眠", "is_correct": false, "explanation": "眠ることを指し、「使う筋肉が違う」という説明とつながらない。"}, {"text": "寄付", "is_correct": false, "explanation": "金品を差し出す行為で、筋肉の違いを述べる文の意味に合わない。"}, {"text": "読書", "is_correct": false, "explanation": "本を読む行為で、使う筋肉が違うという説明が成り立たない。"}], "explanations": {"運動": "体を動かす活動を指し、「運動の種類によって使う筋肉が違う」という説明に合う。", "睡眠": "眠ることを指し、「使う筋肉が違う」という説明とつながらない。", "寄付": "金品を差し出す行為で、筋肉の違いを述べる文の意味に合わない。", "読書": "本を読む行為で、使う筋肉が違うという説明が成り立たない。"}, "sentence_index": 6, "correct_answer": "運動"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は毎朝、バスで会社へ運動しています。", "explanation": "ここは〈移動〉の意味。場所を移ることは移動で、運動は体を使う活動を指すので合わない。"}, {"text": "父は週末、古い椅子の運動をしています。", "explanation": "ここは〈修理〉の意味。壊れた物を直す行為は修理で、運動は体を使う活動を指すので合わない。"}, {"text": "ギターの運動を聴きに行きました。", "explanation": "ここは〈演奏〉の意味。音楽を聴く対象は演奏で、運動は体を使う活動なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37659, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家の近くの公園で、毎朝軽い運動がしています。", "corrected_sentence": "家の近くの公園で、毎朝軽い運動をしています。", "error_description": "「運動をしています」の「を」は目的語を示す。「運動が」にすると「運動がする」となり不自然で、ここは「を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37659, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先月から運動を始だので、体が軽くなりました。", "corrected_sentence": "先月から運動を始めたので、体が軽くなりました。", "error_description": "活用が誤っている（「始だ」）。過去形「始めた」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
