INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37660, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "みっつ、という数。", "primary_collocate": null, "pronunciation": "さん", "ipa": "saɴ", "syllable_count": 2, "sentences": [{"text": "一に二をたすと三になります。", "target_word": "三", "complexity_tier": "T3", "furigana": "一[いち]に二[に]をたすと三[さん]になります。", "sentence_source": "generated"}, {"text": "三は一より大きく、五より小さい数です。", "target_word": "三", "complexity_tier": "T3", "furigana": "三[さん]は一[いち]より大[おお]きく、五[ご]より小[ちい]さい数[かず]です。", "sentence_source": "generated"}, {"text": "六を二で割ると、答えは三です。", "target_word": "三", "complexity_tier": "T3", "furigana": "六[ろく]を二[に]で割[わ]ると、答[こた]えは三[さん]です。", "sentence_source": "generated"}, {"text": "一、二、三と声に出して数えました。", "target_word": "三", "complexity_tier": "T3", "furigana": "一[いち]、二[に]、三[さん]と声[こえ]に出[だ]して数[かぞ]えました。", "sentence_source": "generated"}, {"text": "九から六を引くと、残りは三です。", "target_word": "三", "complexity_tier": "T3", "furigana": "九[きゅう]から六[ろく]を引[ひ]くと、残[のこ]りは三[さん]です。", "sentence_source": "generated"}, {"text": "三に三をかけると九になります。", "target_word": "三", "complexity_tier": "T3", "furigana": "三[さん]に三[さん]をかけると九[きゅう]になります。", "sentence_source": "generated"}, {"text": "三は奇数なので、二では割り切れません。", "target_word": "三", "complexity_tier": "T3", "furigana": "三[さん]は奇数[きすう]なので、二[に]では割[わ]り切[き]れません。", "sentence_source": "generated"}, {"text": "「三」という漢字は、線が横に並んでいます。", "target_word": "三", "complexity_tier": "T3", "furigana": "「三[さん]」という漢字[かんじ]は、線[せん]が横[よこ]に並[なら]んでいます。", "sentence_source": "generated"}, {"text": "数字の三を黒板に大きく書きました。", "target_word": "三", "complexity_tier": "T3", "furigana": "数字[すうじ]の三[さん]を黒板[こくばん]に大[おお]きく書[か]きました。", "sentence_source": "generated"}, {"text": "十二を四で割ると、三が答えです。", "target_word": "三", "complexity_tier": "T3", "furigana": "十二[じゅうに]を四[よん]で割[わ]ると、三[さん]が答[こた]えです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "三", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "数字の3、みっつという数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b294bab-d39d-44d2-ae6c-179982acd0dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37660, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "三", "is_correct": true, "explanation": "1＋2は3なので、「三になります」が計算として正しく成り立つ。"}, {"text": "四", "is_correct": false, "explanation": "1＋2は4ではないので、四を入れると計算結果が合わない。"}, {"text": "五", "is_correct": false, "explanation": "1＋2は5ではないので、五を入れると計算結果が合わない。"}, {"text": "十", "is_correct": false, "explanation": "1＋2は10ではないので、十を入れると計算結果が合わない。"}], "explanations": {"三": "1＋2は3なので、「三になります」が計算として正しく成り立つ。", "四": "1＋2は4ではないので、四を入れると計算結果が合わない。", "五": "1＋2は5ではないので、五を入れると計算結果が合わない。", "十": "1＋2は10ではないので、十を入れると計算結果が合わない。"}, "sentence_index": 0, "correct_answer": "三"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父は柔道で、黒帯の三を持っています。", "explanation": "ここは〈三段（段位）〉の意味。段位は「三段」と言い、数の三だけでは段位を表せないので合わない。"}, {"text": "来週の打ち合わせに三します。", "explanation": "ここは〈参〉の意味。「参加する」は同じさんと読む別語で、数字の三は動詞として使えない。"}, {"text": "夜空に三が浮かんでいます。", "explanation": "ここは〈三日月〉の意味。月の形を表す語は三日月で、三だけでは月を指せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37660, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "三", "is_correct": true, "explanation": "3は奇数なので、二で割り切れないという説明に合う。"}, {"text": "六", "is_correct": false, "explanation": "6は偶数で二で割り切れるので、「奇数なので二では割り切れません」とは合わない。"}, {"text": "八", "is_correct": false, "explanation": "8は偶数で二で割り切れるので、奇数という前提と矛盾する。"}, {"text": "十二", "is_correct": false, "explanation": "12は偶数で二で割り切れるので、奇数という前提と矛盾する。"}], "explanations": {"三": "3は奇数なので、二で割り切れないという説明に合う。", "六": "6は偶数で二で割り切れるので、「奇数なので二では割り切れません」とは合わない。", "八": "8は偶数で二で割り切れるので、奇数という前提と矛盾する。", "十二": "12は偶数で二で割り切れるので、奇数という前提と矛盾する。"}, "sentence_index": 6, "correct_answer": "三"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は三走者として、最後まで走りました。", "explanation": "ここは〈第三（三番目）〉の意味。順番は「第三走者」や「三番目」で表し、「三走者」とは言わない。"}, {"text": "黒板に三を描き、頂点を数えました。", "explanation": "ここは〈三角〉の意味。図形の角を表すには三角が必要で、数字の三だけでは図形を表せない。"}, {"text": "来週の大会で、三を目指します。", "explanation": "ここは〈三位〉の意味。三番目の順位は三位で、数字の三は目指す対象として合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37660, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三のりんごを、かごに入れました。", "corrected_sentence": "三つのりんごを、かごに入れました。", "error_description": "個数を言うときは「三つ」が必要。「三の」は個数の「つ」が抜けていて不自然なので、「三つ」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37660, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "答えは三を五の間にあります。", "corrected_sentence": "答えは三と五の間にあります。", "error_description": "「三と五」の「と」は二つを並べる助詞。「三を」にすると「三」が目的語になり、場所を示す文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37661, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "並列の「と」。「三と四をたす」で三と四を並べて足すことを示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。四に付くのが自然で、三の後ろに置くと並列の意味が崩れるので合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の「で」。「三でたす」は足す対象を示さないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」。足す関係を示せないので合わない。"}], "correct_answer": "と", "explanations": {"と": "並列の「と」。「三と四をたす」で三と四を並べて足すことを示す。", "を": "目的語の「を」。四に付くのが自然で、三の後ろに置くと並列の意味が崩れるので合わない。", "で": "手段・場所の「で」。「三でたす」は足す対象を示さないので合わない。", "から": "起点の「から」。足す関係を示せないので合わない。"}, "error_tags": {"を": "object marker, doubles with を on 四 and doesn''t fit 足す here", "で": "means/location particle, doesn''t fit 足す", "から": "starting point particle, doesn''t fit 足す"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37661, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主格の「が」。「三が来る」の主語を示し、ここに入る。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。来るは目的語を取らないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の「で」。来る主体を示せないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。「三へ来る」は主体を示さず、ここでは合わない。"}], "correct_answer": "が", "explanations": {"が": "主格の「が」。「三が来る」の主語を示し、ここに入る。", "を": "目的語の「を」。来るは目的語を取らないので合わない。", "で": "手段・場所の「で」。来る主体を示せないので合わない。", "へ": "方向の「へ」。「三へ来る」は主体を示さず、ここでは合わない。"}, "error_tags": {"を": "object marker, 来る takes no object", "で": "means/location particle, doesn''t fit 来る", "へ": "direction particle, reads as 次へ三が来る with no fit"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37661, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "三つ。数の三。", "primary_collocate": null, "pronunciation": "さん", "ipa": "saɴ", "syllable_count": 2, "sentences": [{"text": "二の次の数は三です。", "target_word": "三", "complexity_tier": "T3", "furigana": "二[に]の次[つぎ]の数[かず]は三[さん]です。", "sentence_source": "generated"}, {"text": "三と四をたすと七になります。", "target_word": "三", "complexity_tier": "T3", "furigana": "三[さん]と四[よん]をたすと七[なな]になります。", "sentence_source": "generated"}, {"text": "先生は「次は三です」と言って、問題の番号を読みました。", "target_word": "三", "complexity_tier": "T3", "furigana": "先生[せんせい]は「次[つぎ]は三[さん]です」と言[い]って、問題[もんだい]の番号[ばんごう]を読[よ]みました。", "sentence_source": "generated"}, {"text": "三から一を引くと、二が残ります。", "target_word": "三", "complexity_tier": "T3", "furigana": "三[さん]から一[いち]を引[ひ]くと、二[に]が残[のこ]ります。", "sentence_source": "generated"}, {"text": "数字の三は、さんと読みます。", "target_word": "三", "complexity_tier": "T3", "furigana": "数字[すうじ]の三[さん]は、さんと読[よ]みます。", "sentence_source": "generated"}, {"text": "電話番号の最後の数字は三です。", "target_word": "三", "complexity_tier": "T3", "furigana": "電話番号[でんわばんごう]の最後[さいご]の数字[すうじ]は三[さん]です。", "sentence_source": "generated"}, {"text": "三を二回たすと六になります。", "target_word": "三", "complexity_tier": "T3", "furigana": "三[さん]を二回[にかい]たすと六[ろく]になります。", "sentence_source": "generated"}, {"text": "一、二の次に三が来ます。", "target_word": "三", "complexity_tier": "T3", "furigana": "一[いち]、二[に]の次[つぎ]に三[さん]が来[き]ます。", "sentence_source": "generated"}, {"text": "カードの数字が一から三まで順に並んでいます。", "target_word": "三", "complexity_tier": "T3", "furigana": "カードの数字[すうじ]が一[いち]から三[さん]まで順[じゅん]に並[なら]んでいます。", "sentence_source": "generated"}, {"text": "十五は三で割り切れます。", "target_word": "三", "complexity_tier": "T3", "furigana": "十五[じゅうご]は三[さん]で割[わ]り切[き]れます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "三", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "数の三、二の次の数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b294bab-d39d-44d2-ae6c-179982acd0dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37661, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "三", "is_correct": true, "explanation": "二の次の数は三なので、「二の次の数は三です」に合う。"}, {"text": "四", "is_correct": false, "explanation": "二の次の数は三なので、四では「二の次の数」という前提と合わない。"}, {"text": "五", "is_correct": false, "explanation": "二の次の数は三なので、五では文の前提と合わない。"}, {"text": "六", "is_correct": false, "explanation": "二の次の数は三なので、六では文の前提と合わない。"}], "explanations": {"三": "二の次の数は三なので、「二の次の数は三です」に合う。", "四": "二の次の数は三なので、四では「二の次の数」という前提と合わない。", "五": "二の次の数は三なので、五では文の前提と合わない。", "六": "二の次の数は三なので、六では文の前提と合わない。"}, "sentence_index": 0, "correct_answer": "三"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜空に三が浮かんでいます。", "explanation": "ここは〈三日月〉の意味。月の形を表す語は三日月で、三だけでは月を指せない。"}, {"text": "来週の打ち合わせに三します。", "explanation": "ここは〈参〉の意味。「参加する」は同じさんと読む別語で、数字の三は動詞として使えない。"}, {"text": "黒板に三を描き、頂点を数えました。", "explanation": "ここは〈三角〉の意味。図形の角を表すには三角が必要で、数字の三だけでは図形を表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37661, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "三", "is_correct": true, "explanation": "3を2回足すと6になるので、「三を二回たすと六になります」が正しく成り立つ。"}, {"text": "一", "is_correct": false, "explanation": "1を2回足すと2になり、6にはならないので計算が合わない。"}, {"text": "二", "is_correct": false, "explanation": "2を2回足すと4になり、6にはならないので計算が合わない。"}, {"text": "七", "is_correct": false, "explanation": "7を2回足すと14になり、6にはならないので計算が合わない。"}], "explanations": {"三": "3を2回足すと6になるので、「三を二回たすと六になります」が正しく成り立つ。", "一": "1を2回足すと2になり、6にはならないので計算が合わない。", "二": "2を2回足すと4になり、6にはならないので計算が合わない。", "七": "7を2回足すと14になり、6にはならないので計算が合わない。"}, "sentence_index": 6, "correct_answer": "三"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は三走者として、最後まで走りました。", "explanation": "ここは〈第三（三番目）〉の意味。順番は「第三走者」や「三番目」で表し、「三走者」とは言わない。"}, {"text": "姉は茶道で、師範の三を名乗っています。", "explanation": "ここは〈段位・資格〉の意味。資格や段位は「三段」などの熟語で表し、数の三だけでは名乗れないので合わない。"}, {"text": "来週の大会で、三を目指します。", "explanation": "ここは〈三位〉の意味。三番目の順位は三位で、数字の三は目指す対象として合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37661, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家から三目の角を右に曲がります。", "corrected_sentence": "家から三つ目の角を右に曲がります。", "error_description": "順番を表すときは「三つ目」が必要。「三目」は誤りで、「三つ目」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37661, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "数字の三が、正しく書きましょう。", "corrected_sentence": "数字の三を、正しく書きましょう。", "error_description": "「書く」の対象を示す「を」が「が」になっている。「三が書く」となり主語として不自然で、ここは「を」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37662, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「習う」の学ぶ内容を示す「を」が入る。"}, {"text": "が", "is_correct": false, "explanation": "「が」では法則が習う主体になってしまい、ここでは文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や場所を示すので、学ぶ内容を表す語には使わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、学ぶ内容を指す語には合わない。"}], "correct_answer": "を", "explanations": {"を": "「習う」の学ぶ内容を示す「を」が入る。", "が": "「が」では法則が習う主体になってしまい、ここでは文が成り立たない。", "に": "「に」は相手や場所を示すので、学ぶ内容を表す語には使わない。", "へ": "「へ」は方向を示すので、学ぶ内容を指す語には合わない。"}, "error_tags": {"が": "主格", "に": "相手・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37662, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「法則が正しい」と法則を主語として示す。"}, {"text": "を", "is_correct": false, "explanation": "「正しい」は形容詞で、「法則を正しい」では法則を目的語にできず文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を示すので、「法則と正しいこと」では主語にならない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は「わかる」の対象を示さないので、「法則に正しいことがわかりました」は不自然。"}], "correct_answer": "が", "explanations": {"が": "「法則が正しい」と法則を主語として示す。", "を": "「正しい」は形容詞で、「法則を正しい」では法則を目的語にできず文が成り立たない。", "と": "「と」は並列や引用を示すので、「法則と正しいこと」では主語にならない。", "に": "「に」は「わかる」の対象を示さないので、「法則に正しいことがわかりました」は不自然。"}, "error_tags": {"を": "目的語", "と": "並列・引用", "に": "相手・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37662, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものごとの決まり。いつも同じようになる、大切な決まり。", "primary_collocate": null, "pronunciation": "ほうそく", "ipa": "hoːsokɯ", "syllable_count": 4, "sentences": [{"text": "自然には、いつも同じように働く法則があります。", "target_word": "法則", "complexity_tier": "T3", "furigana": "自然[しぜん]には、いつも同[おな]じように働[はたら]く法則[ほうそく]があります。", "sentence_source": "generated"}, {"text": "物は上から下に落ちるという法則を習いました。", "target_word": "法則", "complexity_tier": "T3", "furigana": "物[もの]は上[うえ]から下[した]に落[お]ちるという法則[ほうそく]を習[なら]いました。", "sentence_source": "generated"}, {"text": "先生は、この法則を覚えれば問題が解けると言いました。", "target_word": "法則", "complexity_tier": "T3", "furigana": "先生[せんせい]は、この法則[ほうそく]を覚[おぼ]えれば問題[もんだい]が解[と]けると言[い]いました。", "sentence_source": "generated"}, {"text": "季節が変わる法則を調べて、発表しました。", "target_word": "法則", "complexity_tier": "T3", "furigana": "季節[きせつ]が変[か]わる法則[ほうそく]を調[しら]べて、発表[はっぴょう]しました。", "sentence_source": "generated"}, {"text": "世の中には、努力すれば結果が出るという法則があるそうです。", "target_word": "法則", "complexity_tier": "T3", "furigana": "世[よ]の中[なか]には、努力[どりょく]すれば結果[けっか]が出[で]るという法則[ほうそく]があるそうです。", "sentence_source": "generated"}, {"text": "彼は経験から、商売がうまくいく法則を見つけました。", "target_word": "法則", "complexity_tier": "T3", "furigana": "彼[かれ]は経験[けいけん]から、商売[しょうばい]がうまくいく法則[ほうそく]を見[み]つけました。", "sentence_source": "generated"}, {"text": "法則を知っていれば、次に何が起こるか予想できます。", "target_word": "法則", "complexity_tier": "T3", "furigana": "法則[ほうそく]を知[し]っていれば、次[つぎ]に何[なに]が起[お]こるか予想[よそう]できます。", "sentence_source": "generated"}, {"text": "この実験で、ある法則が正しいことがわかりました。", "target_word": "法則", "complexity_tier": "T3", "furigana": "この実験[じっけん]で、ある法則[ほうそく]が正[ただ]しいことがわかりました。", "sentence_source": "generated"}, {"text": "言葉の変化にも法則があり、規則的に変わります。", "target_word": "法則", "complexity_tier": "T3", "furigana": "言葉[ことば]の変化[へんか]にも法則[ほうそく]があり、規則的[きそくてき]に変[か]わります。", "sentence_source": "generated"}, {"text": "数学の法則を使うと、計算が簡単になります。", "target_word": "法則", "complexity_tier": "T3", "furigana": "数学[すうがく]の法則[ほうそく]を使[つか]うと、計算[けいさん]が簡単[かんたん]になります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "法則", "label": "基本形"}], "register": "polite", "sense_fingerprint": "いつも同じようになる大切な決まり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b294bab-d39d-44d2-ae6c-179982acd0dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37662, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "名前", "is_correct": false, "explanation": "「いつも同じように働く名前」は意味が通らない。名前は呼び名で、「働く」とつながらない。"}, {"text": "法則", "is_correct": true, "explanation": "ものごとの決まりを表し、「いつも同じように働く」規則性として文に合う。"}, {"text": "思い出", "is_correct": false, "explanation": "過去の記憶を指すので、「いつも同じように働く」と結びつかない。"}, {"text": "挨拶", "is_correct": false, "explanation": "人と交わす言葉や動作で、「働く」の内容にはならない。"}], "explanations": {"名前": "「いつも同じように働く名前」は意味が通らない。名前は呼び名で、「働く」とつながらない。", "法則": "ものごとの決まりを表し、「いつも同じように働く」規則性として文に合う。", "思い出": "過去の記憶を指すので、「いつも同じように働く」と結びつかない。", "挨拶": "人と交わす言葉や動作で、「働く」の内容にはならない。"}, "sentence_index": 0, "correct_answer": "法則"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社の法則で、業務中のスマホ利用は禁止されている。", "explanation": "ここは〈規則〉（人が決めた取り決め）の意味。法則は自然や理論の中にある決まりを指すので、会社の取り決めには合わない。"}, {"text": "村の法則で、夜は外に出てはいけない。", "explanation": "ここは〈掟〉（共同体で昔から守られる決まり）の意味。法則は理論的な規則性を指すので、村の掟には合わない。"}, {"text": "国会で新しい法則が成立し、来年から施行されることになった。", "explanation": "ここは〈法律〉の意味。法則は法的効力をもつ決まりではないので、国会で成立する法の文脈には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37662, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反省", "is_correct": false, "explanation": "「反省を知っていれば」は不自然で、次に何が起こるかの予想とつながらない。"}, {"text": "方言", "is_correct": false, "explanation": "「方言を知っていれば」では、次の出来事を予想する根拠にならない。"}, {"text": "法則", "is_correct": true, "explanation": "規則性を表す「法則」で、知ることで次の出来事を予想できる根拠になる。"}, {"text": "祈り", "is_correct": false, "explanation": "「祈りを知る」は不自然で、予想の根拠としても成り立たない。"}], "explanations": {"反省": "「反省を知っていれば」は不自然で、次に何が起こるかの予想とつながらない。", "方言": "「方言を知っていれば」では、次の出来事を予想する根拠にならない。", "法則": "規則性を表す「法則」で、知ることで次の出来事を予想できる根拠になる。", "祈り": "「祈りを知る」は不自然で、予想の根拠としても成り立たない。"}, "sentence_index": 6, "correct_answer": "法則"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "パスポート申請の法則を一つずつ確かめてから、窓口へ行った。", "explanation": "ここは〈手順〉（作業を進める順番）の意味。法則は一定の関係や規則性を指すので、申請の進め方の順番には合わない。"}, {"text": "茶道の法則を習って、お茶の入れ方を学んだ。", "explanation": "ここは〈作法〉（決まった振る舞いの仕方）の意味。法則は物事の規則性を指すので、礼儀の型には合わない。"}, {"text": "この村では、昔から春祭りを雨でも行う法則がある。", "explanation": "ここは〈慣例〉（昔からの習わし）の意味。法則は一定の関係や規則性を指すので、行事の習わしには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37662, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この法則が知っておくと、計算ミスが減ります。", "corrected_sentence": "この法則を知っておくと、計算ミスが減ります。", "error_description": "「知る」の対象を示すのは「を」。「が」は誤りで、「この法則を知っておく」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37662, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究者は、この法則を見つかった。", "corrected_sentence": "研究者は、この法則を見つけた。", "error_description": "「見つける」は他動詞で、「法則」を目的語にとる。「見つかる」は自動詞なので「〜を見つかる」とは言えない。正しくは「見つけた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37663, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「発見する」の対象を示す「を」が入る。"}, {"text": "が", "is_correct": false, "explanation": "「法則が発見しました」では法則が発見する主体になり、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は発見の対象を示せないので、「法則に発見しました」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、発見の対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「発見する」の対象を示す「を」が入る。", "が": "「法則が発見しました」では法則が発見する主体になり、文が成り立たない。", "に": "「に」は発見の対象を示せないので、「法則に発見しました」は不自然。", "へ": "「へ」は方向を示すので、発見の対象にはならない。"}, "error_tags": {"が": "主格", "に": "相手・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37663, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「見つける」の対象を示す「を」が入る。"}, {"text": "と", "is_correct": false, "explanation": "「法則と見つけよう」では並列になり、見つける対象にならない。"}, {"text": "の", "is_correct": false, "explanation": "「法則の見つけよう」では名詞が続くだけで、動詞に続かない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「法則より見つけよう」では対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「見つける」の対象を示す「を」が入る。", "と": "「法則と見つけよう」では並列になり、見つける対象にならない。", "の": "「法則の見つけよう」では名詞が続くだけで、動詞に続かない。", "より": "「より」は比較を示すので、「法則より見つけよう」では対象を表せない。"}, "error_tags": {"と": "並列・引用", "の": "連体修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37663, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある事柄が起こるとき、常に当てはまる一定の関係や規則性。", "primary_collocate": null, "pronunciation": "ほうそく", "ipa": "hoːsokɯ", "syllable_count": 4, "sentences": [{"text": "温度が上がると体積が増えるという関係を、法則として発表しました。", "target_word": "法則", "complexity_tier": "T3", "furigana": "温度[おんど]が上[あ]がると体積[たいせき]が増[ふ]えるという関係[かんけい]を、法則[ほうそく]として発表[はっぴょう]しました。", "sentence_source": "generated"}, {"text": "ニュートンは、物が動く法則を発見しました。", "target_word": "法則", "complexity_tier": "T3", "furigana": "ニュートンは、物[もの]が動[うご]く法則[ほうそく]を発見[はっけん]しました。", "sentence_source": "generated"}, {"text": "科学者は、実験の結果から法則を導きました。", "target_word": "法則", "complexity_tier": "T3", "furigana": "科学者[かがくしゃ]は、実験[じっけん]の結果[けっか]から法則[ほうそく]を導[みちび]きました。", "sentence_source": "generated"}, {"text": "万有引力の法則は、物が引き合う力を説明します。", "target_word": "法則", "complexity_tier": "T3", "furigana": "万有引力[ばんゆういんりょく]の法則[ほうそく]は、物[もの]が引[ひ]き合[あ]う力[ちから]を説明[せつめい]します。", "sentence_source": "generated"}, {"text": "この法則は、どんな場合でも当てはまります。", "target_word": "法則", "complexity_tier": "T3", "furigana": "この法則[ほうそく]は、どんな場合[ばあい]でも当[あ]てはまります。", "sentence_source": "generated"}, {"text": "例外が見つかったので、その法則は見直されました。", "target_word": "法則", "complexity_tier": "T3", "furigana": "例外[れいがい]が見[み]つかったので、その法則[ほうそく]は見直[みなお]されました。", "sentence_source": "generated"}, {"text": "気体の体積と圧力には、一定の法則があります。", "target_word": "法則", "complexity_tier": "T3", "furigana": "気体[きたい]の体積[たいせき]と圧力[あつりょく]には、一定[いってい]の法則[ほうそく]があります。", "sentence_source": "generated"}, {"text": "研究者たちは、データから法則を見つけようとしています。", "target_word": "法則", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]たちは、データから法則[ほうそく]を見[み]つけようとしています。", "sentence_source": "generated"}, {"text": "法則が成り立たない例を、先生が一つ見せてくれました。", "target_word": "法則", "complexity_tier": "T3", "furigana": "法則[ほうそく]が成[な]り立[た]たない例[れい]を、先生[せんせい]が一[ひと]つ見[み]せてくれました。", "sentence_source": "generated"}, {"text": "光の進み方にも法則があり、鏡の反射で確かめられます。", "target_word": "法則", "complexity_tier": "T3", "furigana": "光[ひかり]の進[すす]み方[かた]にも法則[ほうそく]があり、鏡[かがみ]の反射[はんしゃ]で確[たし]かめられます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "法則", "label": "基本形"}], "register": "formal", "sense_fingerprint": "科学などで常に成り立つ一定の関係や規則性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b294bab-d39d-44d2-ae6c-179982acd0dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37663, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "足跡", "is_correct": false, "explanation": "地面に残る跡で、「関係として発表した」の内容にはならない。"}, {"text": "挨拶", "is_correct": false, "explanation": "人と交わす言葉や動作で、科学的な関係を説明する語としては合わない。"}, {"text": "落書き", "is_correct": false, "explanation": "壁などに書かれた文字で、体積と温度の関係を表す語ではない。"}, {"text": "法則", "is_correct": true, "explanation": "一定の関係や規則性を指し、「関係を法則として発表した」と合う。"}], "explanations": {"足跡": "地面に残る跡で、「関係として発表した」の内容にはならない。", "挨拶": "人と交わす言葉や動作で、科学的な関係を説明する語としては合わない。", "落書き": "壁などに書かれた文字で、体積と温度の関係を表す語ではない。", "法則": "一定の関係や規則性を指し、「関係を法則として発表した」と合う。"}, "sentence_index": 0, "correct_answer": "法則"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この実験は、三段階の法則に従って進めた。", "explanation": "ここは〈手順〉（作業を進める順番）の意味。法則は一定の関係や規則性を指すので、実験の段取りには合わない。"}, {"text": "国会で、この法則が新しく可決された。", "explanation": "ここは〈法律〉の意味。法則は国会で可決される法的な決まりではないので、審議の文脈には合わない。"}, {"text": "学校の法則で、授業中は携帯電話を使えない。", "explanation": "ここは〈規則〉（組織が決めた取り決め）の意味。法則は自然や科学の規則性を指すので、学校の取り決めには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37663, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "名簿", "is_correct": false, "explanation": "「一定の名簿」は意味が通らず、気体の関係の説明にならない。"}, {"text": "反省", "is_correct": false, "explanation": "「一定の反省」は、気体の体積と圧力の話には合わない。"}, {"text": "寝息", "is_correct": false, "explanation": "寝息は眠っている人の呼吸で、気体の性質を表す語ではない。"}, {"text": "法則", "is_correct": true, "explanation": "一定の関係や規則性を表し、気体の体積と圧力に当てはまる。"}], "explanations": {"名簿": "「一定の名簿」は意味が通らず、気体の関係の説明にならない。", "反省": "「一定の反省」は、気体の体積と圧力の話には合わない。", "寝息": "寝息は眠っている人の呼吸で、気体の性質を表す語ではない。", "法則": "一定の関係や規則性を表し、気体の体積と圧力に当てはまる。"}, "sentence_index": 6, "correct_answer": "法則"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この会社では、法則として遅刻は認められない。", "explanation": "ここは〈原則〉（守るべき基本方針）の意味。法則は自然界の規則性を指すので、守るべき方針の文脈には合わない。"}, {"text": "仏教の法則で、殺生は禁じられている。", "explanation": "ここは〈戒律〉（宗教で守るべき決まり）の意味。法則は観察される規則性を指すので、宗教上の禁止事項には合わない。"}, {"text": "この村では、昔から春祭りを雨でも行う法則がある。", "explanation": "ここは〈慣例〉（昔からの習わし）の意味。法則は一定の関係や規則性を指すので、行事の習わしには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37663, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この法則を、気体の温度が変わっても成り立つ。", "corrected_sentence": "この法則は、気体の温度が変わっても成り立つ。", "error_description": "「成り立つ」は主題を「は」で示すのが自然。「この法則を」の「を」は他動詞の目的語用なので、「成り立つ」（自動詞）には使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37663, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は、光の法則を生徒にわかりやすく演奏した。", "corrected_sentence": "先生は、光の法則を生徒にわかりやすく説明した。", "error_description": "「法則」と結びつく動詞は「説明する」。「演奏する」は音楽に使う動詞で、法則には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37666, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「上部」を話題として示す助詞。「山の上部は雪で白くなっている」と文の主題を作る。"}, {"text": "を", "is_correct": false, "explanation": "「白くなる」は目的語を取らない変化の動詞なので、「を」は合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す助詞で、ここでは白くなる先を表さないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すが、山の上部と比べる文脈がなく、白くなる文の骨組みに合わない。"}], "correct_answer": "は", "explanations": {"は": "「上部」を話題として示す助詞。「山の上部は雪で白くなっている」と文の主題を作る。", "を": "「白くなる」は目的語を取らない変化の動詞なので、「を」は合わない。", "へ": "「へ」は方向を示す助詞で、ここでは白くなる先を表さないので合わない。", "より": "「より」は比較を表すが、山の上部と比べる文脈がなく、白くなる文の骨組みに合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37666, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「細くなる」の主語を示し、「上部が細くなっている」で文が成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「細くなる」は目的語を取らない変化の動詞なので、「を」は合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表し、状態変化の主語には使わないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は位置を表すが、「細くなる」の主語を作らないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「細くなる」の主語を示し、「上部が細くなっている」で文が成り立つ。", "を": "「細くなる」は目的語を取らない変化の動詞なので、「を」は合わない。", "と": "「と」は並列や相手を表し、状態変化の主語には使わないので合わない。", "に": "「に」は位置を表すが、「細くなる」の主語を作らないので合わない。"}, "error_tags": {"を": "目的語", "と": "並列", "に": "位置"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37666, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものの上の方の部分。", "primary_collocate": null, "pronunciation": "じょうぶ", "ipa": "dʑoːbɯ", "syllable_count": 3, "sentences": [{"text": "塔の上部に、小さな展望台がある。", "target_word": "上部", "complexity_tier": "T3", "furigana": "塔(とう)の上部(じょうぶ)に、小(ちい)さな展望台(てんぼうだい)がある。", "sentence_source": "generated"}, {"text": "山の上部は雪で白くなっているが、ふもとは緑だ。", "target_word": "上部", "complexity_tier": "T3", "furigana": "山(やま)の上部(じょうぶ)は雪(ゆき)で白(しろ)くなっているが、ふもとは緑(みどり)だ。", "sentence_source": "generated"}, {"text": "箱の上部に穴を開けて、ひもを通した。", "target_word": "上部", "complexity_tier": "T3", "furigana": "箱(はこ)の上部(じょうぶ)に穴(あな)を開(あ)けて、ひもを通(とお)した。", "sentence_source": "generated"}, {"text": "ビルの上部が雲に隠れて見えない。", "target_word": "上部", "complexity_tier": "T3", "furigana": "ビルの上部(じょうぶ)が雲(くも)に隠(かく)れて見(み)えない。", "sentence_source": "generated"}, {"text": "木の上部だけ葉が茂っていて、下の方は枯れている。", "target_word": "上部", "complexity_tier": "T3", "furigana": "木(き)の上部(じょうぶ)だけ葉(は)が茂(しげ)っていて、下(した)の方(ほう)は枯(か)れている。", "sentence_source": "generated"}, {"text": "窓の上部が開くので、風を入れられる。", "target_word": "上部", "complexity_tier": "T3", "furigana": "窓(まど)の上部(じょうぶ)が開(あ)くので、風(かぜ)を入(い)れられる。", "sentence_source": "generated"}, {"text": "ページの上部に題名を書くのが決まりだ。", "target_word": "上部", "complexity_tier": "T3", "furigana": "ページの上部(じょうぶ)に題名(だいめい)を書(か)くのが決(き)まりだ。", "sentence_source": "generated"}, {"text": "瓶の上部が細くなっているので、注ぎやすい。", "target_word": "上部", "complexity_tier": "T3", "furigana": "瓶(びん)の上部(じょうぶ)が細(ほそ)くなっているので、注(そそ)ぎやすい。", "sentence_source": "generated"}, {"text": "本棚の上部には、背が低い人は手が届かない。", "target_word": "上部", "complexity_tier": "T3", "furigana": "本棚(ほんだな)の上部(じょうぶ)には、背(せ)が低(ひく)い人(ひと)は手(て)が届(とど)かない。", "sentence_source": "generated"}, {"text": "煙突の上部から、白い煙が出ていた。", "target_word": "上部", "complexity_tier": "T3", "furigana": "煙突(えんとつ)の上部(じょうぶ)から、白(しろ)い煙(けむり)が出(で)ていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "上部", "label": "基本形"}], "register": "標準", "sense_fingerprint": "ものの全体のうち、上の方にあたる部分。下部と対になる。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b294bab-d39d-44d2-ae6c-179982acd0dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37666, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上部", "is_correct": true, "explanation": "塔の一番上の部分を指し、展望台がある場所として自然に入る。"}, {"text": "色", "is_correct": false, "explanation": "色は塔の外観の性質で、展望台の位置を表す語としては入らない。"}, {"text": "材料", "is_correct": false, "explanation": "材料は建てるときに使う素材で、場所を表さないので合わない。"}, {"text": "重さ", "is_correct": false, "explanation": "重さは塔の性質で、展望台の位置を示せないので合わない。"}], "explanations": {"上部": "塔の一番上の部分を指し、展望台がある場所として自然に入る。", "色": "色は塔の外観の性質で、展望台の位置を表す語としては入らない。", "材料": "材料は建てるときに使う素材で、場所を表さないので合わない。", "重さ": "重さは塔の性質で、展望台の位置を示せないので合わない。"}, "sentence_index": 0, "correct_answer": "上部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "飛行機が上部を飛んでいる。", "explanation": "ここは〈上空＝空の高い所〉の意味。空の高い所は「上空」と言い、「上部」は物の部分を指すので、空を飛ぶ場面では使わないので合わない。"}, {"text": "給料の上部を超えないように、支出を抑えている。", "explanation": "ここは〈上限〉の意味。金額の天井は「上限」と言い、「上部」は物の上の部分にしか使わないので合わない。"}, {"text": "成績が上部を占め、表彰された。", "explanation": "ここは〈上位＝順位が高いこと〉の意味。順位の高さは「上位を占める」と言い、「上部」は物の部分を指すので、順位には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37666, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上部", "is_correct": true, "explanation": "ページの一番上の部分を指し、題名を書く場所として合う。"}, {"text": "厚さ", "is_correct": false, "explanation": "厚さはページの性質で、題名を書く場所を表さないので合わない。"}, {"text": "香り", "is_correct": false, "explanation": "香りは紙の性質で、書く場所を示せないので合わない。"}, {"text": "硬さ", "is_correct": false, "explanation": "硬さは紙の性質で、場所を表さないので題名の位置には入らない。"}], "explanations": {"上部": "ページの一番上の部分を指し、題名を書く場所として合う。", "厚さ": "厚さはページの性質で、題名を書く場所を表さないので合わない。", "香り": "香りは紙の性質で、書く場所を示せないので合わない。", "硬さ": "硬さは紙の性質で、場所を表さないので題名の位置には入らない。"}, "sentence_index": 6, "correct_answer": "上部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "飛行機が上部へ飛んでいった。", "explanation": "ここは〈上方〉の意味。方向を示す「へ」と組むなら「上方へ」と言い、「上部」は物の部分を指すので方向には使わないので合わない。"}, {"text": "彼は競技の上部に立つ、実力のある選手だ。", "explanation": "ここは〈頂点＝最も高い地位〉の意味。地位の頂点は「頂点」と言い、「上部」は物の部分を表すので合わない。"}, {"text": "彼は上部のクラスに進み、難しい授業を受けている。", "explanation": "ここは〈上級＝習熟が進んだ段階〉の意味。段階の高い課程は「上級」と言い、「上部」は物の部分を指すので、クラスには使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37666, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓の上部を、涼しい風が入ってくる。", "corrected_sentence": "窓の上部から、涼しい風が入ってくる。", "error_description": "誤った形は「窓の上部を」（格助詞「を」）、正しい形は「窓の上部から」（起点を示す「から」）。「入ってくる」は目的語を取らない自動詞なので「を」は合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37666, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "壁の上部を、大きな絵をかけた。", "corrected_sentence": "壁の上部に、大きな絵をかけた。", "error_description": "誤った形は「壁の上部を」、正しい形は「壁の上部に」。「かける」は場所を表す「に」を取るので、「を」は合わない。目的語の「を」を重ねると不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37667, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「貼る」の場所を示し、「容器の上部に貼る」で自然に文が成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「貼る」の目的語はラベルで、場所の「上部」には「を」は付かないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を表し、「上部とラベルを貼る」では文が成り立たないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すが、貼る場所を比べる文脈がないので合わない。"}], "correct_answer": "に", "explanations": {"に": "「貼る」の場所を示し、「容器の上部に貼る」で自然に文が成り立つ。", "を": "「貼る」の目的語はラベルで、場所の「上部」には「を」は付かないので合わない。", "と": "「と」は並列を表し、「上部とラベルを貼る」では文が成り立たないので合わない。", "より": "「より」は比較を表すが、貼る場所を比べる文脈がないので合わない。"}, "error_tags": {"を": "目的語", "と": "並列", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37667, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「平らだ」の主語を示し、「上部が平らなので」で文が成り立つ。"}, {"text": "に", "is_correct": false, "explanation": "「に」は位置を示すが、「平らだ」の主語にはならないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表し、「平らだ」の主語を作らないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を表すが、状態を述べる主語にはならないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「平らだ」の主語を示し、「上部が平らなので」で文が成り立つ。", "に": "「に」は位置を示すが、「平らだ」の主語にはならないので合わない。", "で": "「で」は場所や手段を表し、「平らだ」の主語を作らないので合わない。", "と": "「と」は並列を表すが、状態を述べる主語にはならないので合わない。"}, "error_tags": {"に": "位置", "で": "場所・手段", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37667, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物の位置が、上にある側の面や部分。", "primary_collocate": null, "pronunciation": "じょうぶ", "ipa": "dʑoːbɯ", "syllable_count": 3, "sentences": [{"text": "机の上部に傷がついたので、塗り直した。", "target_word": "上部", "complexity_tier": "T3", "furigana": "机(つくえ)の上部(じょうぶ)に傷(きず)がついたので、塗(ぬ)り直(なお)した。", "sentence_source": "generated"}, {"text": "容器の上部にラベルを貼ると、棚で見つけやすい。", "target_word": "上部", "complexity_tier": "T3", "furigana": "容器(ようき)の上部(じょうぶ)にラベルを貼(は)ると、棚(たな)で見(み)つけやすい。", "sentence_source": "generated"}, {"text": "テントの上部が破れて、雨が入ってきた。", "target_word": "上部", "complexity_tier": "T3", "furigana": "テントの上部(じょうぶ)が破(やぶ)れて、雨(あめ)が入(はい)ってきた。", "sentence_source": "generated"}, {"text": "車の上部に荷物を載せるため、ベルトで固定した。", "target_word": "上部", "complexity_tier": "T3", "furigana": "車(くるま)の上部(じょうぶ)に荷物(にもつ)を載(の)せるため、ベルトで固定(こてい)した。", "sentence_source": "generated"}, {"text": "氷山は上部だけが海の上に出ていて、大部分は水の中にある。", "target_word": "上部", "complexity_tier": "T3", "furigana": "氷山(ひょうざん)は上部(じょうぶ)だけが海(うみ)の上(うえ)に出(で)ていて、大部分(だいぶぶん)は水(みず)の中(なか)にある。", "sentence_source": "generated"}, {"text": "ケーキの上部にクリームを塗って仕上げる。", "target_word": "上部", "complexity_tier": "T3", "furigana": "ケーキの上部(じょうぶ)にクリームを塗(ぬ)って仕上(しあ)げる。", "sentence_source": "generated"}, {"text": "缶の上部を開けると、中身が飛び出した。", "target_word": "上部", "complexity_tier": "T3", "furigana": "缶(かん)の上部(じょうぶ)を開(あ)けると、中身(なかみ)が飛(と)び出(だ)した。", "sentence_source": "generated"}, {"text": "この棚は上部が平らなので、物を置ける。", "target_word": "上部", "complexity_tier": "T3", "furigana": "この棚(たな)は上部(じょうぶ)が平(たい)らなので、物(もの)を置(お)ける。", "sentence_source": "generated"}, {"text": "壁の上部にカビが生えて、掃除が大変だった。", "target_word": "上部", "complexity_tier": "T3", "furigana": "壁(かべ)の上部(じょうぶ)にカビが生(は)えて、掃除(そうじ)が大変(たいへん)だった。", "sentence_source": "generated"}, {"text": "ドアの上部には、小さなガラスがはめてある。", "target_word": "上部", "complexity_tier": "T3", "furigana": "ドアの上部(じょうぶ)には、小(ちい)さなガラスがはめてある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "上部", "label": "基本形"}], "register": "標準", "sense_fingerprint": "物の上側にある面や部分。上に向いた側を指す。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b294bab-d39d-44d2-ae6c-179982acd0dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37667, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上部", "is_correct": true, "explanation": "机の上の部分を指し、傷がついた場所として自然に入る。"}, {"text": "香り", "is_correct": false, "explanation": "香りは机の性質で、傷の場所を表せないので合わない。"}, {"text": "硬さ", "is_correct": false, "explanation": "硬さは机の性質で、場所を示せないので傷の位置には入らない。"}, {"text": "重さ", "is_correct": false, "explanation": "重さは机の性質で、傷がつく場所にはならないので合わない。"}], "explanations": {"上部": "机の上の部分を指し、傷がついた場所として自然に入る。", "香り": "香りは机の性質で、傷の場所を表せないので合わない。", "硬さ": "硬さは机の性質で、場所を示せないので傷の位置には入らない。", "重さ": "重さは机の性質で、傷がつく場所にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "上部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ヘリが上部を旋回している。", "explanation": "ここは〈上空＝空の高い所〉の意味。空の高い所は「上空」と言い、「上部」は物の部分なので、空を旋回する場面には使わないので合わない。"}, {"text": "月の支払いの上部を超えないように、買い物を控えている。", "explanation": "ここは〈上限〉の意味。金額の天井は「上限」と言い、「上部」は物の上の部分にしか使わないので合わない。"}, {"text": "試験で上部の順位に入り、奨学金をもらった。", "explanation": "ここは〈上位〉の意味。順位の高い側は「上位」と言い、「上部」は順位には使えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37667, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上部", "is_correct": true, "explanation": "缶の上の部分を指し、開ける場所として合う。"}, {"text": "厚さ", "is_correct": false, "explanation": "厚さは缶の性質で、開ける場所を表さないので合わない。"}, {"text": "色", "is_correct": false, "explanation": "色は缶の外観で、開ける場所として入らないので合わない。"}, {"text": "材料", "is_correct": false, "explanation": "材料は缶を作る素材で、開ける位置にはならないので合わない。"}], "explanations": {"上部": "缶の上の部分を指し、開ける場所として合う。", "厚さ": "厚さは缶の性質で、開ける場所を表さないので合わない。", "色": "色は缶の外観で、開ける場所として入らないので合わない。", "材料": "材料は缶を作る素材で、開ける位置にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "上部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "凧が上部へ高く上がっていった。", "explanation": "ここは〈上方〉の意味。方向の「へ」と組むなら「上方へ」と言い、「上部」は物の部分を指すので方向には使わないので合わない。"}, {"text": "彼は業界の上部に立つ、第一人者だ。", "explanation": "ここは〈頂点＝最も高い地位〉の意味。地位の頂点は「頂点」と言い、「上部」は物の部分を表すので合わない。"}, {"text": "来客は来月の上部に訪れる予定だ。", "explanation": "ここは〈上旬＝月の初めの十日間〉の意味。時期には「上旬」を使い、「上部」は物の部分を指すので時期には使えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37667, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "扉の上部を小さな窓が開いている。", "corrected_sentence": "扉の上部に小さな窓が開いている。", "error_description": "誤った形は「扉の上部を」、正しい形は「扉の上部に」。「開いている」は場所を示す「に」を取るので、「を」は合わない。目的語の「を」は不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37667, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鍋の上部を、蓋を載せる。", "corrected_sentence": "鍋の上部に、蓋を載せる。", "error_description": "誤った形は「鍋の上部を」、正しい形は「鍋の上部に」。「載せる」は場所を表す「に」を取る。「を」を重ねると、目的語が二つになり不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
