INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37668, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "まっすぐなものが弓なりに曲がっていること。", "primary_collocate": null, "pronunciation": "わんきょく", "ipa": "wa̠ŋkʲo̞kɯᵝ", "syllable_count": 4, "sentences": [{"text": "強い風で、木の枝が大きく湾曲している。", "target_word": "湾曲", "complexity_tier": "T3", "furigana": "強[つよ]い風[かぜ]で、木[き]の枝[えだ]が大[おお]きく湾曲[わんきょく]している。", "sentence_source": "generated"}, {"text": "地震のあと、線路が湾曲していた。", "target_word": "湾曲", "complexity_tier": "T3", "furigana": "地震[じしん]のあと、線路[せんろ]が湾曲[わんきょく]していた。", "sentence_source": "generated"}, {"text": "湾曲した刀は、日本の文化の一つだ。", "target_word": "湾曲", "complexity_tier": "T3", "furigana": "湾曲[わんきょく]した刀[かたな]は、日本[にほん]の文化[ぶんか]の一[ひと]つだ。", "sentence_source": "generated"}, {"text": "長い間使ったので、板が湾曲してしまった。", "target_word": "湾曲", "complexity_tier": "T3", "furigana": "長[なが]い間[あいだ]使[つか]ったので、板[いた]が湾曲[わんきょく]してしまった。", "sentence_source": "generated"}, {"text": "背中が湾曲していると、姿勢が悪く見える。", "target_word": "湾曲", "complexity_tier": "T3", "furigana": "背中[せなか]が湾曲[わんきょく]していると、姿勢[しせい]が悪[わる]く見[み]える。", "sentence_source": "generated"}, {"text": "熱で金属の棒が湾曲した。", "target_word": "湾曲", "complexity_tier": "T3", "furigana": "熱[ねつ]で金属[きんぞく]の棒[ぼう]が湾曲[わんきょく]した。", "sentence_source": "generated"}, {"text": "この棚は重い本のせいで湾曲している。", "target_word": "湾曲", "complexity_tier": "T3", "furigana": "この棚[たな]は重[おも]い本[ほん]のせいで湾曲[わんきょく]している。", "sentence_source": "generated"}, {"text": "湾曲した道を進むと、小さな橋がある。", "target_word": "湾曲", "complexity_tier": "T3", "furigana": "湾曲[わんきょく]した道[みち]を進[すす]むと、小[ちい]さな橋[はし]がある。", "sentence_source": "generated"}, {"text": "古い定規は湾曲していて、まっすぐな線が引けない。", "target_word": "湾曲", "complexity_tier": "T3", "furigana": "古[ふる]い定規[じょうぎ]は湾曲[わんきょく]していて、まっすぐな線[せん]が引[ひ]けない。", "sentence_source": "generated"}, {"text": "雨にぬれて、ドアが湾曲した。", "target_word": "湾曲", "complexity_tier": "T3", "furigana": "雨[あめ]にぬれて、ドアが湾曲[わんきょく]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "湾曲", "label": "基本形（名詞）"}, {"form": "湾曲する", "label": "する動詞"}, {"form": "湾曲した", "label": "過去・連体形"}, {"form": "湾曲している", "label": "継続"}], "register": "やや硬い", "sense_fingerprint": "まっすぐなものが弓なりに曲がっている状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90fa4bdf-c71d-489f-bb70-e9e1151b79b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37668, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "湾曲", "is_correct": true, "explanation": "まっすぐなものが弓なりに曲がっている状態を表し、枝の形に合う。"}, {"text": "沸騰", "is_correct": false, "explanation": "液体が煮立つ現象で、枝には使えない。"}, {"text": "蒸発", "is_correct": false, "explanation": "液体が気体になる現象で、枝の曲がりを表さない。"}, {"text": "点滅", "is_correct": false, "explanation": "光がついたり消えたりする現象で、枝の形には当てはまらない。"}], "explanations": {"湾曲": "まっすぐなものが弓なりに曲がっている状態を表し、枝の形に合う。", "沸騰": "液体が煮立つ現象で、枝には使えない。", "蒸発": "液体が気体になる現象で、枝の曲がりを表さない。", "点滅": "光がついたり消えたりする現象で、枝の形には当てはまらない。"}, "sentence_index": 0, "correct_answer": "湾曲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この湾曲には大きな港があり、船の出入りが多い。", "explanation": "「湾曲」は曲がりを表す語で、陸地に入り込んだ海には使わない。湾と言う。"}, {"text": "夏の日差しで布が湾曲して、色が変わった。", "explanation": "「湾曲」は曲がりを表す語で、色の変化には使わない。変色と言う。"}, {"text": "プレス機で金属を湾曲させて、小さくまとめた。", "explanation": "「湾曲」は曲がりを表す語で、力で小さく縮めることには使わない。圧縮と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37668, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "湾曲", "is_correct": true, "explanation": "板などが曲がった状態を表し、重みで棚が曲がる文脈に合う。"}, {"text": "点火", "is_correct": false, "explanation": "火をつける行為で、棚の状態には使わない。"}, {"text": "冷却", "is_correct": false, "explanation": "温度を下げる行為で、棚の曲がりを表せない。"}, {"text": "沈没", "is_correct": false, "explanation": "船などが水中に沈むことで、棚には当てはまらない。"}], "explanations": {"湾曲": "板などが曲がった状態を表し、重みで棚が曲がる文脈に合う。", "点火": "火をつける行為で、棚の状態には使わない。", "冷却": "温度を下げる行為で、棚の曲がりを表せない。", "沈没": "船などが水中に沈むことで、棚には当てはまらない。"}, "sentence_index": 6, "correct_answer": "湾曲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試験の点数が湾曲して、平均が大きく上がった。", "explanation": "「湾曲」は曲がりを表す語で、数値の上下には使わない。変動と言う。"}, {"text": "会議の結論が湾曲して、みんなが驚いた。", "explanation": "「湾曲」は物の曲がりを表す語で、話し合いの結論には使わない。"}, {"text": "店の売上が湾曲して、大きく縮んだ。", "explanation": "「湾曲」は曲がりを表す語で、規模の大小には使わない。縮小と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37668, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "強い風で、枝が湾曲させた。", "corrected_sentence": "強い風で、枝が湾曲した。", "error_description": "「枝が湾曲した」が正しい。「湾曲する」は主語の変化を表す使い方で、「させた」は動作主を必要とするため、枝が主語の文と合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37668, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨の後、ドアの湾曲が気づいた。", "corrected_sentence": "雨の後、ドアの湾曲に気づいた。", "error_description": "「湾曲に気づいた」が正しい。「気づく」は対象に「に」（または「を」）を取る。「湾曲が気づいた」では、湾曲が気づく主体になり文が成立しない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
