INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37669, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "まっすぐではなく、ゆるやかにカーブしていること。", "primary_collocate": null, "pronunciation": "わんきょく", "ipa": "wa̠ŋkʲo̞kɯᵝ", "syllable_count": 4, "sentences": [{"text": "この川はゆるやかに湾曲しながら海へ流れている。", "target_word": "湾曲", "complexity_tier": "T3", "furigana": "この川[かわ]はゆるやかに湾曲[わんきょく]しながら海[うみ]へ流[なが]れている。", "sentence_source": "generated"}, {"text": "湾曲した海岸線が、とても美しい。", "target_word": "湾曲", "complexity_tier": "T3", "furigana": "湾曲[わんきょく]した海岸線[かいがんせん]が、とても美[うつく]しい。", "sentence_source": "generated"}, {"text": "湾曲した橋の上から、町が見えた。", "target_word": "湾曲", "complexity_tier": "T3", "furigana": "湾曲[わんきょく]した橋[はし]の上[うえ]から、町[まち]が見[み]えた。", "sentence_source": "generated"}, {"text": "道路が大きく湾曲しているので、スピードを落とした。", "target_word": "湾曲", "complexity_tier": "T3", "furigana": "道路[どうろ]が大[おお]きく湾曲[わんきょく]しているので、スピードを落[お]とした。", "sentence_source": "generated"}, {"text": "湾曲したテレビの画面は、迫力がある。", "target_word": "湾曲", "complexity_tier": "T3", "furigana": "湾曲[わんきょく]したテレビの画面[がめん]は、迫力[はくりょく]がある。", "sentence_source": "generated"}, {"text": "屋根の湾曲した線が、やさしい感じを出している。", "target_word": "湾曲", "complexity_tier": "T3", "furigana": "屋根[やね]の湾曲[わんきょく]した線[せん]が、やさしい感[かん]じを出[だ]している。", "sentence_source": "generated"}, {"text": "弓は、ゆるやかに湾曲した形をしている。", "target_word": "湾曲", "complexity_tier": "T3", "furigana": "弓[ゆみ]は、ゆるやかに湾曲[わんきょく]した形[かたち]をしている。", "sentence_source": "generated"}, {"text": "この線路は山の近くで湾曲している。", "target_word": "湾曲", "complexity_tier": "T3", "furigana": "この線路[せんろ]は山[やま]の近[ちか]くで湾曲[わんきょく]している。", "sentence_source": "generated"}, {"text": "湾曲した階段をのぼって、二階へ行った。", "target_word": "湾曲", "complexity_tier": "T3", "furigana": "湾曲[わんきょく]した階段[かいだん]をのぼって、二階[にかい]へ行[い]った。", "sentence_source": "generated"}, {"text": "湾曲した窓ガラスの向こうに、海が広がっている。", "target_word": "湾曲", "complexity_tier": "T3", "furigana": "湾曲[わんきょく]した窓[まど]ガラスの向[む]こうに、海[うみ]が広[ひろ]がっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "湾曲", "label": "基本形（名詞）"}, {"form": "湾曲する", "label": "する動詞"}, {"form": "湾曲した", "label": "過去・連体形"}, {"form": "湾曲している", "label": "継続"}], "register": "やや硬い", "sense_fingerprint": "線や面がなだらかな曲線を描いている状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90fa4bdf-c71d-489f-bb70-e9e1151b79b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37669, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "湾曲", "is_correct": true, "explanation": "ゆるやかに曲がる様子を表し、「ゆるやかに___しながら海へ流れている」に入る。"}, {"text": "沈没", "is_correct": false, "explanation": "船などが水に沈むことを表すため、川の流れの形を述べる文には入らない。"}, {"text": "点灯", "is_correct": false, "explanation": "明かりがともることを表すため、「ゆるやかに点灯しながら」は意味が成り立たない。"}, {"text": "採点", "is_correct": false, "explanation": "答案などに点数をつけることを表すため、川の流れの様子には合わない。"}], "explanations": {"湾曲": "ゆるやかに曲がる様子を表し、「ゆるやかに___しながら海へ流れている」に入る。", "沈没": "船などが水に沈むことを表すため、川の流れの形を述べる文には入らない。", "点灯": "明かりがともることを表すため、「ゆるやかに点灯しながら」は意味が成り立たない。", "採点": "答案などに点数をつけることを表すため、川の流れの様子には合わない。"}, "sentence_index": 0, "correct_answer": "湾曲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この湾曲には小さな島が多く、夏には魚もよく釣れる。", "explanation": "ここは〈湾〉（入り江）の意味。湾曲は線や面がまがる様子で、場所の名前としては使わないので合わない。"}, {"text": "報道は事実を湾曲して伝えたため、強い批判を受けた。", "explanation": "ここは〈歪曲〉の意味。事実をゆがめて伝えることは歪曲と言い、湾曲は形がまがることだけを表すので合わない。"}, {"text": "幼いころの経験で、彼の性格は湾曲してしまった。", "explanation": "ここは〈歪む〉の意味。性格がゆがむことは歪むと言い、湾曲は線や面の形の曲がりに使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37669, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "湾曲", "is_correct": true, "explanation": "ゆるやかな曲がりを表し、「ゆるやかに___した形」に入る。"}, {"text": "抽選", "is_correct": false, "explanation": "くじを引いて当たりを決めることを表すため、弓の形の説明には入らない。"}, {"text": "解凍", "is_correct": false, "explanation": "凍ったものを溶かすことを表すため、「ゆるやかに解凍した形」は意味が通らない。"}, {"text": "交換", "is_correct": false, "explanation": "取り替えることを表すため、形のまがりを述べる文には入らない。"}], "explanations": {"湾曲": "ゆるやかな曲がりを表し、「ゆるやかに___した形」に入る。", "抽選": "くじを引いて当たりを決めることを表すため、弓の形の説明には入らない。", "解凍": "凍ったものを溶かすことを表すため、「ゆるやかに解凍した形」は意味が通らない。", "交換": "取り替えることを表すため、形のまがりを述べる文には入らない。"}, "sentence_index": 6, "correct_answer": "湾曲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "考え方が湾曲していて、人の話をなかなか聞かない。", "explanation": "ここは〈偏る〉の意味。考えが一方に寄ることは偏ると言い、湾曲は形の曲がりに使うので合わない。"}, {"text": "ルールから湾曲した行動は、認められない。", "explanation": "ここは〈逸脱〉の意味。決まりから外れることは逸脱と言い、湾曲は形の曲がりを表すので合わない。"}, {"text": "彼女の話し方は湾曲があって、聞きやすい。", "explanation": "ここは〈抑揚〉の意味。声の高低や強弱のつけ方は抑揚と言い、湾曲は線や面の形に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37669, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この線路は湾曲に山を回っている。", "corrected_sentence": "この線路は湾曲して山を回っている。", "error_description": "「湾曲」はする動詞の語幹にあたる名詞なので、「湾曲に」では続かない。「湾曲して」の形にして、山を回るという動作につなぐ。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37669, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "湾曲な窓ガラスから、海がよく見える。", "corrected_sentence": "湾曲した窓ガラスから、海がよく見える。", "error_description": "「湾曲」は名詞で、「な」では修飾できない。名詞を修飾する「湾曲した」の形にする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37670, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「滑らか」の主語を示し、「翼面が滑らかなほど」で文が成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「滑らかだ」は目的語を取らないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「滑らかなほど」の主語にはならないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すが、翼面と何を比べるのか文に示されていないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「滑らか」の主語を示し、「翼面が滑らかなほど」で文が成り立つ。", "を": "「を」は目的語を示すが、「滑らかだ」は目的語を取らないので合わない。", "へ": "「へ」は方向を示すが、「滑らかなほど」の主語にはならないので合わない。", "より": "「より」は比較を表すが、翼面と何を比べるのか文に示されていないので合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37670, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「翼面の上側」のように、翼面と上側を結ぶ連体修飾の「の」。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表すが、名詞同士を連体修飾で結ぶ働きはないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は位置を示すが、名詞を直接つなぐ連体修飾にはならないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、名詞を直接つなげて「上側」を修飾することはないので合わない。"}], "correct_answer": "の", "explanations": {"の": "「翼面の上側」のように、翼面と上側を結ぶ連体修飾の「の」。", "で": "「で」は場所や手段を表すが、名詞同士を連体修飾で結ぶ働きはないので合わない。", "に": "「に」は位置を示すが、名詞を直接つなぐ連体修飾にはならないので合わない。", "から": "「から」は起点を示すが、名詞を直接つなげて「上側」を修飾することはないので合わない。"}, "error_tags": {"で": "場所・手段", "に": "位置", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37670, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "飛行機の羽の、上や下の、平らな部分のことです。", "primary_collocate": null, "pronunciation": "よくめん", "ipa": "jokɯmeɴ", "syllable_count": 4, "sentences": [{"text": "飛行機の翼面に霜がつくと、飛ぶ前に取り除く。", "target_word": "翼面", "complexity_tier": "T3", "furigana": "飛行機(ひこうき)の翼面(よくめん)に霜(しも)がつくと、飛(と)ぶ前(まえ)に取(と)り除(のぞ)く。", "sentence_source": "generated"}, {"text": "翼面が滑らかなほど、空気の抵抗は小さくなる。", "target_word": "翼面", "complexity_tier": "T3", "furigana": "翼面(よくめん)が滑(なめ)らかなほど、空気(くうき)の抵抗(ていこう)は小(ちい)さくなる。", "sentence_source": "generated"}, {"text": "整備士が翼面の汚れを丁寧に拭いた。", "target_word": "翼面", "complexity_tier": "T3", "furigana": "整備士(せいびし)が翼面(よくめん)の汚(よご)れを丁寧(ていねい)に拭(ふ)いた。", "sentence_source": "generated"}, {"text": "雨の日は、翼面が濡れて光って見えた。", "target_word": "翼面", "complexity_tier": "T3", "furigana": "雨(あめ)の日(ひ)は、翼面(よくめん)が濡(ぬ)れて光(ひか)って見(み)えた。", "sentence_source": "generated"}, {"text": "翼面の上を空気が流れて、機体が浮き上がる。", "target_word": "翼面", "complexity_tier": "T3", "furigana": "翼面(よくめん)の上(うえ)を空気(くうき)が流(なが)れて、機体(きたい)が浮(う)き上(あ)がる。", "sentence_source": "generated"}, {"text": "模型飛行機の翼面に、赤いシールを貼った。", "target_word": "翼面", "complexity_tier": "T3", "furigana": "模型飛行機(もけいひこうき)の翼面(よくめん)に、赤(あか)いシールを貼(は)った。", "sentence_source": "generated"}, {"text": "翼面に小さなへこみが見つかり、修理が必要になった。", "target_word": "翼面", "complexity_tier": "T3", "furigana": "翼面(よくめん)に小(ちい)さなへこみが見(み)つかり、修理(しゅうり)が必要(ひつよう)になった。", "sentence_source": "generated"}, {"text": "この翼面の上側は曲がっているが、下側はほぼ平らだ。", "target_word": "翼面", "complexity_tier": "T3", "furigana": "この翼面(よくめん)の上側(うわがわ)は曲(ま)がっているが、下側(したがわ)はほぼ平(たい)らだ。", "sentence_source": "generated"}, {"text": "新しい塗料を翼面に塗ると、軽くて丈夫になる。", "target_word": "翼面", "complexity_tier": "T3", "furigana": "新(あたら)しい塗料(とりょう)を翼面(よくめん)に塗(ぬ)ると、軽(かる)くて丈夫(じょうぶ)になる。", "sentence_source": "generated"}, {"text": "翼面が広い飛行機ほど、大きな揚力を得やすい。", "target_word": "翼面", "complexity_tier": "T3", "furigana": "翼面(よくめん)が広(ひろ)い飛行機(ひこうき)ほど、大(おお)きな揚力(ようりょく)を得(え)やすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "翼面", "label": "基本形"}], "register": "標準", "sense_fingerprint": "飛行機の翼の上側や下側にある、平らな面。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b294bab-d39d-44d2-ae6c-179982acd0dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37670, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "翼面", "is_correct": true, "explanation": "霜がつく飛行機の面を指し、場所として自然に入る。"}, {"text": "香り", "is_correct": false, "explanation": "香りは飛行機の性質で、霜がつく場所を示せないので合わない。"}, {"text": "色", "is_correct": false, "explanation": "色は飛行機の外観で、霜がつく位置にはならないので合わない。"}, {"text": "硬さ", "is_correct": false, "explanation": "硬さは機体の性質で、霜の場所を表さないので合わない。"}], "explanations": {"翼面": "霜がつく飛行機の面を指し、場所として自然に入る。", "香り": "香りは飛行機の性質で、霜がつく場所を示せないので合わない。", "色": "色は飛行機の外観で、霜がつく位置にはならないので合わない。", "硬さ": "硬さは機体の性質で、霜の場所を表さないので合わない。"}, "sentence_index": 0, "correct_answer": "翼面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ビルの翼面が濡れて光って見えた。", "explanation": "ここは〈壁面＝建物の表面〉の意味。翼面は翼のある機体の面を指すので、ビルには使わないので合わない。"}, {"text": "鳥は翼面を広げて、大きく羽ばたいた。", "explanation": "ここは〈翼〉の意味。翼は広げるものなので、面を広げるとは言わず合わない。"}, {"text": "池の翼面が濡れて光って見えた。", "explanation": "ここは〈水面〉の意味。水の表面は「水面」と言い、翼面は機体の面を指すので池には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37670, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "翼面", "is_correct": true, "explanation": "機体の面で、へこみが見つかる場所として自然に入る。"}, {"text": "色", "is_correct": false, "explanation": "色は機体の外観で、へこみが見つかる場所を表せないので合わない。"}, {"text": "重さ", "is_correct": false, "explanation": "重さは機体の性質で、へこみの場所を表せないので合わない。"}, {"text": "厚さ", "is_correct": false, "explanation": "厚さは面の性質で、へこみの場所にはならないので合わない。"}], "explanations": {"翼面": "機体の面で、へこみが見つかる場所として自然に入る。", "色": "色は機体の外観で、へこみが見つかる場所を表せないので合わない。", "重さ": "重さは機体の性質で、へこみの場所を表せないので合わない。", "厚さ": "厚さは面の性質で、へこみの場所にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "翼面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "床の翼面を磨くと、つやが出る。", "explanation": "ここは〈表面〉の意味。床の表面は「表面」と言い、翼面は翼のある機体の面を指すので床には使わないので合わない。"}, {"text": "船の翼面が風を受けて大きく膨らむ。", "explanation": "ここは〈帆〉の意味。帆は風で膨らむが、翼面は硬い機体の面で膨らむものではないので合わない。"}, {"text": "新聞の翼面に、写真が大きく載った。", "explanation": "ここは〈紙面〉の意味。新聞の面は「紙面」と言い、翼面は機体の面なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37670, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "整備士が翼面から塗料を塗った。", "corrected_sentence": "整備士が翼面に塗料を塗った。", "error_description": "誤った形は「翼面から」、正しい形は「翼面に」。塗料を置く先は、到達点を示す「に」で表す。「から」は起点を示すので、ここでは合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37670, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "翼面を雨で濡れると、機体は重くなる。", "corrected_sentence": "翼面が雨で濡れると、機体は重くなる。", "error_description": "誤った形は「翼面を」、正しい形は「翼面が」。「濡れる」は目的語を取らない自動詞で、主語を「が」で示すので、「を」は合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37671, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「沿う」が取る相手を示し、「翼面に沿った」で文が成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「沿う」は目的語を取らないので、ここでは合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「沿う」と結びつかず不自然なので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すが、翼面と何かを比べる文脈がないので合わない。"}], "correct_answer": "に", "explanations": {"に": "「沿う」が取る相手を示し、「翼面に沿った」で文が成り立つ。", "を": "「を」は目的語を示すが、「沿う」は目的語を取らないので、ここでは合わない。", "へ": "「へ」は方向を示すが、「沿う」と結びつかず不自然なので合わない。", "より": "「より」は比較を表すが、翼面と何かを比べる文脈がないので合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37671, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「平らだ」の主語を示し、「翼面が平らだと」で文が成り立つ。"}, {"text": "に", "is_correct": false, "explanation": "「に」は位置を示すが、「平らだ」の主語にはならないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表すが、「平らだ」の主語を作らないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を表すが、状態の主語にはならないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「平らだ」の主語を示し、「翼面が平らだと」で文が成り立つ。", "に": "「に」は位置を示すが、「平らだ」の主語にはならないので合わない。", "で": "「で」は場所や手段を表すが、「平らだ」の主語を作らないので合わない。", "と": "「と」は並列を表すが、状態の主語にはならないので合わない。"}, "error_tags": {"に": "位置", "で": "場所・手段", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37671, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "飛行機や翼のあるものの、表面の平らな部分。特に空気の流れに影響を与える面。", "primary_collocate": null, "pronunciation": "よくめん", "ipa": "jokɯmeɴ", "syllable_count": 4, "sentences": [{"text": "翼面の形を変えると、飛行機の動きが変わる。", "target_word": "翼面", "complexity_tier": "T3", "furigana": "翼面(よくめん)の形(かたち)を変(か)えると、飛行機(ひこうき)の動(うご)きが変(か)わる。", "sentence_source": "generated"}, {"text": "風洞実験で、翼面に沿った空気の流れを調べた。", "target_word": "翼面", "complexity_tier": "T3", "furigana": "風洞実験(ふうどうじっけん)で、翼面(よくめん)に沿(そ)った空気(くうき)の流(なが)れを調(しら)べた。", "sentence_source": "generated"}, {"text": "鳥の翼面は羽が重なり、空気をうまく受け止める。", "target_word": "翼面", "complexity_tier": "T3", "furigana": "鳥(とり)の翼面(よくめん)は羽(はね)が重(かさ)なり、空気(くうき)をうまく受(う)け止(と)める。", "sentence_source": "generated"}, {"text": "翼面を傾けて、機体は右へ曲がっていった。", "target_word": "翼面", "complexity_tier": "T3", "furigana": "翼面(よくめん)を傾(かたむ)けて、機体(きたい)は右(みぎ)へ曲(ま)がっていった。", "sentence_source": "generated"}, {"text": "翼面に凹凸があると、空気の流れが乱れる。", "target_word": "翼面", "complexity_tier": "T3", "furigana": "翼面(よくめん)に凹凸(おうとつ)があると、空気(くうき)の流(なが)れが乱(みだ)れる。", "sentence_source": "generated"}, {"text": "グライダーは大きな翼面で風に乗り、長く飛ぶ。", "target_word": "翼面", "complexity_tier": "T3", "furigana": "グライダーは大(おお)きな翼面(よくめん)で風(かぜ)に乗(の)り、長(なが)く飛(と)ぶ。", "sentence_source": "generated"}, {"text": "翼面の角度を調整して、上昇する力を強めた。", "target_word": "翼面", "complexity_tier": "T3", "furigana": "翼面(よくめん)の角度(かくど)を調整(ちょうせい)して、上昇(じょうしょう)する力(ちから)を強(つよ)めた。", "sentence_source": "generated"}, {"text": "紙飛行機でも、翼面が平らだとよく滑空する。", "target_word": "翼面", "complexity_tier": "T3", "furigana": "紙飛行機(かみひこうき)でも、翼面(よくめん)が平(たい)らだとよく滑空(かっくう)する。", "sentence_source": "generated"}, {"text": "設計者は翼面の面積を増やして、着陸の速度を落とした。", "target_word": "翼面", "complexity_tier": "T3", "furigana": "設計者(せっけいしゃ)は翼面(よくめん)の面積(めんせき)を増(ふ)やして、着陸(ちゃくりく)の速度(そくど)を落(お)とした。", "sentence_source": "generated"}, {"text": "翼面を流れる空気が速いほど、浮く力は大きくなる。", "target_word": "翼面", "complexity_tier": "T3", "furigana": "翼面(よくめん)を流(なが)れる空気(くうき)が速(はや)いほど、浮(う)く力(ちから)は大(おお)きくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "翼面", "label": "基本形"}], "register": "標準", "sense_fingerprint": "飛行機や鳥など翼のあるものの平らな面で、空気の流れや浮く力に関わる部分。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b294bab-d39d-44d2-ae6c-179982acd0dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37671, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "翼面", "is_correct": true, "explanation": "翼面の形は、飛行機の動きを変える部分として自然に入る。"}, {"text": "音", "is_correct": false, "explanation": "音は機体の部分ではなく、形を変える対象として合わないので不適切。"}, {"text": "香り", "is_correct": false, "explanation": "香りは形を持たないので、形を変える対象として合わない。"}, {"text": "重さ", "is_correct": false, "explanation": "重さは形の対象ではないので、「重さの形」とは言えず合わない。"}], "explanations": {"翼面": "翼面の形は、飛行機の動きを変える部分として自然に入る。", "音": "音は機体の部分ではなく、形を変える対象として合わないので不適切。", "香り": "香りは形を持たないので、形を変える対象として合わない。", "重さ": "重さは形の対象ではないので、「重さの形」とは言えず合わない。"}, "sentence_index": 0, "correct_answer": "翼面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "翼面を傾けて、船は右へ曲がっていった。", "explanation": "ここは〈舵〉の意味。船の向きを変えるのは舵で、翼面は翼のある機体の面を指すので船には使わないので合わない。"}, {"text": "屋根の翼面が雨に濡れて光った。", "explanation": "ここは〈屋根の表面〉の意味。屋根の表面は「屋根の面」と言い、翼面は翼のある機体の面を指すので屋根には使わないので合わない。"}, {"text": "翼面を張って、船が進んだ。", "explanation": "ここは〈帆〉の意味。帆は風を受けるため張るもので、機体の翼面を張るとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37671, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "翼面", "is_correct": true, "explanation": "翼面の角度は、上昇する力を調整する部分として自然に入る。"}, {"text": "色", "is_correct": false, "explanation": "色には角度がないので、角度を調整する対象として合わない。"}, {"text": "厚さ", "is_correct": false, "explanation": "厚さは角度を持たないので、調整の対象として合わない。"}, {"text": "硬さ", "is_correct": false, "explanation": "硬さは角度を持たないので、調整の対象として合わない。"}], "explanations": {"翼面": "翼面の角度は、上昇する力を調整する部分として自然に入る。", "色": "色には角度がないので、角度を調整する対象として合わない。", "厚さ": "厚さは角度を持たないので、調整の対象として合わない。", "硬さ": "硬さは角度を持たないので、調整の対象として合わない。"}, "sentence_index": 6, "correct_answer": "翼面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "翼面を振って、涼をとった。", "explanation": "ここは〈扇〉の意味。涼をとる道具は扇で、翼面は機体の面を指すので合わない。"}, {"text": "川の翼面が凍った。", "explanation": "ここは〈表面〉の意味。水の表面は「表面」と言い、翼面は翼のある機体の面を指すので川には使わないので合わない。"}, {"text": "翼面を開けて、風を入れた。", "explanation": "ここは〈窓〉の意味。風を入れる開口部は窓で、翼面は機体の面を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37671, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "翼面を沿う空気の流れは、なめらかだ。", "corrected_sentence": "翼面に沿う空気の流れは、なめらかだ。", "error_description": "誤った形は「翼面を沿う」、正しい形は「翼面に沿う」。「沿う」は場所の相手を表す「に」を取るので、「を」は合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37671, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "翼面を角度を変えて、上昇する力を強めた。", "corrected_sentence": "翼面の角度を変えて、上昇する力を強めた。", "error_description": "誤った形は「翼面を角度を」、正しい形は「翼面の角度を」。「角度」は「翼面の」と「の」で結ぶ。「を」を重ねると目的語が二つになり不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80b4207-85b8-4c0b-8de4-163f04aa7930') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37672, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『力が低下する』で、力が主語。低下の主語を示す格助詞。"}, {"text": "を", "is_correct": false, "explanation": "『を』は目的語。低下は目的語を取らないので、『力を低下』は文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "『に』は相手や着点。『力に低下』は意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は手段や場所。『力で低下』は主語を示せず、意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "『力が低下する』で、力が主語。低下の主語を示す格助詞。", "を": "『を』は目的語。低下は目的語を取らないので、『力を低下』は文が成り立たない。", "に": "『に』は相手や着点。『力に低下』は意味が通らない。", "で": "『で』は手段や場所。『力で低下』は主語を示せず、意味が通らない。"}, "error_tags": {"を": "目的語の格", "に": "相手・着点の格", "で": "手段・場所の格"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上昇", "is_correct": true, "explanation": "正解。低下の対義語で、程度が以前より高くなる意味。士気が下がる文の反対になる。"}, {"text": "減少", "is_correct": false, "explanation": "低下とほぼ同じ方向の語で、対義語ではない。"}, {"text": "停止", "is_correct": false, "explanation": "動きや働きが止まる意味で、程度が下がる意味とは関係しない。"}, {"text": "解消", "is_correct": false, "explanation": "問題や不足がなくなる意味で、程度が下がる意味の反対語ではない。"}], "correct_answer": "上昇", "explanations": {"上昇": "正解。低下の対義語で、程度が以前より高くなる意味。士気が下がる文の反対になる。", "減少": "低下とほぼ同じ方向の語で、対義語ではない。", "停止": "動きや働きが止まる意味で、程度が下がる意味とは関係しない。", "解消": "問題や不足がなくなる意味で、程度が下がる意味の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37672, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『低下を感じて』で、感じる対象（低下）を示す目的語。"}, {"text": "の", "is_correct": false, "explanation": "『の』は名詞をつなぐ格。『低下の感じて』は文が続かず、感じる対象にならない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示す。『低下へ感じて』は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較の基準。『低下より感じて』は比べる対象が合わず、感じる対象にならない。"}], "correct_answer": "を", "explanations": {"を": "『低下を感じて』で、感じる対象（低下）を示す目的語。", "の": "『の』は名詞をつなぐ格。『低下の感じて』は文が続かず、感じる対象にならない。", "へ": "『へ』は方向を示す。『低下へ感じて』は意味が通らない。", "より": "『より』は比較の基準。『低下より感じて』は比べる対象が合わず、感じる対象にならない。"}, "error_tags": {"の": "連体の格", "へ": "方向の格", "より": "比較の格"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上昇", "is_correct": true, "explanation": "正解。低下の対義語で、程度が以前より高くなる意味。自信が下がる文の反対になる。"}, {"text": "発生", "is_correct": false, "explanation": "新しく起こる意味で、程度が下がる意味の反対語ではない。"}, {"text": "継続", "is_correct": false, "explanation": "同じ状態が続く意味で、程度が下がる意味とは関係しない。"}, {"text": "整理", "is_correct": false, "explanation": "物事をまとめて片づける意味で、程度の変化とは関係しない。"}], "correct_answer": "上昇", "explanations": {"上昇": "正解。低下の対義語で、程度が以前より高くなる意味。自信が下がる文の反対になる。", "発生": "新しく起こる意味で、程度が下がる意味の反対語ではない。", "継続": "同じ状態が続く意味で、程度が下がる意味とは関係しない。", "整理": "物事をまとめて片づける意味で、程度の変化とは関係しない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37672, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "気持ちや力、数などが、前より少なくなること。", "primary_collocate": null, "pronunciation": "ていか", "ipa": "teika", "syllable_count": 3, "sentences": [{"text": "睡眠不足が続いて、仕事への意欲が低下した。", "target_word": "低下", "complexity_tier": "T3", "furigana": "睡眠不足[すいみんぶそく]が続[つづ]いて、仕事[しごと]への意欲[いよく]が低下[ていか]した。", "sentence_source": "generated"}, {"text": "年をとると、筋肉の力が低下しやすくなる。", "target_word": "低下", "complexity_tier": "T3", "furigana": "年[とし]をとると、筋肉[きんにく]の力[ちから]が低下[ていか]しやすくなる。", "sentence_source": "generated"}, {"text": "出生率の低下が社会の問題になっている。", "target_word": "低下", "complexity_tier": "T3", "furigana": "出生率[しゅっしょうりつ]の低下[ていか]が社会[しゃかい]の問題[もんだい]になっている。", "sentence_source": "generated"}, {"text": "試合に負け続けて、チームの士気が低下した。", "target_word": "低下", "complexity_tier": "T3", "furigana": "試合[しあい]に負[ま]け続[つづ]けて、チームの士気[しき]が低下[ていか]した。", "sentence_source": "generated"}, {"text": "病気で食欲が低下し、ほとんど食べられなかった。", "target_word": "低下", "complexity_tier": "T3", "furigana": "病気[びょうき]で食欲[しょくよく]が低下[ていか]し、ほとんど食[た]べられなかった。", "sentence_source": "generated"}, {"text": "集中力の低下を防ぐために、一時間ごとに休む。", "target_word": "低下", "complexity_tier": "T3", "furigana": "集中力[しゅうちゅうりょく]の低下[ていか]を防[ふせ]ぐために、一時間[いちじかん]ごとに休[やす]む。", "sentence_source": "generated"}, {"text": "雨が続いて、来店者の数が低下した。", "target_word": "低下", "complexity_tier": "T3", "furigana": "雨[あめ]が続[つづ]いて、来店者[らいてんしゃ]の数[かず]が低下[ていか]した。", "sentence_source": "generated"}, {"text": "体力の低下を感じて、毎朝散歩を始めた。", "target_word": "低下", "complexity_tier": "T3", "furigana": "体力[たいりょく]の低下[ていか]を感[かん]じて、毎朝[まいあさ]散歩[さんぽ]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "不安が大きくなると、やる気が低下するものだ。", "target_word": "低下", "complexity_tier": "T3", "furigana": "不安[ふあん]が大[おお]きくなると、やる気[き]が低下[ていか]するものだ。", "sentence_source": "generated"}, {"text": "失敗が重なって、彼の自信は低下していった。", "target_word": "低下", "complexity_tier": "T3", "furigana": "失敗[しっぱい]が重[かさ]なって、彼[かれ]の自信[じしん]は低下[ていか]していった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "低下する", "label": "dictionary form"}, {"form": "低下した", "label": "past"}, {"form": "低下して", "label": "te-form"}, {"form": "低下している", "label": "progressive"}, {"form": "低下しない", "label": "negative"}], "register": "neutral", "sense_fingerprint": "意欲・体力・数量などが以前より減ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b8ac3e6-a2ff-4eb9-b4fb-6cf755747119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37672, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "低下", "is_correct": true, "explanation": "正解。意欲が以前より減ることを表し、「仕事への意欲が＿した」に入る。"}, {"text": "作成", "is_correct": false, "explanation": "「意欲が作成した」は成り立たない。作成は書類や物を新しくつくる語。"}, {"text": "分類", "is_correct": false, "explanation": "「意欲が分類した」は意味が通らない。分類は物や情報を種類ごとに分ける語。"}, {"text": "提案", "is_correct": false, "explanation": "「意欲が提案した」は主語と動詞が合わない。提案は人が案を出す行為。"}], "explanations": {"低下": "正解。意欲が以前より減ることを表し、「仕事への意欲が＿した」に入る。", "作成": "「意欲が作成した」は成り立たない。作成は書類や物を新しくつくる語。", "分類": "「意欲が分類した」は意味が通らない。分類は物や情報を種類ごとに分ける語。", "提案": "「意欲が提案した」は主語と動詞が合わない。提案は人が案を出す行為。"}, "sentence_index": 0, "correct_answer": "低下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "エレベーターが低下して、一階に着いた。", "explanation": "ここは〈下へ動く〉の意味。低下は程度や力が以前より減ることなので、乗り物の移動には使わない。"}, {"text": "りんごが木から低下して、地面に落ちた。", "explanation": "ここは〈落下〉の意味。低下は物が落ちる動きを表さず、程度が下がる意味なので合わない。"}, {"text": "飛行機が山に低下した。", "explanation": "ここは〈墜落〉の意味。低下は能力や量が下がることで、飛行機が落ちる事故には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37672, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "低下", "is_correct": true, "explanation": "正解。来店者の数が以前より減ることを表し、文に合う。"}, {"text": "整理", "is_correct": false, "explanation": "「数が整理した」は成り立たない。整理は物を片づける語。"}, {"text": "発見", "is_correct": false, "explanation": "「数が発見した」は意味が通らない。発見は未知のものを見つける語。"}, {"text": "採用", "is_correct": false, "explanation": "「数が採用した」は合わない。採用は人を雇う、案を取り入れる語。"}], "explanations": {"低下": "正解。来店者の数が以前より減ることを表し、文に合う。", "整理": "「数が整理した」は成り立たない。整理は物を片づける語。", "発見": "「数が発見した」は意味が通らない。発見は未知のものを見つける語。", "採用": "「数が採用した」は合わない。採用は人を雇う、案を取り入れる語。"}, "sentence_index": 6, "correct_answer": "低下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "嵐の中で船が低下した。", "explanation": "ここは〈沈没〉の意味。低下は程度が下がることで、船が水に沈むことには使わない。"}, {"text": "子どもが階段から低下して、けがをした。", "explanation": "ここは〈転落〉の意味。低下は人が高い所から落ちる出来事には使わない。"}, {"text": "パラシュートで低下して、地面に着いた。", "explanation": "ここは〈降下〉の意味。低下は程度が下がることで、降りていく動きには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37672, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもの減少と高齢化で、地域の活力を低下が心配だ。", "corrected_sentence": "子どもの減少と高齢化で、地域の活力の低下が心配だ。", "error_description": "「低下」の前は『の』で名詞をつなぐ。『を』は動作の目的語を示すので、名詞『低下』の前に置くと文が壊れる。『活力の低下』が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37672, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大雨の日は、来店者の数が低下やすい。", "corrected_sentence": "大雨の日は、来店者の数が低下しやすい。", "error_description": "「低下」はサ変名詞なので『しやすい』と続ける。『し』が抜けた『低下やすい』は語形が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37673, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『気温が低下する』で、気温が主語。低下の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "『を』は目的語。低下は目的語を取らないので、『気温を低下』は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "『に』は相手や着点。『気温に低下』は意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は手段や原因。『気温で低下』は主語を示せず、不自然。"}], "correct_answer": "が", "explanations": {"が": "『気温が低下する』で、気温が主語。低下の主語を示す。", "を": "『を』は目的語。低下は目的語を取らないので、『気温を低下』は成り立たない。", "に": "『に』は相手や着点。『気温に低下』は意味が通らない。", "で": "『で』は手段や原因。『気温で低下』は主語を示せず、不自然。"}, "error_tags": {"を": "目的語の格", "に": "相手・着点の格", "で": "手段・原因の格"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上昇", "is_correct": true, "explanation": "正解。低下の対義語で、精度や程度が以前より高くなる意味。問題になる文の反対になる。"}, {"text": "減少", "is_correct": false, "explanation": "低下とほぼ同じ方向の語で、対義語ではない。"}, {"text": "停止", "is_correct": false, "explanation": "動きや働きが止まる意味で、程度が下がる意味とは関係しない。"}, {"text": "解消", "is_correct": false, "explanation": "問題や不足がなくなる意味で、程度が下がる意味の反対語ではない。"}], "correct_answer": "上昇", "explanations": {"上昇": "正解。低下の対義語で、精度や程度が以前より高くなる意味。問題になる文の反対になる。", "減少": "低下とほぼ同じ方向の語で、対義語ではない。", "停止": "動きや働きが止まる意味で、程度が下がる意味とは関係しない。", "解消": "問題や不足がなくなる意味で、程度が下がる意味の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37673, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『視力が低下した』で、視力が主語。低下の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "『を』は目的語。低下は目的語を取らないので、『視力を低下した』は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示す。『視力へ低下した』は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較の基準。『視力より低下した』は比較の文にならない。"}], "correct_answer": "が", "explanations": {"が": "『視力が低下した』で、視力が主語。低下の主語を示す。", "を": "『を』は目的語。低下は目的語を取らないので、『視力を低下した』は成り立たない。", "へ": "『へ』は方向を示す。『視力へ低下した』は意味が通らない。", "より": "『より』は比較の基準。『視力より低下した』は比較の文にならない。"}, "error_tags": {"を": "目的語の格", "へ": "方向の格", "より": "比較の格"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上昇", "is_correct": true, "explanation": "正解。低下の対義語で、程度が以前より高くなる意味。血圧が下がる文の反対になる。"}, {"text": "発生", "is_correct": false, "explanation": "新しく起こる意味で、程度が下がる意味の反対語ではない。"}, {"text": "継続", "is_correct": false, "explanation": "同じ状態が続く意味で、程度が下がる意味とは関係しない。"}, {"text": "整理", "is_correct": false, "explanation": "物事をまとめて片づける意味で、程度の変化とは関係しない。"}], "correct_answer": "上昇", "explanations": {"上昇": "正解。低下の対義語で、程度が以前より高くなる意味。血圧が下がる文の反対になる。", "発生": "新しく起こる意味で、程度が下がる意味の反対語ではない。", "継続": "同じ状態が続く意味で、程度が下がる意味とは関係しない。", "整理": "物事をまとめて片づける意味で、程度の変化とは関係しない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37673, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "状態や程度が、以前よりも低くなること。", "primary_collocate": null, "pronunciation": "ていか", "ipa": "teika", "syllable_count": 3, "sentences": [{"text": "古くなったので、電池の性能が低下した。", "target_word": "低下", "complexity_tier": "T3", "furigana": "古[ふる]くなったので、電池[でんち]の性能[せいのう]が低下[ていか]した。", "sentence_source": "generated"}, {"text": "気温が低下して、朝は霜がおりた。", "target_word": "低下", "complexity_tier": "T3", "furigana": "気温[きおん]が低下[ていか]して、朝[あさ]は霜[しも]がおりた。", "sentence_source": "generated"}, {"text": "英語の成績が低下したので、勉強の仕方を変えた。", "target_word": "低下", "complexity_tier": "T3", "furigana": "英語[えいご]の成績[せいせき]が低下[ていか]したので、勉強[べんきょう]の仕方[しかた]を変[か]えた。", "sentence_source": "generated"}, {"text": "工場では、機械の精度の低下がよく問題になる。", "target_word": "低下", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、機械[きかい]の精度[せいど]の低下[ていか]がよく問題[もんだい]になる。", "sentence_source": "generated"}, {"text": "湖の水質が低下し、魚がすめなくなった。", "target_word": "低下", "complexity_tier": "T3", "furigana": "湖[みずうみ]の水質[すいしつ]が低下[ていか]し、魚[さかな]がすめなくなった。", "sentence_source": "generated"}, {"text": "気圧の低下で、頭が痛くなる人もいる。", "target_word": "低下", "complexity_tier": "T3", "furigana": "気圧[きあつ]の低下[ていか]で、頭[あたま]が痛[いた]くなる人[ひと]もいる。", "sentence_source": "generated"}, {"text": "画質の低下を防ぐため、写真を何度もコピーしない。", "target_word": "低下", "complexity_tier": "T3", "furigana": "画質[がしつ]の低下[ていか]を防[ふせ]ぐため、写真[しゃしん]を何度[なんど]もコピーしない。", "sentence_source": "generated"}, {"text": "視力が低下したので、新しいめがねを買った。", "target_word": "低下", "complexity_tier": "T3", "furigana": "視力[しりょく]が低下[ていか]したので、新[あたら]しいめがねを買[か]った。", "sentence_source": "generated"}, {"text": "この町では、土地の価値が年々低下している。", "target_word": "低下", "complexity_tier": "T3", "furigana": "この町[まち]では、土地[とち]の価値[かち]が年々[ねんねん]低下[ていか]している。", "sentence_source": "generated"}, {"text": "血圧が低下したら、すぐに横になったほうがいい。", "target_word": "低下", "complexity_tier": "T3", "furigana": "血圧[けつあつ]が低下[ていか]したら、すぐに横[よこ]になったほうがいい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "低下する", "label": "dictionary form"}, {"form": "低下した", "label": "past"}, {"form": "低下して", "label": "te-form"}, {"form": "低下している", "label": "progressive"}, {"form": "低下しない", "label": "negative"}], "register": "neutral", "sense_fingerprint": "性能・水準・温度などの程度が以前より下がること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b8ac3e6-a2ff-4eb9-b4fb-6cf755747119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37673, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "低下", "is_correct": true, "explanation": "正解。性能が以前より下がることを表し、文に合う。"}, {"text": "作成", "is_correct": false, "explanation": "「性能が作成した」は成り立たない。作成は物や文書を新しくつくる語。"}, {"text": "分類", "is_correct": false, "explanation": "「性能が分類した」は意味が通らない。分類は物を種類ごとに分ける語。"}, {"text": "提案", "is_correct": false, "explanation": "「性能が提案した」は主語と動詞が合わない。提案は人が案を出す行為。"}], "explanations": {"低下": "正解。性能が以前より下がることを表し、文に合う。", "作成": "「性能が作成した」は成り立たない。作成は物や文書を新しくつくる語。", "分類": "「性能が分類した」は意味が通らない。分類は物を種類ごとに分ける語。", "提案": "「性能が提案した」は主語と動詞が合わない。提案は人が案を出す行為。"}, "sentence_index": 0, "correct_answer": "低下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "旅客機が山腹に低下した。", "explanation": "ここは〈墜落〉の意味。低下は性能や量が下がることで、機体が山に落ちる事故には使わない。"}, {"text": "列車が低下して、トンネルに入った。", "explanation": "低下は程度が下がることで、列車が下へ進む動きや場所の移動には使わない。"}, {"text": "石が崖から低下した。", "explanation": "ここは〈落下〉の意味。低下は物が落ちる動きを表さず、程度が下がる意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37673, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "低下", "is_correct": true, "explanation": "正解。画質が下がることを表し、「画質の＿を防ぐ」に入る。"}, {"text": "整理", "is_correct": false, "explanation": "「画質の整理を防ぐ」は意味が通らない。整理は物を片づける語。"}, {"text": "発見", "is_correct": false, "explanation": "「画質の発見を防ぐ」は成り立たない。発見は未知のものを見つける語。"}, {"text": "採用", "is_correct": false, "explanation": "「画質の採用を防ぐ」は合わない。採用は人を雇う、案を取り入れる語。"}], "explanations": {"低下": "正解。画質が下がることを表し、「画質の＿を防ぐ」に入る。", "整理": "「画質の整理を防ぐ」は意味が通らない。整理は物を片づける語。", "発見": "「画質の発見を防ぐ」は成り立たない。発見は未知のものを見つける語。", "採用": "「画質の採用を防ぐ」は合わない。採用は人を雇う、案を取り入れる語。"}, "sentence_index": 6, "correct_answer": "低下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雪が屋根から低下した。", "explanation": "ここは〈滑り落ちる〉の意味。低下は程度が下がることで、雪が屋根を滑る動きには使わない。"}, {"text": "潜水艦が深海へ低下した。", "explanation": "ここは〈沈没〉の意味。低下は程度が下がることで、潜水艦が海に沈むことには使わない。"}, {"text": "飛行機が着陸に向けて低下した。", "explanation": "ここは〈降下〉の意味。低下は性能や量が下がることで、高度を下げて降りていく動きには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37673, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒波で気温が低下て、水道管が凍った。", "corrected_sentence": "寒波で気温が低下して、水道管が凍った。", "error_description": "「低下」はサ変名詞なので、て形は『して』になる。『低下て』は『し』が抜けた誤りで、『低下して』が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37673, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "体温の低下に防ぐために、厚着をする。", "corrected_sentence": "体温の低下を防ぐために、厚着をする。", "error_description": "『防ぐ』の対象は『を』で示す。『低下に防ぐ』は『に』を使った誤りで、対象を示せない。『低下を防ぐ』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37674, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『下部に』で、名前を書く欄の位置を示す。"}, {"text": "を", "is_correct": false, "explanation": "『を』は目的語。『下部を名前を書く』は目的語が二つ重なり、文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "『が』は主語。『下部が名前を書く欄』と読まれ、位置を示せない。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較の基準。比べる対象がなく、位置を示せない。"}], "correct_answer": "に", "explanations": {"に": "『下部に』で、名前を書く欄の位置を示す。", "を": "『を』は目的語。『下部を名前を書く』は目的語が二つ重なり、文が成り立たない。", "が": "『が』は主語。『下部が名前を書く欄』と読まれ、位置を示せない。", "より": "『より』は比較の基準。比べる対象がなく、位置を示せない。"}, "error_tags": {"を": "目的語の格", "が": "主語の格", "より": "比較の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37674, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『下部に、縮尺が書いてある』で、書いてある位置を示す。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向。『下部へ』は位置ではなく方向の意味になり、書いてある場所を示せない。"}, {"text": "を", "is_correct": false, "explanation": "『を』は目的語。『下部を』に続く動詞がなく、『縮尺が書いてある』とも続かないので文が壊れる。"}, {"text": "の", "is_correct": false, "explanation": "『の』は名詞をつなぐ格。『下部の、縮尺が書いてある』は文が続かない。"}], "correct_answer": "に", "explanations": {"に": "『下部に、縮尺が書いてある』で、書いてある位置を示す。", "へ": "『へ』は方向。『下部へ』は位置ではなく方向の意味になり、書いてある場所を示せない。", "を": "『を』は目的語。『下部を』に続く動詞がなく、『縮尺が書いてある』とも続かないので文が壊れる。", "の": "『の』は名詞をつなぐ格。『下部の、縮尺が書いてある』は文が続かない。"}, "error_tags": {"へ": "方向の格", "を": "目的語の格", "の": "連体の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37674, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものの下の方の部分のこと。", "primary_collocate": null, "pronunciation": "かぶ", "ipa": "kabɯ", "syllable_count": 2, "sentences": [{"text": "柱の下部にひびが入っている。", "target_word": "下部", "complexity_tier": "T3", "furigana": "柱[はしら]の下部[かぶ]にひびが入[はい]っている。", "sentence_source": "generated"}, {"text": "紙の下部に名前を書く欄がある。", "target_word": "下部", "complexity_tier": "T3", "furigana": "紙[かみ]の下部[かぶ]に名前[なまえ]を書[か]く欄[らん]がある。", "sentence_source": "generated"}, {"text": "ビルの下部は店で、上の階は事務所だ。", "target_word": "下部", "complexity_tier": "T3", "furigana": "ビルの下部[かぶ]は店[みせ]で、上[うえ]の階[かい]は事務所[じむしょ]だ。", "sentence_source": "generated"}, {"text": "画面の下部に、字幕が出る。", "target_word": "下部", "complexity_tier": "T3", "furigana": "画面[がめん]の下部[かぶ]に、字幕[じまく]が出[で]る。", "sentence_source": "generated"}, {"text": "木の幹の下部は、苔で緑色になっていた。", "target_word": "下部", "complexity_tier": "T3", "furigana": "木[き]の幹[みき]の下部[かぶ]は、苔[こけ]で緑色[みどりいろ]になっていた。", "sentence_source": "generated"}, {"text": "山の下部は雲に隠れて見えなかった。", "target_word": "下部", "complexity_tier": "T3", "furigana": "山[やま]の下部[かぶ]は雲[くも]に隠[かく]れて見[み]えなかった。", "sentence_source": "generated"}, {"text": "箱の下部に穴があいていて、中身が落ちた。", "target_word": "下部", "complexity_tier": "T3", "furigana": "箱[はこ]の下部[かぶ]に穴[あな]があいていて、中身[なかみ]が落[お]ちた。", "sentence_source": "generated"}, {"text": "地図の下部に、縮尺が書いてある。", "target_word": "下部", "complexity_tier": "T3", "furigana": "地図[ちず]の下部[かぶ]に、縮尺[しゅくしゃく]が書[か]いてある。", "sentence_source": "generated"}, {"text": "冷蔵庫の下部には、野菜を入れる引き出しがある。", "target_word": "下部", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]の下部[かぶ]には、野菜[やさい]を入[い]れる引[ひ]き出[だ]しがある。", "sentence_source": "generated"}, {"text": "旗の下部が破れていて、風でばたばたと音を立てた。", "target_word": "下部", "complexity_tier": "T3", "furigana": "旗[はた]の下部[かぶ]が破[やぶ]れていて、風[かぜ]でばたばたと音[おと]を立[た]てた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "下部", "label": "dictionary form"}, {"form": "下部の", "label": "attributive with の"}, {"form": "下部に", "label": "location with に"}], "register": "neutral", "sense_fingerprint": "物の下の方にあたる部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b8ac3e6-a2ff-4eb9-b4fb-6cf755747119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37674, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下部", "is_correct": true, "explanation": "正解。物の下の方の部分を表し、「柱の＿にひびが入っている」に入る。"}, {"text": "作業", "is_correct": false, "explanation": "「柱の作業にひびが入っている」は意味が通らない。作業は人が行う仕事。"}, {"text": "説明", "is_correct": false, "explanation": "「柱の説明にひびが入っている」は成り立たない。説明は内容を伝える行為。"}, {"text": "注文", "is_correct": false, "explanation": "「柱の注文にひびが入っている」は合わない。注文は品物を頼む行為。"}], "explanations": {"下部": "正解。物の下の方の部分を表し、「柱の＿にひびが入っている」に入る。", "作業": "「柱の作業にひびが入っている」は意味が通らない。作業は人が行う仕事。", "説明": "「柱の説明にひびが入っている」は成り立たない。説明は内容を伝える行為。", "注文": "「柱の注文にひびが入っている」は合わない。注文は品物を頼む行為。"}, "sentence_index": 0, "correct_answer": "下部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来年の下部に、新しい工場が建つ。", "explanation": "ここは〈後半〉の意味。下部は物の下側を表す語で、期間の後半には使わない。"}, {"text": "午後の下部に会議がある。", "explanation": "ここは〈後半〉の意味。下部は物の形の下側を表す語で、時間の後半には使わない。"}, {"text": "会議の下部で、新商品が発表された。", "explanation": "ここは〈途中〉の意味。下部は物の下側にあたる部分で、出来事の一部を指す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37674, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下部", "is_correct": true, "explanation": "正解。箱の下の方の部分を表し、「箱の＿に穴があいていて」に入る。"}, {"text": "点検", "is_correct": false, "explanation": "「箱の点検に穴があいていて」は意味が通らない。点検は調べる行為。"}, {"text": "製造", "is_correct": false, "explanation": "「箱の製造に穴があいていて」は文が成り立たない。製造は物をつくる行為。"}, {"text": "代金", "is_correct": false, "explanation": "「箱の代金に穴があいていて」は合わない。代金は支払うお金。"}], "explanations": {"下部": "正解。箱の下の方の部分を表し、「箱の＿に穴があいていて」に入る。", "点検": "「箱の点検に穴があいていて」は意味が通らない。点検は調べる行為。", "製造": "「箱の製造に穴があいていて」は文が成り立たない。製造は物をつくる行為。", "代金": "「箱の代金に穴があいていて」は合わない。代金は支払うお金。"}, "sentence_index": 6, "correct_answer": "下部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来週の下部に、試験がある。", "explanation": "ここは〈後半〉の意味。下部は物の下側を表す語で、期間の後半には使わない。"}, {"text": "今季の下部に、チームの優勝が決まった。", "explanation": "ここは〈後半〉の意味。下部は物の下側を表す語で、期間の後半には使わない。"}, {"text": "先月の下部に、店の改装が決まった。", "explanation": "ここは〈後半〉の意味。下部は物の下側を表す語で、期間の後半には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37674, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "壁の下部を、古いポスターが貼られている。", "corrected_sentence": "壁の下部に、古いポスターが貼られている。", "error_description": "『下部』は場所を表すので、後ろには位置の『に』を使う。『を』は目的語を示す格で、位置の名詞には合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37674, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ドアの下部を泥で汚れている。", "corrected_sentence": "ドアの下部が泥で汚れている。", "error_description": "『汚れている』は主語に『が』を使う。『を』は目的語を示すので、主語になる『下部』に続けると文が壊れる。『ドアの下部が泥で汚れている』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37675, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『壁の下部』で、壁のうちの下の部分を示す。"}, {"text": "を", "is_correct": false, "explanation": "『壁を下部』は目的語になり、『色がちがっている』と続かない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向。『壁へ下部』は部分の関係を表せない。"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点。『壁から下部』は部分の関係を表せない。"}], "correct_answer": "の", "explanations": {"の": "『壁の下部』で、壁のうちの下の部分を示す。", "を": "『壁を下部』は目的語になり、『色がちがっている』と続かない。", "へ": "『へ』は方向。『壁へ下部』は部分の関係を表せない。", "から": "『から』は起点。『壁から下部』は部分の関係を表せない。"}, "error_tags": {"を": "目的語の格", "へ": "方向の格", "から": "起点の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37675, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『下部のふた』と続き、機械の下部にあるふたを示す。"}, {"text": "に", "is_correct": false, "explanation": "『に』は相手や着点。『機械に下部のふたを開けて』は機械を相手にする形になり、不自然。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較の基準。『下部よりふた』は比べる対象がなく、文が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向。『機械へ下部のふた』は名詞のつながりにならず、ふたの所在を示せない。"}], "correct_answer": "の", "explanations": {"の": "『下部のふた』と続き、機械の下部にあるふたを示す。", "に": "『に』は相手や着点。『機械に下部のふたを開けて』は機械を相手にする形になり、不自然。", "より": "『より』は比較の基準。『下部よりふた』は比べる対象がなく、文が通らない。", "へ": "『へ』は方向。『機械へ下部のふた』は名詞のつながりにならず、ふたの所在を示せない。"}, "error_tags": {"に": "相手・着点の格", "より": "比較の格", "へ": "方向の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37675, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物の下の方の部分。下側。", "primary_collocate": null, "pronunciation": "かぶ", "ipa": "kabɯ", "syllable_count": 2, "sentences": [{"text": "本棚の下部は重い本を置く場所だ。", "target_word": "下部", "complexity_tier": "T3", "furigana": "本棚[ほんだな]の下部[かぶ]は重[おも]い本[ほん]を置[お]く場所[ばしょ]だ。", "sentence_source": "generated"}, {"text": "壁の下部だけ色がちがっている。", "target_word": "下部", "complexity_tier": "T3", "furigana": "壁[かべ]の下部[かぶ]だけ色[いろ]がちがっている。", "sentence_source": "generated"}, {"text": "傘の下部にある留め具をおす。", "target_word": "下部", "complexity_tier": "T3", "furigana": "傘[かさ]の下部[かぶ]にある留[と]め具[ぐ]をおす。", "sentence_source": "generated"}, {"text": "体の下部が冷えると、風邪をひきやすい。", "target_word": "下部", "complexity_tier": "T3", "furigana": "体[からだ]の下部[かぶ]が冷[ひ]えると、風邪[かぜ]をひきやすい。", "sentence_source": "generated"}, {"text": "窓の下部が曇って、外が見えにくい。", "target_word": "下部", "complexity_tier": "T3", "furigana": "窓[まど]の下部[かぶ]が曇[くも]って、外[そと]が見[み]えにくい。", "sentence_source": "generated"}, {"text": "瓶の下部に、茶色いかすがたまっている。", "target_word": "下部", "complexity_tier": "T3", "furigana": "瓶[びん]の下部[かぶ]に、茶色[ちゃいろ]いかすがたまっている。", "sentence_source": "generated"}, {"text": "グラフの下部は、数字が小さい部分だ。", "target_word": "下部", "complexity_tier": "T3", "furigana": "グラフの下部[かぶ]は、数字[すうじ]が小[ちい]さい部分[ぶぶん]だ。", "sentence_source": "generated"}, {"text": "機械の下部のふたを開けて、電池を入れる。", "target_word": "下部", "complexity_tier": "T3", "furigana": "機械[きかい]の下部[かぶ]のふたを開[あ]けて、電池[でんち]を入[い]れる。", "sentence_source": "generated"}, {"text": "看板の下部がさびて、文字が読めない。", "target_word": "下部", "complexity_tier": "T3", "furigana": "看板[かんばん]の下部[かぶ]がさびて、文字[もじ]が読[よ]めない。", "sentence_source": "generated"}, {"text": "シャツの下部に汚れがついている。", "target_word": "下部", "complexity_tier": "T3", "furigana": "シャツの下部[かぶ]に汚[よご]れがついている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "下部", "label": "dictionary form"}, {"form": "下部の", "label": "attributive with の"}, {"form": "下部に", "label": "location with に"}], "register": "neutral", "sense_fingerprint": "物の下側にあたる部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b8ac3e6-a2ff-4eb9-b4fb-6cf755747119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37675, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下部", "is_correct": true, "explanation": "正解。物の下側の部分を表し、「本棚の＿は重い本を置く場所だ」に入る。"}, {"text": "作業", "is_correct": false, "explanation": "「本棚の作業は重い本を置く場所だ」は意味が通らない。作業は人が行う仕事。"}, {"text": "説明", "is_correct": false, "explanation": "「本棚の説明は重い本を置く場所だ」は成り立たない。説明は内容を伝える行為。"}, {"text": "注文", "is_correct": false, "explanation": "「本棚の注文は重い本を置く場所だ」は合わない。注文は品物を頼む行為。"}], "explanations": {"下部": "正解。物の下側の部分を表し、「本棚の＿は重い本を置く場所だ」に入る。", "作業": "「本棚の作業は重い本を置く場所だ」は意味が通らない。作業は人が行う仕事。", "説明": "「本棚の説明は重い本を置く場所だ」は成り立たない。説明は内容を伝える行為。", "注文": "「本棚の注文は重い本を置く場所だ」は合わない。注文は品物を頼む行為。"}, "sentence_index": 0, "correct_answer": "下部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来月の下部に、旅行の予定を入れた。", "explanation": "ここは〈後半〉の意味。下部は物の下側を表す語で、期間の後半には使わない。"}, {"text": "新人は午後の下部で、基礎から一年間鍛えられた。", "explanation": "ここは〈後半〉の意味。下部は物の下側を表す語で、期間の後半には使わない。"}, {"text": "会議の下部で、新商品が発表された。", "explanation": "ここは〈途中〉の意味。下部は物の下側にあたる部分で、出来事の一部を指す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37675, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下部", "is_correct": true, "explanation": "正解。シャツの下の方の部分を表し、「シャツの＿に汚れがついている」に入る。"}, {"text": "点検", "is_correct": false, "explanation": "「シャツの点検に汚れがついている」は意味が通らない。点検は調べる行為。"}, {"text": "製造", "is_correct": false, "explanation": "「シャツの製造に汚れがついている」は文が成り立たない。製造は物をつくる行為。"}, {"text": "代金", "is_correct": false, "explanation": "「シャツの代金に汚れがついている」は合わない。代金は支払うお金。"}], "explanations": {"下部": "正解。シャツの下の方の部分を表し、「シャツの＿に汚れがついている」に入る。", "点検": "「シャツの点検に汚れがついている」は意味が通らない。点検は調べる行為。", "製造": "「シャツの製造に汚れがついている」は文が成り立たない。製造は物をつくる行為。", "代金": "「シャツの代金に汚れがついている」は合わない。代金は支払うお金。"}, "sentence_index": 6, "correct_answer": "下部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来季の下部に、新しい選手が入る。", "explanation": "ここは〈後半〉の意味。下部は物の下側を表す語で、期間の後半には使わない。"}, {"text": "人生の下部で、大きな夢を見る。", "explanation": "ここは〈後半〉の意味。下部は物の下側を表す語で、人生の時期には使わない。"}, {"text": "経済的に苦しい下部の家庭に、食料を届ける活動が続いている。", "explanation": "ここは〈下層〉の語を使う場面（社会の経済的に低い層）。下部は物の下の方を表す語なので、社会階層の意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37675, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "机の下部を、傷がついている。", "corrected_sentence": "机の下部に、傷がついている。", "error_description": "『下部』は場所を表すので、後ろには位置の『に』を使う。『を』は目的語を示す格で、位置の名詞には合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37675, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "袋の下部が叫ばれている。", "corrected_sentence": "袋の下部が縫われている。", "error_description": "『下部』と続く動詞は、布や袋の縫い目に関する動詞にする。『叫ばれ』は声に関する語で、袋には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37676, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『売り上げ』は比較の対象なので、『を』で示すのが正しい"}, {"text": "が", "is_correct": false, "explanation": "主語を示す『が』では売り上げが比較する主体になり、文が通らない"}, {"text": "に", "is_correct": false, "explanation": "相手や帰着点を示す『に』では比較の対象を表せない"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す『へ』は、比較の対象を指すには使えない"}], "correct_answer": "を", "explanations": {"を": "『売り上げ』は比較の対象なので、『を』で示すのが正しい", "が": "主語を示す『が』では売り上げが比較する主体になり、文が通らない", "に": "相手や帰着点を示す『に』では比較の対象を表せない", "へ": "方向を示す『へ』は、比較の対象を指すには使えない"}, "error_tags": {"が": "主語", "に": "相手・帰着点", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37676, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『写真』は比較の対象なので、『を』で示すのが正しい"}, {"text": "より", "is_correct": false, "explanation": "比べる基準を示す『より』は、比較の対象を直接示せない"}, {"text": "が", "is_correct": false, "explanation": "主語を示す『が』では写真が比較する主体になり、文が通らない"}, {"text": "の", "is_correct": false, "explanation": "名詞を連ねる『の』では動詞の目的語にならず、文が通らない"}], "correct_answer": "を", "explanations": {"を": "『写真』は比較の対象なので、『を』で示すのが正しい", "より": "比べる基準を示す『より』は、比較の対象を直接示せない", "が": "主語を示す『が』では写真が比較する主体になり、文が通らない", "の": "名詞を連ねる『の』では動詞の目的語にならず、文が通らない"}, "error_tags": {"より": "比較の基準", "の": "連体修飾", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37676, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "二つのものをくらべて、同じところやちがうところを考えること。", "primary_collocate": null, "pronunciation": "ひかく", "ipa": "çikakɯ", "syllable_count": 3, "sentences": [{"text": "二つの店の値段を比較してから買う。", "target_word": "比較", "complexity_tier": "T3", "furigana": "二[ふた]つの店[みせ]の値段[ねだん]を比較[ひかく]してから買[か]う。", "sentence_source": "generated"}, {"text": "去年と今年の売り上げを比較する。", "target_word": "比較", "complexity_tier": "T3", "furigana": "去年[きょねん]と今年[ことし]の売[う]り上[あ]げを比較[ひかく]する。", "sentence_source": "generated"}, {"text": "他人と比較ばかりすると、自分がいやになる。", "target_word": "比較", "complexity_tier": "T3", "furigana": "他人[たにん]と比較[ひかく]ばかりすると、自分[じぶん]がいやになる。", "sentence_source": "generated"}, {"text": "日本と韓国の食べ物を比較して、発表した。", "target_word": "比較", "complexity_tier": "T3", "furigana": "日本[にほん]と韓国[かんこく]の食[た]べ物[もの]を比較[ひかく]して、発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "比較すると、こちらのほうが軽い。", "target_word": "比較", "complexity_tier": "T3", "furigana": "比較[ひかく]すると、こちらのほうが軽[かる]い。", "sentence_source": "generated"}, {"text": "二つの辞書を比較して、説明のわかりやすい方を選んだ。", "target_word": "比較", "complexity_tier": "T3", "furigana": "二[ふた]つの辞書[じしょ]を比較[ひかく]して、説明[せつめい]のわかりやすい方[ほう]を選[えら]んだ。", "sentence_source": "generated"}, {"text": "兄と比較されるのが、子どものころからいやだった。", "target_word": "比較", "complexity_tier": "T3", "furigana": "兄[あに]と比較[ひかく]されるのが、子[こ]どものころからいやだった。", "sentence_source": "generated"}, {"text": "新旧の写真を比較すれば、町の変化がよくわかる。", "target_word": "比較", "complexity_tier": "T3", "furigana": "新旧[しんきゅう]の写真[しゃしん]を比較[ひかく]すれば、町[まち]の変化[へんか]がよくわかる。", "sentence_source": "generated"}, {"text": "二つの案を比較した結果、安いほうに決まった。", "target_word": "比較", "complexity_tier": "T3", "furigana": "二[ふた]つの案[あん]を比較[ひかく]した結果[けっか]、安[やす]いほうに決[き]まった。", "sentence_source": "generated"}, {"text": "比較のために、同じ条件で実験をする。", "target_word": "比較", "complexity_tier": "T3", "furigana": "比較[ひかく]のために、同[おな]じ条件[じょうけん]で実験[じっけん]をする。", "sentence_source": "generated"}], "morphological_forms": [{"form": "比較する", "label": "dictionary form"}, {"form": "比較した", "label": "past"}, {"form": "比較して", "label": "te-form"}, {"form": "比較される", "label": "passive"}, {"form": "比較しない", "label": "negative"}], "register": "neutral", "sense_fingerprint": "二つのものをくらべて同じ点やちがう点を考えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b8ac3e6-a2ff-4eb9-b4fb-6cf755747119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37676, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比較", "is_correct": true, "explanation": "二つの店の値段を並べて違いを見る、という意味で文に合う"}, {"text": "感謝", "is_correct": false, "explanation": "値段に感謝するとは言わず、文の流れに合わない"}, {"text": "注文", "is_correct": false, "explanation": "値段を注文するとは言わず、店に品物を頼む意味になってしまう"}, {"text": "包装", "is_correct": false, "explanation": "値段を包装することはできず、文が通らない"}], "explanations": {"比較": "二つの店の値段を並べて違いを見る、という意味で文に合う", "感謝": "値段に感謝するとは言わず、文の流れに合わない", "注文": "値段を注文するとは言わず、店に品物を頼む意味になってしまう", "包装": "値段を包装することはできず、文が通らない"}, "sentence_index": 0, "correct_answer": "比較"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "事故を見て、すぐに警察に比較した。", "explanation": "ここは〈通報〉の意味。比較は物事を並べて違いを調べる行為で、知らせる意味では使わない。"}, {"text": "手がかりをもとに、犯人の正体を比較した。", "explanation": "ここは〈推理〉の意味。比較は二つ以上を並べる行為で、手がかりから一人の正体を割り出す意味にはならない。"}, {"text": "朝、教室で先生に比較した。", "explanation": "ここは〈挨拶〉の意味。比較は物事の違いを見る行為で、人に向けて礼をする意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37676, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比較", "is_correct": true, "explanation": "兄と並べて違いを見ることを表し、文に自然につながる"}, {"text": "掃除", "is_correct": false, "explanation": "兄と掃除されるという形は意味が通らず、文が成り立たない"}, {"text": "収穫", "is_correct": false, "explanation": "兄と収穫されるという形は、文の流れに合わない"}, {"text": "出発", "is_correct": false, "explanation": "兄と出発されるという形にはならない"}], "explanations": {"比較": "兄と並べて違いを見ることを表し、文に自然につながる", "掃除": "兄と掃除されるという形は意味が通らず、文が成り立たない", "収穫": "兄と収穫されるという形は、文の流れに合わない", "出発": "兄と出発されるという形にはならない"}, "sentence_index": 6, "correct_answer": "比較"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来月の大会に比較した。", "explanation": "ここは〈申し込む〉の意味。比較は物を並べて違いを調べる行為で、大会へ参加の手続きをする意味にはならない。"}, {"text": "寝坊して、先生に比較した。", "explanation": "ここは〈謝る〉の意味。比較は物事を並べる行為で、相手に詫びる意味では使わない。"}, {"text": "悲しくて比較した。", "explanation": "ここは〈泣く〉の意味。比較は二つ以上を並べる行為で、感情の表現には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37676, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい案を古い案へ比較した結果、安いほうに決まった。", "corrected_sentence": "新しい案を古い案と比較した結果、安いほうに決まった。", "error_description": "比べる相手は『と』で示す。『へ』は方向を表す助詞なので、比較の相手には使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
