INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37677, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "二つ以上の物事を比べて、その違いや共通点を調べること。", "primary_collocate": null, "pronunciation": "ひかく", "ipa": "çikakɯ", "syllable_count": 3, "sentences": [{"text": "三つの会社の給料を比較する。", "target_word": "比較", "complexity_tier": "T3", "furigana": "三[みっ]つの会社[かいしゃ]の給料[きゅうりょう]を比較[ひかく]する。", "sentence_source": "generated"}, {"text": "表で各国の人口を比較した。", "target_word": "比較", "complexity_tier": "T3", "furigana": "表[ひょう]で各国[かっこく]の人口[じんこう]を比較[ひかく]した。", "sentence_source": "generated"}, {"text": "複数の商品を比較し、品質を調べた。", "target_word": "比較", "complexity_tier": "T3", "furigana": "複数[ふくすう]の商品[しょうひん]を比較[ひかく]し、品質[ひんしつ]を調[しら]べた。", "sentence_source": "generated"}, {"text": "他の地域と比較して、この町は雨が少ない。", "target_word": "比較", "complexity_tier": "T3", "furigana": "他[ほか]の地域[ちいき]と比較[ひかく]して、この町[まち]は雨[あめ]が少[すく]ない。", "sentence_source": "generated"}, {"text": "正確に比較するには、同じ方法で調べることが大切だ。", "target_word": "比較", "complexity_tier": "T3", "furigana": "正確[せいかく]に比較[ひかく]するには、同[おな]じ方法[ほうほう]で調[しら]べることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "四つの方法を比較した結果、共通点が見つかった。", "target_word": "比較", "complexity_tier": "T3", "furigana": "四[よっ]つの方法[ほうほう]を比較[ひかく]した結果[けっか]、共通点[きょうつうてん]が見[み]つかった。", "sentence_source": "generated"}, {"text": "価格を比較できるサイトで、安いホテルをさがした。", "target_word": "比較", "complexity_tier": "T3", "furigana": "価格[かかく]を比較[ひかく]できるサイトで、安[やす]いホテルをさがした。", "sentence_source": "generated"}, {"text": "昔の言葉と今の言葉を比較して、変化を調べる。", "target_word": "比較", "complexity_tier": "T3", "furigana": "昔[むかし]の言葉[ことば]と今[いま]の言葉[ことば]を比較[ひかく]して、変化[へんか]を調[しら]べる。", "sentence_source": "generated"}, {"text": "新しい薬と古い薬を比較する実験が行われた。", "target_word": "比較", "complexity_tier": "T3", "furigana": "新[あたら]しい薬[くすり]と古[ふる]い薬[くすり]を比較[ひかく]する実験[じっけん]が行[おこな]われた。", "sentence_source": "generated"}, {"text": "三人の意見を比較して、共通点をまとめた。", "target_word": "比較", "complexity_tier": "T3", "furigana": "三人[さんにん]の意見[いけん]を比較[ひかく]して、共通点[きょうつうてん]をまとめた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "比較する", "label": "dictionary form"}, {"form": "比較した", "label": "past"}, {"form": "比較して", "label": "te-form"}, {"form": "比較できる", "label": "potential"}, {"form": "比較しない", "label": "negative"}], "register": "neutral", "sense_fingerprint": "複数の物事を比べて違いや共通点を調べること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b8ac3e6-a2ff-4eb9-b4fb-6cf755747119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37677, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比較", "is_correct": true, "explanation": "三つの会社の給料を並べて違いを見ることを表し、文に合う"}, {"text": "翻訳", "is_correct": false, "explanation": "給料を翻訳するとは言わず、文が通らない"}, {"text": "注意", "is_correct": false, "explanation": "給料に注意するという言い方は不自然で、文の意味が通らない"}, {"text": "栽培", "is_correct": false, "explanation": "給料を栽培することはできず、文が通らない"}], "explanations": {"比較": "三つの会社の給料を並べて違いを見ることを表し、文に合う", "翻訳": "給料を翻訳するとは言わず、文が通らない", "注意": "給料に注意するという言い方は不自然で、文の意味が通らない", "栽培": "給料を栽培することはできず、文が通らない"}, "sentence_index": 0, "correct_answer": "比較"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "事故を見て、すぐに消防署に比較した。", "explanation": "ここは〈通報〉の意味。比較は物事を並べて違いを調べる行為で、知らせる意味では使わない。"}, {"text": "証拠をもとに、容疑者の正体を比較した。", "explanation": "ここは〈推理〉の意味。比較は二つ以上を並べる行為で、証拠から一人の正体を割り出す意味にはならない。"}, {"text": "朝、会社の受付で社長に比較した。", "explanation": "ここは〈挨拶〉の意味。比較は物事の違いを見る行為で、人に向けて礼をする意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37677, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比較", "is_correct": true, "explanation": "価格を並べて比べられる、という意味で文に合う"}, {"text": "包装", "is_correct": false, "explanation": "価格を包装できるとは言わず、文が通らない"}, {"text": "感謝", "is_correct": false, "explanation": "価格に感謝できるとは言わず、文の意味が通らない"}, {"text": "出発", "is_correct": false, "explanation": "価格を出発させるという言い方はなく、文が通らない"}], "explanations": {"比較": "価格を並べて比べられる、という意味で文に合う", "包装": "価格を包装できるとは言わず、文が通らない", "感謝": "価格に感謝できるとは言わず、文の意味が通らない", "出発": "価格を出発させるという言い方はなく、文が通らない"}, "sentence_index": 6, "correct_answer": "比較"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "次のコンテストに比較した。", "explanation": "ここは〈申し込む〉の意味。比較は物を並べて違いを調べる行為で、大会への参加手続きの意味にはならない。"}, {"text": "遅刻して、友人に比較した。", "explanation": "ここは〈謝る〉の意味。比較は物事を並べる行為で、相手に詫びる意味では使わない。"}, {"text": "痛くて比較した。", "explanation": "ここは〈泣く〉の意味。比較は二つ以上を並べる行為で、痛みによる反応を表す言葉ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37677, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二つの会社の給料が比較して、差を調べた。", "corrected_sentence": "二つの会社の給料を比較して、差を調べた。", "error_description": "比較の対象は『を』で示す。『が』は主語の格助詞なので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37677, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三人の意見比較して、違いをまとめた。", "corrected_sentence": "三人の意見を比較して、違いをまとめた。", "error_description": "比較の対象の後には『を』が必要。省くと文が不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
