INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37678, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "でこぼこがない、平らなこと。", "primary_collocate": null, "pronunciation": "へいたん", "ipa": "heːtaɴ", "syllable_count": 4, "sentences": [{"text": "この道は石も穴もなく、とても平坦だ。", "target_word": "平坦", "complexity_tier": "T3", "furigana": "この道[みち]は石[いし]も穴[あな]もなく、とても平坦[へいたん]だ。", "sentence_source": "generated"}, {"text": "畑の土をならして、平坦にした。", "target_word": "平坦", "complexity_tier": "T3", "furigana": "畑[はたけ]の土[つち]をならして、平坦[へいたん]にした。", "sentence_source": "generated"}, {"text": "山を越えると、平坦な土地が広がっていた。", "target_word": "平坦", "complexity_tier": "T3", "furigana": "山[やま]を越[こ]えると、平坦[へいたん]な土地[とち]が広[ひろ]がっていた。", "sentence_source": "generated"}, {"text": "平坦な道なので、自転車でも疲れない。", "target_word": "平坦", "complexity_tier": "T3", "furigana": "平坦[へいたん]な道[みち]なので、自転車[じてんしゃ]でも疲[つか]れない。", "sentence_source": "generated"}, {"text": "坂ばかりの町とちがって、ここは平坦だから歩きやすい。", "target_word": "平坦", "complexity_tier": "T3", "furigana": "坂[さか]ばかりの町[まち]とちがって、ここは平坦[へいたん]だから歩[ある]きやすい。", "sentence_source": "generated"}, {"text": "工事のあと、グラウンドは平坦になり、ボールがまっすぐ転がる。", "target_word": "平坦", "complexity_tier": "T3", "furigana": "工事[こうじ]のあと、グラウンドは平坦[へいたん]になり、ボールがまっすぐ転[ころ]がる。", "sentence_source": "generated"}, {"text": "平坦な場所を選んで、テントを立てた。", "target_word": "平坦", "complexity_tier": "T3", "furigana": "平坦[へいたん]な場所[ばしょ]を選[えら]んで、テントを立[た]てた。", "sentence_source": "generated"}, {"text": "山道は岩が多くて、平坦ではない。", "target_word": "平坦", "complexity_tier": "T3", "furigana": "山道[やまみち]は岩[いわ]が多[おお]くて、平坦[へいたん]ではない。", "sentence_source": "generated"}, {"text": "雪が降って、でこぼこの道が平坦に見えた。", "target_word": "平坦", "complexity_tier": "T3", "furigana": "雪[ゆき]が降[ふ]って、でこぼこの道[みち]が平坦[へいたん]に見[み]えた。", "sentence_source": "generated"}, {"text": "平坦な砂浜を、子どもたちが走っている。", "target_word": "平坦", "complexity_tier": "T3", "furigana": "平坦[へいたん]な砂浜[すなはま]を、子[こ]どもたちが走[はし]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "平坦だ", "label": "終止形"}, {"form": "平坦な", "label": "連体形"}, {"form": "平坦に", "label": "連用形"}, {"form": "平坦で", "label": "連用形(て形)"}], "register": "標準", "sense_fingerprint": "道や土地にでこぼこがなく平らなようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04de0b4-b7c5-4a40-b388-094939d08f82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37678, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平坦", "is_correct": true, "explanation": "空欄に入る語。「とても〜だ」で、道に石や穴がない様子を表す。"}, {"text": "鮮やか", "is_correct": false, "explanation": "色や印象を表す語で、路面の平らさの説明には使わない。"}, {"text": "陽気", "is_correct": false, "explanation": "人や雰囲気の明るさを表す語で、道の状態には合わない。"}, {"text": "静か", "is_correct": false, "explanation": "音や雰囲気を表す語で、路面の状態を述べる文には合わない。"}], "explanations": {"平坦": "空欄に入る語。「とても〜だ」で、道に石や穴がない様子を表す。", "鮮やか": "色や印象を表す語で、路面の平らさの説明には使わない。", "陽気": "人や雰囲気の明るさを表す語で、道の状態には合わない。", "静か": "音や雰囲気を表す語で、路面の状態を述べる文には合わない。"}, "sentence_index": 0, "correct_answer": "平坦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ケーキを子どもたち全員に平坦に配った。", "explanation": "平坦は表面にでこぼこがないことを表すので、分配の公平さは表せない。"}, {"text": "雨に打たれても、あの犬は平坦だ。", "explanation": "平坦は表面の凹凸がないことを表すので、雨に動じない様子は表せない。"}, {"text": "ボールは平坦に跳ね返り、高く弾んだ。", "explanation": "平坦は表面の凹凸がないことを表すので、高く弾む軌道には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37678, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平坦", "is_correct": true, "explanation": "空欄に入る語。「〜な場所」で、テントを張れる平らな場所を表す。"}, {"text": "大胆", "is_correct": false, "explanation": "性格や行動の形容で、場所の形状には使わない。"}, {"text": "陽気", "is_correct": false, "explanation": "人や雰囲気の明るさを表す語で、場所の状態には合わない。"}, {"text": "乱暴", "is_correct": false, "explanation": "人の振る舞いを表す語で、場所の状態には使えない。"}], "explanations": {"平坦": "空欄に入る語。「〜な場所」で、テントを張れる平らな場所を表す。", "大胆": "性格や行動の形容で、場所の形状には使わない。", "陽気": "人や雰囲気の明るさを表す語で、場所の状態には合わない。", "乱暴": "人の振る舞いを表す語で、場所の状態には使えない。"}, "sentence_index": 6, "correct_answer": "平坦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は平坦と答えた。", "explanation": "平坦は表面の状態を表す語で、人の態度には使えない。"}, {"text": "彼は平坦で机をたたいた。", "explanation": "平坦は地形や表面の形容で、手のひらの形には使えない。"}, {"text": "紙を平坦に丸めた。", "explanation": "平坦は表面の状態を表す語で、丸める動作の説明には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37678, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この道は平坦を、自転車で楽に走れる。", "corrected_sentence": "この道は平坦で、自転車で楽に走れる。", "error_description": "「平坦」に続く助詞が誤り。「平坦を」では目的語になり文が成り立たない。状態を述べて後続に続けるには「平坦で」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "平坦に", "is_correct": true, "explanation": "連用形。「にした」の前に置き、土を平らにした結果を表す。"}, {"text": "平坦だ", "is_correct": false, "explanation": "終止形。文末で言い切る形で、「にした」の位置には入らない。"}, {"text": "平坦な", "is_correct": false, "explanation": "連体形。後ろに名詞が続く形で、「にした」の前には置けない。"}, {"text": "平坦で", "is_correct": false, "explanation": "て形。「〜で、〜」と続ける形で、「にした」の文には合わない。"}], "correct_form": "平坦に", "base_form": "平坦", "form_label": "連用形", "sentence_index": 1, "explanations": {"平坦に": "連用形。「にした」の前に置き、土を平らにした結果を表す。", "平坦だ": "終止形。文末で言い切る形で、「にした」の位置には入らない。", "平坦な": "連体形。後ろに名詞が続く形で、「にした」の前には置けない。", "平坦で": "て形。「〜で、〜」と続ける形で、「にした」の文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37678, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "平坦に石を見つけて、水面に投げて遊んだ。", "corrected_sentence": "平坦な石を見つけて、水面に投げて遊んだ。", "error_description": "連用形「平坦に」は直後の石ではなく動詞「見つけて」を修飾してしまい、平らな石の意味にならない。石を修飾するには連体形「平坦な」が必要。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "平坦ではない", "is_correct": true, "explanation": "否定形。「岩が多くて、」に続けて平らでないことを言い切る形。"}, {"text": "平坦だった", "is_correct": false, "explanation": "過去形。過去の状態を表すので、現在の否定文には合わない。"}, {"text": "平坦だ", "is_correct": false, "explanation": "肯定形。岩が多いという前文と合わず、否定の文にならない。"}, {"text": "平坦さ", "is_correct": false, "explanation": "名詞化した形。文の述語にはならず、「ではない」とは結びつかない。"}], "correct_form": "平坦ではない", "base_form": "平坦", "form_label": "否定形", "sentence_index": 7, "explanations": {"平坦ではない": "否定形。「岩が多くて、」に続けて平らでないことを言い切る形。", "平坦だった": "過去形。過去の状態を表すので、現在の否定文には合わない。", "平坦だ": "肯定形。岩が多いという前文と合わず、否定の文にならない。", "平坦さ": "名詞化した形。文の述語にはならず、「ではない」とは結びつかない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
