INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37679, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "でこぼこや傾きがなく、表面が平らなようす。", "primary_collocate": null, "pronunciation": "へいたん", "ipa": "heːtaɴ", "syllable_count": 4, "sentences": [{"text": "机の上が平坦でないと、ペンが転がってしまう。", "target_word": "平坦", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]が平坦[へいたん]でないと、ペンが転[ころ]がってしまう。", "sentence_source": "generated"}, {"text": "このテーブルは表面が平坦で、字が書きやすい。", "target_word": "平坦", "complexity_tier": "T3", "furigana": "このテーブルは表面[ひょうめん]が平坦[へいたん]で、字[じ]が書[か]きやすい。", "sentence_source": "generated"}, {"text": "平坦な床の上にボールを置くと、止まったままだった。", "target_word": "平坦", "complexity_tier": "T3", "furigana": "平坦[へいたん]な床[ゆか]の上[うえ]にボールを置[お]くと、止[と]まったままだった。", "sentence_source": "generated"}, {"text": "屋根が平坦で傾きがないから、雨水がたまりやすい。", "target_word": "平坦", "complexity_tier": "T3", "furigana": "屋根[やね]が平坦[へいたん]で傾[かたむ]きがないから、雨水[あまみず]がたまりやすい。", "sentence_source": "generated"}, {"text": "平坦な板の上に、ガラスのコップを置いた。", "target_word": "平坦", "complexity_tier": "T3", "furigana": "平坦[へいたん]な板[いた]の上[うえ]に、ガラスのコップを置[お]いた。", "sentence_source": "generated"}, {"text": "地面を平坦にならしてから、タイルを敷く。", "target_word": "平坦", "complexity_tier": "T3", "furigana": "地面[じめん]を平坦[へいたん]にならしてから、タイルを敷[し]く。", "sentence_source": "generated"}, {"text": "平坦な石を探して、水面に投げて遊んだ。", "target_word": "平坦", "complexity_tier": "T3", "furigana": "平坦[へいたん]な石[いし]を探[さが]して、水面[すいめん]に投[な]げて遊[あそ]んだ。", "sentence_source": "generated"}, {"text": "この鏡は表面が平坦で、顔がゆがまずに映る。", "target_word": "平坦", "complexity_tier": "T3", "furigana": "この鏡[かがみ]は表面[ひょうめん]が平坦[へいたん]で、顔[かお]がゆがまずに映[うつ]る。", "sentence_source": "generated"}, {"text": "斜めの台ではなく、平坦な台の上で実験をする。", "target_word": "平坦", "complexity_tier": "T3", "furigana": "斜[なな]めの台[だい]ではなく、平坦[へいたん]な台[だい]の上[うえ]で実験[じっけん]をする。", "sentence_source": "generated"}, {"text": "平坦な棚なので、丸い缶を置いても転がらない。", "target_word": "平坦", "complexity_tier": "T3", "furigana": "平坦[へいたん]な棚[たな]なので、丸[まる]い缶[かん]を置[お]いても転[ころ]がらない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "平坦だ", "label": "終止形"}, {"form": "平坦な", "label": "連体形"}, {"form": "平坦に", "label": "連用形"}, {"form": "平坦で", "label": "連用形(て形)"}], "register": "標準", "sense_fingerprint": "物の表面に凹凸も傾きもなく平らなようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T4: contains vocabulary far above tier T4: ゆがま (Zipf 1.36)']::text[], 'a04de0b4-b7c5-4a40-b388-094939d08f82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37679, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平坦", "is_correct": true, "explanation": "空欄に入る語。「〜でないと」で、机の表面に凹凸がある場合の条件を述べる。"}, {"text": "鮮やか", "is_correct": false, "explanation": "色の形容で、机の表面の状態には合わない。"}, {"text": "静か", "is_correct": false, "explanation": "音や雰囲気を表す語で、表面の状態には使えない。"}, {"text": "豊か", "is_correct": false, "explanation": "量や内容の豊富さを表す語で、表面の状態には使えない。"}], "explanations": {"平坦": "空欄に入る語。「〜でないと」で、机の表面に凹凸がある場合の条件を述べる。", "鮮やか": "色の形容で、机の表面の状態には合わない。", "静か": "音や雰囲気を表す語で、表面の状態には使えない。", "豊か": "量や内容の豊富さを表す語で、表面の状態には使えない。"}, "sentence_index": 0, "correct_answer": "平坦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "お茶を平坦に入れた。", "explanation": "平坦は表面の状態を表す語で、飲み物を注ぐ動作には使えない。"}, {"text": "子どもが平坦に走り回った。", "explanation": "平坦は表面の状態を表すので、人の動きの勢いには使えない。"}, {"text": "手紙を平坦で書いた。", "explanation": "平坦は表面の形容で、文字の種類は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37679, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平坦", "is_correct": true, "explanation": "空欄に入る語。「〜な石」で、水面に投げて跳ねる平らな石を表す。"}, {"text": "陽気", "is_correct": false, "explanation": "人や雰囲気の明るさを表す語で、石の状態には使わない。"}, {"text": "大胆", "is_correct": false, "explanation": "行動の形容で、石の形状には使えない。"}, {"text": "乱暴", "is_correct": false, "explanation": "人の振る舞いを表す語で、石を探す文には合わない。"}], "explanations": {"平坦": "空欄に入る語。「〜な石」で、水面に投げて跳ねる平らな石を表す。", "陽気": "人や雰囲気の明るさを表す語で、石の状態には使わない。", "大胆": "行動の形容で、石の形状には使えない。", "乱暴": "人の振る舞いを表す語で、石を探す文には合わない。"}, "sentence_index": 6, "correct_answer": "平坦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は平坦で棚をたたいた。", "explanation": "平坦は表面の形容で、手のひらの形には使えない。"}, {"text": "熱を測ったら、平坦だった。", "explanation": "平坦は表面の凹凸がないことで、体温の正常さは表せない。"}, {"text": "水を平坦に注いだ。", "explanation": "平坦は表面の状態を表す語で、水の注ぎ方には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37679, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "床が平坦を、ボールが止まりやすい。", "corrected_sentence": "床が平坦で、ボールが止まりやすい。", "error_description": "「平坦を」の「を」が誤り。状態を表して後続に続けるには「平坦で」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "平坦で", "is_correct": true, "explanation": "て形。「表面が平坦で、」と続けて後ろの文につなぐ形。"}, {"text": "平坦だ", "is_correct": false, "explanation": "終止形。文末で言い切る形で、「字が書きやすい」の前には置けない。"}, {"text": "平坦な", "is_correct": false, "explanation": "連体形。後ろに名詞が続く形で、「表面が」の述語には使えない。"}, {"text": "平坦に", "is_correct": false, "explanation": "連用形。「〜に」で用言を修飾する形で、「で、」と続く文には合わない。"}], "correct_form": "平坦で", "base_form": "平坦", "form_label": "連用形(て形)", "sentence_index": 1, "explanations": {"平坦で": "て形。「表面が平坦で、」と続けて後ろの文につなぐ形。", "平坦だ": "終止形。文末で言い切る形で、「字が書きやすい」の前には置けない。", "平坦な": "連体形。後ろに名詞が続く形で、「表面が」の述語には使えない。", "平坦に": "連用形。「〜に」で用言を修飾する形で、「で、」と続く文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37679, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "平坦だ板を置いて、コップを乗せた。", "corrected_sentence": "平坦な板を置いて、コップを乗せた。", "error_description": "名詞「板」を修飾する部分で「平坦だ」になっている。名詞の前では連体形「平坦な」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "平坦で", "is_correct": true, "explanation": "て形。「表面が平坦で、」と続けて後ろの文につなぐ形。"}, {"text": "平坦だった", "is_correct": false, "explanation": "過去形。現在の状態を表す文には合わない。"}, {"text": "平坦じゃない", "is_correct": false, "explanation": "口語の否定形。「表面が」の後の述語として「で、」と続く文には入らない。"}, {"text": "平坦さ", "is_correct": false, "explanation": "名詞化した形。述語にはならず、「で、顔が」の文には合わない。"}], "correct_form": "平坦で", "base_form": "平坦", "form_label": "連用形(て形)", "sentence_index": 7, "explanations": {"平坦で": "て形。「表面が平坦で、」と続けて後ろの文につなぐ形。", "平坦だった": "過去形。現在の状態を表す文には合わない。", "平坦じゃない": "口語の否定形。「表面が」の後の述語として「で、」と続く文には入らない。", "平坦さ": "名詞化した形。述語にはならず、「で、顔が」の文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37680, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「面」が「平らな」の主語を示す「が」。文が自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」は「平らな」の主語にならず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "場所・方向の「に」は主語にならず、「面に平らな」では文の構造が合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」は主語を作れず、「面と平らな」と続けると意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「面」が「平らな」の主語を示す「が」。文が自然に続く。", "を": "目的語の「を」は「平らな」の主語にならず、文が成り立たない。", "に": "場所・方向の「に」は主語にならず、「面に平らな」では文の構造が合わない。", "と": "並列の「と」は主語を作れず、「面と平らな」と続けると意味が通らない。"}, "error_tags": {"を": "目的語", "に": "場所・方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37680, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37680, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものの外側の平らなところ。", "primary_collocate": null, "pronunciation": "めん", "ipa": "meɴ", "syllable_count": 2, "sentences": [{"text": "立方体には六つの面があります。", "target_word": "面", "complexity_tier": "T3", "furigana": "立方体[りっぽうたい]には六[むっ]つの面[めん]があります。", "sentence_source": "generated"}, {"text": "この箱は面が平らなので、積み重ねやすい。", "target_word": "面", "complexity_tier": "T3", "furigana": "この箱[はこ]は面[めん]が平[たい]らなので、積[つ]み重[かさ]ねやすい。", "sentence_source": "generated"}, {"text": "サイコロの面には、一から六までの点がある。", "target_word": "面", "complexity_tier": "T3", "furigana": "サイコロの面[めん]には、一[いち]から六[ろく]までの点[てん]がある。", "sentence_source": "generated"}, {"text": "机の面をふくと、きれいになった。", "target_word": "面", "complexity_tier": "T3", "furigana": "机[つくえ]の面[めん]をふくと、きれいになった。", "sentence_source": "generated"}, {"text": "面がでこぼこだと、ボールはまっすぐ転がらない。", "target_word": "面", "complexity_tier": "T3", "furigana": "面[めん]がでこぼこだと、ボールはまっすぐ転[ころ]がらない。", "sentence_source": "generated"}, {"text": "木の板の面にやすりをかけて、なめらかにした。", "target_word": "面", "complexity_tier": "T3", "furigana": "木[き]の板[いた]の面[めん]にやすりをかけて、なめらかにした。", "sentence_source": "generated"}, {"text": "鏡の面にほこりがついていたので、布でふいた。", "target_word": "面", "complexity_tier": "T3", "furigana": "鏡[かがみ]の面[めん]にほこりがついていたので、布[ぬの]でふいた。", "sentence_source": "generated"}, {"text": "テーブルの上の面だけ、色がはげている。", "target_word": "面", "complexity_tier": "T3", "furigana": "テーブルの上[うえ]の面[めん]だけ、色[いろ]がはげている。", "sentence_source": "generated"}, {"text": "三角すいは、四つの面でできている。", "target_word": "面", "complexity_tier": "T3", "furigana": "三角[さんかく]すいは、四[よっ]つの面[めん]でできている。", "sentence_source": "generated"}, {"text": "この石は面が広いから、座るのにちょうどいい。", "target_word": "面", "complexity_tier": "T3", "furigana": "この石[いし]は面[めん]が広[ひろ]いから、座[すわ]るのにちょうどいい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "面", "label": "基本形"}], "register": "一般", "sense_fingerprint": "立体の外側にある平らな一つの面（立方体の面など）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T1: contains vocabulary far above tier T1: 転がら (Zipf 2.02)']::text[], '755579f7-4a87-4e7f-897a-270cbb3c668d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37680, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "面", "is_correct": true, "explanation": "立方体の外側にある一つ一つの平らな面を指すので、六つの面と合う。"}, {"text": "音", "is_correct": false, "explanation": "「六つの音がある」では立方体の形の話にならず、意味が通らない。"}, {"text": "声", "is_correct": false, "explanation": "立方体に「六つの声がある」とは言えず、文の意味が成り立たない。"}, {"text": "夢", "is_correct": false, "explanation": "「六つの夢がある」は立方体の話題に合わず、意味が通らない。"}], "explanations": {"面": "立方体の外側にある一つ一つの平らな面を指すので、六つの面と合う。", "音": "「六つの音がある」では立方体の形の話にならず、意味が通らない。", "声": "立方体に「六つの声がある」とは言えず、文の意味が成り立たない。", "夢": "「六つの夢がある」は立方体の話題に合わず、意味が通らない。"}, "sentence_index": 0, "correct_answer": "面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は面をしかめて、何も言わなかった。", "explanation": "ここは〈顔〉の意味で使っている。この語は物の平らな外側を指すので、顔の表情の話には合わない。"}, {"text": "この問題には、別の面もある。", "explanation": "ここは〈側面・一面〉の意味。物の外側の平らな部分ではなく、物事の見方の一つを指す。"}, {"text": "夏祭りで、子どもがお面をかぶって走り回った。", "explanation": "ここは〈お面（仮面）〉の意味。物の平らな外側という定義とは別の意味で、顔を覆う仮面の話には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37680, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "面", "is_correct": true, "explanation": "鏡の表面にほこりがついていた、という意味で合う。"}, {"text": "夜", "is_correct": false, "explanation": "「鏡の夜にほこりがついていた」は意味が通らず、不自然。"}, {"text": "雲", "is_correct": false, "explanation": "「鏡の雲」は場所として成り立たず、文がおかしい。"}, {"text": "息", "is_correct": false, "explanation": "「鏡の息にほこりがついていた」は意味が通らない。"}], "explanations": {"面": "鏡の表面にほこりがついていた、という意味で合う。", "夜": "「鏡の夜にほこりがついていた」は意味が通らず、不自然。", "雲": "「鏡の雲」は場所として成り立たず、文がおかしい。", "息": "「鏡の息にほこりがついていた」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "上司と面と向かって話すのは、少し緊張する。", "explanation": "ここは〈向き合うこと〉の意味。物の外側の平らな部分とは別で、人と直接向き合う話に使う。"}, {"text": "彼は大きな困難に面して、計画をあきらめた。", "explanation": "ここは〈直面する〉の意味。物の外側の平らな部分という定義とは別の意味で、困難に出会う話には合わない。"}, {"text": "彼女は面を伏せて、涙をこらえた。", "explanation": "ここは〈顔〉の意味。物の平らな外側とは別で、人の表情の話に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37680, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この台は面を平らなので、物を置きやすい。", "corrected_sentence": "この台は面が平らなので、物を置きやすい。", "error_description": "「面」が「平らな」の主語になるので「が」が正しい。「を」にすると「平らな」と結びつかない誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37680, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窓の面を水滴がついていたので、布でふいた。", "corrected_sentence": "窓の面に水滴がついていたので、布でふいた。", "error_description": "「ついている」の場所を示す「に」が正しい。「を」にすると「ついている」と結びつかない誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37681, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「面」に水のしずくが付く、という着点を示す「に」。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」は「付いている」と合わず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「ガラスの面で水のしずくが付いている」は、付着の場所を「で」で示すのが不自然で、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」では、付着する場所を示す文の意味にならない。"}], "correct_answer": "に", "explanations": {"に": "「面」に水のしずくが付く、という着点を示す「に」。", "を": "目的語の「を」は「付いている」と合わず、文が成り立たない。", "で": "「ガラスの面で水のしずくが付いている」は、付着の場所を「で」で示すのが不自然で、文が成り立たない。", "から": "起点の「から」では、付着する場所を示す文の意味にならない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37681, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「面」が「さびて」の主語を示す「が」。文が自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」は「さびて」の主語にならず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "場所・方向の「に」は主語にならず、「面にさびて」では文が通らない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」は主語を作れず、「面とさびて」では文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「面」が「さびて」の主語を示す「が」。文が自然に続く。", "を": "目的語の「を」は「さびて」の主語にならず、文が成り立たない。", "に": "場所・方向の「に」は主語にならず、「面にさびて」では文が通らない。", "と": "並列の「と」は主語を作れず、「面とさびて」では文が成り立たない。"}, "error_tags": {"を": "目的語", "に": "場所・方向", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37681, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物の表面。特に、上の部分や外側に見える部分。", "primary_collocate": null, "pronunciation": "めん", "ipa": "meɴ", "syllable_count": 2, "sentences": [{"text": "壁の面に、青いペンキがべっとりついていた。", "target_word": "面", "complexity_tier": "T3", "furigana": "壁[かべ]の面[めん]に、青[あお]いペンキがべっとりついていた。", "sentence_source": "generated"}, {"text": "ガラスの面に水のしずくがたくさん付いている。", "target_word": "面", "complexity_tier": "T3", "furigana": "ガラスの面[めん]に水[みず]のしずくがたくさん付[つ]いている。", "sentence_source": "generated"}, {"text": "ざらざらした面を、紙やすりで磨いた。", "target_word": "面", "complexity_tier": "T3", "furigana": "ざらざらした面[めん]を、紙[かみ]やすりで磨[みが]いた。", "sentence_source": "generated"}, {"text": "机の面に傷があるので、シールをはった。", "target_word": "面", "complexity_tier": "T3", "furigana": "机[つくえ]の面[めん]に傷[きず]があるので、シールをはった。", "sentence_source": "generated"}, {"text": "この布は、片方の面だけ模様がある。", "target_word": "面", "complexity_tier": "T3", "furigana": "この布[ぬの]は、片方[かたほう]の面[めん]だけ模様[もよう]がある。", "sentence_source": "generated"}, {"text": "氷の面がつるつるで、歩くとすべりそうだ。", "target_word": "面", "complexity_tier": "T3", "furigana": "氷[こおり]の面[めん]がつるつるで、歩[ある]くとすべりそうだ。", "sentence_source": "generated"}, {"text": "ノートの面に、ペンで名前を書いた。", "target_word": "面", "complexity_tier": "T3", "furigana": "ノートの面[めん]に、ペンで名前[なまえ]を書[か]いた。", "sentence_source": "generated"}, {"text": "金属の面がさびて、茶色くなってきた。", "target_word": "面", "complexity_tier": "T3", "furigana": "金属[きんぞく]の面[めん]がさびて、茶色[ちゃいろ]くなってきた。", "sentence_source": "generated"}, {"text": "平らな面にシートを置いてから、組み立ててください。", "target_word": "面", "complexity_tier": "T3", "furigana": "平[たい]らな面[めん]にシートを置[お]いてから、組[く]み立[た]ててください。", "sentence_source": "generated"}, {"text": "車のドアの面に、ぶつけた跡が残っている。", "target_word": "面", "complexity_tier": "T3", "furigana": "車[くるま]のドアの面[めん]に、ぶつけた跡[あと]が残[のこ]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "面", "label": "基本形"}], "register": "一般", "sense_fingerprint": "物の外に見えている表面の部分（壁・ガラス・金属などの面）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: contains vocabulary far above tier T1: べっとり (Zipf 2.01)','sentence 2 above tier T1: contains vocabulary far above tier T1: ざらざら (Zipf 2.37)']::text[], '755579f7-4a87-4e7f-897a-270cbb3c668d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37681, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "面", "is_correct": true, "explanation": "壁の表面に青いペンキがついた、という意味で合う。"}, {"text": "音", "is_correct": false, "explanation": "「壁の音に」は意味が通らず、ペンキがつく場所として不自然。"}, {"text": "夢", "is_correct": false, "explanation": "「壁の夢に」は文の意味が通らない。"}, {"text": "声", "is_correct": false, "explanation": "「壁の声に」は成り立たず、ペンキがつく場所を示せない。"}], "explanations": {"面": "壁の表面に青いペンキがついた、という意味で合う。", "音": "「壁の音に」は意味が通らず、ペンキがつく場所として不自然。", "夢": "「壁の夢に」は文の意味が通らない。", "声": "「壁の声に」は成り立たず、ペンキがつく場所を示せない。"}, "sentence_index": 0, "correct_answer": "面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この件には、別の面もある。", "explanation": "ここは〈側面・一面〉の意味。物の表面ではなく、物事の見方の一つを指す。"}, {"text": "ハロウィンの夜、子どもが怪獣のお面をかぶっていた。", "explanation": "ここは〈お面（仮面）〉の意味。表面や外側を指す定義とは別の意味で、顔を覆う仮面の話には合わない。"}, {"text": "彼女は面を伏せて、黙り込んだ。", "explanation": "ここは〈顔〉の意味。物の平らな外側を指す定義とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37681, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "面", "is_correct": true, "explanation": "ノートの表面に名前を書いた、という意味で合う。"}, {"text": "波", "is_correct": false, "explanation": "「ノートの波に」は意味が通らず、書く場所として不自然。"}, {"text": "星", "is_correct": false, "explanation": "「ノートの星に」は書く場所として成り立たない。"}, {"text": "名", "is_correct": false, "explanation": "「ノートの名に」は名前を書く場所として不自然で、意味が通らない。"}], "explanations": {"面": "ノートの表面に名前を書いた、という意味で合う。", "波": "「ノートの波に」は意味が通らず、書く場所として不自然。", "星": "「ノートの星に」は書く場所として成り立たない。", "名": "「ノートの名に」は名前を書く場所として不自然で、意味が通らない。"}, "sentence_index": 6, "correct_answer": "面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼と面と向かって、話し合った。", "explanation": "ここは〈向き合うこと〉の意味。物の表面とは別で、人と直接向き合う話に使う。"}, {"text": "彼女は試練に面して、ひるまず立ち向かった。", "explanation": "ここは〈直面する〉の意味。物の表面を指す定義とは別で、試練に出会う話には合わない。"}, {"text": "彼女は面を伏せて、涙をこらえた。", "explanation": "ここは〈顔〉の意味。物の表面とは別で、人の表情の話に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37681, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鏡の面を、指紋がはっきり付いている。", "corrected_sentence": "鏡の面に、指紋がはっきり付いている。", "error_description": "「付く」の着点を示す「に」が正しい。「を」にすると「付いている」と結びつかない誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37681, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ガラス戸の面をくもって、外が見えなかった。", "corrected_sentence": "ガラス戸の面がくもって、外が見えなかった。", "error_description": "「くもる」の主語を示す「が」が正しい。「を」にすると主語として動詞と結びつかない誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
