INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37682, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『かける』の目的語として、高圧を加えるという意味で正しい"}, {"text": "が", "is_correct": false, "explanation": "主語を示す『が』では、高圧が動作主になり文が通らない"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示す『と』では、高圧をかける対象を表せない"}, {"text": "から", "is_correct": false, "explanation": "起点を示す『から』では、高圧をかけるという動作に合わない"}], "correct_answer": "を", "explanations": {"を": "『かける』の目的語として、高圧を加えるという意味で正しい", "が": "主語を示す『が』では、高圧が動作主になり文が通らない", "と": "並列や相手を示す『と』では、高圧をかける対象を表せない", "から": "起点を示す『から』では、高圧をかけるという動作に合わない"}, "error_tags": {"が": "主語", "と": "並列・相手", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37682, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "強い力で押すこと。", "primary_collocate": null, "pronunciation": "こうあつ", "ipa": "koːatsɯ", "syllable_count": 4, "sentences": [{"text": "ポンプが高圧で水を押し出すので、遠くまで届く。", "target_word": "高圧", "complexity_tier": "T3", "furigana": "ポンプが高圧[こうあつ]で水[みず]を押[お]し出[だ]すので、遠[とお]くまで届[とど]く。", "sentence_source": "generated"}, {"text": "工場では高圧で金属の板を押して、形を作る。", "target_word": "高圧", "complexity_tier": "T3", "furigana": "工場[こうじょう]では高圧[こうあつ]で金属[きんぞく]の板[いた]を押[お]して、形[かたち]を作[つく]る。", "sentence_source": "generated"}, {"text": "高圧をかけて押し固めると、粉は硬い塊になる。", "target_word": "高圧", "complexity_tier": "T3", "furigana": "高圧[こうあつ]をかけて押[お]し固[かた]めると、粉[こな]は硬[かた]い塊[かたまり]になる。", "sentence_source": "generated"}, {"text": "機械が高圧で押すため、缶はすぐにつぶれた。", "target_word": "高圧", "complexity_tier": "T3", "furigana": "機械[きかい]が高圧[こうあつ]で押[お]すため、缶[かん]はすぐにつぶれた。", "sentence_source": "generated"}, {"text": "高圧で押された空気が、細い管から勢いよく出た。", "target_word": "高圧", "complexity_tier": "T3", "furigana": "高圧[こうあつ]で押[お]された空気[くうき]が、細[ほそ]い管[くだ]から勢[いきお]いよく出[で]た。", "sentence_source": "generated"}, {"text": "高圧で押し付けても、この紙は破れなかった。", "target_word": "高圧", "complexity_tier": "T3", "furigana": "高圧[こうあつ]で押[お]し付[つ]けても、この紙[かみ]は破[やぶ]れなかった。", "sentence_source": "generated"}, {"text": "洗車場では高圧で水を押し出し、泥を落とす。", "target_word": "高圧", "complexity_tier": "T3", "furigana": "洗車場[せんしゃじょう]では高圧[こうあつ]で水[みず]を押[お]し出[だ]し、泥[どろ]を落[お]とす。", "sentence_source": "generated"}, {"text": "油の出が悪いときは、高圧をかけると流れやすくなる。", "target_word": "高圧", "complexity_tier": "T3", "furigana": "油[あぶら]の出[で]が悪[わる]いときは、高圧[こうあつ]をかけると流[なが]れやすくなる。", "sentence_source": "generated"}, {"text": "職人は粘土に高圧をかけて、固い器にした。", "target_word": "高圧", "complexity_tier": "T3", "furigana": "職人[しょくにん]は粘土[ねんど]に高圧[こうあつ]をかけて、固[かた]い器[うつわ]にした。", "sentence_source": "generated"}, {"text": "高圧で押さないと、このゴムは型にぴったり入らない。", "target_word": "高圧", "complexity_tier": "T3", "furigana": "高圧[こうあつ]で押[お]さないと、このゴムは型[かた]にぴったり入[はい]らない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "高圧", "label": "base"}, {"form": "高圧で", "label": "means"}, {"form": "高圧を", "label": "object"}], "register": "neutral", "sense_fingerprint": "強い力で押す、押しつける作用(機械・ポンプなどが物を強く押す)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b8ac3e6-a2ff-4eb9-b4fb-6cf755747119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37682, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高圧", "is_correct": true, "explanation": "圧力を加える手段を表し、水を押し出す文に合う"}, {"text": "注意", "is_correct": false, "explanation": "注意で水を押し出すとは言えず、文が通らない"}, {"text": "感想", "is_correct": false, "explanation": "感想で水を押し出すという意味にはならない"}, {"text": "包装", "is_correct": false, "explanation": "包装で水を押し出すことはできず、文が通らない"}], "explanations": {"高圧": "圧力を加える手段を表し、水を押し出す文に合う", "注意": "注意で水を押し出すとは言えず、文が通らない", "感想": "感想で水を押し出すという意味にはならない", "包装": "包装で水を押し出すことはできず、文が通らない"}, "sentence_index": 0, "correct_answer": "高圧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "上司は部下に、いつも高圧で接する。", "explanation": "ここは〈高圧的〉の意味。押す力の話ではなく態度の話なので、この文脈では使わない。"}, {"text": "この子は高圧で歌う。", "explanation": "声の高さの話で、押す力を表す高圧は歌い方には使わない。"}, {"text": "金属を高圧で溶かした。", "explanation": "金属を溶かすのは熱の働きなので、押す力の高圧では言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
