INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37684, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "後退", "is_correct": true, "explanation": "後退は前進の対義語で、前へ進めない場面では後ろへ下がる動きとして対になる。"}, {"text": "購読", "is_correct": false, "explanation": "購読は新聞や雑誌を定期的に受け取ることで、前進の対義語ではない。"}, {"text": "維持", "is_correct": false, "explanation": "維持は今の状態を保つことで、前進の対義語ではない。"}, {"text": "上昇", "is_correct": false, "explanation": "上昇は上へ向かうことで、前進の対義語ではない。"}], "correct_answer": "後退", "explanations": {"後退": "後退は前進の対義語で、前へ進めない場面では後ろへ下がる動きとして対になる。", "購読": "購読は新聞や雑誌を定期的に受け取ることで、前進の対義語ではない。", "維持": "維持は今の状態を保つことで、前進の対義語ではない。", "上昇": "上昇は上へ向かうことで、前進の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37684, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "前に進むことです。", "primary_collocate": null, "pronunciation": "ぜんしん", "ipa": "dzeɴɕiɴ", "syllable_count": 4, "sentences": [{"text": "車はゆっくり前進して、白い線の前で止まった。", "target_word": "前進", "complexity_tier": "T3", "furigana": "車[くるま]はゆっくり前進[ぜんしん]して、白[しろ]い線[せん]の前[まえ]で止[と]まった。", "sentence_source": "generated"}, {"text": "先生の合図で、列は一歩ずつ前進した。", "target_word": "前進", "complexity_tier": "T3", "furigana": "先生[せんせい]の合図[あいず]で、列[れつ]は一歩[いっぽ]ずつ前進[ぜんしん]した。", "sentence_source": "generated"}, {"text": "船は霧の中を静かに前進している。", "target_word": "前進", "complexity_tier": "T3", "furigana": "船[ふね]は霧[きり]の中[なか]を静[しず]かに前進[ぜんしん]している。", "sentence_source": "generated"}, {"text": "後退ではなく前進のボタンを押すと、ロボットは前に動く。", "target_word": "前進", "complexity_tier": "T3", "furigana": "後退[こうたい]ではなく前進[ぜんしん]のボタンを押[お]すと、ロボットは前[まえ]に動[うご]く。", "sentence_source": "generated"}, {"text": "前が空いたので、バスは少し前進した。", "target_word": "前進", "complexity_tier": "T3", "furigana": "前[まえ]が空[あ]いたので、バスは少[すこ]し前進[ぜんしん]した。", "sentence_source": "generated"}, {"text": "赤ちゃんは腕の力で、床の上を前進した。", "target_word": "前進", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんは腕[うで]の力[ちから]で、床[ゆか]の上[うえ]を前進[ぜんしん]した。", "sentence_source": "generated"}, {"text": "信号が青になり、先頭の自転車が前進を始めた。", "target_word": "前進", "complexity_tier": "T3", "furigana": "信号[しんごう]が青[あお]になり、先頭[せんとう]の自転車[じてんしゃ]が前進[ぜんしん]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "運転手は車をバックさせず、そのまま前進させた。", "target_word": "前進", "complexity_tier": "T3", "furigana": "運転手[うんてんしゅ]は車[くるま]をバックさせず、そのまま前進[ぜんしん]させた。", "sentence_source": "generated"}, {"text": "雪が深くて、前進するのにとても時間がかかった。", "target_word": "前進", "complexity_tier": "T3", "furigana": "雪[ゆき]が深[ふか]くて、前進[ぜんしん]するのにとても時間[じかん]がかかった。", "sentence_source": "generated"}, {"text": "前進できないときは、いったん止まって道を確かめる。", "target_word": "前進", "complexity_tier": "T3", "furigana": "前進[ぜんしん]できないときは、いったん止[と]まって道[みち]を確[たし]かめる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "前進", "label": "base"}, {"form": "前進する", "label": "dictionary"}, {"form": "前進した", "label": "past"}, {"form": "前進して", "label": "te-form"}, {"form": "前進しない", "label": "negative"}], "register": "neutral", "sense_fingerprint": "人や乗り物などが前の方向へ進む動き(後退の反対)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b8ac3e6-a2ff-4eb9-b4fb-6cf755747119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37684, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前進", "is_correct": true, "explanation": "「前進して」で、車が前へ進む動きとして文脈に合う。"}, {"text": "解散", "is_correct": false, "explanation": "「解散して」は集団が別れる意味で、車が白い線の前で止まるまでの動きには合わない。"}, {"text": "相談", "is_correct": false, "explanation": "相談は話し合うことなので、車がゆっくり動く文脈には合わない。"}, {"text": "納得", "is_correct": false, "explanation": "納得は理解して受け入れることで、車の動きには使わない。"}], "explanations": {"前進": "「前進して」で、車が前へ進む動きとして文脈に合う。", "解散": "「解散して」は集団が別れる意味で、車が白い線の前で止まるまでの動きには合わない。", "相談": "相談は話し合うことなので、車がゆっくり動く文脈には合わない。", "納得": "納得は理解して受け入れることで、車の動きには使わない。"}, "sentence_index": 0, "correct_answer": "前進"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "高校を卒業して、彼は大学へ前進した。", "explanation": "前進は前へ進む動きを表すので、進学の意味では使わない。"}, {"text": "子どもは毎晩十時に前進した。", "explanation": "前進は前へ進む動きを表すので、眠りにつく意味では使わない。"}, {"text": "薬を飲んで、熱が前進した。", "explanation": "前進は前へ進む動きを指すので、熱が下がる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37684, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前進", "is_correct": true, "explanation": "「前進を始めた」で、自転車が進み出す動きに合う。"}, {"text": "欠席", "is_correct": false, "explanation": "欠席は会や授業に出ないことで、自転車には合わない。"}, {"text": "所持", "is_correct": false, "explanation": "所持は持っていることで、動き出す文脈には合わない。"}, {"text": "帰宅", "is_correct": false, "explanation": "帰宅は家へ帰ることで、信号が青になった直後の動きには合わない。"}], "explanations": {"前進": "「前進を始めた」で、自転車が進み出す動きに合う。", "欠席": "欠席は会や授業に出ないことで、自転車には合わない。", "所持": "所持は持っていることで、動き出す文脈には合わない。", "帰宅": "帰宅は家へ帰ることで、信号が青になった直後の動きには合わない。"}, "sentence_index": 6, "correct_answer": "前進"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鍋のお湯が前進して、沸騰した。", "explanation": "前進は前へ進む動きを表すので、お湯が沸く意味では使わない。"}, {"text": "その店は三年前に前進した。", "explanation": "前進は前へ進む動きで、店の開業には使わない。"}, {"text": "春になり、雪が前進した。", "explanation": "雪は前へ進むのではなく融けるので、この語義とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37684, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "船は港へ向かって前進されている。", "corrected_sentence": "船は港へ向かって前進している。", "error_description": "「前進される」は受身の形で、前進は自動詞なので受身にできない。正しくは「前進している」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37684, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先頭の列が少しずつ前進に続けた。", "corrected_sentence": "先頭の列が少しずつ前進を続けた。", "error_description": "「前進を続ける」が正しい。「続ける」の目的語には「を」が必要で、「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
