INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37685, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "後退", "is_correct": true, "explanation": "後退は前進の対義語で、目的地へ進む動きと反対の動きとして対になる。"}, {"text": "購読", "is_correct": false, "explanation": "購読は新聞や雑誌を定期的に受け取ることで、前進の対義語ではない。"}, {"text": "維持", "is_correct": false, "explanation": "維持は今の状態を保つことで、前進の対義語ではない。"}, {"text": "上昇", "is_correct": false, "explanation": "上昇は上へ向かうことで、前進の対義語ではない。"}], "correct_answer": "後退", "explanations": {"後退": "後退は前進の対義語で、目的地へ進む動きと反対の動きとして対になる。", "購読": "購読は新聞や雑誌を定期的に受け取ることで、前進の対義語ではない。", "維持": "維持は今の状態を保つことで、前進の対義語ではない。", "上昇": "上昇は上へ向かうことで、前進の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37685, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある方向に向かって進むこと。特に、目的地や目標に向かって移動すること。", "primary_collocate": null, "pronunciation": "ぜんしん", "ipa": "dzeɴɕiɴ", "syllable_count": 4, "sentences": [{"text": "登山隊は頂上に向かって、一歩ずつ前進した。", "target_word": "前進", "complexity_tier": "T3", "furigana": "登山隊[とざんたい]は頂上[ちょうじょう]に向[む]かって、一歩[いっぽ]ずつ前進[ぜんしん]した。", "sentence_source": "generated"}, {"text": "私たちは目的地を目指して、夜の道を前進した。", "target_word": "前進", "complexity_tier": "T3", "furigana": "私[わたし]たちは目的地[もくてきち]を目指[めざ]して、夜[よる]の道[みち]を前進[ぜんしん]した。", "sentence_source": "generated"}, {"text": "探検隊は川に沿って、南の村へ前進した。", "target_word": "前進", "complexity_tier": "T3", "furigana": "探検隊[たんけんたい]は川[かわ]に沿[そ]って、南[みなみ]の村[むら]へ前進[ぜんしん]した。", "sentence_source": "generated"}, {"text": "部隊は国境に向かって前進を続けた。", "target_word": "前進", "complexity_tier": "T3", "furigana": "部隊[ぶたい]は国境[こっきょう]に向[む]かって前進[ぜんしん]を続[つづ]けた。", "sentence_source": "generated"}, {"text": "船は港を目指して前進し、夕方に着いた。", "target_word": "前進", "complexity_tier": "T3", "furigana": "船[ふね]は港[みなと]を目指[めざ]して前進[ぜんしん]し、夕方[ゆうがた]に着[つ]いた。", "sentence_source": "generated"}, {"text": "地図を見ながら、出口に向かって前進した。", "target_word": "前進", "complexity_tier": "T3", "furigana": "地図[ちず]を見[み]ながら、出口[でぐち]に向[む]かって前進[ぜんしん]した。", "sentence_source": "generated"}, {"text": "彼らは嵐の中でも、ゴールへ前進をやめなかった。", "target_word": "前進", "complexity_tier": "T3", "furigana": "彼[かれ]らは嵐[あらし]の中[なか]でも、ゴールへ前進[ぜんしん]をやめなかった。", "sentence_source": "generated"}, {"text": "隊員たちは救助を待つ人のもとへ前進した。", "target_word": "前進", "complexity_tier": "T3", "furigana": "隊員[たいいん]たちは救助[きゅうじょ]を待[ま]つ人[ひと]のもとへ前進[ぜんしん]した。", "sentence_source": "generated"}, {"text": "目標の山小屋まで、あと二キロ前進すればよい。", "target_word": "前進", "complexity_tier": "T3", "furigana": "目標[もくひょう]の山小屋[やまごや]まで、あと二[に]キロ前進[ぜんしん]すればよい。", "sentence_source": "generated"}, {"text": "暗い洞窟を、光の見える出口に向かって前進した。", "target_word": "前進", "complexity_tier": "T3", "furigana": "暗[くら]い洞窟[どうくつ]を、光[ひかり]の見[み]える出口[でぐち]に向[む]かって前進[ぜんしん]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "前進", "label": "base"}, {"form": "前進する", "label": "dictionary"}, {"form": "前進した", "label": "past"}, {"form": "前進を続ける", "label": "continuative"}, {"form": "前進し", "label": "stem"}], "register": "neutral", "sense_fingerprint": "目的地や目標へ向かって移動し進んでいくこと(隊・船・人などの行軍や移動)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b8ac3e6-a2ff-4eb9-b4fb-6cf755747119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37685, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前進", "is_correct": true, "explanation": "「一歩ずつ前進した」で、頂上へ向かって進む動きに合う。"}, {"text": "相談", "is_correct": false, "explanation": "「一歩ずつ相談した」は成り立たず、移動の文脈に合わない。"}, {"text": "納得", "is_correct": false, "explanation": "納得は理解して受け入れることで、一歩ずつの移動には合わない。"}, {"text": "欠席", "is_correct": false, "explanation": "欠席は会や授業に出ないことで、登山の移動には合わない。"}], "explanations": {"前進": "「一歩ずつ前進した」で、頂上へ向かって進む動きに合う。", "相談": "「一歩ずつ相談した」は成り立たず、移動の文脈に合わない。", "納得": "納得は理解して受け入れることで、一歩ずつの移動には合わない。", "欠席": "欠席は会や授業に出ないことで、登山の移動には合わない。"}, "sentence_index": 0, "correct_answer": "前進"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "子どもは毎晩十時に前進した。", "explanation": "前進は目的地へ向かう移動を表すので、眠りにつく意味では使わない。"}, {"text": "薬を飲んで、熱が前進した。", "explanation": "目的地へ移動する語義とは違い、熱が下がる意味では使わない。"}, {"text": "雨に濡れた洗濯物が前進して、夕方には乾いた。", "explanation": "目的地へ向かう語義とは違い、洗濯物が乾く意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37685, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前進", "is_correct": true, "explanation": "「ゴールへ前進をやめなかった」で、嵐の中でも進み続ける意味に合う。"}, {"text": "所持", "is_correct": false, "explanation": "「ゴールへ所持をやめなかった」は成り立たず、移動の文脈に合わない。"}, {"text": "帰宅", "is_correct": false, "explanation": "帰宅は家へ帰ることで、ゴールへ向かう文脈には合わない。"}, {"text": "購入", "is_correct": false, "explanation": "購入は買うことで、ゴールへ向かう移動の文脈には合わない。"}], "explanations": {"前進": "「ゴールへ前進をやめなかった」で、嵐の中でも進み続ける意味に合う。", "所持": "「ゴールへ所持をやめなかった」は成り立たず、移動の文脈に合わない。", "帰宅": "帰宅は家へ帰ることで、ゴールへ向かう文脈には合わない。", "購入": "購入は買うことで、ゴールへ向かう移動の文脈には合わない。"}, "sentence_index": 6, "correct_answer": "前進"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ダイエットで体重が前進した。", "explanation": "前進は目的地へ向かう移動を表すので、体重が減る意味では使わない。"}, {"text": "その店は三年前に前進した。", "explanation": "目的地への移動を表す語義とは違い、店の開業には使わない。"}, {"text": "春になり、雪が前進した。", "explanation": "雪は目的地へ進むのではなく融けるので、この語義とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37685, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "探検隊は南の村へ前進された。", "corrected_sentence": "探検隊は南の村へ前進した。", "error_description": "「前進される」は受身にできない。前進は自動詞なので「前進した」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37685, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨が強くなっても、隊員たちは前進に続けた。", "corrected_sentence": "雨が強くなっても、隊員たちは前進を続けた。", "error_description": "「前進を続ける」が正しい。「続ける」の目的語には「を」が必要で、「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37686, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「行く際に」の「際」に直接続く助詞で、時点を表す。"}, {"text": "を", "is_correct": false, "explanation": "「際を」は目的語の形で、時点を表す「際」の文脈には合わない。"}, {"text": "で", "is_correct": false, "explanation": "「際で」は場所や手段を示すので、時点を表す「際」には続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「際へ」は方向を示すので、時点を表す「際」には続かない。"}], "correct_answer": "に", "explanations": {"に": "「行く際に」の「際」に直接続く助詞で、時点を表す。", "を": "「際を」は目的語の形で、時点を表す「際」の文脈には合わない。", "で": "「際で」は場所や手段を示すので、時点を表す「際」には続かない。", "へ": "「際へ」は方向を示すので、時点を表す「際」には続かない。"}, "error_tags": {"を": "object marker", "で": "location or means", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37686, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「薬を飲む際は」で、動作の時を取り上げる「は」。"}, {"text": "が", "is_correct": false, "explanation": "「際が」は主語の形で、後続の「使ってください」と噛み合わず不自然。"}, {"text": "の", "is_correct": false, "explanation": "「際の、」は名詞を修飾する形で、文が途中で切れて成立しない。"}, {"text": "と", "is_correct": false, "explanation": "「際と、」は並列の形で、ここでは文として成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「薬を飲む際は」で、動作の時を取り上げる「は」。", "が": "「際が」は主語の形で、後続の「使ってください」と噛み合わず不自然。", "の": "「際の、」は名詞を修飾する形で、文が途中で切れて成立しない。", "と": "「際と、」は並列の形で、ここでは文として成り立たない。"}, "error_tags": {"が": "subject marker with no fitting subject", "の": "attributive, sentence left unfinished", "と": "listing particle, no list here"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37686, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをするとき、その時。", "primary_collocate": null, "pronunciation": "さい", "ipa": "sai", "syllable_count": 2, "sentences": [{"text": "部屋を出る際は、必ず電気を消してください。", "target_word": "際", "complexity_tier": "T3", "furigana": "部屋[へや]を出[で]る際[さい]は、必[かなら]ず電気[でんき]を消[け]してください。", "sentence_source": "generated"}, {"text": "海外へ行く際には、パスポートが必要です。", "target_word": "際", "complexity_tier": "T3", "furigana": "海外[かいがい]へ行[い]く際[さい]には、パスポートが必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "駅で電車を降りる際、傘を忘れてしまいました。", "target_word": "際", "complexity_tier": "T3", "furigana": "駅[えき]で電車[でんしゃ]を降[お]りる際[さい]、傘[かさ]を忘[わす]れてしまいました。", "sentence_source": "generated"}, {"text": "ご来店の際は、この券をお持ちください。", "target_word": "際", "complexity_tier": "T3", "furigana": "ご来店[らいてん]の際[さい]は、この券[けん]をお持[も]ちください。", "sentence_source": "generated"}, {"text": "契約書に署名する際は、内容をよく確認しましょう。", "target_word": "際", "complexity_tier": "T3", "furigana": "契約書[けいやくしょ]に署名[しょめい]する際[さい]は、内容[ないよう]をよく確認[かくにん]しましょう。", "sentence_source": "generated"}, {"text": "地震が起きた際、私たちは机の下に隠れました。", "target_word": "際", "complexity_tier": "T3", "furigana": "地震[じしん]が起[お]きた際[さい]、私[わたし]たちは机[つくえ]の下[した]に隠[かく]れました。", "sentence_source": "generated"}, {"text": "引っ越しの際に、古い本をたくさん捨てました。", "target_word": "際", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの際[さい]に、古[ふる]い本[ほん]をたくさん捨[す]てました。", "sentence_source": "generated"}, {"text": "薬を飲む際は、水かお湯を使ってください。", "target_word": "際", "complexity_tier": "T3", "furigana": "薬[くすり]を飲[の]む際[さい]は、水[みず]かお湯[ゆ]を使[つか]ってください。", "sentence_source": "generated"}, {"text": "不明な点がある際は、受付までご連絡ください。", "target_word": "際", "complexity_tier": "T3", "furigana": "不明[ふめい]な点[てん]がある際[さい]は、受付[うけつけ]までご連絡[れんらく]ください。", "sentence_source": "generated"}, {"text": "荷物を受け取る際には、身分証明書を見せてください。", "target_word": "際", "complexity_tier": "T3", "furigana": "荷物[にもつ]を受[う]け取[と]る際[さい]には、身分証明書[みぶんしょうめいしょ]を見[み]せてください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "際", "label": "base"}, {"form": "際は", "label": "topic"}, {"form": "際に", "label": "temporal"}, {"form": "際の", "label": "attributive"}], "register": "formal", "sense_fingerprint": "ある動作や出来事が行われるとき(「〜する際」「〜の際」の形で使う改まった言い方)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b8ac3e6-a2ff-4eb9-b4fb-6cf755747119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37686, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "際", "is_correct": true, "explanation": "「部屋を出る際は」で、部屋を出る時点を示す形式名詞として合う。"}, {"text": "窓", "is_correct": false, "explanation": "「部屋を出る窓は」は意味が通らず、時点を表す文脈に合わない。"}, {"text": "机", "is_correct": false, "explanation": "「部屋を出る机は」は意味が通らず、時点を表す文脈に合わない。"}, {"text": "床", "is_correct": false, "explanation": "「部屋を出る床は」は意味が通らず、時点を表す文脈に合わない。"}], "explanations": {"際": "「部屋を出る際は」で、部屋を出る時点を示す形式名詞として合う。", "窓": "「部屋を出る窓は」は意味が通らず、時点を表す文脈に合わない。", "机": "「部屋を出る机は」は意味が通らず、時点を表す文脈に合わない。", "床": "「部屋を出る床は」は意味が通らず、時点を表す文脈に合わない。"}, "sentence_index": 0, "correct_answer": "際"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ご飯の際を、ひとくち食べた。", "explanation": "ここは〈縁・ぎわ〉の意味。食べ物の縁を指す語義で、時点を表す定義とは合わない。"}, {"text": "会議の際を、一人で走った。", "explanation": "ここは〈縁〉の意味。際を場所の縁として使う語義で、時点を表す定義とは合わない。"}, {"text": "夏休みの際を、ずっと待っていた。", "explanation": "時点を表す用法とは違い、「際を待つ」は目的語の形で不自然なので使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37686, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "際", "is_correct": true, "explanation": "「引っ越しの際に」で、引っ越しの時点を示す形式名詞として合う。"}, {"text": "鍋", "is_correct": false, "explanation": "「引っ越しの鍋に」は意味が通らず、時点を表す文脈に合わない。"}, {"text": "壁", "is_correct": false, "explanation": "「引っ越しの壁に」は意味が通らず、時点を表す文脈に合わない。"}, {"text": "傘", "is_correct": false, "explanation": "「引っ越しの傘に」は意味が通らず、時点を表す文脈に合わない。"}], "explanations": {"際": "「引っ越しの際に」で、引っ越しの時点を示す形式名詞として合う。", "鍋": "「引っ越しの鍋に」は意味が通らず、時点を表す文脈に合わない。", "壁": "「引っ越しの壁に」は意味が通らず、時点を表す文脈に合わない。", "傘": "「引っ越しの傘に」は意味が通らず、時点を表す文脈に合わない。"}, "sentence_index": 6, "correct_answer": "際"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試験の際を、ぎりぎりで書いた。", "explanation": "時点を表す用法とは違い、「試験の際を書く」は成り立たないので使わない。"}, {"text": "友達の際で、ずっと話していた。", "explanation": "ここは〈縁〉の意味。場所の縁を表す語義で、時点を表す定義とは合わない。"}, {"text": "寒さの際で、手が冷えた。", "explanation": "〈縁・ぎわ〉の用法で、時点を表す定義とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37686, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寄付の際で、領収書をもらいましょう。", "corrected_sentence": "寄付の際に、領収書をもらいましょう。", "error_description": "時点を表す「際」には「に」が続く。「で」は場所や手段を示すので、時点の意味では使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37686, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会議の際を、資料を配ってください。", "corrected_sentence": "会議の際は、資料を配ってください。", "error_description": "時を取り上げるには「際は」が正しい。「際を」は目的語の形で、ここでは不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8445de1d-1c15-4976-b2ee-9407739fffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37688, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "回避可能", "is_correct": true, "explanation": "避けられることを表し、反対になる。"}, {"text": "必然", "is_correct": false, "explanation": "必ず起こることで、類義語に近い。"}, {"text": "避けがたい", "is_correct": false, "explanation": "避けにくいことで、類義語である。"}, {"text": "仕方ない", "is_correct": false, "explanation": "どうしようもないことで、類義語に近い。"}], "correct_answer": "回避可能", "explanations": {"回避可能": "避けられることを表し、反対になる。", "必然": "必ず起こることで、類義語に近い。", "避けがたい": "避けにくいことで、類義語である。", "仕方ない": "どうしようもないことで、類義語に近い。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2933db7-1d61-47a0-b652-d7662d66cfd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37688, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "避けられる", "is_correct": true, "explanation": "避けることができるという意味で、反対になる。"}, {"text": "必然", "is_correct": false, "explanation": "必ず起こることで、類義語に近い。"}, {"text": "不可欠", "is_correct": false, "explanation": "なくてはならない意味で、反対ではない。"}, {"text": "必須", "is_correct": false, "explanation": "必ず必要な意味で、反対ではない。"}], "correct_answer": "避けられる", "explanations": {"避けられる": "避けることができるという意味で、反対になる。", "必然": "必ず起こることで、類義語に近い。", "不可欠": "なくてはならない意味で、反対ではない。", "必須": "必ず必要な意味で、反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2933db7-1d61-47a0-b652-d7662d66cfd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37688, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "どうしようもなく、さけられないこと。", "primary_collocate": null, "pronunciation": "ふかひ", "ipa": "ɸɯkahi", "syllable_count": 3, "sentences": [{"text": "事故は不可避だった。", "target_word": "不可避", "complexity_tier": "T2", "furigana": "事故[じこ]は不可避[ふかひ]だった。", "sentence_source": "generated"}, {"text": "不可避な別れに、彼女は涙を流した。", "target_word": "不可避な", "complexity_tier": "T3", "furigana": "不可避[ふかひ]な別[わか]れに、彼女[かのじょ]は涙[なみだ]を流[なが]した。", "sentence_source": "generated"}, {"text": "不可避なことは、受け入れるしかない。", "target_word": "不可避な", "complexity_tier": "T3", "furigana": "不可避[ふかひ]なことは、受[う]け入[い]れるしかない。", "sentence_source": "generated"}, {"text": "遅れるのは不可避だと、彼は言った。", "target_word": "不可避", "complexity_tier": "T3", "furigana": "遅[おく]れるのは不可避[ふかひ]だと、彼[かれ]は言[い]った。", "sentence_source": "generated"}, {"text": "不可避の別れが、もうすぐ来る。", "target_word": "不可避", "complexity_tier": "T3", "furigana": "不可避[ふかひ]の別[わか]れが、もうすぐ来[く]る。", "sentence_source": "generated"}, {"text": "試合に負けるのは不可避だった。", "target_word": "不可避", "complexity_tier": "T3", "furigana": "試合[しあい]に負[ま]けるのは不可避[ふかひ]だった。", "sentence_source": "generated"}, {"text": "不可避に見える問題も、考えれば道がある。", "target_word": "不可避に", "complexity_tier": "T3", "furigana": "不可避[ふかひ]に見[み]える問題[もんだい]も、考[かんが]えれば道[みち]がある。", "sentence_source": "generated"}, {"text": "失敗は不可避ではありませんでした。", "target_word": "不可避", "complexity_tier": "T3", "furigana": "失敗[しっぱい]は不可避[ふかひ]ではありませんでした。", "sentence_source": "generated"}, {"text": "不可避であっても、あきらめたくない。", "target_word": "不可避", "complexity_tier": "T3", "furigana": "不可避[ふかひ]であっても、あきらめたくない。", "sentence_source": "generated"}, {"text": "年をとることは不可避です。", "target_word": "不可避", "complexity_tier": "T2", "furigana": "年[とし]をとることは不可避[ふかひ]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "不可避だ", "label": "活用"}, {"form": "不可避な", "label": "活用"}, {"form": "不可避に", "label": "活用"}, {"form": "不可避だった", "label": "活用"}], "register": "plain", "sense_fingerprint": "形状詞 | どうしても避けられない様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5c0cbd4-9068-402c-8710-9d8b63a52347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37688, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不可避", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "深い", "is_correct": false, "explanation": "「ふかい」は最後の一拍だけが違う。"}, {"text": "不覚", "is_correct": false, "explanation": "「ふかく」は最後の一拍だけが違う。"}, {"text": "深み", "is_correct": false, "explanation": "「ふかみ」は最後の一拍だけが違う。"}, {"text": "深さ", "is_correct": false, "explanation": "「ふかさ」は最後の一拍だけが違う。"}], "explanations": {"不可避": "見出し語そのもの。", "深い": "「ふかい」は最後の一拍だけが違う。", "不覚": "「ふかく」は最後の一拍だけが違う。", "深み": "「ふかみ」は最後の一拍だけが違う。", "深さ": "「ふかさ」は最後の一拍だけが違う。"}, "sentence_index": null, "correct_answer": "不可避"}, "level_3": {"options": [{"text": "不可避", "is_correct": true, "explanation": "事故は避けられなかったという意味に合う。"}, {"text": "親切", "is_correct": false, "explanation": "形は合うが意味が合わない。事故が親切では意味をなさない。"}, {"text": "上手", "is_correct": false, "explanation": "形は合うが意味が合わない。事故が上手では意味をなさない。"}, {"text": "元気", "is_correct": false, "explanation": "形は合うが意味が合わない。事故が元気では意味をなさない。"}], "explanations": {"不可避": "事故は避けられなかったという意味に合う。", "親切": "形は合うが意味が合わない。事故が親切では意味をなさない。", "上手": "形は合うが意味が合わない。事故が上手では意味をなさない。", "元気": "形は合うが意味が合わない。事故が元気では意味をなさない。"}, "sentence_index": 0, "correct_answer": "不可避"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この映画は不可避で、涙が出るほど感動した。", "explanation": "「不可避」は感動の意味を持たない。"}, {"text": "彼は不可避な声で、先生に質問した。", "explanation": "声の様子を「不可避」とは言わない。"}, {"text": "公園の桜は不可避に咲いて、とてもきれいだ。", "explanation": "桜の咲き方を「不可避に」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2933db7-1d61-47a0-b652-d7662d66cfd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37688, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不可避", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "不感", "is_correct": false, "explanation": "「ふかん」は最後の一拍だけが違う。"}, {"text": "深手", "is_correct": false, "explanation": "「ふかで」は最後の一拍だけが違う。"}, {"text": "蒸かす", "is_correct": false, "explanation": "「ふかす」は最後の一拍だけが違う。"}, {"text": "深め", "is_correct": false, "explanation": "「ふかめ」は最後の一拍だけが違う。"}], "explanations": {"不可避": "見出し語そのもの。", "不感": "「ふかん」は最後の一拍だけが違う。", "深手": "「ふかで」は最後の一拍だけが違う。", "蒸かす": "「ふかす」は最後の一拍だけが違う。", "深め": "「ふかめ」は最後の一拍だけが違う。"}, "sentence_index": null, "correct_answer": "不可避"}, "level_3": {"options": [{"text": "不可避に", "is_correct": true, "explanation": "避けられないように見える問題という意味に合う。"}, {"text": "元気に", "is_correct": false, "explanation": "形は合うが意味が合わない。問題が元気に見えることはない。"}, {"text": "親切に", "is_correct": false, "explanation": "形は合うが意味が合わない。問題が親切に見えることはない。"}, {"text": "上手に", "is_correct": false, "explanation": "形は合うが意味が合わない。問題が上手に見えることはない。"}], "explanations": {"不可避に": "避けられないように見える問題という意味に合う。", "元気に": "形は合うが意味が合わない。問題が元気に見えることはない。", "親切に": "形は合うが意味が合わない。問題が親切に見えることはない。", "上手に": "形は合うが意味が合わない。問題が上手に見えることはない。"}, "sentence_index": 6, "correct_answer": "不可避に"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この魚は不可避で、とても新鮮です。", "explanation": "「不可避」は魚の状態を表さない。"}, {"text": "弟は不可避に走って、学校に着いた。", "explanation": "走り方を「不可避に」とは言わない。"}, {"text": "私の部屋は不可避なので、毎日そうじしています。", "explanation": "部屋の様子を「不可避」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2933db7-1d61-47a0-b652-d7662d66cfd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.va