INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37689, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "物事を避けることができない様子や、必然的に起こることを表す。", "primary_collocate": null, "pronunciation": "ふかひ", "ipa": "ɸɯkahi", "syllable_count": 3, "sentences": [{"text": "気候変動という地球的危機の緩和に向け、産業セクターにおける排出量の抑制は、持続可能性を担保する上で不可避の責務である。", "target_word": "不可避", "complexity_tier": "T6", "furigana": "気候変動[きこうへんどう]という地球的[ちきゅうてき]危機[きき]の緩和[かんわ]に向[む]け、産業[さんぎょう]セクターにおける排出量[はいしゅつりょう]の抑制[よくせい]は、持続可能性[じぞくかのうせい]を担保[たんぽ]する上[うえ]で不可避[ふかひ]の責務[せきむ]である。", "sentence_source": "mined"}, {"text": "人口減少に伴う税収の落ち込みは、不可避である。", "target_word": "不可避である", "complexity_tier": "T4", "furigana": "人口減少[じんこうげんしょう]に伴[ともな]う税収[ぜいしゅう]の落[お]ち込[こ]みは、不可避[ふかひ]である。", "sentence_source": "generated"}, {"text": "制度改革は、国際競争の中で不可避な選択となった。", "target_word": "不可避な", "complexity_tier": "T5", "furigana": "制度改革[せいどかいかく]は、国際競争[こくさいきょうそう]の中[なか]で不可避[ふかひ]な選択[せんたく]となった。", "sentence_source": "generated"}, {"text": "衝突が不可避であることは、誰の目にも明らかだった。", "target_word": "不可避", "complexity_tier": "T5", "furigana": "衝突[しょうとつ]が不可避[ふかひ]であることは、誰[だれ]の目[め]にも明[あき]らかだった。", "sentence_source": "generated"}, {"text": "不可避の事態に備え、あらかじめ対策を講じておく。", "target_word": "不可避", "complexity_tier": "T4", "furigana": "不可避[ふかひ]の事態[じたい]に備[そな]え、あらかじめ対策[たいさく]を講[こう]じておく。", "sentence_source": "generated"}, {"text": "値上げは不可避だと、社長は記者会見で語った。", "target_word": "不可避", "complexity_tier": "T4", "furigana": "値上[ねあ]げは不可避[ふかひ]だと、社長[しゃちょう]は記者会見[きしゃかいけん]で語[かた]った。", "sentence_source": "generated"}, {"text": "不可避に思われた対立も、対話によって解消された。", "target_word": "不可避に", "complexity_tier": "T5", "furigana": "不可避[ふかひ]に思[おも]われた対立[たいりつ]も、対話[たいわ]によって解消[かいしょう]された。", "sentence_source": "generated"}, {"text": "高齢化に対応した制度の見直しは、もはや不可避だ。", "target_word": "不可避だ", "complexity_tier": "T4", "furigana": "高齢化[こうれいか]に対応[たいおう]した制度[せいど]の見直[みなお]しは、もはや不可避[ふかひ]だ。", "sentence_source": "generated"}, {"text": "専門家は、混乱が不可避だと見ている。", "target_word": "不可避", "complexity_tier": "T3", "furigana": "専門家[せんもんか]は、混乱[こんらん]が不可避[ふかひ]だと見[み]ている。", "sentence_source": "generated"}, {"text": "対応が遅れれば、被害の拡大は不可避となる。", "target_word": "不可避", "complexity_tier": "T4", "furigana": "対応[たいおう]が遅[おく]れれば、被害[ひがい]の拡大[かくだい]は不可避[ふかひ]となる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "不可避だ", "label": "活用"}, {"form": "不可避な", "label": "活用"}, {"form": "不可避に", "label": "活用"}, {"form": "不可避である", "label": "活用"}, {"form": "不可避性", "label": "派生"}], "register": "formal", "sense_fingerprint": "形状詞 | 避けられず必然的に起こる様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5c0cbd4-9068-402c-8710-9d8b63a52347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37689, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不可避", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "深い", "is_correct": false, "explanation": "「ふかい」は最後の一拍だけが違う。"}, {"text": "深み", "is_correct": false, "explanation": "「ふかみ」は最後の一拍だけが違う。"}, {"text": "不覚", "is_correct": false, "explanation": "「ふかく」は最後の一拍だけが違う。"}, {"text": "深さ", "is_correct": false, "explanation": "「ふかさ」は最後の一拍だけが違う。"}], "explanations": {"不可避": "見出し語そのもの。", "深い": "「ふかい」は最後の一拍だけが違う。", "深み": "「ふかみ」は最後の一拍だけが違う。", "不覚": "「ふかく」は最後の一拍だけが違う。", "深さ": "「ふかさ」は最後の一拍だけが違う。"}, "sentence_index": null, "correct_answer": "不可避"}, "level_3": {"options": [{"text": "不可避", "is_correct": true, "explanation": "避けられない責務という意味に合う。"}, {"text": "無関係", "is_correct": false, "explanation": "形は合うが意味が合わない。責務が「無関係」では文意に反する。"}, {"text": "無縁", "is_correct": false, "explanation": "形は合うが意味が合わない。責務と無縁では文意に反する。"}, {"text": "不要", "is_correct": false, "explanation": "形は合うが意味が合わない。抑制が不要では文脈と合わない。"}], "explanations": {"不可避": "避けられない責務という意味に合う。", "無関係": "形は合うが意味が合わない。責務が「無関係」では文意に反する。", "無縁": "形は合うが意味が合わない。責務と無縁では文意に反する。", "不要": "形は合うが意味が合わない。抑制が不要では文脈と合わない。"}, "sentence_index": 0, "correct_answer": "不可避"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店のラーメンは不可避で、いつも行列ができる。", "explanation": "「不可避」は避けられないことで、おいしさの意味はない。"}, {"text": "彼女は不可避な服を着て、パーティーに出かけた。", "explanation": "「不可避」は服の様子を表さない。"}, {"text": "彼は不可避に新しい車を買って、喜んでいる。", "explanation": "買う行為を避けられないものとして使うのは、文脈に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2933db7-1d61-47a0-b652-d7662d66cfd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37689, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不可避", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "不感", "is_correct": false, "explanation": "「ふかん」は最後の一拍だけが違う。"}, {"text": "深手", "is_correct": false, "explanation": "「ふかで」は最後の一拍だけが違う。"}, {"text": "蒸かす", "is_correct": false, "explanation": "「ふかす」は最後の一拍だけが違う。"}, {"text": "深め", "is_correct": false, "explanation": "「ふかめ」は最後の一拍だけが違う。"}], "explanations": {"不可避": "見出し語そのもの。", "不感": "「ふかん」は最後の一拍だけが違う。", "深手": "「ふかで」は最後の一拍だけが違う。", "蒸かす": "「ふかす」は最後の一拍だけが違う。", "深め": "「ふかめ」は最後の一拍だけが違う。"}, "sentence_index": null, "correct_answer": "不可避"}, "level_3": {"options": [{"text": "不可避に", "is_correct": true, "explanation": "避けられないものに思われたという意味に合う。"}, {"text": "新鮮に", "is_correct": false, "explanation": "形は合うが意味が合わない。対立が新鮮に思われても解消の話と合わない。"}, {"text": "派手に", "is_correct": false, "explanation": "形は合うが意味が合わない。対立が派手に思われるのは文脈に合わない。"}, {"text": "豊かに", "is_correct": false, "explanation": "形は合うが意味が合わない。対立が豊かに思われるのは不自然。"}], "explanations": {"不可避に": "避けられないものに思われたという意味に合う。", "新鮮に": "形は合うが意味が合わない。対立が新鮮に思われても解消の話と合わない。", "派手に": "形は合うが意味が合わない。対立が派手に思われるのは文脈に合わない。", "豊かに": "形は合うが意味が合わない。対立が豊かに思われるのは不自然。"}, "sentence_index": 6, "correct_answer": "不可避に"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この椅子は不可避となって、とても座りやすい。", "explanation": "「不可避」は椅子の性質を表さない。"}, {"text": "彼は不可避を食べて、元気になった。", "explanation": "「不可避」は食べ物ではなく、食べる対象にならない。"}, {"text": "彼女は不可避な声で、友だちに挨拶した。", "explanation": "声の様子を「不可避」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2933db7-1d61-47a0-b652-d7662d66cfd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37689, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "人口減少は、不可避に流れだ。", "corrected_sentence": "人口減少は、不可避な流れだ。", "error_description": "名詞「流れ」を修飾するので、「不可避に」ではなく「不可避な」にする。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "不可避である", "is_correct": true, "explanation": "文末で「~である」と断定する形で自然。"}, {"text": "不可避な", "is_correct": false, "explanation": "連体形のため、文末では使えない。"}, {"text": "不可避に", "is_correct": false, "explanation": "連用形のため、文末では使えない。"}, {"text": "不可避性", "is_correct": false, "explanation": "名詞形で、述語として使えない。"}], "correct_form": "不可避である", "base_form": "不可避", "form_label": "である形", "sentence_index": 1, "explanations": {"不可避である": "文末で「~である」と断定する形で自然。", "不可避な": "連体形のため、文末では使えない。", "不可避に": "連用形のため、文末では使えない。", "不可避性": "名詞形で、述語として使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2933db7-1d61-47a0-b652-d7662d66cfd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37689, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "高齢化は、もはや不可避を現実だ。", "corrected_sentence": "高齢化は、もはや不可避な現実だ。", "error_description": "名詞「現実」を修飾するので、「不可避を」ではなく「不可避な」にする。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "不可避だ", "is_correct": true, "explanation": "文末の断定形で自然。"}, {"text": "不可避の", "is_correct": false, "explanation": "名詞を修飾する形で、文末では使えない。"}, {"text": "不可避な", "is_correct": false, "explanation": "連体形のため、文末では使えない。"}, {"text": "不可避に", "is_correct": false, "explanation": "連用形のため、文末では使えない。"}], "correct_form": "不可避だ", "base_form": "不可避", "form_label": "終止形", "sentence_index": 7, "explanations": {"不可避だ": "文末の断定形で自然。", "不可避の": "名詞を修飾する形で、文末では使えない。", "不可避な": "連体形のため、文末では使えない。", "不可避に": "連用形のため、文末では使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2933db7-1d61-47a0-b652-d7662d66cfd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37690, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吸引", "is_correct": true, "explanation": "反発の対義語。反発は押し返す力、吸引は引き寄せる力で、物理の対になる。"}, {"text": "衝突", "is_correct": false, "explanation": "物がぶつかることで、押し返す作用の反対語ではない。"}, {"text": "摩擦", "is_correct": false, "explanation": "接する面で動きを妨げる力で、反発の反対語とは言えない。"}, {"text": "圧力", "is_correct": false, "explanation": "押す力の大きさを指すもので、反発の反対語ではない。"}], "correct_answer": "吸引", "explanations": {"吸引": "反発の対義語。反発は押し返す力、吸引は引き寄せる力で、物理の対になる。", "衝突": "物がぶつかることで、押し返す作用の反対語ではない。", "摩擦": "接する面で動きを妨げる力で、反発の反対語とは言えない。", "圧力": "押す力の大きさを指すもので、反発の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37690, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吸引", "is_correct": true, "explanation": "反発の対義語。反発は押し返す力、吸引は引き寄せる力で、物理の対になる。"}, {"text": "弾力", "is_correct": false, "explanation": "押されると元に戻る性質で、反発と関係は深いが反対語ではない。"}, {"text": "振動", "is_correct": false, "explanation": "小刻みに揺れる動きで、押し返す作用の反対語ではない。"}, {"text": "加速", "is_correct": false, "explanation": "速さを増すことで、押し返す力の反対語とは言えない。"}], "correct_answer": "吸引", "explanations": {"吸引": "反発の対義語。反発は押し返す力、吸引は引き寄せる力で、物理の対になる。", "弾力": "押されると元に戻る性質で、反発と関係は深いが反対語ではない。", "振動": "小刻みに揺れる動きで、押し返す作用の反対語ではない。", "加速": "速さを増すことで、押し返す力の反対語とは言えない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37690, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "何かが押されたとき、押し返す力のこと。", "primary_collocate": null, "pronunciation": "はんぱつ", "ipa": "hampatsɯ", "syllable_count": 4, "sentences": [{"text": "磁石の同じ極を近づけると、強い反発を感じる。", "target_word": "反発", "complexity_tier": "T3", "furigana": "磁石[じしゃく]の同[おな]じ極[きょく]を近[ちか]づけると、強[つよ]い反発[はんぱつ]を感[かん]じる。", "sentence_source": "generated"}, {"text": "ゴムのボールは、床に落ちると反発して高くはねる。", "target_word": "反発", "complexity_tier": "T3", "furigana": "ゴムのボールは、床[ゆか]に落[お]ちると反発[はんぱつ]して高[たか]くはねる。", "sentence_source": "generated"}, {"text": "手でばねを押すと、反発が手に伝わってくる。", "target_word": "反発", "complexity_tier": "T3", "furigana": "手[て]でばねを押[お]すと、反発[はんぱつ]が手[て]に伝[つた]わってくる。", "sentence_source": "generated"}, {"text": "このマットレスは反発が強く、体を押し返してくる。", "target_word": "反発", "complexity_tier": "T3", "furigana": "このマットレスは反発[はんぱつ]が強[つよ]く、体[からだ]を押[お]し返[かえ]してくる。", "sentence_source": "generated"}, {"text": "反発が大きいほど、ボールは高くはね返る。", "target_word": "反発", "complexity_tier": "T3", "furigana": "反発[はんぱつ]が大[おお]きいほど、ボールは高[たか]くはね返[かえ]る。", "sentence_source": "generated"}, {"text": "スポンジを強く押したら、反発で手が押し戻された。", "target_word": "反発", "complexity_tier": "T3", "furigana": "スポンジを強[つよ]く押[お]したら、反発[はんぱつ]で手[て]が押[お]し戻[もど]された。", "sentence_source": "generated"}, {"text": "同じ電気を帯びたものは、反発して離れていく。", "target_word": "反発", "complexity_tier": "T3", "furigana": "同[おな]じ電気[でんき]を帯[お]びたものは、反発[はんぱつ]して離[はな]れていく。", "sentence_source": "generated"}, {"text": "壁にぶつかった球は、その反発で逆向きに進んだ。", "target_word": "反発", "complexity_tier": "T3", "furigana": "壁[かべ]にぶつかった球[たま]は、その反発[はんぱつ]で逆向[ぎゃくむ]きに進[すす]んだ。", "sentence_source": "generated"}, {"text": "反発が弱いまくらは、頭をのせるとゆっくり沈む。", "target_word": "反発", "complexity_tier": "T3", "furigana": "反発[はんぱつ]が弱[よわ]いまくらは、頭[あたま]をのせるとゆっくり沈[しず]む。", "sentence_source": "generated"}, {"text": "押す力が強いと、反発も同じだけ強くなる。", "target_word": "反発", "complexity_tier": "T3", "furigana": "押[お]す力[ちから]が強[つよ]いと、反発[はんぱつ]も同[おな]じだけ強[つよ]くなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "反発", "label": "基本形"}, {"form": "反発する", "label": "動詞形"}, {"form": "反発して", "label": "て形"}], "register": "一般", "sense_fingerprint": "押されたものが押し返す物理的な力（ばね・ボール・磁石）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '755579f7-4a87-4e7f-897a-270cbb3c668d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37690, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反発", "is_correct": true, "explanation": "磁石どうしが押し返し合う力を指すので、「強い反発を感じる」が自然に合う。"}, {"text": "反発し", "is_correct": false, "explanation": "「強い反発し」では連用形が名詞の後に続かず、文法的に成り立たない。"}, {"text": "反発する", "is_correct": false, "explanation": "「強い反発する」と動詞形を名詞の位置に置くと、文法的に続かない。"}, {"text": "反発した", "is_correct": false, "explanation": "「強い反発した」は過去形になり、「を感じる」の目的語として名詞にならない。"}], "explanations": {"反発": "磁石どうしが押し返し合う力を指すので、「強い反発を感じる」が自然に合う。", "反発し": "「強い反発し」では連用形が名詞の後に続かず、文法的に成り立たない。", "反発する": "「強い反発する」と動詞形を名詞の位置に置くと、文法的に続かない。", "反発した": "「強い反発した」は過去形になり、「を感じる」の目的語として名詞にならない。"}, "sentence_index": 0, "correct_answer": "反発"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先週下がった株価が、今週は反発した。", "explanation": "ここは〈株価が持ち直す〉の意味。押し返す力とは別で、相場の話に使う。"}, {"text": "先生の注意に、彼は強く反発した。", "explanation": "ここは〈反対する〉の意味。物を押し返す力ではなく、人が逆らう態度を指す。"}, {"text": "父の提案に、母が反発して口論になった。", "explanation": "ここは〈反対する〉の意味。物理的な押し返す力の話ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37690, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反発", "is_correct": true, "explanation": "同じ電気を帯びたものが離れる、という文で「反発して」が成り立つ。"}, {"text": "反発だ", "is_correct": false, "explanation": "「反発だ、離れていく」では文が続かず、文法的に成り立たない。"}, {"text": "反発の", "is_correct": false, "explanation": "「の」は名詞の後にしか続かず、「反発の離れていく」は文法的に成り立たない。"}, {"text": "反発な", "is_correct": false, "explanation": "「な」は名詞を修飾する形で、「反発な離れていく」は文が続かない。"}], "explanations": {"反発": "同じ電気を帯びたものが離れる、という文で「反発して」が成り立つ。", "反発だ": "「反発だ、離れていく」では文が続かず、文法的に成り立たない。", "反発の": "「の」は名詞の後にしか続かず、「反発の離れていく」は文法的に成り立たない。", "反発な": "「な」は名詞を修飾する形で、「反発な離れていく」は文が続かない。"}, "sentence_index": 6, "correct_answer": "反発"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先週の下落のあと、株価が反発して値を戻した。", "explanation": "ここは〈株価が持ち直す〉の意味。押し返す力とは別で、相場の用語として使う。"}, {"text": "新しい方針に、現場から反発が広がった。", "explanation": "ここは〈反対〉の意味。物が押し返す力ではなく、人の反対の態度を指す。"}, {"text": "父の命令に、つい反発してしまった。", "explanation": "ここは〈反対する〉の意味。物理的に押し返す力の話ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37690, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ばねを押すと、反発を手に伝わってくる。", "corrected_sentence": "ばねを押すと、反発が手に伝わってくる。", "error_description": "「反発」が「伝わってくる」の主語になるので「が」が正しい。「を」にすると動詞と結びつかない誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37690, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "磁石の同じ極どうしは、反発を離れていく。", "corrected_sentence": "磁石の同じ極どうしは、反発して離れていく。", "error_description": "「反発して」の形が必要。「反発を」にすると後の「離れていく」と文として結びつかない誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
