INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37691, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「恐れる」の目的語を示す「を」。「反発を恐れて」と自然に続く。"}, {"text": "に", "is_correct": false, "explanation": "「反発に恐れて」では目的語にならず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」では「恐れて」の目的語にならず、文が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「恐れる」の対象にならず、「反発へ恐れて」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「恐れる」の目的語を示す「を」。「反発を恐れて」と自然に続く。", "に": "「反発に恐れて」では目的語にならず、文が成り立たない。", "と": "並列の「と」では「恐れて」の目的語にならず、文が通らない。", "へ": "方向の「へ」は「恐れる」の対象にならず、「反発へ恐れて」は成り立たない。"}, "error_tags": {"に": "場所・相手", "と": "並列", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37691, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "意見や決定などに対して、それに逆らって反対すること。", "primary_collocate": null, "pronunciation": "はんぱつ", "ipa": "hampatsɯ", "syllable_count": 4, "sentences": [{"text": "新しい校則に、生徒たちは強く反発した。", "target_word": "反発", "complexity_tier": "T3", "furigana": "新[あたら]しい校則[こうそく]に、生徒[せいと]たちは強[つよ]く反発[はんぱつ]した。", "sentence_source": "generated"}, {"text": "部長の一方的な決定に、社員から反発の声が上がった。", "target_word": "反発", "complexity_tier": "T3", "furigana": "部長[ぶちょう]の一方的[いっぽうてき]な決定[けってい]に、社員[しゃいん]から反発[はんぱつ]の声[こえ]が上[あ]がった。", "sentence_source": "generated"}, {"text": "その発言に、ネット上で強い反発が広がった。", "target_word": "反発", "complexity_tier": "T3", "furigana": "その発言[はつげん]に、ネット上[じょう]で強[つよ]い反発[はんぱつ]が広[ひろ]がった。", "sentence_source": "generated"}, {"text": "親に命令されると、つい反発したくなる。", "target_word": "反発", "complexity_tier": "T3", "furigana": "親[おや]に命令[めいれい]されると、つい反発[はんぱつ]したくなる。", "sentence_source": "generated"}, {"text": "増税の案は、国民の反発を招いた。", "target_word": "反発", "complexity_tier": "T3", "furigana": "増税[ぞうぜい]の案[あん]は、国民[こくみん]の反発[はんぱつ]を招[まね]いた。", "sentence_source": "generated"}, {"text": "彼の意見には反発を覚えたが、理由を聞いて納得した。", "target_word": "反発", "complexity_tier": "T3", "furigana": "彼[かれ]の意見[いけん]には反発[はんぱつ]を覚[おぼ]えたが、理由[りゆう]を聞[き]いて納得[なっとく]した。", "sentence_source": "generated"}, {"text": "その案の欠点を指摘すると、委員たちは反発した。", "target_word": "反発", "complexity_tier": "T3", "furigana": "その案[あん]の欠点[けってん]を指摘[してき]すると、委員[いいん]たちは反発[はんぱつ]した。", "sentence_source": "generated"}, {"text": "住民の反発を恐れて、市は計画を見直した。", "target_word": "反発", "complexity_tier": "T3", "furigana": "住民[じゅうみん]の反発[はんぱつ]を恐[おそ]れて、市[し]は計画[けいかく]を見直[みなお]した。", "sentence_source": "generated"}, {"text": "厳しく叱ると、かえって子どもの反発を強めてしまう。", "target_word": "反発", "complexity_tier": "T3", "furigana": "厳[きび]しく叱[しか]ると、かえって子[こ]どもの反発[はんぱつ]を強[つよ]めてしまう。", "sentence_source": "generated"}, {"text": "相手の考えに反発するだけでなく、まず話を聞こう。", "target_word": "反発", "complexity_tier": "T3", "furigana": "相手[あいて]の考[かんが]えに反発[はんぱつ]するだけでなく、まず話[はなし]を聞[き]こう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "反発", "label": "基本形"}, {"form": "反発する", "label": "動詞形"}, {"form": "反発した", "label": "過去形"}], "register": "一般", "sense_fingerprint": "意見・決定・校則などに逆らって反対する態度（生徒の反発・反対の声）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '755579f7-4a87-4e7f-897a-270cbb3c668d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37691, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反発", "is_correct": true, "explanation": "「強く反発した」の形で、生徒が反対の態度を示したことを表す。"}, {"text": "反発し", "is_correct": false, "explanation": "「強く反発しした」と動詞の形が重なり、文法的に成り立たない。"}, {"text": "反発して", "is_correct": false, "explanation": "「強く反発してした」と「て」と過去形が重なり、文法的に成り立たない。"}, {"text": "反発する", "is_correct": false, "explanation": "「強く反発するした」と続けると、文法的に成り立たない。"}], "explanations": {"反発": "「強く反発した」の形で、生徒が反対の態度を示したことを表す。", "反発し": "「強く反発しした」と動詞の形が重なり、文法的に成り立たない。", "反発して": "「強く反発してした」と「て」と過去形が重なり、文法的に成り立たない。", "反発する": "「強く反発するした」と続けると、文法的に成り立たない。"}, "sentence_index": 0, "correct_answer": "反発"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "前日の下落から、日経平均が反発した。", "explanation": "ここは〈株価が持ち直す〉の意味。人の反対の態度とは別で、相場の話に使う。"}, {"text": "ばねを強く押すと、強い反発が手に返ってきた。", "explanation": "ここは〈押し返す力〉の意味。人の反対を表す語義とは別で、物理の話に使う。"}, {"text": "ボールが床に当たり、高く反発した。", "explanation": "ここは〈はね返る力〉の意味。人の意見への反対とは別で、物の動きの話に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37691, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反発", "is_correct": true, "explanation": "委員が反対の態度を示したことを表し、「反発した」と続けて自然に合う。"}, {"text": "反発だ", "is_correct": false, "explanation": "「反発だした」と続けると、文法的に成り立たない。"}, {"text": "反発の", "is_correct": false, "explanation": "「反発のした」と続けると、名詞の後に動詞が続かず、文法的に成り立たない。"}, {"text": "反発な", "is_correct": false, "explanation": "「反発なした」と続けると、「な」の形が動詞に続かず、文法的に成り立たない。"}], "explanations": {"反発": "委員が反対の態度を示したことを表し、「反発した」と続けて自然に合う。", "反発だ": "「反発だした」と続けると、文法的に成り立たない。", "反発の": "「反発のした」と続けると、名詞の後に動詞が続かず、文法的に成り立たない。", "反発な": "「反発なした」と続けると、「な」の形が動詞に続かず、文法的に成り立たない。"}, "sentence_index": 6, "correct_answer": "反発"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "前日の下落から、株価が反発して値を戻した。", "explanation": "ここは〈株価が持ち直す〉の意味。人の反対の態度とは別の語義。"}, {"text": "壁に当たった球が、強く反発して戻ってきた。", "explanation": "ここは〈押し返す力〉の意味。人の反対とは別で、物の動きに使う。"}, {"text": "磁石の同じ極どうしが、強く反発し合う。", "explanation": "ここは〈押し返す力〉の意味。意見に逆らう態度とは別で、物理の話に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37691, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生の提案に、生徒たちは強く反発しした。", "corrected_sentence": "先生の提案に、生徒たちは強く反発した。", "error_description": "「反発した」が正しい形。「しした」と動詞の形を重ねたのは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37691, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生の指示は、生徒たちの反発に招いた。", "corrected_sentence": "先生の指示は、生徒たちの反発を招いた。", "error_description": "「招く」の目的語を示す「を」が正しい。「に」にすると「招いた」と結びつかない誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
