INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37692, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「加えた」の目的語を示す。「推力を加えた」が自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「推力へ加えた」では加える対象が合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、「推力より加えた」は文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾だが、「推力の加えた」では動詞の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「加えた」の目的語を示す。「推力を加えた」が自然。", "へ": "方向を示すが、「推力へ加えた」では加える対象が合わない。", "より": "比較を示すが、「推力より加えた」は文として成り立たない。", "の": "連体修飾だが、「推力の加えた」では動詞の目的語にならない。"}, "error_tags": {"へ": "方向", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37692, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものを前に押す力のことです。", "primary_collocate": null, "pronunciation": "すいりょく", "ipa": "sɯiɾʲokɯ", "syllable_count": 3, "sentences": [{"text": "船は風の推力で前に進んだ。", "target_word": "推力", "complexity_tier": "T3", "furigana": "船[ふね]は風[かぜ]の推力[すいりょく]で前[まえ]に進[すす]んだ。", "sentence_source": "generated"}, {"text": "足に力を入れて、自転車に強い推力を与えた。", "target_word": "推力", "complexity_tier": "T3", "furigana": "足[あし]に力[ちから]を入[い]れて、自転車[じてんしゃ]に強[つよ]い推力[すいりょく]を与[あた]えた。", "sentence_source": "generated"}, {"text": "推力が足りなくて、重い箱は動かなかった。", "target_word": "推力", "complexity_tier": "T3", "furigana": "推力[すいりょく]が足[た]りなくて、重[おも]い箱[はこ]は動[うご]かなかった。", "sentence_source": "generated"}, {"text": "このボートは小さいが、水を後ろに押して推力を得る。", "target_word": "推力", "complexity_tier": "T3", "furigana": "このボートは小[ちい]さいが、水[みず]を後[うし]ろに押[お]して推力[すいりょく]を得[え]る。", "sentence_source": "generated"}, {"text": "泳ぐとき、足で水を蹴ると前に進む推力が生まれる。", "target_word": "推力", "complexity_tier": "T3", "furigana": "泳[およ]ぐとき、足[あし]で水[みず]を蹴[け]ると前[まえ]に進[すす]む推力[すいりょく]が生[う]まれる。", "sentence_source": "generated"}, {"text": "風が弱い日は、ヨットの推力も小さくなる。", "target_word": "推力", "complexity_tier": "T3", "furigana": "風[かぜ]が弱[よわ]い日[ひ]は、ヨットの推力[すいりょく]も小[ちい]さくなる。", "sentence_source": "generated"}, {"text": "もっと強く押して推力を大きくするように、先生は言った。", "target_word": "推力", "complexity_tier": "T3", "furigana": "もっと強[つよ]く押[お]して推力[すいりょく]を大[おお]きくするように、先生[せんせい]は言[い]った。", "sentence_source": "generated"}, {"text": "彼は台車の後ろから、前へ向かって推力を加えた。", "target_word": "推力", "complexity_tier": "T3", "furigana": "彼[かれ]は台車[だいしゃ]の後[うし]ろから、前[まえ]へ向[む]かって推力[すいりょく]を加[くわ]えた。", "sentence_source": "generated"}, {"text": "向かい風が強く、推力より抵抗のほうが大きかった。", "target_word": "推力", "complexity_tier": "T3", "furigana": "向[む]かい風[かぜ]が強[つよ]く、推力[すいりょく]より抵抗[ていこう]のほうが大[おお]きかった。", "sentence_source": "generated"}, {"text": "坂を上るには、車に大きな推力が必要だ。", "target_word": "推力", "complexity_tier": "T3", "furigana": "坂[さか]を上[のぼ]るには、車[くるま]に大[おお]きな推力[すいりょく]が必要[ひつよう]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "推力", "label": "基本形"}], "register": "一般（普通体）", "sense_fingerprint": "物を前へ押し進める力。日常の場面での前向きの押す力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a59e52e-a96c-4120-ac95-7f3d10883587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37692, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "推力", "is_correct": true, "explanation": "「風の推力で前に進んだ」は、風が船を押す力として自然に合う。"}, {"text": "重量", "is_correct": false, "explanation": "重さを表すため、風の力で船が前へ進んだ場面に合わない。"}, {"text": "湿度", "is_correct": false, "explanation": "空気の湿り気を表し、船を前へ進ませる力とは無関係。"}, {"text": "明るさ", "is_correct": false, "explanation": "光の度合いを表し、船が前へ進む理由にならない。"}], "explanations": {"推力": "「風の推力で前に進んだ」は、風が船を押す力として自然に合う。", "重量": "重さを表すため、風の力で船が前へ進んだ場面に合わない。", "湿度": "空気の湿り気を表し、船を前へ進ませる力とは無関係。", "明るさ": "光の度合いを表し、船が前へ進む理由にならない。"}, "sentence_index": 0, "correct_answer": "推力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "刑事は証拠から、犯人の行動を推力で割り出した。", "explanation": "ここは〈推理〉の意味。推力は物を前へ押す力で、証拠から考えを導く場面には使わない。"}, {"text": "タンクの中の推力が高すぎて、ふたが飛んだ。", "explanation": "ここは〈圧力〉の意味。推力は前へ押し進める力で、容器の内側から押し広げる力には合わない。"}, {"text": "ボールは推力で、地面へ落ちていった。", "explanation": "ここは〈重力〉の意味。推力は前へ押す力なので、下へ落ちる理由にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37692, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "推力", "is_correct": true, "explanation": "「推力を大きくする」は、押す力を増やす文脈に合う。"}, {"text": "色", "is_correct": false, "explanation": "「色を大きくする」とは言わず、押す力の話に合わない。"}, {"text": "雨", "is_correct": false, "explanation": "「雨を大きくする」は不自然で、力を増やす文脈に合わない。"}, {"text": "体温", "is_correct": false, "explanation": "体温は上げると言い、押す力を大きくする文脈に合わない。"}], "explanations": {"推力": "「推力を大きくする」は、押す力を増やす文脈に合う。", "色": "「色を大きくする」とは言わず、押す力の話に合わない。", "雨": "「雨を大きくする」は不自然で、力を増やす文脈に合わない。", "体温": "体温は上げると言い、押す力を大きくする文脈に合わない。"}, "sentence_index": 6, "correct_answer": "推力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ロープにかかる推力が大きすぎて、とうとう切れた。", "explanation": "ここは〈張力〉の意味。ロープが引っ張られる力は張力で、前へ押す推力とは言わない。"}, {"text": "坂を上るには、私に大きな推力が必要だ。", "explanation": "ここは〈体力〉の意味。推力は物を前へ押す力で、人の持久力には使わない。"}, {"text": "月の推力で、潮が満ちてくる。", "explanation": "ここは〈引力〉の意味。推力は物を前へ押す力で、遠くから引き寄せる力は引力と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37692, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ヨットは風の推力に沖へ進んだ。", "corrected_sentence": "ヨットは風の推力で沖へ進んだ。", "error_description": "「推力」の後には手段を表す「で」が入る。「に」にすると「推力に進んだ」となり、意味が通らない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37692, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ボートは水を押す推力を、前へ進んだ。", "corrected_sentence": "ボートは水を押す推力で、前へ進んだ。", "error_description": "推力を進む手段として示すなら「で」。「を」にすると目的語になり、「前へ進んだ」と合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37693, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「出せる」の目的語を示す。「推力を出せる」が自然。"}, {"text": "に", "is_correct": false, "explanation": "「推力に出せる」では目的語にならず不自然。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾だが、「推力の出せる」で文が終わらず、述語がない。"}, {"text": "と", "is_correct": false, "explanation": "並列を示すが、「推力と出せる」では動詞の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「出せる」の目的語を示す。「推力を出せる」が自然。", "に": "「推力に出せる」では目的語にならず不自然。", "の": "連体修飾だが、「推力の出せる」で文が終わらず、述語がない。", "と": "並列を示すが、「推力と出せる」では動詞の目的語にならない。"}, "error_tags": {"に": "相手・対象", "の": "連体修飾", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37693, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「最大にした」の目的語を示す。「推力を最大にした」が自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「推力へ最大にした」では意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、「推力より最大にした」は不自然。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾だが、「推力の最大にした」では動詞の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「最大にした」の目的語を示す。「推力を最大にした」が自然。", "へ": "方向を示すが、「推力へ最大にした」では意味が通らない。", "より": "比較を示すが、「推力より最大にした」は不自然。", "の": "連体修飾だが、「推力の最大にした」では動詞の目的語にならない。"}, "error_tags": {"へ": "方向", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37693, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物体を前方に押し進める力。飛行機やロケットなどの推進に使われる。", "primary_collocate": null, "pronunciation": "すいりょく", "ipa": "sɯiɾʲokɯ", "syllable_count": 3, "sentences": [{"text": "ロケットは大きな推力で空へ上がっていく。", "target_word": "推力", "complexity_tier": "T3", "furigana": "ロケットは大[おお]きな推力[すいりょく]で空[そら]へ上[あ]がっていく。", "sentence_source": "generated"}, {"text": "この飛行機のエンジンは、強い推力を出せる。", "target_word": "推力", "complexity_tier": "T3", "furigana": "この飛行機[ひこうき]のエンジンは、強[つよ]い推力[すいりょく]を出[だ]せる。", "sentence_source": "generated"}, {"text": "推力が重さより小さいと、ロケットは地上から離れられない。", "target_word": "推力", "complexity_tier": "T3", "furigana": "推力[すいりょく]が重[おも]さより小[ちい]さいと、ロケットは地上[ちじょう]から離[はな]れられない。", "sentence_source": "generated"}, {"text": "ジェットエンジンは、空気を後ろに噴き出して推力を得る。", "target_word": "推力", "complexity_tier": "T3", "furigana": "ジェットエンジンは、空気[くうき]を後[うし]ろに噴[ふ]き出[だ]して推力[すいりょく]を得[え]る。", "sentence_source": "generated"}, {"text": "新しいエンジンは、前のものより推力が二割大きい。", "target_word": "推力", "complexity_tier": "T3", "furigana": "新[あたら]しいエンジンは、前[まえ]のものより推力[すいりょく]が二割[にわり]大[おお]きい。", "sentence_source": "generated"}, {"text": "燃料が切れると、推力がなくなって機体は速度を落とした。", "target_word": "推力", "complexity_tier": "T3", "furigana": "燃料[ねんりょう]が切[き]れると、推力[すいりょく]がなくなって機体[きたい]は速度[そくど]を落[お]とした。", "sentence_source": "generated"}, {"text": "宇宙船は小さな推力で、少しずつ向きを変えた。", "target_word": "推力", "complexity_tier": "T3", "furigana": "宇宙船[うちゅうせん]は小[ちい]さな推力[すいりょく]で、少[すこ]しずつ向[む]きを変[か]えた。", "sentence_source": "generated"}, {"text": "離陸のとき、パイロットはエンジンの推力を最大にした。", "target_word": "推力", "complexity_tier": "T3", "furigana": "離陸[りりく]のとき、パイロットはエンジンの推力[すいりょく]を最大[さいだい]にした。", "sentence_source": "generated"}, {"text": "推力を調べるために、工場でエンジンの試験を行った。", "target_word": "推力", "complexity_tier": "T3", "furigana": "推力[すいりょく]を調[しら]べるために、工場[こうじょう]でエンジンの試験[しけん]を行[おこな]った。", "sentence_source": "generated"}, {"text": "小型の衛星には、推力の弱いエンジンで十分だ。", "target_word": "推力", "complexity_tier": "T3", "furigana": "小型[こがた]の衛星[えいせい]には、推力[すいりょく]の弱[よわ]いエンジンで十分[じゅうぶん]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "推力", "label": "基本形"}], "register": "技術（普通体）", "sense_fingerprint": "飛行機・ロケット・エンジンが出す推進のための力という技術的な意味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a59e52e-a96c-4120-ac95-7f3d10883587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37693, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "推力", "is_correct": true, "explanation": "「大きな推力で空へ上がっていく」は、ロケットを押し上げる力として合う。"}, {"text": "重量", "is_correct": false, "explanation": "重さで空へ上がるとは言わず、推進の文脈に合わない。"}, {"text": "電圧", "is_correct": false, "explanation": "電気の圧力を表し、ロケットの上昇の説明にならない。"}, {"text": "湿度", "is_correct": false, "explanation": "空気の湿り気を表し、上昇の力にならない。"}], "explanations": {"推力": "「大きな推力で空へ上がっていく」は、ロケットを押し上げる力として合う。", "重量": "重さで空へ上がるとは言わず、推進の文脈に合わない。", "電圧": "電気の圧力を表し、ロケットの上昇の説明にならない。", "湿度": "空気の湿り気を表し、上昇の力にならない。"}, "sentence_index": 0, "correct_answer": "推力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "翼が空気を下へ押して、機体を浮かせる推力を得る。", "explanation": "ここは〈揚力〉の意味。推力は機体を前へ進ませる力で、浮かせる力は揚力と言う。"}, {"text": "ロケットの推力は地面に向かって働くので、機体は下へ落ちていく。", "explanation": "ここは〈重力〉の意味。推力は前へ押し進める力で、機体を地面へ引く力ではない。"}, {"text": "ブレーキは、路面との推力で車の速度を落とす。", "explanation": "ここは〈摩擦〉の意味。推力は前へ進ませる力で、速度を落とすのは摩擦力による。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37693, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "推力", "is_correct": true, "explanation": "「小さな推力で向きを変えた」は、噴射の力で宇宙船が向きを変える意味に合う。"}, {"text": "色", "is_correct": false, "explanation": "色で向きを変えるとは言わず、意味が通らない。"}, {"text": "年齢", "is_correct": false, "explanation": "年齢の大小で宇宙船の向きは変わらず、無関係。"}, {"text": "雨", "is_correct": false, "explanation": "雨で宇宙船の向きは変わらず、推進の文脈に合わない。"}], "explanations": {"推力": "「小さな推力で向きを変えた」は、噴射の力で宇宙船が向きを変える意味に合う。", "色": "色で向きを変えるとは言わず、意味が通らない。", "年齢": "年齢の大小で宇宙船の向きは変わらず、無関係。", "雨": "雨で宇宙船の向きは変わらず、推進の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "推力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このモーターは、推力が三キロワットある。", "explanation": "ここは〈出力〉の意味。推力は物を前へ押す力で、キロワットで表す仕事率には使わない。"}, {"text": "ガスボンベの推力が高すぎて、ふたが飛んだ。", "explanation": "ここは〈圧力〉の意味。推力は前へ押し進める力で、容器の内側の押す力を言う語ではない。"}, {"text": "ロープの推力が弱くて、衛星を引っ張れなかった。", "explanation": "ここは〈牽引力〉の意味。推力は前へ押す力で、ロープが引く力には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37693, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小型機は強い推力に滑走路から離陸した。", "corrected_sentence": "小型機は強い推力で滑走路から離陸した。", "error_description": "「推力」の後には手段を表す「で」が入る。「に」にすると「推力に離陸した」となり不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37693, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "探査機は小さな推力を、ゆっくり向きを変えた。", "corrected_sentence": "探査機は小さな推力で、ゆっくり向きを変えた。", "error_description": "小さな推力を手段として示すなら「で」。「を」にすると目的語になり、「ゆっくり向きを変えた」と合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
