INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37694, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "「常に」は「いつも」という意味です。", "primary_collocate": null, "pronunciation": "つねに", "ipa": "tsɯneɲi", "syllable_count": 3, "sentences": [{"text": "常に笑顔でいたい。", "target_word": "常に", "complexity_tier": "T1", "furigana": "常[つね]に笑顔[えがお]でいたい。", "sentence_source": "generated"}, {"text": "彼は常に元気だ。", "target_word": "常に", "complexity_tier": "T1", "furigana": "彼[かれ]は常[つね]に元気[げんき]だ。", "sentence_source": "generated"}, {"text": "私は常に地図を持っています。", "target_word": "常に", "complexity_tier": "T2", "furigana": "私[わたし]は常[つね]に地図[ちず]を持[も]っています。", "sentence_source": "generated"}, {"text": "常に水を飲むようにしている。", "target_word": "常に", "complexity_tier": "T3", "furigana": "常[つね]に水[みず]を飲[の]むようにしている。", "sentence_source": "generated"}, {"text": "安全のため、常に周りを確認してください。", "target_word": "常に", "complexity_tier": "T3", "furigana": "安全[あんぜん]のため、常[つね]に周[まわ]りを確認[かくにん]してください。", "sentence_source": "generated"}, {"text": "彼女の部屋は常にきれいに片づいている。", "target_word": "常に", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の部屋[へや]は常[つね]にきれいに片[かた]づいている。", "sentence_source": "generated"}, {"text": "この店は常に客でいっぱいだ。", "target_word": "常に", "complexity_tier": "T3", "furigana": "この店[みせ]は常[つね]に客[きゃく]でいっぱいだ。", "sentence_source": "generated"}, {"text": "常に準備しておけば、あわてることはない。", "target_word": "常に", "complexity_tier": "T4", "furigana": "常[つね]に準備[じゅんび]しておけば、あわてることはない。", "sentence_source": "generated"}, {"text": "彼は常に約束の時間より早く来る。", "target_word": "常に", "complexity_tier": "T3", "furigana": "彼[かれ]は常[つね]に約束[やくそく]の時間[じかん]より早[はや]く来[く]る。", "sentence_source": "generated"}, {"text": "常に忙しい人ほど、休む時間を大切にするべきだ。", "target_word": "常に", "complexity_tier": "T4", "furigana": "常[つね]に忙[いそが]しい人[ひと]ほど、休[やす]む時間[じかん]を大切[たいせつ]にするべきだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "常々", "label": "派生"}, {"form": "常日頃", "label": "派生"}], "register": "plain", "sense_fingerprint": "副詞 | いつもそうであるという頻度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T3: contains vocabulary far above tier T3: 片づい (Zipf 1.86)']::text[], '61f01209-a5ab-450f-a9fd-dfc8a97e8f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37694, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "常", "is_correct": true, "explanation": "「つね」で、聞こえた語そのものです。"}, {"text": "爪", "is_correct": false, "explanation": "「つめ」で、最後の音が違います。"}, {"text": "鶴", "is_correct": false, "explanation": "「つる」で、最後の音が違います。"}, {"text": "壺", "is_correct": false, "explanation": "「つぼ」で、最後の音が違います。"}, {"text": "綱", "is_correct": false, "explanation": "「つな」で、最後の音が違います。"}], "explanations": {"常": "「つね」で、聞こえた語そのものです。", "爪": "「つめ」で、最後の音が違います。", "鶴": "「つる」で、最後の音が違います。", "壺": "「つぼ」で、最後の音が違います。", "綱": "「つな」で、最後の音が違います。"}, "sentence_index": null, "correct_answer": "常"}, "level_3": {"options": [{"text": "常に", "is_correct": true, "explanation": "「いつも笑顔でいたい」という意味に合います。"}, {"text": "突然", "is_correct": false, "explanation": "形は合うが、「突然笑顔でいたい」は願いとして意味が合わない。"}, {"text": "大変", "is_correct": false, "explanation": "形は合うが、「大変笑顔でいたい」は不自然で意味が合わない。"}, {"text": "昨日", "is_correct": false, "explanation": "形は合うが、昨日のことを「いたい」と願うのは意味が合わない。"}], "explanations": {"常に": "「いつも笑顔でいたい」という意味に合います。", "突然": "形は合うが、「突然笑顔でいたい」は願いとして意味が合わない。", "大変": "形は合うが、「大変笑顔でいたい」は不自然で意味が合わない。", "昨日": "形は合うが、昨日のことを「いたい」と願うのは意味が合わない。"}, "sentence_index": 0, "correct_answer": "常に"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は常に一度だけ富士山に登った。", "explanation": "「常に」は「いつも」の意味で、一度だけの出来事には使えません。"}, {"text": "彼は先週の月曜日に常に学校を休んだ。", "explanation": "「先週の月曜日」は一回だけの日なので、「いつも」を表す「常に」は使えません。"}, {"text": "この電車は常に明日から運行する。", "explanation": "「常に」は継続を表すので、明日から始まる一回の予定とは合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37694, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "常", "is_correct": true, "explanation": "「つね」で、聞こえた語そのものです。"}, {"text": "月", "is_correct": false, "explanation": "「つき」で、最後の音が違います。"}, {"text": "杖", "is_correct": false, "explanation": "「つえ」で、最後の音が違います。"}, {"text": "角", "is_correct": false, "explanation": "「つの」で、最後の音が違います。"}, {"text": "妻", "is_correct": false, "explanation": "「つま」で、最後の音が違います。"}], "explanations": {"常": "「つね」で、聞こえた語そのものです。", "月": "「つき」で、最後の音が違います。", "杖": "「つえ」で、最後の音が違います。", "角": "「つの」で、最後の音が違います。", "妻": "「つま」で、最後の音が違います。"}, "sentence_index": null, "correct_answer": "常"}, "level_3": {"options": [{"text": "常に", "is_correct": true, "explanation": "「この店はいつも客でいっぱいだ」という意味に合います。"}, {"text": "少しも", "is_correct": false, "explanation": "「少しも」は否定の文で使う語です。「いっぱいだ」という肯定の文には合いません。"}, {"text": "決して", "is_correct": false, "explanation": "形は合うが、「決して」は否定と使うので意味が合わない。"}, {"text": "めったに", "is_correct": false, "explanation": "形は合うが、「めったに」は否定と使い、いっぱいという意味と合わない。"}], "explanations": {"常に": "「この店はいつも客でいっぱいだ」という意味に合います。", "少しも": "「少しも」は否定の文で使う語です。「いっぱいだ」という肯定の文には合いません。", "決して": "形は合うが、「決して」は否定と使うので意味が合わない。", "めったに": "形は合うが、「めったに」は否定と使い、いっぱいという意味と合わない。"}, "sentence_index": 6, "correct_answer": "常に"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友達は今朝、常に駅で私を待っていた。", "explanation": "今朝の一回の出来事に「常に」は使えません。"}, {"text": "常に今年の春、私は引っ越しをした。", "explanation": "引っ越しは一度の出来事で、「いつも」の意味の「常に」とは合いません。"}, {"text": "彼は常に初めて海を見た。", "explanation": "「初めて」は一度きりの経験で、「常に」とは意味が矛盾します。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37694, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母は常で台所をきれいにしている。", "corrected_sentence": "母は常に台所をきれいにしている。", "error_description": "「いつも」の意味の副詞は「常に」です。「常で」とは言いません。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37694, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟は常な部屋で本を読んでいる。", "corrected_sentence": "弟は常に部屋で本を読んでいる。", "error_description": "「いつも」の意味では副詞の「常に」を使い、「常な」とは言わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37696, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「それを」で打ち消す対象を示す。「それを打ち消して」と自然。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「それが打ち消して」では兄の行動に合わない。"}, {"text": "に", "is_correct": false, "explanation": "相手を示すが、「それに打ち消して」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "並列を示すが、「それと打ち消して」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「それを」で打ち消す対象を示す。「それを打ち消して」と自然。", "が": "主語を示すが、「それが打ち消して」では兄の行動に合わない。", "に": "相手を示すが、「それに打ち消して」は不自然。", "と": "並列を示すが、「それと打ち消して」は意味が通らない。"}, "error_tags": {"が": "主語", "に": "相手", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37696, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「情報を打ち消した」の目的語を示す。自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「情報へ打ち消した」は対象が合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、「情報より打ち消した」は意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾だが、「情報の打ち消した」では動詞の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「情報を打ち消した」の目的語を示す。自然。", "へ": "方向を示すが、「情報へ打ち消した」は対象が合わない。", "より": "比較を示すが、「情報より打ち消した」は意味が通らない。", "の": "連体修飾だが、「情報の打ち消した」では動詞の目的語にならない。"}, "error_tags": {"へ": "方向", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37696, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かを、なかったことにする。", "primary_collocate": null, "pronunciation": "うちけす", "ipa": "ɯt͡ɕikesɯ", "syllable_count": 4, "sentences": [{"text": "社長は、会社が売られるといううわさをはっきり打ち消した。", "target_word": "打ち消した", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は、会社[かいしゃ]が売[う]られるといううわさをはっきり打[う]ち消[け]した。", "sentence_source": "generated"}, {"text": "「行かない」と言ったあとで、兄はそれを打ち消して「やっぱり行く」と言った。", "target_word": "打ち消して", "complexity_tier": "T3", "furigana": "「行[い]かない」と言[い]ったあとで、兄[あに]はそれを打[う]ち消[け]して「やっぱり行[い]く」と言[い]った。", "sentence_source": "generated"}, {"text": "首相は、辞める考えはないと言って、報道を打ち消した。", "target_word": "打ち消した", "complexity_tier": "T3", "furigana": "首相[しゅしょう]は、辞[や]める考[かんが]えはないと言[い]って、報道[ほうどう]を打[う]ち消[け]した。", "sentence_source": "generated"}, {"text": "「さっきの話は忘れて」と言って、彼女は自分の発言を打ち消した。", "target_word": "打ち消した", "complexity_tier": "T3", "furigana": "「さっきの話[はなし]は忘[わす]れて」と言[い]って、彼女[かのじょ]は自分[じぶん]の発言[はつげん]を打[う]ち消[け]した。", "sentence_source": "generated"}, {"text": "本人が出てきて、結婚するという話を打ち消した。", "target_word": "打ち消した", "complexity_tier": "T3", "furigana": "本人[ほんにん]が出[で]てきて、結婚[けっこん]するという話[はなし]を打[う]ち消[け]した。", "sentence_source": "generated"}, {"text": "会社は、不正があったという報道を打ち消す声明を出した。", "target_word": "打ち消す", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は、不正[ふせい]があったという報道[ほうどう]を打[う]ち消[け]す声明[せいめい]を出[だ]した。", "sentence_source": "generated"}, {"text": "先生は、テストが中止になるといううわさを打ち消した。", "target_word": "打ち消した", "complexity_tier": "T3", "furigana": "先生[せんせい]は、テストが中止[ちゅうし]になるといううわさを打[う]ち消[け]した。", "sentence_source": "generated"}, {"text": "市は、工事が遅れるという情報を打ち消した。", "target_word": "打ち消した", "complexity_tier": "T3", "furigana": "市[し]は、工事[こうじ]が遅[おく]れるという情報[じょうほう]を打[う]ち消[け]した。", "sentence_source": "generated"}, {"text": "警察は、犯人が逃げたという見方を打ち消した。", "target_word": "打ち消した", "complexity_tier": "T3", "furigana": "警察[けいさつ]は、犯人[はんにん]が逃[に]げたという見方[みかた]を打[う]ち消[け]した。", "sentence_source": "generated"}, {"text": "友達は、私が怒っているといううわさを打ち消してくれた。", "target_word": "打ち消して", "complexity_tier": "T3", "furigana": "友達[ともだち]は、私[わたし]が怒[おこ]っているといううわさを打[う]ち消[け]してくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "打ち消す", "label": "基本形"}, {"form": "打ち消した", "label": "過去形"}, {"form": "打ち消さない", "label": "否定形"}, {"form": "打ち消して", "label": "て形"}, {"form": "打ち消せば", "label": "仮定形"}], "register": "一般（普通体）", "sense_fingerprint": "うわさ・報道・発言などを、事実ではない、なかったと言って否定する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a59e52e-a96c-4120-ac95-7f3d10883587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37696, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打ち消した", "is_correct": true, "explanation": "「うわさをはっきり打ち消した」は、うわさを否定して無かったことにする意味に合う。"}, {"text": "祝った", "is_correct": false, "explanation": "うわさを祝うとは言わず、否定の文脈に合わない。"}, {"text": "磨いた", "is_correct": false, "explanation": "うわさを磨くとは言わず、意味が通らない。"}, {"text": "煮た", "is_correct": false, "explanation": "うわさを煮るとは言わず、不自然。"}], "explanations": {"打ち消した": "「うわさをはっきり打ち消した」は、うわさを否定して無かったことにする意味に合う。", "祝った": "うわさを祝うとは言わず、否定の文脈に合わない。", "磨いた": "うわさを磨くとは言わず、意味が通らない。", "煮た": "うわさを煮るとは言わず、不自然。"}, "sentence_index": 0, "correct_answer": "打ち消した"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "社長は、契約の申し込みを打ち消した。", "explanation": "ここは〈取り消す〉の意味。打ち消すは噂や報道を否定する動詞で、申し込みの撤回には合わない。"}, {"text": "彼女は失敗の記録を打ち消して、ファイルを削除した。", "explanation": "ここは〈消す〉の意味。打ち消すは噂や発言をなかったことにする動詞で、データの削除には使わない。"}, {"text": "社長は、会社の株をすべて打ち消した。", "explanation": "ここは〈売り払う〉の意味。打ち消すは噂や報道を否定する動詞で、株を手放す行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37696, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打ち消した", "is_correct": true, "explanation": "「うわさを打ち消した」は、テストの中止のうわさを否定する意味に合う。"}, {"text": "踏んだ", "is_correct": false, "explanation": "うわさを踏むとは言わず、不自然。"}, {"text": "焼いた", "is_correct": false, "explanation": "うわさを焼くとは言わず、意味が通らない。"}, {"text": "刻んだ", "is_correct": false, "explanation": "うわさを刻むとは言わず、文脈に合わない。"}], "explanations": {"打ち消した": "「うわさを打ち消した」は、テストの中止のうわさを否定する意味に合う。", "踏んだ": "うわさを踏むとは言わず、不自然。", "焼いた": "うわさを焼くとは言わず、意味が通らない。", "刻んだ": "うわさを刻むとは言わず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "打ち消した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市は、道路の看板を打ち消して、撤去した。", "explanation": "ここは〈撤去する〉の意味。打ち消すは噂や発言の否定で、看板のような物には使わない。"}, {"text": "彼は部屋のドアを打ち消して、鍵をかけた。", "explanation": "ここは〈閉める〉の意味。打ち消すは噂や言葉を否定する動詞で、ドアには使わない。"}, {"text": "彼女は約束を打ち消して、もう一度会う日を決めた。", "explanation": "ここは〈撤回する〉の意味。打ち消すは噂や報道の否定で、約束そのものの取りやめには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37696, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "社長は、うわさを打ち消しだ。", "corrected_sentence": "社長は、うわさを打ち消した。", "error_description": "「打ち消す」の過去形は「打ち消した」。「打ち消し」に「だ」を付けるのは誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "打ち消して", "is_correct": true, "explanation": "「それを打ち消して「やっぱり行く」と言った」の「て形」で、文が続く。"}, {"text": "打ち消す", "is_correct": false, "explanation": "辞書形では後ろの文と続かず、文が成り立たない。"}, {"text": "打ち消せば", "is_correct": false, "explanation": "仮定形で、「〜て」の文の流れに合わない。"}, {"text": "打ち消された", "is_correct": false, "explanation": "受身形で、兄が打ち消した主語関係に合わない。"}], "correct_form": "打ち消して", "base_form": "打ち消す", "form_label": "て形", "sentence_index": 1, "explanations": {"打ち消して": "「それを打ち消して「やっぱり行く」と言った」の「て形」で、文が続く。", "打ち消す": "辞書形では後ろの文と続かず、文が成り立たない。", "打ち消せば": "仮定形で、「〜て」の文の流れに合わない。", "打ち消された": "受身形で、兄が打ち消した主語関係に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37696, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市長は、報道に打ち消した。", "corrected_sentence": "市長は、報道を打ち消した。", "error_description": "「打ち消す」の目的語には「を」を使う。「に」にすると「報道に打ち消した」となり不自然。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "打ち消した", "is_correct": true, "explanation": "「工事が遅れるという情報を打ち消した」の過去形で、文末に合う。"}, {"text": "打ち消さない", "is_correct": false, "explanation": "否定形で、過去の出来事を述べる文末と合わない。"}, {"text": "打ち消せた", "is_correct": false, "explanation": "可能形の過去で、市が実際に打ち消した出来事とは意味が変わる。"}, {"text": "打ち消させた", "is_correct": false, "explanation": "使役形で、市が誰かに打ち消させた意味になり文が変わる。"}], "correct_form": "打ち消した", "base_form": "打ち消す", "form_label": "過去形", "sentence_index": 7, "explanations": {"打ち消した": "「工事が遅れるという情報を打ち消した」の過去形で、文末に合う。", "打ち消さない": "否定形で、過去の出来事を述べる文末と合わない。", "打ち消せた": "可能形の過去で、市が実際に打ち消した出来事とは意味が変わる。", "打ち消させた": "使役形で、市が誰かに打ち消させた意味になり文が変わる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37697, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「周りの音を」の目的語を示す。「音を打ち消す」と自然。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「音が打ち消してくれる」では主語の関係が逆で不自然。"}, {"text": "に", "is_correct": false, "explanation": "相手を示すが、「音に打ち消す」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "並列を示すが、「音と打ち消す」は文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「周りの音を」の目的語を示す。「音を打ち消す」と自然。", "が": "主語を示すが、「音が打ち消してくれる」では主語の関係が逆で不自然。", "に": "相手を示すが、「音に打ち消す」は不自然。", "と": "並列を示すが、「音と打ち消す」は文が成り立たない。"}, "error_tags": {"が": "主語", "に": "相手", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37697, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「寒さを打ち消す」の目的語を示す。自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「寒さへ打ち消す」は不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、「寒さより打ち消す」は意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾だが、「寒さの打ち消す」では動詞の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「寒さを打ち消す」の目的語を示す。自然。", "へ": "方向を示すが、「寒さへ打ち消す」は不自然。", "より": "比較を示すが、「寒さより打ち消す」は意味が通らない。", "の": "連体修飾だが、「寒さの打ち消す」では動詞の目的語にならない。"}, "error_tags": {"へ": "方向", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37697, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある状態や影響などを、力や作用によってなくすこと。", "primary_collocate": null, "pronunciation": "うちけす", "ipa": "ɯt͡ɕikesɯ", "syllable_count": 4, "sentences": [{"text": "この薬は、毒の働きを打ち消す。", "target_word": "打ち消す", "complexity_tier": "T3", "furigana": "この薬[くすり]は、毒[どく]の働[はたら]きを打[う]ち消[け]す。", "sentence_source": "generated"}, {"text": "このイヤホンは、周りの音を打ち消してくれる。", "target_word": "打ち消して", "complexity_tier": "T3", "furigana": "このイヤホンは、周[まわ]りの音[おと]を打[う]ち消[け]してくれる。", "sentence_source": "generated"}, {"text": "香水の強いにおいが、料理の香りを打ち消してしまった。", "target_word": "打ち消して", "complexity_tier": "T3", "furigana": "香水[こうすい]の強[つよ]いにおいが、料理[りょうり]の香[かお]りを打[う]ち消[け]してしまった。", "sentence_source": "generated"}, {"text": "二つの波がぶつかると、たがいの動きを打ち消すことがある。", "target_word": "打ち消す", "complexity_tier": "T3", "furigana": "二[ふた]つの波[なみ]がぶつかると、たがいの動[うご]きを打[う]ち消[け]すことがある。", "sentence_source": "generated"}, {"text": "砂糖を少し入れて、レモンの酸っぱさを打ち消した。", "target_word": "打ち消した", "complexity_tier": "T3", "furigana": "砂糖[さとう]を少[すこ]し入[い]れて、レモンの酸[す]っぱさを打[う]ち消[け]した。", "sentence_source": "generated"}, {"text": "プラスとマイナスの電気は、たがいの力を打ち消す。", "target_word": "打ち消す", "complexity_tier": "T3", "furigana": "プラスとマイナスの電気[でんき]は、たがいの力[ちから]を打[う]ち消[け]す。", "sentence_source": "generated"}, {"text": "ミントのガムが、口のにおいを打ち消してくれる。", "target_word": "打ち消して", "complexity_tier": "T3", "furigana": "ミントのガムが、口[くち]のにおいを打[う]ち消[け]してくれる。", "sentence_source": "generated"}, {"text": "冬の寒さを打ち消すように、部屋のストーブが強く燃えていた。", "target_word": "打ち消す", "complexity_tier": "T3", "furigana": "冬[ふゆ]の寒[さむ]さを打[う]ち消[け]すように、部屋[へや]のストーブが強[つよ]く燃[も]えていた。", "sentence_source": "generated"}, {"text": "冷たい風が、夏の暑さを打ち消してくれた。", "target_word": "打ち消して", "complexity_tier": "T3", "furigana": "冷[つめ]たい風[かぜ]が、夏[なつ]の暑[あつ]さを打[う]ち消[け]してくれた。", "sentence_source": "generated"}, {"text": "左右から同じ力で引くと、力が打ち消されて動かない。", "target_word": "打ち消されて", "complexity_tier": "T3", "furigana": "左右[さゆう]から同[おな]じ力[ちから]で引[ひ]くと、力[ちから]が打[う]ち消[け]されて動[うご]かない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "打ち消す", "label": "基本形"}, {"form": "打ち消した", "label": "過去形"}, {"form": "打ち消さない", "label": "否定形"}, {"form": "打ち消して", "label": "て形"}, {"form": "打ち消せば", "label": "仮定形"}], "register": "一般（普通体）", "sense_fingerprint": "におい・音・毒・力などの状態や影響を、逆の作用でなくす（打ち消し合う）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a59e52e-a96c-4120-ac95-7f3d10883587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37697, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打ち消す", "is_correct": true, "explanation": "「毒の働きを打ち消す」は、薬が毒の作用を相殺する意味に合う。"}, {"text": "祝う", "is_correct": false, "explanation": "毒の働きを祝うとは言わず、意味が通らない。"}, {"text": "磨く", "is_correct": false, "explanation": "毒の働きを磨くとは言わず、不自然。"}, {"text": "煮る", "is_correct": false, "explanation": "毒の働きを煮るとは言わず、文脈に合わない。"}], "explanations": {"打ち消す": "「毒の働きを打ち消す」は、薬が毒の作用を相殺する意味に合う。", "祝う": "毒の働きを祝うとは言わず、意味が通らない。", "磨く": "毒の働きを磨くとは言わず、不自然。", "煮る": "毒の働きを煮るとは言わず、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "打ち消す"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この薬は、傷口の細菌を打ち消すために塗る。", "explanation": "ここは〈殺す・消毒する〉の意味。打ち消すは働きや影響をなくす意味で、細菌そのものを殺す場面には言わない。"}, {"text": "厚い雲が太陽を打ち消して、あたりが暗くなった。", "explanation": "ここは〈覆い隠す〉の意味。打ち消すは作用を相殺する意味で、光を遮って見えなくする場面には使わない。"}, {"text": "この薬は、毒を体の外へ打ち消して出す。", "explanation": "ここは〈排出する〉の意味。打ち消すは作用をなくすことで、体から外へ出す行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37697, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打ち消して", "is_correct": true, "explanation": "「口のにおいを打ち消してくれる」は、ミントが口のにおいを消す意味に合う。"}, {"text": "撫でて", "is_correct": false, "explanation": "においを撫でるとは言わず、不自然。"}, {"text": "焼いて", "is_correct": false, "explanation": "においを焼くとは言わず、意味が通らない。"}, {"text": "叩いて", "is_correct": false, "explanation": "においを叩くとは言わず、文脈に合わない。"}], "explanations": {"打ち消して": "「口のにおいを打ち消してくれる」は、ミントが口のにおいを消す意味に合う。", "撫でて": "においを撫でるとは言わず、不自然。", "焼いて": "においを焼くとは言わず、意味が通らない。", "叩いて": "においを叩くとは言わず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "打ち消して"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厚いカーテンで、夏の日差しを打ち消して、部屋を暗くした。", "explanation": "ここは〈遮る〉の意味。打ち消すは作用をなくす意味で、光を止めて通さない場面には使わない。"}, {"text": "水で汚れを打ち消して、きれいにした。", "explanation": "ここは〈洗い流す〉の意味。打ち消すは作用を相殺する意味で、汚れを流して落とす行為には使わない。"}, {"text": "ヤスリで板の厚さを打ち消した。", "explanation": "ここは〈削る〉の意味。打ち消すは作用をなくす意味で、物を削り取る行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37697, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この氷は、熱の働きに打ち消す。", "corrected_sentence": "この氷は、熱の働きを打ち消す。", "error_description": "「打ち消す」の目的語には「を」を使う。「に」にすると「働きに打ち消す」となり不自然。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "打ち消して", "is_correct": true, "explanation": "「周りの音を打ち消してくれる」の「て形」で、後ろの「くれる」と続く。"}, {"text": "打ち消さない", "is_correct": false, "explanation": "否定形で、「くれる」と続かない。"}, {"text": "打ち消せば", "is_correct": false, "explanation": "仮定形で、「くれる」の文の流れに合わない。"}, {"text": "打ち消した", "is_correct": false, "explanation": "過去形で、「くれる」と続かず現在の文と合わない。"}], "correct_form": "打ち消して", "base_form": "打ち消す", "form_label": "て形", "sentence_index": 1, "explanations": {"打ち消して": "「周りの音を打ち消してくれる」の「て形」で、後ろの「くれる」と続く。", "打ち消さない": "否定形で、「くれる」と続かない。", "打ち消せば": "仮定形で、「くれる」の文の流れに合わない。", "打ち消した": "過去形で、「くれる」と続かず現在の文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37697, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "換気扇が、台所のにおいを打ち消しくれる。", "corrected_sentence": "換気扇が、台所のにおいを打ち消してくれる。", "error_description": "「打ち消して」の「て」が抜けており、「くれる」と続かない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "打ち消す", "is_correct": true, "explanation": "「冬の寒さを打ち消すように」で、「ように」の前に辞書形が入り目的を示す。"}, {"text": "打ち消して", "is_correct": false, "explanation": "て形で、「ように」の前に続かず文が途切れる。"}, {"text": "打ち消し", "is_correct": false, "explanation": "連用形で、「ように」の前に続かず文が途切れる。"}, {"text": "打ち消そう", "is_correct": false, "explanation": "意志形で、「ように」の前に続かない。"}], "correct_form": "打ち消す", "base_form": "打ち消す", "form_label": "基本形", "sentence_index": 7, "explanations": {"打ち消す": "「冬の寒さを打ち消すように」で、「ように」の前に辞書形が入り目的を示す。", "打ち消して": "て形で、「ように」の前に続かず文が途切れる。", "打ち消し": "連用形で、「ように」の前に続かず文が途切れる。", "打ち消そう": "意志形で、「ように」の前に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37698, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "ジェットが主語となり、空へ上がっていく動作の主体になる"}, {"text": "を", "is_correct": false, "explanation": "「上がる」「行く」は目的語を取らないので、「を」は合わない"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は行き先を表し、ジェットが上がる主語の位置には入らない"}, {"text": "の", "is_correct": false, "explanation": "「の」では名詞句になり、「上がっていく」の主語にならない"}], "correct_answer": "が", "explanations": {"が": "ジェットが主語となり、空へ上がっていく動作の主体になる", "を": "「上がる」「行く」は目的語を取らないので、「を」は合わない", "へ": "「へ」は行き先を表し、ジェットが上がる主語の位置には入らない", "の": "「の」では名詞句になり、「上がっていく」の主語にならない"}, "error_tags": {"を": "目的語", "へ": "方向", "の": "所属"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37698, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "乗り物を使う手段を表し、「小さなジェットで移動した」となる"}, {"text": "に", "is_correct": false, "explanation": "移動の手段ではなく着点を示すので、ここでは合わない"}, {"text": "から", "is_correct": false, "explanation": "直後の「東京から」と重なり、起点が二つになって不自然"}, {"text": "まで", "is_correct": false, "explanation": "「まで」が二つ並び、「ジェットまで」は不自然"}], "correct_answer": "で", "explanations": {"で": "乗り物を使う手段を表し、「小さなジェットで移動した」となる", "に": "移動の手段ではなく着点を示すので、ここでは合わない", "から": "直後の「東京から」と重なり、起点が二つになって不自然", "まで": "「まで」が二つ並び、「ジェットまで」は不自然"}, "error_tags": {"に": "着点", "から": "起点", "まで": "終点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37698, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "空を飛ぶ乗り物の一種で、後ろから強い風を出して前に進むもの。", "primary_collocate": null, "pronunciation": "じぇっと", "ipa": "dʑetːo", "syllable_count": 3, "sentences": [{"text": "ジェットは、後ろから強い風を出して空を飛ぶ。", "target_word": "ジェット", "complexity_tier": "T3", "furigana": "ジェットは、後[うし]ろから強[つよ]い風[かぜ]を出[だ]して空[そら]を飛[と]ぶ。", "sentence_source": "generated"}, {"text": "空港で、大きなジェットが空へ上がっていくのを見た。", "target_word": "ジェット", "complexity_tier": "T3", "furigana": "空港[くうこう]で、大[おお]きなジェットが空[そら]へ上[あ]がっていくのを見[み]た。", "sentence_source": "generated"}, {"text": "ジェットは普通の飛行機より速く飛べる。", "target_word": "ジェット", "complexity_tier": "T3", "furigana": "ジェットは普通[ふつう]の飛行機[ひこうき]より速[はや]く飛[と]べる。", "sentence_source": "generated"}, {"text": "弟はジェットに乗って、外国へ行ってみたいと言っている。", "target_word": "ジェット", "complexity_tier": "T3", "furigana": "弟[おとうと]はジェットに乗[の]って、外国[がいこく]へ行[い]ってみたいと言[い]っている。", "sentence_source": "generated"}, {"text": "青い空に、ジェットが白い線を残して飛んでいた。", "target_word": "ジェット", "complexity_tier": "T3", "furigana": "青[あお]い空[そら]に、ジェットが白[しろ]い線[せん]を残[のこ]して飛[と]んでいた。", "sentence_source": "generated"}, {"text": "ジェットが頭の上を通ると、窓がふるえた。", "target_word": "ジェット", "complexity_tier": "T3", "furigana": "ジェットが頭[あたま]の上[うえ]を通[とお]ると、窓[まど]がふるえた。", "sentence_source": "generated"}, {"text": "昔のジェットは音が大きかったそうだ。", "target_word": "ジェット", "complexity_tier": "T3", "furigana": "昔[むかし]のジェットは音[おと]が大[おお]きかったそうだ。", "sentence_source": "generated"}, {"text": "父は小さなジェットで東京から大阪まで移動した。", "target_word": "ジェット", "complexity_tier": "T3", "furigana": "父[ちち]は小[ちい]さなジェットで東京[とうきょう]から大阪[おおさか]まで移動[いどう]した。", "sentence_source": "generated"}, {"text": "遠くからジェットの音が聞こえて、空を見上げた。", "target_word": "ジェット", "complexity_tier": "T3", "furigana": "遠[とお]くからジェットの音[おと]が聞[き]こえて、空[そら]を見上[みあ]げた。", "sentence_source": "generated"}, {"text": "ジェットは車や船より、ずっと速く進める乗り物だ。", "target_word": "ジェット", "complexity_tier": "T3", "furigana": "ジェットは車[くるま]や船[ふね]より、ずっと速[はや]く進[すす]める乗[の]り物[もの]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ジェット", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "後ろへ強く噴き出して進む空の乗り物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0625842b-0888-44c2-8a00-218ebf20c50e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37698, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ジェット", "is_correct": true, "explanation": "文の主語。後ろへ強い風を出して空を飛ぶ乗り物を指すので合う"}, {"text": "船", "is_correct": false, "explanation": "船は空を飛ばないので、「空を飛ぶ」の主語にならない"}, {"text": "電車", "is_correct": false, "explanation": "電車は線路の上を走るもので、空を飛ばない"}, {"text": "風", "is_correct": false, "explanation": "風は乗り物ではないので、後ろから風を出して飛ぶ主体にならない"}], "explanations": {"ジェット": "文の主語。後ろへ強い風を出して空を飛ぶ乗り物を指すので合う", "船": "船は空を飛ばないので、「空を飛ぶ」の主語にならない", "電車": "電車は線路の上を走るもので、空を飛ばない", "風": "風は乗り物ではないので、後ろから風を出して飛ぶ主体にならない"}, "sentence_index": 0, "correct_answer": "ジェット"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ジェットは、ペダルを踏んで道路を走る乗り物だ。", "explanation": "ここは〈自転車〉の意味。ジェットは空を飛ぶ乗り物で、道路を走るものではないので合わない"}, {"text": "ジェットはプロペラを回して、ゆっくり空を飛ぶ。", "explanation": "〈プロペラ機〉の仕組みの話。ジェットはプロペラを使わず、後ろへ噴き出す力で進むので合わない"}, {"text": "ジェットは宇宙へ向けて、勢いよく打ち上げられる。", "explanation": "〈ロケット〉の意味。ジェットは大気の中を飛ぶ航空機で、宇宙へ打ち上げるものではない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37698, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ジェット", "is_correct": true, "explanation": "文の主語。昔の乗り物として音の大きさを述べている"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆は音の大きさが話題にならない道具で、この文に合わない"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖には音の大きさを語る話題がなく、この文に合わない"}, {"text": "椅子", "is_correct": false, "explanation": "椅子は音が大きかったという話題に合わない"}], "explanations": {"ジェット": "文の主語。昔の乗り物として音の大きさを述べている", "鉛筆": "鉛筆は音の大きさが話題にならない道具で、この文に合わない", "砂糖": "砂糖には音の大きさを語る話題がなく、この文に合わない", "椅子": "椅子は音が大きかったという話題に合わない"}, "sentence_index": 6, "correct_answer": "ジェット"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ジェットは、大きな帆に風を受けて海の上を進む。", "explanation": "〈帆船〉の説明。ジェットはエンジンの噴き出す力で進む航空機なので、帆で風を受けて海を進むとは言えない"}, {"text": "ジェットは、エンジンを使わずに風だけで空を滑るように飛ぶ。", "explanation": "〈グライダー〉の説明。ジェットはエンジンで推進する乗り物なので合わない"}, {"text": "ジェットは、ガスの浮力で空にゆっくり浮かんでいる。", "explanation": "〈飛行船〉の説明。ジェットは浮力で浮く乗り物ではなく、噴き出す力で進む"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37698, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は小さなジェットを乗って、東京へ行った。", "corrected_sentence": "父は小さなジェットに乗って、東京へ行った。", "error_description": "『乗る』は『に』と組むので『を』は誤り。正しくは『ジェットに乗って』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37698, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は小さなジェットに乗りて、大阪へ行った。", "corrected_sentence": "父は小さなジェットに乗って、大阪へ行った。", "error_description": "『乗る』のて形は『乗って』。『乗りて』は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
