INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37699, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ジェットの部品」として、部品の所属を示す"}, {"text": "が", "is_correct": false, "explanation": "ジェットが部品を作る主語になり、不自然"}, {"text": "より", "is_correct": false, "explanation": "比較になり、「作っている」と続かない"}, {"text": "に", "is_correct": false, "explanation": "「ジェットに部品を作る」では相手を表し、「ジェットの部品」の意味にならない"}], "correct_answer": "の", "explanations": {"の": "「ジェットの部品」として、部品の所属を示す", "が": "ジェットが部品を作る主語になり、不自然", "より": "比較になり、「作っている」と続かない", "に": "「ジェットに部品を作る」では相手を表し、「ジェットの部品」の意味にならない"}, "error_tags": {"が": "主語", "より": "比較", "に": "相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37699, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ジェットエンジンによって推進する航空機、またはそのエンジン。", "primary_collocate": null, "pronunciation": "じぇっと", "ipa": "dʑetːo", "syllable_count": 3, "sentences": [{"text": "空港に着くと、白いジェットが滑走路に止まっていた。", "target_word": "ジェット", "complexity_tier": "T3", "furigana": "空港[くうこう]に着[つ]くと、白[しろ]いジェットが滑走路[かっそうろ]に止[と]まっていた。", "sentence_source": "generated"}, {"text": "このジェットのエンジンは、とても力が強い。", "target_word": "ジェット", "complexity_tier": "T3", "furigana": "このジェットのエンジンは、とても力[ちから]が強[つよ]い。", "sentence_source": "generated"}, {"text": "社長は出張のために、小さなジェットを借りた。", "target_word": "ジェット", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は出張[しゅっちょう]のために、小[ちい]さなジェットを借[か]りた。", "sentence_source": "generated"}, {"text": "古いジェットは、燃料をたくさん使う。", "target_word": "ジェット", "complexity_tier": "T3", "furigana": "古[ふる]いジェットは、燃料[ねんりょう]をたくさん使[つか]う。", "sentence_source": "generated"}, {"text": "整備士が、ジェットを丁寧に調べている。", "target_word": "ジェット", "complexity_tier": "T3", "furigana": "整備士[せいびし]が、ジェットを丁寧[ていねい]に調[しら]べている。", "sentence_source": "generated"}, {"text": "軍の新しいジェットが、基地から飛び立った。", "target_word": "ジェット", "complexity_tier": "T3", "furigana": "軍[ぐん]の新[あたら]しいジェットが、基地[きち]から飛[と]び立[た]った。", "sentence_source": "generated"}, {"text": "ジェットは、プロペラ機より高いところを飛べる。", "target_word": "ジェット", "complexity_tier": "T3", "furigana": "ジェットは、プロペラ機[き]より高[たか]いところを飛[と]べる。", "sentence_source": "generated"}, {"text": "工場では、ジェットの部品を一つずつ作っている。", "target_word": "ジェット", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、ジェットの部品[ぶひん]を一[ひと]つずつ作[つく]っている。", "sentence_source": "generated"}, {"text": "世界一速いジェットの記録を、テレビで見た。", "target_word": "ジェット", "complexity_tier": "T3", "furigana": "世界一[せかいいち]速[はや]いジェットの記録[きろく]を、テレビで見[み]た。", "sentence_source": "generated"}, {"text": "彼はジェットのパイロットになるために、勉強を続けている。", "target_word": "ジェット", "complexity_tier": "T3", "furigana": "彼[かれ]はジェットのパイロットになるために、勉強[べんきょう]を続[つづ]けている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ジェット", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ジェットエンジンで推進する航空機やその機関", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0625842b-0888-44c2-8a00-218ebf20c50e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37699, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ジェット", "is_correct": true, "explanation": "形容詞「白い」に続く名詞で、滑走路に止まった機体を指す"}, {"text": "船", "is_correct": false, "explanation": "船は滑走路に止まらないので、この文に合わない"}, {"text": "電車", "is_correct": false, "explanation": "電車は滑走路に止まらないので、この文に合わない"}, {"text": "風", "is_correct": false, "explanation": "風は止まっている機体にならないので、白い風は不自然"}], "explanations": {"ジェット": "形容詞「白い」に続く名詞で、滑走路に止まった機体を指す", "船": "船は滑走路に止まらないので、この文に合わない", "電車": "電車は滑走路に止まらないので、この文に合わない", "風": "風は止まっている機体にならないので、白い風は不自然"}, "sentence_index": 0, "correct_answer": "ジェット"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ジェットのペダルを踏んで、坂道をゆっくり下った。", "explanation": "〈自転車〉の説明。ジェットは航空機やそのエンジンを指し、ペダルで進む乗り物ではないので合わない"}, {"text": "ジェットのプロペラは、エンジンの力でゆっくり回る。", "explanation": "〈プロペラ機〉の話。ジェットにはプロペラがなく、噴き出す力で進むので合わない"}, {"text": "ジェットは燃料と一緒に酸素を積んで、宇宙まで飛んでいく。", "explanation": "〈ロケット〉の説明。ジェットは大気を取り込んで飛ぶ航空機なので、酸素を積んで宇宙へ行くとは言えない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37699, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ジェット", "is_correct": true, "explanation": "文の主語で、プロペラ機より高く飛べる機体を指す"}, {"text": "車", "is_correct": false, "explanation": "車は空を飛べないので、この文に合わない"}, {"text": "椅子", "is_correct": false, "explanation": "椅子は飛ばないので、飛ぶ主語にならない"}, {"text": "窓", "is_correct": false, "explanation": "窓は高いところを飛べないので、この文に合わない"}], "explanations": {"ジェット": "文の主語で、プロペラ機より高く飛べる機体を指す", "車": "車は空を飛べないので、この文に合わない", "椅子": "椅子は飛ばないので、飛ぶ主語にならない", "窓": "窓は高いところを飛べないので、この文に合わない"}, "sentence_index": 6, "correct_answer": "ジェット"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ジェットは、馬に引かれて道を進む乗り物だ。", "explanation": "〈馬車〉の説明。ジェットは噴き出す力で飛ぶ航空機やそのエンジンで、馬が引いて道を進むものではない"}, {"text": "ジェットは、エンジンを切っても風に乗って長く飛び続けられる。", "explanation": "〈グライダー〉の特徴。ジェットはエンジンがなければ推進できないので合わない"}, {"text": "ジェットは、熱した空気の力で空へゆっくり上がる。", "explanation": "〈気球〉の説明。ジェットは熱気で浮くのではなく、噴き出す力で飛ぶ"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37699, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "空港の隅に、白いジェットを一機止まっている。", "corrected_sentence": "空港の隅に、白いジェットが一機止まっている。", "error_description": "『止まる』は主語に『が』をとるので、『を』は誤り。正しくは『ジェットが』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
