INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37700, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「ついていて」の主語（ついているもの）を示す「が」。プロペラが飛行機についている。"}, {"text": "を", "is_correct": false, "explanation": "「つく」は目的語を取らない動詞なので、「を」では文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すので、「プロペラでついていて」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、「プロペラとついていて」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「ついていて」の主語（ついているもの）を示す「が」。プロペラが飛行機についている。", "を": "「つく」は目的語を取らない動詞なので、「を」では文が成り立たない。", "で": "「で」は場所や手段を示すので、「プロペラでついていて」は意味が通らない。", "と": "「と」は並列や相手を示すので、「プロペラとついていて」は成り立たない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
