INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37700, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "回る羽根で飛行機を進ませるもの。", "primary_collocate": null, "pronunciation": "ぷろぺら", "ipa": "pɯɾopeɾa", "syllable_count": 4, "sentences": [{"text": "飛行機のプロペラが回り始めて、うるさい音がした。", "target_word": "プロペラ", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]のプロペラが回[まわ]り始[はじ]めて、うるさい音[おと]がした。", "sentence_source": "generated"}, {"text": "古い小さな飛行機にはプロペラがついていて、ゆっくり飛ぶ。", "target_word": "プロペラ", "complexity_tier": "T3", "furigana": "古[ふる]い小[ちい]さな飛行機[ひこうき]にはプロペラがついていて、ゆっくり飛[と]ぶ。", "sentence_source": "generated"}, {"text": "プロペラが止まったので、飛行機は急に高度を下げた。", "target_word": "プロペラ", "complexity_tier": "T3", "furigana": "プロペラが止[と]まったので、飛行機[ひこうき]は急[きゅう]に高度[こうど]を下[さ]げた。", "sentence_source": "generated"}, {"text": "子どものころ、プロペラの回る飛行機を見るのが好きだった。", "target_word": "プロペラ", "complexity_tier": "T3", "furigana": "子[こ]どものころ、プロペラの回[まわ]る飛行機[ひこうき]を見[み]るのが好[す]きだった。", "sentence_source": "generated"}, {"text": "飛行機が動き出す前に、整備士はプロペラを念入りに調べた。", "target_word": "プロペラ", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]が動[うご]き出[だ]す前[まえ]に、整備士[せいびし]はプロペラを念入[ねんい]りに調[しら]べた。", "sentence_source": "generated"}, {"text": "プロペラが風を切る音で、近くの鳥が飛び立った。", "target_word": "プロペラ", "complexity_tier": "T3", "furigana": "プロペラが風[かぜ]を切[き]る音[おと]で、近[ちか]くの鳥[とり]が飛[と]び立[た]った。", "sentence_source": "generated"}, {"text": "博物館に、戦争の時代の飛行機のプロペラが飾ってある。", "target_word": "プロペラ", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]に、戦争[せんそう]の時代[じだい]の飛行機[ひこうき]のプロペラが飾[かざ]ってある。", "sentence_source": "generated"}, {"text": "プロペラが回ると、飛行機は前に進む。", "target_word": "プロペラ", "complexity_tier": "T3", "furigana": "プロペラが回[まわ]ると、飛行機[ひこうき]は前[まえ]に進[すす]む。", "sentence_source": "generated"}, {"text": "強い風でプロペラが曲がってしまい、飛行機は飛べなかった。", "target_word": "プロペラ", "complexity_tier": "T3", "furigana": "強[つよ]い風[かぜ]でプロペラが曲[ま]がってしまい、飛行機[ひこうき]は飛[と]べなかった。", "sentence_source": "generated"}, {"text": "飛行機の前についているプロペラは、大きな羽根のような形をしている。", "target_word": "プロペラ", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]の前[まえ]についているプロペラは、大[おお]きな羽根[はね]のような形[かたち]をしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "プロペラ", "label": "基本形"}], "register": "中立", "sense_fingerprint": "飛行機の前などについていて、回って機体を前に進める羽根", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f06b4680-4fa3-4940-ae92-665bd01dff19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37700, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "プロペラ", "is_correct": true, "explanation": "「回り始めて」の主語で、回転する羽根を指すので文に合う。"}, {"text": "翼", "is_correct": false, "explanation": "翼は固定されていて回転しないので、「回り始めて」と続かない。"}, {"text": "燃料", "is_correct": false, "explanation": "燃料は液体で回転しないので、「回り始めて」の主語にはならない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は回転する部品ではないので、「回り始めて」とは合わない。"}], "explanations": {"プロペラ": "「回り始めて」の主語で、回転する羽根を指すので文に合う。", "翼": "翼は固定されていて回転しないので、「回り始めて」と続かない。", "燃料": "燃料は液体で回転しないので、「回り始めて」の主語にはならない。", "窓": "窓は回転する部品ではないので、「回り始めて」とは合わない。"}, "sentence_index": 0, "correct_answer": "プロペラ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この車はプロペラが強力で、坂道もすいすい登る。", "explanation": "ここは〈エンジン〉の意味。プロペラは回る羽根で、車の動力源を表さないので合わない。"}, {"text": "自転車のプロペラが回ると、ペダルも一緒に動く。", "explanation": "ここは〈車輪〉の意味。プロペラは飛行機や船を進ませる羽根で、自転車の車輪ではないので合わない。"}, {"text": "雨の日は傘のプロペラを広げて外を歩く。", "explanation": "ここは〈雨具〉の意味。プロペラは回転する羽根で、広げて雨をよける布や骨の部分ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37700, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "プロペラ", "is_correct": true, "explanation": "博物館に展示される飛行機の部品で、「飾ってある」と自然に続く。"}, {"text": "滑走路", "is_correct": false, "explanation": "滑走路は展示できる物ではないので、「飾ってある」と続かない。"}, {"text": "高度", "is_correct": false, "explanation": "高度は物として存在しないので、「飾ってある」の主語にはならない。"}, {"text": "気流", "is_correct": false, "explanation": "気流は目に見えない空気の流れなので、飾ってあるものとして成り立たない。"}], "explanations": {"プロペラ": "博物館に展示される飛行機の部品で、「飾ってある」と自然に続く。", "滑走路": "滑走路は展示できる物ではないので、「飾ってある」と続かない。", "高度": "高度は物として存在しないので、「飾ってある」の主語にはならない。", "気流": "気流は目に見えない空気の流れなので、飾ってあるものとして成り立たない。"}, "sentence_index": 6, "correct_answer": "プロペラ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窓のプロペラを引いて、部屋を暗くした。", "explanation": "ここは〈カーテン〉の意味。プロペラは回転する羽根で、掛けて光をさえぎる布ではないので合わない。"}, {"text": "ドアのプロペラを回すと、扉がゆっくり開く。", "explanation": "ここは〈取っ手〉の意味。プロペラは推進のための羽根で、扉を開けるために握って回す部品ではないので合わない。"}, {"text": "時計のプロペラは、一周すると一時間を指す。", "explanation": "ここは〈針〉の意味。プロペラは回る羽根で、時間を指す部品ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37700, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "強い風が吹いたので、プロペラを大きな音を立てて回った。", "corrected_sentence": "強い風が吹いたので、プロペラが大きな音を立てて回った。", "error_description": "「回る」は自動詞なので、回る主体のプロペラには「が」を使う。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37700, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "整備士は、プロペラを回しで異音を確かめた。", "corrected_sentence": "整備士は、プロペラを回して異音を確かめた。", "error_description": "「回す」の連用形には「て」を続けて「回して」とする。「回しで」は「で」を使った誤った活用なので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37701, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37701, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「換える」で、置き換え先（新しいもの）を示す「に」。新しいプロペラに換える。"}, {"text": "が", "is_correct": false, "explanation": "「新しいプロペラが換えて」では主語と目的語が合わず、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、「プロペラから換えて」では意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「プロペラより換えて」は成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「換える」で、置き換え先（新しいもの）を示す「に」。新しいプロペラに換える。", "が": "「新しいプロペラが換えて」では主語と目的語が合わず、文が成り立たない。", "から": "「から」は起点を示すので、「プロペラから換えて」では意味が通らない。", "より": "「より」は比較を示すので、「プロペラより換えて」は成り立たない。"}, "error_tags": {"が": "主語", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37701, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "飛行機や船を動かすために、回転する羽根のついた装置。", "primary_collocate": null, "pronunciation": "ぷろぺら", "ipa": "pɯɾopeɾa", "syllable_count": 4, "sentences": [{"text": "小さな船のプロペラに網がからまって、船が動かなくなった。", "target_word": "プロペラ", "complexity_tier": "T3", "furigana": "小[ちい]さな船[ふね]のプロペラに網[あみ]がからまって、船[ふね]が動[うご]かなくなった。", "sentence_source": "generated"}, {"text": "船のプロペラは水の中で回り、船体を前へ押し出す。", "target_word": "プロペラ", "complexity_tier": "T3", "furigana": "船[ふね]のプロペラは水[みず]の中[なか]で回[まわ]り、船体[せんたい]を前[まえ]へ押[お]し出[だ]す。", "sentence_source": "generated"}, {"text": "修理の人がプロペラの羽根を一枚ずつ新しいものに替えた。", "target_word": "プロペラ", "complexity_tier": "T3", "furigana": "修理[しゅうり]の人[ひと]がプロペラの羽根[はね]を一枚[いちまい]ずつ新[あたら]しいものに替[か]えた。", "sentence_source": "generated"}, {"text": "この装置は、プロペラを速く回すほど、大きな力が出る。", "target_word": "プロペラ", "complexity_tier": "T3", "furigana": "この装置[そうち]は、プロペラを速[はや]く回[まわ]すほど、大[おお]きな力[ちから]が出[で]る。", "sentence_source": "generated"}, {"text": "潜水士は海に入って、船のプロペラのきずを確かめた。", "target_word": "プロペラ", "complexity_tier": "T3", "furigana": "潜水士[せんすいし]は海[うみ]に入[はい]って、船[ふね]のプロペラのきずを確[たし]かめた。", "sentence_source": "generated"}, {"text": "大型の飛行機では、プロペラの回転数をエンジンで細かく調整する。", "target_word": "プロペラ", "complexity_tier": "T3", "furigana": "大型[おおがた]の飛行機[ひこうき]では、プロペラの回転数[かいてんすう]をエンジンで細[こま]かく調整[ちょうせい]する。", "sentence_source": "generated"}, {"text": "ゴミがプロペラに巻きついたため、ボートは港に戻れなかった。", "target_word": "プロペラ", "complexity_tier": "T3", "furigana": "ゴミがプロペラに巻[ま]きついたため、ボートは港[みなと]に戻[もど]れなかった。", "sentence_source": "generated"}, {"text": "新しいプロペラに換えてから、船は燃料をあまり使わずに走れる。", "target_word": "プロペラ", "complexity_tier": "T3", "furigana": "新[あたら]しいプロペラに換[か]えてから、船[ふね]は燃料[ねんりょう]をあまり使[つか]わずに走[はし]れる。", "sentence_source": "generated"}, {"text": "工場では、金属を削ってプロペラの形を作っている。", "target_word": "プロペラ", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、金属[きんぞく]を削[けず]ってプロペラの形[かたち]を作[つく]っている。", "sentence_source": "generated"}, {"text": "プロペラの羽根の数が多いと、音は小さくなりやすい。", "target_word": "プロペラ", "complexity_tier": "T3", "furigana": "プロペラの羽根[はね]の数[かず]が多[おお]いと、音[おと]は小[ちい]さくなりやすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "プロペラ", "label": "基本形"}], "register": "中立", "sense_fingerprint": "飛行機や船を推進させる、回転羽根つきの装置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f06b4680-4fa3-4940-ae92-665bd01dff19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37701, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "プロペラ", "is_correct": true, "explanation": "網がからまる対象となる船の推進装置を指し、文に合う。"}, {"text": "船室", "is_correct": false, "explanation": "船室は人が過ごす空間で、網がからまる対象にはならないので文が合わない。"}, {"text": "食堂", "is_correct": false, "explanation": "食堂は人が食事をする場所で、網がからまることはないので合わない。"}, {"text": "厨房", "is_correct": false, "explanation": "厨房は調理場で、網がからまる部品ではないので文が成り立たない。"}], "explanations": {"プロペラ": "網がからまる対象となる船の推進装置を指し、文に合う。", "船室": "船室は人が過ごす空間で、網がからまる対象にはならないので文が合わない。", "食堂": "食堂は人が食事をする場所で、網がからまることはないので合わない。", "厨房": "厨房は調理場で、網がからまる部品ではないので文が成り立たない。"}, "sentence_index": 0, "correct_answer": "プロペラ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ビンのプロペラを強く回すと、ふたが開く。", "explanation": "ここは〈栓〉の意味。プロペラは回転する羽根の装置で、容器を密閉する栓ではないので合わない。"}, {"text": "この時計は、プロペラを速く回すほど、針が早く進む。", "explanation": "ここは〈歯車〉の意味。プロペラは羽根で、かみ合って動力を伝える歯車ではないので合わない。"}, {"text": "この車は、プロペラを右に回すと、左に曲がる。", "explanation": "ここは〈ハンドル〉の意味。プロペラは推進のための羽根で、進路を決める操作部品ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37701, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "プロペラ", "is_correct": true, "explanation": "ゴミが巻きついた対象で、船の推進装置を指すので文に合う。"}, {"text": "空気", "is_correct": false, "explanation": "空気は物に巻きつかず、「ゴミが空気に巻きつく」は意味が通らない。"}, {"text": "光", "is_correct": false, "explanation": "光は物に巻きつかず、「ゴミが光に巻きつく」は意味が通らない。"}, {"text": "砂", "is_correct": false, "explanation": "砂は網のように巻きつかず、「ゴミが砂に巻きつく」は成り立たない。"}], "explanations": {"プロペラ": "ゴミが巻きついた対象で、船の推進装置を指すので文に合う。", "空気": "空気は物に巻きつかず、「ゴミが空気に巻きつく」は意味が通らない。", "光": "光は物に巻きつかず、「ゴミが光に巻きつく」は意味が通らない。", "砂": "砂は網のように巻きつかず、「ゴミが砂に巻きつく」は成り立たない。"}, "sentence_index": 6, "correct_answer": "プロペラ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "家の玄関のプロペラを開けて、客を迎えた。", "explanation": "ここは〈扉〉の意味。プロペラは回転して推進する羽根で、開け閉めする扉ではないので合わない。"}, {"text": "この懐中電灯のプロペラを入れ替えると、明かりがつく。", "explanation": "ここは〈電池〉の意味。プロペラは電気を蓄える部品ではないので、入れ替えて明かりをつける物にはならない。"}, {"text": "ヨットのプロペラを広げて、風を受けた。", "explanation": "ここは〈帆〉の意味。プロペラは回転して推進する羽根で、風を受けて船を走らせる布ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37701, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "潜水士は、プロペラを汚れを落とした。", "corrected_sentence": "潜水士は、プロペラの汚れを落とした。", "error_description": "「プロペラの汚れ」のように名詞をつなぐ「の」が正しい。「を」を入れると文の構造が壊れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37701, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工場では、金属を削ってプロペラを踏んでいる。", "corrected_sentence": "工場では、金属を削ってプロペラを作っている。", "error_description": "「プロペラを」に続く動詞は「作る」が正しい。「踏む」はプロペラの製造とは合わず、誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
