INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37702, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "〈釣り合っている〉の主語「重さ」を示す「が」。"}, {"text": "に", "is_correct": false, "explanation": "〈釣り合う〉は相手を「と」で表すので、「重さに釣り合っている」では釣り合う相手が示せない。"}, {"text": "から", "is_correct": false, "explanation": "「重さから」は起点や理由を表し、〈釣り合っている〉の主語にはならない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す「より」は、〈釣り合っている〉の主語を示せず、文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "〈釣り合っている〉の主語「重さ」を示す「が」。", "に": "〈釣り合う〉は相手を「と」で表すので、「重さに釣り合っている」では釣り合う相手が示せない。", "から": "「重さから」は起点や理由を表し、〈釣り合っている〉の主語にはならない。", "より": "比較を表す「より」は、〈釣り合っている〉の主語を示せず、文として成り立たない。"}, "error_tags": {"に": "相手・方向", "から": "起点・理由", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37702, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものが重さを同じにして、どちらかにかたむかないこと。", "primary_collocate": null, "pronunciation": "つりあう", "ipa": "t͡sɯɾiaɯ", "syllable_count": 4, "sentences": [{"text": "天びんの両側の重さが同じで、きれいに釣り合った。", "target_word": "釣り合った", "complexity_tier": "T3", "furigana": "天[てん]びんの両側[りょうがわ]の重[おも]さが同[おな]じで、きれいに釣[つ]り合[あ]った。", "sentence_source": "generated"}, {"text": "左に石を置くと、右の箱と釣り合った。", "target_word": "釣り合った", "complexity_tier": "T3", "furigana": "左[ひだり]に石[いし]を置[お]くと、右[みぎ]の箱[はこ]と釣[つ]り合[あ]った。", "sentence_source": "generated"}, {"text": "シーソーは、二人の重さが違うと釣り合わない。", "target_word": "釣り合わない", "complexity_tier": "T3", "furigana": "シーソーは、二人[ふたり]の重[おも]さが違[ちが]うと釣[つ]り合[あ]わない。", "sentence_source": "generated"}, {"text": "りんご三個と、おもりが釣り合っている。", "target_word": "釣り合っている", "complexity_tier": "T3", "furigana": "りんご三個[さんこ]と、おもりが釣[つ]り合[あ]っている。", "sentence_source": "generated"}, {"text": "片方が重すぎて、はかりが釣り合わなかった。", "target_word": "釣り合わなかった", "complexity_tier": "T3", "furigana": "片方[かたほう]が重[おも]すぎて、はかりが釣[つ]り合[あ]わなかった。", "sentence_source": "generated"}, {"text": "荷物の重さが左右で釣り合うように、棒の両端にかごを下げた。", "target_word": "釣り合う", "complexity_tier": "T3", "furigana": "荷物[にもつ]の重[おも]さが左右[さゆう]で釣[つ]り合[あ]うように、棒[ぼう]の両端[りょうはし]にかごを下[さ]げた。", "sentence_source": "generated"}, {"text": "砂を少しずつ足すと、やがて両方の皿が釣り合った。", "target_word": "釣り合った", "complexity_tier": "T3", "furigana": "砂[すな]を少[すこ]しずつ足[た]すと、やがて両方[りょうほう]の皿[さら]が釣[つ]り合[あ]った。", "sentence_source": "generated"}, {"text": "やじろべえは、左右の重さが釣り合っているので、倒れない。", "target_word": "釣り合っている", "complexity_tier": "T3", "furigana": "やじろべえは、左右[さゆう]の重[おも]さが釣[つ]り合[あ]っているので、倒[たお]れない。", "sentence_source": "generated"}, {"text": "重さが釣り合っていないので、棚がかたむいている。", "target_word": "釣り合っていない", "complexity_tier": "T3", "furigana": "重[おも]さが釣[つ]り合[あ]っていないので、棚[たな]がかたむいている。", "sentence_source": "generated"}, {"text": "おもりを一つ取ると、天びんは釣り合わなくなった。", "target_word": "釣り合わなく", "complexity_tier": "T3", "furigana": "おもりを一[ひと]つ取[と]ると、天[てん]びんは釣[つ]り合[あ]わなくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "釣り合う", "label": "基本形"}, {"form": "釣り合った", "label": "過去形"}, {"form": "釣り合わない", "label": "否定形"}, {"form": "釣り合って", "label": "て形"}, {"form": "釣り合えば", "label": "仮定形"}], "register": "一般（普通体）", "sense_fingerprint": "天びんやシーソーなどで、両側の重さが同じになってかたむかない", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a59e52e-a96c-4120-ac95-7f3d10883587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37702, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "釣り合った", "is_correct": true, "explanation": "過去形で「きれいに釣り合った」という結果を言い切れる。前の「重さが同じで」とも合う。"}, {"text": "釣り合って", "is_correct": false, "explanation": "て形は文を言い切れず、「。」で終えられない。"}, {"text": "釣り合えば", "is_correct": false, "explanation": "条件の形で、主節がないと文が終わらない。"}, {"text": "傾いた", "is_correct": false, "explanation": "かたむいたという意味になり、「重さが同じで」と矛盾する。"}], "explanations": {"釣り合った": "過去形で「きれいに釣り合った」という結果を言い切れる。前の「重さが同じで」とも合う。", "釣り合って": "て形は文を言い切れず、「。」で終えられない。", "釣り合えば": "条件の形で、主節がないと文が終わらない。", "傾いた": "かたむいたという意味になり、「重さが同じで」と矛盾する。"}, "sentence_index": 0, "correct_answer": "釣り合った"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "右の皿におもりを載せると、天びんは釣り合って右にかたむいた。", "explanation": "ここは〈かたむく〉の意味。片方に寄ることは〈かたむく〉で言い、〈釣り合う〉は重さが同じでかたむかない状態を表すので、同じ文に入れると矛盾する。"}, {"text": "計算の答えと先生の答えが釣り合った。", "explanation": "ここは〈一致する〉の意味。答えが同じことは〈一致する〉で言い、〈釣り合う〉は重さや力の均衡に使うので合わない。"}, {"text": "二本のレールは釣り合って、平行に走っている。", "explanation": "ここは〈平行〉の意味。並んで同じ向きに進むことは〈平行〉で言い、〈釣り合う〉は重さや力が均衡する状態を表すので、レールの走り方とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37702, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "釣り合った", "is_correct": true, "explanation": "過去形で「釣り合った」という結果を言い切れる。「砂を足すと、やがて」の流れにも合う。"}, {"text": "釣り合い", "is_correct": false, "explanation": "連用形の名詞のような形で、文末に置けない。"}, {"text": "釣り合わせて", "is_correct": false, "explanation": "使役のて形で、動かす人が必要になり、皿が主語の文と合わない。"}, {"text": "沈んだ", "is_correct": false, "explanation": "両方の皿が沈むという意味になり、釣り合った結果と矛盾する。"}], "explanations": {"釣り合った": "過去形で「釣り合った」という結果を言い切れる。「砂を足すと、やがて」の流れにも合う。", "釣り合い": "連用形の名詞のような形で、文末に置けない。", "釣り合わせて": "使役のて形で、動かす人が必要になり、皿が主語の文と合わない。", "沈んだ": "両方の皿が沈むという意味になり、釣り合った結果と矛盾する。"}, "sentence_index": 6, "correct_answer": "釣り合った"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "波が来ると、船は釣り合って激しく揺れた。", "explanation": "ここは〈揺れる〉の意味。ゆれ動くことは〈揺れる〉で言い、〈釣り合う〉は両側の重さが同じでかたむかない状態を表すので、激しく揺れる話とは合わない。"}, {"text": "二つのパーツの形が釣り合って、きちんとはまった。", "explanation": "ここは〈合う〉の意味。形の一致は〈合う〉で言い、〈釣り合う〉は重さや力の均衡に使うので合わない。"}, {"text": "二つの数の値が釣り合っていれば、答えは正しい。", "explanation": "ここは〈等しい〉の意味。数値が同じことは〈等しい〉で言い、〈釣り合う〉は重さの均衡に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37702, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "おもりの数を増やすと、左の皿を釣り合った。", "corrected_sentence": "おもりの数を増やすと、左の皿と釣り合った。", "error_description": "〈釣り合う〉は相手を「と」で表す。「を」は誤りで、正しくは「と」。〈釣り合う〉は自動詞なので「を」の目的語は取れない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "釣り合った", "is_correct": true, "explanation": "過去形で、置いた後に釣り合ったという出来事を表す。"}, {"text": "釣り合わない", "is_correct": false, "explanation": "否定形で、釣り合ったという結果と逆になる。"}, {"text": "釣り合って", "is_correct": false, "explanation": "て形で、文を言い切れず「。」で終えられない。"}, {"text": "釣り合えば", "is_correct": false, "explanation": "仮定形で、実際に起きた結果を述べる文と合わない。"}], "correct_form": "釣り合った", "base_form": "釣り合う", "form_label": "過去形", "sentence_index": 1, "explanations": {"釣り合った": "過去形で、置いた後に釣り合ったという出来事を表す。", "釣り合わない": "否定形で、釣り合ったという結果と逆になる。", "釣り合って": "て形で、文を言い切れず「。」で終えられない。", "釣り合えば": "仮定形で、実際に起きた結果を述べる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37702, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "おもりを一つ足すと、天びんは釣り合わなった。", "corrected_sentence": "おもりを一つ足すと、天びんは釣り合わなくなった。", "error_description": "「釣り合わなった」は活用の誤り。否定形の「釣り合わない」を結果の過去として言うには「釣り合わなくなった」と「なく」が要る。「釣り合わなった」は文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "釣り合っている", "is_correct": true, "explanation": "〜ている形で、今も続く釣り合いの状態を表し、「倒れない」の理由になる。"}, {"text": "釣り合わない", "is_correct": false, "explanation": "否定形で、左右の重さが釣り合わないことになり、「倒れない」の理由と逆になる。"}, {"text": "釣り合わなかった", "is_correct": false, "explanation": "過去の否定形で、今の状態ではなく過去に釣り合わなかったことになり、「倒れない」の理由と合わない。"}, {"text": "釣り合っていない", "is_correct": false, "explanation": "〜ていない形で、左右の重さが釣り合っていないことになり、「倒れない」の理由と逆になる。"}], "correct_form": "釣り合っている", "base_form": "釣り合う", "form_label": "ている形", "sentence_index": 7, "explanations": {"釣り合っている": "〜ている形で、今も続く釣り合いの状態を表し、「倒れない」の理由になる。", "釣り合わない": "否定形で、左右の重さが釣り合わないことになり、「倒れない」の理由と逆になる。", "釣り合わなかった": "過去の否定形で、今の状態ではなく過去に釣り合わなかったことになり、「倒れない」の理由と合わない。", "釣り合っていない": "〜ていない形で、左右の重さが釣り合っていないことになり、「倒れない」の理由と逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
