INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37703, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "property", "definition": "二つの物事が、重さや力などのつりあいをとって、安定した状態にあること。", "primary_collocate": null, "pronunciation": "つりあう", "ipa": "t͡sɯɾiaɯ", "syllable_count": 4, "sentences": [{"text": "引く力と押す力が釣り合って、箱は動かなかった。", "target_word": "釣り合って", "complexity_tier": "T3", "furigana": "引[ひ]く力[ちから]と押[お]す力[ちから]が釣[つ]り合[あ]って、箱[はこ]は動[うご]かなかった。", "sentence_source": "generated"}, {"text": "収入と支出が釣り合っていて、家計は安定している。", "target_word": "釣り合っていて", "complexity_tier": "T3", "furigana": "収入[しゅうにゅう]と支出[ししゅつ]が釣[つ]り合[あ]っていて、家計[かけい]は安定[あんてい]している。", "sentence_source": "generated"}, {"text": "上向きの力と重力が釣り合うと、風船は空中で止まる。", "target_word": "釣り合う", "complexity_tier": "T3", "furigana": "上向[うわむ]きの力[ちから]と重力[じゅうりょく]が釣[つ]り合[あ]うと、風船[ふうせん]は空中[くうちゅう]で止[と]まる。", "sentence_source": "generated"}, {"text": "売る量と買う量が釣り合えば、値段は変わらない。", "target_word": "釣り合えば", "complexity_tier": "T3", "furigana": "売[う]る量[りょう]と買[か]う量[りょう]が釣[つ]り合[あ]えば、値段[ねだん]は変[か]わらない。", "sentence_source": "generated"}, {"text": "川の流れと船の力が釣り合って、船は同じ場所にとどまった。", "target_word": "釣り合って", "complexity_tier": "T3", "furigana": "川[かわ]の流[なが]れと船[ふね]の力[ちから]が釣[つ]り合[あ]って、船[ふね]は同[おな]じ場所[ばしょ]にとどまった。", "sentence_source": "generated"}, {"text": "二つの国の力が釣り合っているので、戦争にならない。", "target_word": "釣り合っている", "complexity_tier": "T3", "furigana": "二[ふた]つの国[くに]の力[ちから]が釣[つ]り合[あ]っているので、戦争[せんそう]にならない。", "sentence_source": "generated"}, {"text": "食べる量と運動量が釣り合えば、体重は変わらない。", "target_word": "釣り合えば", "complexity_tier": "T3", "furigana": "食[た]べる量[りょう]と運動量[うんどうりょう]が釣[つ]り合[あ]えば、体重[たいじゅう]は変[か]わらない。", "sentence_source": "generated"}, {"text": "浮力と重さが釣り合うと、物は水の中で止まる。", "target_word": "釣り合う", "complexity_tier": "T3", "furigana": "浮力[ふりょく]と重[おも]さが釣[つ]り合[あ]うと、物[もの]は水[みず]の中[なか]で止[と]まる。", "sentence_source": "generated"}, {"text": "左右の綱の力が釣り合い、橋は安定して立っている。", "target_word": "釣り合い", "complexity_tier": "T3", "furigana": "左右[さゆう]の綱[つな]の力[ちから]が釣[つ]り合[あ]い、橋[はし]は安定[あんてい]して立[た]っている。", "sentence_source": "generated"}, {"text": "水が入る量と出る量が釣り合って、水位は一定だった。", "target_word": "釣り合って", "complexity_tier": "T3", "furigana": "水[みず]が入[はい]る量[りょう]と出[で]る量[りょう]が釣[つ]り合[あ]って、水位[すいい]は一定[いってい]だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "釣り合う", "label": "基本形"}, {"form": "釣り合った", "label": "過去形"}, {"form": "釣り合わない", "label": "否定形"}, {"form": "釣り合って", "label": "て形"}, {"form": "釣り合えば", "label": "仮定形"}], "register": "一般（普通体）", "sense_fingerprint": "二つの力や量が等しく、均衡して安定した状態になる（力・収支・需給など）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a59e52e-a96c-4120-ac95-7f3d10883587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37703, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "釣り合って", "is_correct": true, "explanation": "て形で、釣り合った状態のまま「箱は動かなかった」へ続く。"}, {"text": "釣り合え", "is_correct": false, "explanation": "命令形で、「箱は動かなかった」と続かない。"}, {"text": "釣り合わせて", "is_correct": false, "explanation": "使役形で、釣り合わせる人が必要になり、力を主語にする文と合わない。"}, {"text": "釣り合わなくて", "is_correct": false, "explanation": "釣り合わない状態なら箱は動くはずなので、「動かなかった」と矛盾する。"}], "explanations": {"釣り合って": "て形で、釣り合った状態のまま「箱は動かなかった」へ続く。", "釣り合え": "命令形で、「箱は動かなかった」と続かない。", "釣り合わせて": "使役形で、釣り合わせる人が必要になり、力を主語にする文と合わない。", "釣り合わなくて": "釣り合わない状態なら箱は動くはずなので、「動かなかった」と矛盾する。"}, "sentence_index": 0, "correct_answer": "釣り合って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "荷物が偏ったせいで、船は釣り合って転覆した。", "explanation": "ここは〈転覆する〉の意味。ひっくり返ることは〈転覆する〉で言い、〈釣り合う〉は両側の力が均衡して安定した状態を表すので、転覆の話とは合わない。"}, {"text": "模範解答と私の答えが釣り合った。", "explanation": "ここは〈一致する〉の意味。答えが同じことは〈一致する〉で言い、〈釣り合う〉は力や量のつり合いに使うので合わない。"}, {"text": "二本のレールは釣り合って、平行に走っている。", "explanation": "ここは〈平行〉の意味。並んで同じ向きに進むことは〈平行〉で言い、〈釣り合う〉は力が均衡して安定する状態を表すので、レールの走り方とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37703, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "釣り合えば", "is_correct": true, "explanation": "仮定形で、「〜ば」が条件となり「体重は変わらない」と続く。"}, {"text": "釣り合った", "is_correct": false, "explanation": "過去形だと条件の流れと合わず、「変わらない」と続く論理が成り立たない。"}, {"text": "釣り合わなければ", "is_correct": false, "explanation": "釣り合わなければ体重が変わることになり、文の内容と矛盾する。"}, {"text": "釣り合わせれば", "is_correct": false, "explanation": "使役の仮定形で、釣り合わせる人が必要になり、量を主語にする文と合わない。"}], "explanations": {"釣り合えば": "仮定形で、「〜ば」が条件となり「体重は変わらない」と続く。", "釣り合った": "過去形だと条件の流れと合わず、「変わらない」と続く論理が成り立たない。", "釣り合わなければ": "釣り合わなければ体重が変わることになり、文の内容と矛盾する。", "釣り合わせれば": "使役の仮定形で、釣り合わせる人が必要になり、量を主語にする文と合わない。"}, "sentence_index": 6, "correct_answer": "釣り合えば"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "客の数が釣り合って、店は一時間で急に混み合った。", "explanation": "ここは〈急増する〉の意味。数が急に増えることは〈急増する〉で言い、〈釣り合う〉は数や力が均衡して安定した状態を指すので、急な増加とは合わない。"}, {"text": "部屋の家具が釣り合って、あちこちに散らばった。", "explanation": "ここは〈散らばる〉の意味。物があちこちに広がることは〈散らばる〉で言い、〈釣り合う〉は均衡して安定した状態を表すので、散らばる動きとは合わない。"}, {"text": "一人だけ釣り合って、ほかの選手を大きく引き離した。", "explanation": "ここは〈引き離す〉の意味。差を大きく広げることは〈引き離す〉で言い、〈釣り合う〉は均衡して安定した状態を指すので、選手の差が広がる話には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37703, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "需要と供給を釣り合って、値段は安定した。", "corrected_sentence": "需要と供給が釣り合って、値段は安定した。", "error_description": "〈釣り合う〉は「二つのものが釣り合う」と主語に「が」を取る。「を」は誤りで、正しくは「が」。自動詞に目的語の「を」は付かない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "釣り合っていて", "is_correct": true, "explanation": "〜ていて形で、「家計は安定している」と並ぶ状態を表す。"}, {"text": "釣り合っている", "is_correct": false, "explanation": "終止形なので、後ろに「、家計は」を続けると文として成り立たない。"}, {"text": "釣り合わない", "is_correct": false, "explanation": "否定形で、収入と支出が釣り合う状態と逆になる。"}, {"text": "釣り合わせて", "is_correct": false, "explanation": "使役のて形で、釣り合わせる人が必要になり、収入と支出を主語にする文と合わない。"}], "correct_form": "釣り合っていて", "base_form": "釣り合う", "form_label": "〜ていて形", "sentence_index": 1, "explanations": {"釣り合っていて": "〜ていて形で、「家計は安定している」と並ぶ状態を表す。", "釣り合っている": "終止形なので、後ろに「、家計は」を続けると文として成り立たない。", "釣り合わない": "否定形で、収入と支出が釣り合う状態と逆になる。", "釣り合わせて": "使役のて形で、釣り合わせる人が必要になり、収入と支出を主語にする文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37703, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "客の数と席の数が釣り合うば、待ち時間はなくなる。", "corrected_sentence": "客の数と席の数が釣り合えば、待ち時間はなくなる。", "error_description": "「釣り合うば」は仮定形の誤り。〈釣り合う〉の仮定形は語尾をエ段にした「釣り合えば」で、「釣り合うば」は成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "釣り合う", "is_correct": true, "explanation": "基本形で、「〜と」の後に一般的な条件を述べる文と合う。"}, {"text": "釣り合った", "is_correct": false, "explanation": "過去形だと一般的な条件ではなく、一度の出来事になってしまう。"}, {"text": "釣り合わなかった", "is_correct": false, "explanation": "過去の否定形で、一度の出来事の不成立を表すので、「〜と止まる」という一般的な条件とは合わない。"}, {"text": "釣り合って", "is_correct": false, "explanation": "て形で、「〜と」の前に置けず、条件を述べる文として成り立たない。"}], "correct_form": "釣り合う", "base_form": "釣り合う", "form_label": "基本形", "sentence_index": 7, "explanations": {"釣り合う": "基本形で、「〜と」の後に一般的な条件を述べる文と合う。", "釣り合った": "過去形だと一般的な条件ではなく、一度の出来事になってしまう。", "釣り合わなかった": "過去の否定形で、一度の出来事の不成立を表すので、「〜と止まる」という一般的な条件とは合わない。", "釣り合って": "て形で、「〜と」の前に置けず、条件を述べる文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37704, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "〈達する〉は「〜に達する」で到達点を表すので、「定常に」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「定常を達した」は到達点を「を」で取れず成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「定常で」は手段や場所を表し、到達を表せない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、「定常から達した」は到達を表せない。"}], "correct_answer": "に", "explanations": {"に": "〈達する〉は「〜に達する」で到達点を表すので、「定常に」が正しい。", "を": "「定常を達した」は到達点を「を」で取れず成り立たない。", "で": "「定常で」は手段や場所を表し、到達を表せない。", "から": "「から」は起点を表すので、「定常から達した」は到達を表せない。"}, "error_tags": {"を": "対象", "で": "手段・場所", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37704, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「定常のまま」の「の」。状態がそのまま保たれることを表す形の一部。"}, {"text": "が", "is_correct": false, "explanation": "「定常がまま」は成り立たず、主語を取る形ではない。"}, {"text": "を", "is_correct": false, "explanation": "「定常をまま」は成り立たず、目的語を取る形ではない。"}, {"text": "に", "is_correct": false, "explanation": "「定常にまま」は成り立たず、「まま」の前には「の」が要る。"}], "correct_answer": "の", "explanations": {"の": "「定常のまま」の「の」。状態がそのまま保たれることを表す形の一部。", "が": "「定常がまま」は成り立たず、主語を取る形ではない。", "を": "「定常をまま」は成り立たず、目的語を取る形ではない。", "に": "「定常にまま」は成り立たず、「まま」の前には「の」が要る。"}, "error_tags": {"が": "主語", "を": "対象", "に": "方向・状態"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37704, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かがずっと変わらないで同じ状態を続けること。", "primary_collocate": null, "pronunciation": "ていじょう", "ipa": "teːd͡ʑoː", "syllable_count": 4, "sentences": [{"text": "水の流れが定常になるまで、しばらく待ちました。", "target_word": "定常", "complexity_tier": "T3", "furigana": "水[みず]の流[なが]れが定常[ていじょう]になるまで、しばらく待[ま]ちました。", "sentence_source": "generated"}, {"text": "部屋の温度が定常に達したので、実験を始めた。", "target_word": "定常", "complexity_tier": "T3", "furigana": "部屋[へや]の温度[おんど]が定常[ていじょう]に達[たっ]したので、実験[じっけん]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "この機械は、回転数が定常になっているときが一番安定している。", "target_word": "定常", "complexity_tier": "T3", "furigana": "この機械[きかい]は、回転数[かいてんすう]が定常[ていじょう]になっているときが一番[いちばん]安定[あんてい]している。", "sentence_source": "generated"}, {"text": "この川の流れは季節に関係なく定常で、水量があまり変わらない。", "target_word": "定常", "complexity_tier": "T3", "furigana": "この川[かわ]の流[なが]れは季節[きせつ]に関係[かんけい]なく定常[ていじょう]で、水量[すいりょう]があまり変[か]わらない。", "sentence_source": "generated"}, {"text": "心拍数が定常に戻るまで、患者さんは静かに休んでいた。", "target_word": "定常", "complexity_tier": "T3", "furigana": "心拍数[しんぱくすう]が定常[ていじょう]に戻[もど]るまで、患者[かんじゃ]さんは静[しず]かに休[やす]んでいた。", "sentence_source": "generated"}, {"text": "電力の使用量が定常になれば、来月から計画を立てやすくなる。", "target_word": "定常", "complexity_tier": "T3", "furigana": "電力[でんりょく]の使用量[しようりょう]が定常[ていじょう]になれば、来月[らいげつ]から計画[けいかく]を立[た]てやすくなる。", "sentence_source": "generated"}, {"text": "電流が定常になるのを確認してから、数値を記録した。", "target_word": "定常", "complexity_tier": "T3", "furigana": "電流[でんりゅう]が定常[ていじょう]になるのを確認[かくにん]してから、数値[すうち]を記録[きろく]した。", "sentence_source": "generated"}, {"text": "温度は定常のまま続いているので、機械には問題がないと思う。", "target_word": "定常", "complexity_tier": "T3", "furigana": "温度[おんど]は定常[ていじょう]のまま続[つづ]いているので、機械[きかい]には問題[もんだい]がないと思[おも]う。", "sentence_source": "generated"}, {"text": "風の強さが定常ではなく、ときどき急に変わった。", "target_word": "定常", "complexity_tier": "T3", "furigana": "風[かぜ]の強[つよ]さが定常[ていじょう]ではなく、ときどき急[きゅう]に変[か]わった。", "sentence_source": "generated"}, {"text": "池の水位は定常を保っていて、雨の日でもほとんど変わらない。", "target_word": "定常", "complexity_tier": "T3", "furigana": "池[いけ]の水位[すいい]は定常[ていじょう]を保[たも]っていて、雨[あめ]の日[ひ]でもほとんど変[か]わらない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "定常", "label": "基本形"}, {"form": "定常的", "label": "形状詞形"}, {"form": "定常状態", "label": "複合語"}], "register": "書き言葉・専門的", "sense_fingerprint": "ずっと変わらず同じ状態が続くこと(定常状態)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a59e52e-a96c-4120-ac95-7f3d10883587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37704, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "定常", "is_correct": true, "explanation": "変わらず同じ状態が続く意味で、「流れが〜になる」に合う。"}, {"text": "流量", "is_correct": false, "explanation": "流れの量を表す語で、「流れが流量になる」は意味をなさない。"}, {"text": "水深", "is_correct": false, "explanation": "水の深さの意味で、流れの状態を述べる文と合わない。"}, {"text": "落差", "is_correct": false, "explanation": "高低の差の意味で、「流れが〜になるまで」と合わない。"}], "explanations": {"定常": "変わらず同じ状態が続く意味で、「流れが〜になる」に合う。", "流量": "流れの量を表す語で、「流れが流量になる」は意味をなさない。", "水深": "水の深さの意味で、流れの状態を述べる文と合わない。", "落差": "高低の差の意味で、「流れが〜になるまで」と合わない。"}, "sentence_index": 0, "correct_answer": "定常"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この電車は定常で、毎朝七時に駅に着く。", "explanation": "ここは〈定期〉の意味。決まった周期で繰り返すことは〈定期〉で言い、〈定常〉は状態が変わらず続くことを指すので合わない。"}, {"text": "この症状は定常で、すぐに治った。", "explanation": "ここは〈一時的〉の意味。短い間だけ続いてすぐ治る様子は〈一時的〉で言い、〈定常〉は変わらず続く状態を指すので、すぐ治る話とは合わない。"}, {"text": "地震は定常に起きた。", "explanation": "ここは〈突然〉の意味。前触れなく起きることは〈突然〉で言い、〈定常〉は変わらず続く状態を指すので、地震の起き方には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37704, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "定常", "is_correct": true, "explanation": "変わらず続く状態の意味で、「電流が〜になる」と合う。"}, {"text": "電圧", "is_correct": false, "explanation": "電気の圧力の意味で、「電流が電圧になる」は成り立たない。"}, {"text": "周波数", "is_correct": false, "explanation": "振動の回数の意味で、電流の状態を述べる文と合わない。"}, {"text": "波形", "is_correct": false, "explanation": "波の形の意味で、「電流が波形になる」は意味をなさない。"}], "explanations": {"定常": "変わらず続く状態の意味で、「電流が〜になる」と合う。", "電圧": "電気の圧力の意味で、「電流が電圧になる」は成り立たない。", "周波数": "振動の回数の意味で、電流の状態を述べる文と合わない。", "波形": "波の形の意味で、「電流が波形になる」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "定常"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この金庫は定常で、番号を入れないと開かない。", "explanation": "ここは〈固定〉の意味。ものが動かないよう留められている状態は〈固定〉で言い、〈定常〉は時間とともに変わらない状態を指すので、施錠の説明には使わない。"}, {"text": "池の水位は定常で、いつ上がるかわからない。", "explanation": "ここは〈不定〉の意味。決まった傾向がないことは〈不定〉で言い、〈定常〉は変わらず続く状態を指すので、いつ変わるかわからない話とは合わない。"}, {"text": "このバスは定常の人数しか乗れない。", "explanation": "ここは〈定員〉の意味。乗れる人数の上限は〈定員〉で言い、〈定常〉は状態が変わらず続く意味なので、乗車人数の説明には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37704, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "電流が定常を続くまで、数値を記録した。", "corrected_sentence": "電流が定常のまま続くまで、数値を記録した。", "error_description": "〈続く〉は自動詞なので「定常を続く」は成り立たない。状態が保たれることは「定常のまま続く」と言う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37704, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "電圧が定常を保たれていて、機械は止まらない。", "corrected_sentence": "電圧が定常に保たれていて、機械は止まらない。", "error_description": "〈保たれる〉では「電圧」が主語になるので、「定常を」は目的語を取れない。状態を表すには「定常に保たれる」と「に」を取る。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
