INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37705, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「定常の動作」の「の」。〈定常〉が名詞「動作」を修飾する連体の形を作る。"}, {"text": "を", "is_correct": false, "explanation": "「定常を動作」は成り立たず、「動作」は目的語にならない。"}, {"text": "に", "is_correct": false, "explanation": "「定常に動作」は成り立たず、〈定常〉を名詞に続ける形ではない。"}, {"text": "へ", "is_correct": false, "explanation": "「定常へ動作」は方向を表し、名詞を修飾できない。"}], "correct_answer": "の", "explanations": {"の": "「定常の動作」の「の」。〈定常〉が名詞「動作」を修飾する連体の形を作る。", "を": "「定常を動作」は成り立たず、「動作」は目的語にならない。", "に": "「定常に動作」は成り立たず、〈定常〉を名詞に続ける形ではない。", "へ": "「定常へ動作」は方向を表し、名詞を修飾できない。"}, "error_tags": {"を": "対象", "に": "方向・状態", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37705, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "状態や動作が一定に保たれて、変わらないこと。", "primary_collocate": null, "pronunciation": "ていじょう", "ipa": "teːd͡ʑoː", "syllable_count": 4, "sentences": [{"text": "この装置は、動作が定常になると音が静かになる。", "target_word": "定常", "complexity_tier": "T3", "furigana": "この装置[そうち]は、動作[どうさ]が定常[ていじょう]になると音[おと]が静[しず]かになる。", "sentence_source": "generated"}, {"text": "一定の速さで走る車は、速さが定常になっていると言える。", "target_word": "定常", "complexity_tier": "T3", "furigana": "一定[いってい]の速[はや]さで走[はし]る車[くるま]は、速[はや]さが定常[ていじょう]になっていると言[い]える。", "sentence_source": "generated"}, {"text": "製造ラインが定常で動いているあいだは、検査の回数を減らせる。", "target_word": "定常", "complexity_tier": "T3", "furigana": "製造[せいぞう]ラインが定常[ていじょう]で動[うご]いているあいだは、検査[けんさ]の回数[かいすう]を減[へ]らせる。", "sentence_source": "generated"}, {"text": "気体の流れが定常になると、圧力の変化も小さくなる。", "target_word": "定常", "complexity_tier": "T3", "furigana": "気体[きたい]の流[なが]れが定常[ていじょう]になると、圧力[あつりょく]の変化[へんか]も小[ちい]さくなる。", "sentence_source": "generated"}, {"text": "体温が定常になるまで、静かに待つ必要がある。", "target_word": "定常", "complexity_tier": "T3", "furigana": "体温[たいおん]が定常[ていじょう]になるまで、静[しず]かに待[ま]つ必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "回転数が定常になったので、エンジンの音が一定になった。", "target_word": "定常", "complexity_tier": "T3", "furigana": "回転数[かいてんすう]が定常[ていじょう]になったので、エンジンの音[おと]が一定[いってい]になった。", "sentence_source": "generated"}, {"text": "最初は不安定だったが、三十分後に定常へ移った。", "target_word": "定常", "complexity_tier": "T3", "furigana": "最初[さいしょ]は不安定[ふあんてい]だったが、三十分後[さんじゅっぷんご]に定常[ていじょう]へ移[うつ]った。", "sentence_source": "generated"}, {"text": "定常の動作を確認するため、機械を一時間回し続けた。", "target_word": "定常", "complexity_tier": "T3", "furigana": "定常[ていじょう]の動作[どうさ]を確認[かくにん]するため、機械[きかい]を一時間[いちじかん]回[まわ]し続[つづ]けた。", "sentence_source": "generated"}, {"text": "数値が定常ではないので、もう一度測り直します。", "target_word": "定常", "complexity_tier": "T3", "furigana": "数値[すうち]が定常[ていじょう]ではないので、もう一度[いちど]測[はか]り直[なお]します。", "sentence_source": "generated"}, {"text": "工場が定常に動いていれば、毎日同じ数の製品ができる。", "target_word": "定常", "complexity_tier": "T3", "furigana": "工場[こうじょう]が定常[ていじょう]に動[うご]いていれば、毎日[まいにち]同[おな]じ数[かず]の製品[せいひん]ができる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "定常", "label": "基本形"}, {"form": "定常的", "label": "形状詞形"}, {"form": "定常運転", "label": "複合語"}], "register": "書き言葉・専門的", "sense_fingerprint": "状態や動作が一定に保たれて変化しないこと(定常運転・定常流)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a59e52e-a96c-4120-ac95-7f3d10883587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37705, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "定常", "is_correct": true, "explanation": "変わらず続く状態の意味で、「動作が〜になると」に合う。"}, {"text": "回転数", "is_correct": false, "explanation": "回る速さの数値を表し、「動作が回転数になる」は成り立たない。"}, {"text": "音量", "is_correct": false, "explanation": "音の大きさの意味で、「動作が音量になる」は意味をなさない。"}, {"text": "出力", "is_correct": false, "explanation": "仕事の量の意味で、「動作が出力になる」は不自然。"}], "explanations": {"定常": "変わらず続く状態の意味で、「動作が〜になると」に合う。", "回転数": "回る速さの数値を表し、「動作が回転数になる」は成り立たない。", "音量": "音の大きさの意味で、「動作が音量になる」は意味をなさない。", "出力": "仕事の量の意味で、「動作が出力になる」は不自然。"}, "sentence_index": 0, "correct_answer": "定常"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "気体の流れは定常に止まり、圧力の変化もなくなった。", "explanation": "ここは〈停止〉の意味。動いていたものが止まることは〈停止〉で言い、〈定常〉は動きが変わらず続く状態を指すので、止まる出来事には合わない。"}, {"text": "この圧力の上昇は定常で、すぐに元に戻った。", "explanation": "ここは〈一時的〉の意味。短い間だけ起きて元に戻る様子は〈一時的〉で言い、〈定常〉は変わらず続く状態を指すので、元に戻る話とは合わない。"}, {"text": "圧力は定常に変動して、流れが安定しない。", "explanation": "ここは〈変動〉の意味。値が変わり続けることは〈変動〉で言い、〈定常〉は変わらず保たれる状態を指すので、「変動して安定しない」とは両立しない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37705, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "定常", "is_correct": true, "explanation": "変わらず続く状態の意味で、「三十分後に〜へ移った」と合う。"}, {"text": "振幅", "is_correct": false, "explanation": "振れ幅の意味で、「振幅へ移った」は状態の変化として成り立たない。"}, {"text": "周波数", "is_correct": false, "explanation": "振動の回数の意味で、「周波数へ移った」は不自然。"}, {"text": "電圧", "is_correct": false, "explanation": "電気の圧力の意味で、「電圧へ移った」は成り立たない。"}], "explanations": {"定常": "変わらず続く状態の意味で、「三十分後に〜へ移った」と合う。", "振幅": "振れ幅の意味で、「振幅へ移った」は状態の変化として成り立たない。", "周波数": "振動の回数の意味で、「周波数へ移った」は不自然。", "電圧": "電気の圧力の意味で、「電圧へ移った」は成り立たない。"}, "sentence_index": 6, "correct_answer": "定常"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工場の機械は定常を繰り返して、毎日同じ数の製品ができる。", "explanation": "ここは〈繰り返す〉の意味。同じ動きを重ねることは〈繰り返す〉で言い、〈定常〉は変わらず続く状態を指すので「繰り返して」とは合わない。"}, {"text": "工場の生産量は定常に急増した。", "explanation": "ここは〈急増する〉の意味。数が急に大きく増えることは〈急増する〉で言い、〈定常〉は変わらず保たれる状態を指すので、急増とは合わない。"}, {"text": "この機械の部品は定常に固定されていて、外れない。", "explanation": "ここは〈固定〉の意味。動かないよう留めることは〈固定〉で言い、〈定常〉は動きが変わらず続く状態を指すので、部品の留め方の説明には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37705, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "回転数が定常に保つと、エンジンの音が一定になる。", "corrected_sentence": "回転数を定常に保つと、エンジンの音が一定になる。", "error_description": "〈保つ〉は保つ対象を「を」で表す。「回転数が」の「が」は誤りで、正しくは「回転数を」。「定常に保つ」の「に」は誤りではない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37705, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "回転が定常の続けば、機械は止まらない。", "corrected_sentence": "回転が定常のまま続けば、機械は止まらない。", "error_description": "「定常の続けば」は「まま」が抜けている。状態が保たれることは「定常のまま続けば」と言う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37706, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "手段を表す「で」。釣り合いによって天びんが水平になる、という意味になる。"}, {"text": "を", "is_correct": false, "explanation": "対象を表す「を」。「釣り合いを水平になる」は成り立たないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」。「釣り合いへ水平になる」は向きを示せず不自然。"}, {"text": "に", "is_correct": false, "explanation": "帰着点を表す「に」だが、「釣り合いに水平になる」は釣り合いを水平の帰着点にできず文が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "手段を表す「で」。釣り合いによって天びんが水平になる、という意味になる。", "を": "対象を表す「を」。「釣り合いを水平になる」は成り立たないので合わない。", "へ": "方向を表す「へ」。「釣り合いへ水平になる」は向きを示せず不自然。", "に": "帰着点を表す「に」だが、「釣り合いに水平になる」は釣り合いを水平の帰着点にできず文が成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "に": "帰着点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37706, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37706, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つのものが、ちょうど同じくらいの強さで引っ張り合って、動かないこと。", "primary_collocate": null, "pronunciation": "つりあい", "ipa": "tsɯɾiai", "syllable_count": 4, "sentences": [{"text": "左右の力の釣り合いがとれて、棒は動かなくなった。", "target_word": "釣り合い", "complexity_tier": "T3", "furigana": "左右[さゆう]の力[ちから]の釣[つ]り合[あ]いがとれて、棒[ぼう]は動[うご]かなくなった。", "sentence_source": "generated"}, {"text": "天びんは、両方の皿の重さの釣り合いで水平になる。", "target_word": "釣り合い", "complexity_tier": "T3", "furigana": "天[てん]びんは、両方[りょうほう]の皿[さら]の重[おも]さの釣[つ]り合[あ]いで水平[すいへい]になる。", "sentence_source": "generated"}, {"text": "綱引きは、両チームの力が釣り合いの状態になって、少しも動かなかった。", "target_word": "釣り合い", "complexity_tier": "T3", "furigana": "綱引[つなひ]きは、両[りょう]チームの力[ちから]が釣[つ]り合[あ]いの状態[じょうたい]になって、少[すこ]しも動[うご]かなかった。", "sentence_source": "generated"}, {"text": "二つのばねが同じ強さで物を両側から引くと、釣り合いがとれて物は止まる。", "target_word": "釣り合い", "complexity_tier": "T3", "furigana": "二[ふた]つのばねが同[おな]じ強[つよ]さで物[もの]を両側[りょうがわ]から引[ひ]くと、釣[つ]り合[あ]いがとれて物[もの]は止[と]まる。", "sentence_source": "generated"}, {"text": "釣り合いが崩れたので、おもりは右へ傾いた。", "target_word": "釣り合い", "complexity_tier": "T3", "furigana": "釣[つ]り合[あ]いが崩[くず]れたので、おもりは右[みぎ]へ傾[かたむ]いた。", "sentence_source": "generated"}, {"text": "二人が同じ強さで綱を引いたので、釣り合いがとれて赤い印は動かなかった。", "target_word": "釣り合い", "complexity_tier": "T3", "furigana": "二人[ふたり]が同[おな]じ強[つよ]さで綱[つな]を引[ひ]いたので、釣[つ]り合[あ]いがとれて赤[あか]い印[しるし]は動[うご]かなかった。", "sentence_source": "generated"}, {"text": "力の釣り合いを調べる実験で、ばねはかりを使った。", "target_word": "釣り合い", "complexity_tier": "T3", "furigana": "力[ちから]の釣[つ]り合[あ]いを調[しら]べる実験[じっけん]で、ばねはかりを使[つか]った。", "sentence_source": "generated"}, {"text": "風船が空中で止まっているのは、浮く力と重さの釣り合いが取れているからだ。", "target_word": "釣り合い", "complexity_tier": "T3", "furigana": "風船[ふうせん]が空中[くうちゅう]で止[と]まっているのは、浮[う]く力[ちから]と重[おも]さの釣[つ]り合[あ]いが取[と]れているからだ。", "sentence_source": "generated"}, {"text": "釣り合いが取れていれば、物体は動かず、静かに止まっている。", "target_word": "釣り合い", "complexity_tier": "T3", "furigana": "釣[つ]り合[あ]いが取[と]れていれば、物体[ぶったい]は動[うご]かず、静[しず]かに止[と]まっている。", "sentence_source": "generated"}, {"text": "両側から引く力の釣り合いが少し変わると、物はすぐ動き出す。", "target_word": "釣り合い", "complexity_tier": "T3", "furigana": "両側[りょうがわ]から引[ひ]く力[ちから]の釣[つ]り合[あ]いが少[すこ]し変[か]わると、物[もの]はすぐ動[うご]き出[だ]す。", "sentence_source": "generated"}], "morphological_forms": [{"form": "釣り合い", "label": "基本形"}, {"form": "釣合い", "label": "送り仮名の省略形"}, {"form": "つりあい", "label": "ひらがな形"}], "register": "標準", "sense_fingerprint": "二つの力が同じ強さで引き合い、物が動かない状態(力の釣り合い)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a59e52e-a96c-4120-ac95-7f3d10883587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37706, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "釣り合い", "is_correct": true, "explanation": "左右の力が同じ強さで引き合い、棒が動かない状態を表すので「釣り合いがとれて」に入る。"}, {"text": "振動", "is_correct": false, "explanation": "振動は細かく揺れ続ける現象で、力がとれて棒が静止する文脈には合わない。"}, {"text": "回転", "is_correct": false, "explanation": "回転は物が軸の周りを回ることで、「回転がとれて」は静止するという結果と合わない。"}, {"text": "反発", "is_correct": false, "explanation": "反発は押し返し合う働きで、「反発がとれて」では棒が動かなくなった理由にならない。"}], "explanations": {"釣り合い": "左右の力が同じ強さで引き合い、棒が動かない状態を表すので「釣り合いがとれて」に入る。", "振動": "振動は細かく揺れ続ける現象で、力がとれて棒が静止する文脈には合わない。", "回転": "回転は物が軸の周りを回ることで、「回転がとれて」は静止するという結果と合わない。", "反発": "反発は押し返し合う働きで、「反発がとれて」では棒が動かなくなった理由にならない。"}, "sentence_index": 0, "correct_answer": "釣り合い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "同じ極の磁石は、釣り合いで互いに離れていく。", "explanation": "ここは〈反発〉の意味。釣り合いは力が等しく物が動かない状態なので、離れていく動きには合わない。"}, {"text": "磁石は、釣り合いで鉄くずを引きつける。", "explanation": "ここは〈引力〉の意味。釣り合いは力が等しく止まる状態を指すので、引きつける働きとは別物。"}, {"text": "ギターの弦は、釣り合いで細かく揺れて音を出す。", "explanation": "ここは〈振動〉の意味。釣り合いは止まっている状態を表すので、揺れて音を出す現象は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37706, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "釣り合い", "is_correct": true, "explanation": "「力の釣り合いを調べる」という文脈にそのまま入る語。ばねはかりで力のつり合いを調べる実験に合う。"}, {"text": "慣性", "is_correct": false, "explanation": "慣性は物が動き続けようとする性質で、「力の慣性を調べる」とは言わない。"}, {"text": "電圧", "is_correct": false, "explanation": "電圧は電気を押し出す強さで、ばねはかりで測る力の実験とは関係しない。"}, {"text": "密度", "is_correct": false, "explanation": "密度は単位体積あたりの質量で、「力の密度」は力の実験の対象として成り立たない。"}], "explanations": {"釣り合い": "「力の釣り合いを調べる」という文脈にそのまま入る語。ばねはかりで力のつり合いを調べる実験に合う。", "慣性": "慣性は物が動き続けようとする性質で、「力の慣性を調べる」とは言わない。", "電圧": "電圧は電気を押し出す強さで、ばねはかりで測る力の実験とは関係しない。", "密度": "密度は単位体積あたりの質量で、「力の密度」は力の実験の対象として成り立たない。"}, "sentence_index": 6, "correct_answer": "釣り合い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この床は釣り合いが大きく、箱が動きにくい。", "explanation": "ここは〈摩擦〉の意味。摩擦は接する面どうしが妨げ合う抵抗で、釣り合いは力が等しい状態なので大きさは表せない。"}, {"text": "急ブレーキをかけても、釣り合いで体は前へ進み続ける。", "explanation": "ここは〈慣性〉の意味。慣性は動きを続けようとする性質で、釣り合いは力が等しく止まる状態を表すので合わない。"}, {"text": "積み木は、釣り合いが低いので倒れにくい。", "explanation": "ここは〈重心〉の意味。物の重さが集まる点の位置を指す語で、釣り合いの状態とは別物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37706, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ロープの両端の力が釣り合いに状態になり、箱は動かない。", "corrected_sentence": "ロープの両端の力が釣り合いの状態になり、箱は動かない。", "error_description": "「釣り合い」に続く助詞が「に」になっている。名詞「状態」につなぐには「の」が正しく、「釣り合いに状態」は不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37706, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "両側の力の釣り合いが取れてので、箱は動かない。", "corrected_sentence": "両側の力の釣り合いが取れているので、箱は動かない。", "error_description": "「取れている」の「いる」が抜けて「取れてので」になっている。「取れているので」が正しく、「ている」で結果の状態を表す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37708, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「重力があるので」の主語を示す「が」。"}, {"text": "を", "is_correct": false, "explanation": "対象を表す「を」。「重力をあるので」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」。「重力へあるので」は意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」。「重力からあるので」は文の形が崩れる。"}], "correct_answer": "が", "explanations": {"が": "「重力があるので」の主語を示す「が」。", "を": "対象を表す「を」。「重力をあるので」は成り立たない。", "へ": "方向を表す「へ」。「重力へあるので」は意味が通らない。", "から": "起点を表す「から」。「重力からあるので」は文の形が崩れる。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37708, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「重力のせいで」の「の」で、重力と「せい」をつなぐ。"}, {"text": "に", "is_correct": false, "explanation": "帰着を表す「に」。「重力にせいで」は名詞どうしをつなげない。"}, {"text": "と", "is_correct": false, "explanation": "並列を表す「と」。「重力とせいで」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」。「重力よりせいで」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「重力のせいで」の「の」で、重力と「せい」をつなぐ。", "に": "帰着を表す「に」。「重力にせいで」は名詞どうしをつなげない。", "と": "並列を表す「と」。「重力とせいで」は成り立たない。", "より": "比較の「より」。「重力よりせいで」は意味が通らない。"}, "error_tags": {"に": "帰着点", "と": "並列", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37708, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物を下に引っぱる、見えない力のこと。", "primary_collocate": null, "pronunciation": "じゅうりょく", "ipa": "d͡ʑɯːɾjokɯ", "syllable_count": 4, "sentences": [{"text": "手を離すと、ボールは重力で下に落ちる。", "target_word": "重力", "complexity_tier": "T3", "furigana": "手[て]を離[はな]すと、ボールは重力[じゅうりょく]で下[した]に落[お]ちる。", "sentence_source": "generated"}, {"text": "重力があるので、私たちは地面に立っていられる。", "target_word": "重力", "complexity_tier": "T3", "furigana": "重力[じゅうりょく]があるので、私[わたし]たちは地面[じめん]に立[た]っていられる。", "sentence_source": "generated"}, {"text": "月は地球より重力が小さいから、体が軽く感じられる。", "target_word": "重力", "complexity_tier": "T3", "furigana": "月[つき]は地球[ちきゅう]より重力[じゅうりょく]が小[ちい]さいから、体[からだ]が軽[かる]く感[かん]じられる。", "sentence_source": "generated"}, {"text": "宇宙では重力がほとんどないため、水が丸い玉になって浮く。", "target_word": "重力", "complexity_tier": "T3", "furigana": "宇宙[うちゅう]では重力[じゅうりょく]がほとんどないため、水[みず]が丸[まる]い玉[たま]になって浮[う]く。", "sentence_source": "generated"}, {"text": "重力は目に見えないが、りんごを木から落とす。", "target_word": "重力", "complexity_tier": "T3", "furigana": "重力[じゅうりょく]は目[め]に見[み]えないが、りんごを木[き]から落[お]とす。", "sentence_source": "generated"}, {"text": "重力に逆らって、鳥は空高く飛んでいく。", "target_word": "重力", "complexity_tier": "T3", "furigana": "重力[じゅうりょく]に逆[さか]らって、鳥[とり]は空高[そらたか]く飛[と]んでいく。", "sentence_source": "generated"}, {"text": "宇宙飛行士は、重力の弱い場所で体を動かす練習をした。", "target_word": "重力", "complexity_tier": "T3", "furigana": "宇宙飛行士[うちゅうひこうし]は、重力[じゅうりょく]の弱[よわ]い場所[ばしょ]で体[からだ]を動[うご]かす練習[れんしゅう]をした。", "sentence_source": "generated"}, {"text": "坂道では、重力のせいで自転車が勝手に進み出す。", "target_word": "重力", "complexity_tier": "T3", "furigana": "坂道[さかみち]では、重力[じゅうりょく]のせいで自転車[じてんしゃ]が勝手[かって]に進[すす]み出[だ]す。", "sentence_source": "generated"}, {"text": "水が低い所へ流れるのは、重力が下へ引くからだ。", "target_word": "重力", "complexity_tier": "T3", "furigana": "水[みず]が低[ひく]い所[ところ]へ流[なが]れるのは、重力[じゅうりょく]が下[した]へ引[ひ]くからだ。", "sentence_source": "generated"}, {"text": "ジャンプしても、すぐ重力に引かれて地面に戻ってくる。", "target_word": "重力", "complexity_tier": "T3", "furigana": "ジャンプしても、すぐ重力[じゅうりょく]に引[ひ]かれて地面[じめん]に戻[もど]ってくる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "重力", "label": "基本形"}, {"form": "重力の", "label": "名詞+の"}], "register": "標準", "sense_fingerprint": "物を下へ引く目に見えない力(日常的な意味の重力)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T3: contains vocabulary far above tier T3: 進み出す (Zipf 1.07)']::text[], '8a59e52e-a96c-4120-ac95-7f3d10883587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37708, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重力", "is_correct": true, "explanation": "物を下へ引く見えない力で、手を離したボールが下へ落ちる理由になる。"}, {"text": "摩擦", "is_correct": false, "explanation": "摩擦は接する面どうしの抵抗で、ボールを下へ落とす力にはならない。"}, {"text": "電圧", "is_correct": false, "explanation": "電圧は電気を押し出す強さで、ボールが下に落ちる力とは関係しない。"}, {"text": "圧力", "is_correct": false, "explanation": "圧力は面を押す力の大きさで、落下の理由としては合わない。"}], "explanations": {"重力": "物を下へ引く見えない力で、手を離したボールが下へ落ちる理由になる。", "摩擦": "摩擦は接する面どうしの抵抗で、ボールを下へ落とす力にはならない。", "電圧": "電圧は電気を押し出す強さで、ボールが下に落ちる力とは関係しない。", "圧力": "圧力は面を押す力の大きさで、落下の理由としては合わない。"}, "sentence_index": 0, "correct_answer": "重力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "仕事の重力に押しつぶされそうで、毎晩なかなか眠れない。", "explanation": "ここは〈重圧〉の意味。重力は地球が物を引く力で、プレッシャーを表す比喩には使わない。"}, {"text": "この部屋は重力が低く、冷房をつけなくても涼しい。", "explanation": "ここは〈温度〉の意味。部屋の涼しさは温度や気温で表すので、重力という語は使わない。"}, {"text": "この積み木は重力の位置が低いので、倒れにくい。", "explanation": "ここは〈重心〉の意味。物の重さが集まる点を指す語で、重力の位置とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37708, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重力", "is_correct": true, "explanation": "宇宙飛行士が体を動かす練習をした場所の、引く力の弱さを表す語。"}, {"text": "慣性", "is_correct": false, "explanation": "慣性は動き続けようとする性質で、「慣性の弱い場所」とは言わない。"}, {"text": "比重", "is_correct": false, "explanation": "比重は同じ体積の物質の重さの比で、場所の弱さの言い方には合わない。"}, {"text": "熱量", "is_correct": false, "explanation": "熱量はエネルギーの大きさで、「熱量の弱い場所」は練習の文脈と合わない。"}], "explanations": {"重力": "宇宙飛行士が体を動かす練習をした場所の、引く力の弱さを表す語。", "慣性": "慣性は動き続けようとする性質で、「慣性の弱い場所」とは言わない。", "比重": "比重は同じ体積の物質の重さの比で、場所の弱さの言い方には合わない。", "熱量": "熱量はエネルギーの大きさで、「熱量の弱い場所」は練習の文脈と合わない。"}, "sentence_index": 6, "correct_answer": "重力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の言葉には、重力があって胸に響いた。", "explanation": "ここは〈重み〉の意味。重力は物を引く力で、言葉の重みという比喩には使わない。"}, {"text": "選手の重力が伝わってきて、観客は息をのんだ。", "explanation": "ここは〈気迫〉の意味。気迫は精神の張りつめた強さで、重力という語は使わない。"}, {"text": "会場は重力に包まれ、みんなが盛り上がっていた。", "explanation": "ここは〈熱気〉の意味。会場の盛り上がりを表す語で、重力は物理的に引く力なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37708, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "重力が引かれて、ボールは床に落ちた。", "corrected_sentence": "重力に引かれて、ボールは床に落ちた。", "error_description": "「重力」に続く助詞が「が」になっている。「引かれる」の起点は「に」で示すので、「重力に引かれて」が正しい。「が」だと重力が引かれる側になってしまう。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37708, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "荷物は重力に引いて、ゆっくり下へ落ちていく。", "corrected_sentence": "荷物は重力に引かれて、ゆっくり下へ落ちていく。", "error_description": "「引かれて」の受身形が「引いて」になっている。重力に引かれる物を主語にするには受身の「引かれて」が正しく、能動の「引いて」は文の形が崩れる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37709, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「重力が二倍になれば」の主語を示す「が」。"}, {"text": "を", "is_correct": false, "explanation": "対象を表す「を」。「重力を二倍になれば」は「に」が必要で成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」。「重力へ二倍になれば」は意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」。「重力から二倍になれば」は文の形が崩れる。"}], "correct_answer": "が", "explanations": {"が": "「重力が二倍になれば」の主語を示す「が」。", "を": "対象を表す「を」。「重力を二倍になれば」は「に」が必要で成り立たない。", "へ": "方向を表す「へ」。「重力へ二倍になれば」は意味が通らない。", "から": "起点を表す「から」。「重力から二倍になれば」は文の形が崩れる。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37709, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37709, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物体が地球などに引かれる力。重さの原因となる。", "primary_collocate": null, "pronunciation": "じゅうりょく", "ipa": "d͡ʑɯːɾjokɯ", "syllable_count": 4, "sentences": [{"text": "物の重さは、地球の重力が物を引く強さで決まる。", "target_word": "重力", "complexity_tier": "T3", "furigana": "物[もの]の重[おも]さは、地球[ちきゅう]の重力[じゅうりょく]が物[もの]を引[ひ]く強[つよ]さで決[き]まる。", "sentence_source": "generated"}, {"text": "重力が二倍になれば、同じ荷物も二倍重く感じられる。", "target_word": "重力", "complexity_tier": "T3", "furigana": "重力[じゅうりょく]が二倍[にばい]になれば、同[おな]じ荷物[にもつ]も二倍[にばい]重[おも]く感[かん]じられる。", "sentence_source": "generated"}, {"text": "惑星の大きさによって、表面の重力は変わる。", "target_word": "重力", "complexity_tier": "T3", "furigana": "惑星[わくせい]の大[おお]きさによって、表面[ひょうめん]の重力[じゅうりょく]は変[か]わる。", "sentence_source": "generated"}, {"text": "月の重力は地球の六分の一なので、体重計の数字も小さくなる。", "target_word": "重力", "complexity_tier": "T3", "furigana": "月[つき]の重力[じゅうりょく]は地球[ちきゅう]の六分[ろくぶん]の一[いち]なので、体重計[たいじゅうけい]の数字[すうじ]も小[ちい]さくなる。", "sentence_source": "generated"}, {"text": "人工衛星は、地球の重力に引かれながら周りを回っている。", "target_word": "重力", "complexity_tier": "T3", "furigana": "人工衛星[じんこうえいせい]は、地球[ちきゅう]の重力[じゅうりょく]に引[ひ]かれながら周[まわ]りを回[まわ]っている。", "sentence_source": "generated"}, {"text": "重力の強さを測る装置を使って、山の上と海辺を比べた。", "target_word": "重力", "complexity_tier": "T3", "furigana": "重力[じゅうりょく]の強[つよ]さを測[はか]る装置[そうち]を使[つか]って、山[やま]の上[うえ]と海辺[うみべ]を比[くら]べた。", "sentence_source": "generated"}, {"text": "重力が働かない宇宙船の中では、物に重さがない。", "target_word": "重力", "complexity_tier": "T3", "furigana": "重力[じゅうりょく]が働[はたら]かない宇宙船[うちゅうせん]の中[なか]では、物[もの]に重[おも]さがない。", "sentence_source": "generated"}, {"text": "りんごが落ちるのを見て、ニュートンは重力の法則を考えた。", "target_word": "重力", "complexity_tier": "T3", "furigana": "りんごが落[お]ちるのを見[み]て、ニュートンは重力[じゅうりょく]の法則[ほうそく]を考[かんが]えた。", "sentence_source": "generated"}, {"text": "重力の影響で、高い所から落とした物はだんだん速くなる。", "target_word": "重力", "complexity_tier": "T3", "furigana": "重力[じゅうりょく]の影響[えいきょう]で、高[たか]い所[ところ]から落[お]とした物[もの]はだんだん速[はや]くなる。", "sentence_source": "generated"}, {"text": "木星は地球より重力が大きいので、人間は立っていられないほど重く感じる。", "target_word": "重力", "complexity_tier": "T3", "furigana": "木星[もくせい]は地球[ちきゅう]より重力[じゅうりょく]が大[おお]きいので、人間[にんげん]は立[た]っていられないほど重[おも]く感[かん]じる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "重力", "label": "基本形"}, {"form": "重力の", "label": "名詞+の(連体修飾)"}], "register": "標準・科学的", "sense_fingerprint": "物体が地球や天体に引かれる力で、物の重さを生む原因(科学的な意味)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a59e52e-a96c-4120-ac95-7f3d10883587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37709, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重力", "is_correct": true, "explanation": "地球が物を引く強さを表し、物の重さを決める原因として文に合う。"}, {"text": "摩擦", "is_correct": false, "explanation": "摩擦は接する面の抵抗で、地球が物を引く強さの意味にはならない。"}, {"text": "電圧", "is_correct": false, "explanation": "電圧は電気を押し出す強さで、物を引く強さには当たらない。"}, {"text": "圧力", "is_correct": false, "explanation": "圧力は面にかかる押す力の大きさで、引く強さの表現には合わない。"}], "explanations": {"重力": "地球が物を引く強さを表し、物の重さを決める原因として文に合う。", "摩擦": "摩擦は接する面の抵抗で、地球が物を引く強さの意味にはならない。", "電圧": "電圧は電気を押し出す強さで、物を引く強さには当たらない。", "圧力": "圧力は面にかかる押す力の大きさで、引く強さの表現には合わない。"}, "sentence_index": 0, "correct_answer": "重力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この磁石は、重力で鉄くずを引き寄せている。", "explanation": "ここは〈磁力〉の意味。鉄を引き寄せるのは磁石の磁力で、重力は物の質量による引く力なので合わない。"}, {"text": "彼は重力を込めた一撃で、相手を倒した。", "explanation": "ここは〈力の強さ〉の意味。一撃に力を込める言い方では「力」を使い、重力は地球が物を引く力なので合わない。"}, {"text": "電線に流す重力を大きくすると、明かりが明るくなる。", "explanation": "ここは〈電流〉の意味。明かりを明るくするのは流れる電流で、重力を大きくしても電気の流れは変わらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37709, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重力", "is_correct": true, "explanation": "物を引く力で、重力が働かない宇宙船の中では物に重さがないという文に合う。"}, {"text": "比重", "is_correct": false, "explanation": "比重は物質の重さの比で、働く力ではないので「が働かない」とは言わない。"}, {"text": "熱量", "is_correct": false, "explanation": "熱量は熱エネルギーの量で、働く力の主語にはならない。"}, {"text": "音量", "is_correct": false, "explanation": "音量は音の大きさで、「音量が働かない」は宇宙船の文脈と合わない。"}], "explanations": {"重力": "物を引く力で、重力が働かない宇宙船の中では物に重さがないという文に合う。", "比重": "比重は物質の重さの比で、働く力ではないので「が働かない」とは言わない。", "熱量": "熱量は熱エネルギーの量で、働く力の主語にはならない。", "音量": "音量は音の大きさで、「音量が働かない」は宇宙船の文脈と合わない。"}, "sentence_index": 6, "correct_answer": "重力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ボールの重力は、移動した距離を時間で割って求める。", "explanation": "ここは〈速さ〉の意味。距離を時間で割って求めるのは速さで、重力は物を引く力なので計算の対象にならない。"}, {"text": "真空中の重力は、毎秒およそ三十万キロメートルだ。", "explanation": "ここは〈光速〉の意味。毎秒三十万キロメートルは光の速さで、重力の値を表す語ではない。"}, {"text": "重力の単位はクーロンである。", "explanation": "ここは〈電荷〉の意味。クーロンは電荷の単位で、重力の単位ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37709, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "重力を影響を受けて、小石は地面へ落ちていく。", "corrected_sentence": "重力の影響を受けて、小石は地面へ落ちていく。", "error_description": "「重力」に続く助詞が「を」になっている。「影響を受ける」の「を」と重なって二重になるので、「重力の影響を受けて」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37709, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "木星の重力に引いて、衛星は回り続けている。", "corrected_sentence": "木星の重力に引かれて、衛星は回り続けている。", "error_description": "「引かれて」の受身形が「引いて」になっている。衛星が木星の重力に引かれる関係は受身の「引かれて」で表すので、能動の「引いて」は文の形が崩れる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31593bee-9d7c-4111-ba54-8a4f3e4c8c7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
