INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37711, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37711, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事を数字を使って考え、結果を出すこと。また、その結果を予測すること。", "primary_collocate": null, "pronunciation": "けいさん", "ipa": "keːsaɴ", "syllable_count": 4, "sentences": [{"text": "デザイナーの直感に頼るのではなく、計算された論理によって、機能的かつ独創的な都市空間を創出することが目指されています。", "target_word": "計算", "complexity_tier": "T4", "furigana": "デザイナーの直感[ちょっかん]に頼[たよ]るのではなく、計算[けいさん]された論理[ろんり]によって、機能的[きのうてき]かつ独創的[どくそうてき]な都市空間[としくうかん]を創出[そうしゅつ]することが目指[めざ]されています。", "sentence_source": "mined"}, {"text": "彼は損をしないように、すべてを計算して行動している。", "target_word": "計算", "complexity_tier": "T3", "furigana": "彼[かれ]は損[そん]をしないように、すべてを計算[けいさん]して行動[こうどう]している。", "sentence_source": "generated"}, {"text": "計算どおりに客が増えて、店は初日から忙しくなった。", "target_word": "計算", "complexity_tier": "T3", "furigana": "計算[けいさん]どおりに客[きゃく]が増[ふ]えて、店[みせ]は初日[しょにち]から忙[いそが]しくなった。", "sentence_source": "generated"}, {"text": "雨が降ることは計算に入れていなかったので、傘を持ってこなかった。", "target_word": "計算", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ることは計算[けいさん]に入[い]れていなかったので、傘[かさ]を持[も]ってこなかった。", "sentence_source": "generated"}, {"text": "新商品の利益を計算すると、初年度は赤字になることがわかった。", "target_word": "計算", "complexity_tier": "T3", "furigana": "新商品の利益を計算[けいさん]すると、初年度は赤字になることがわかった。", "sentence_source": "generated"}, {"text": "社長は利益が出るまでの期間を計算して、新しい店を開く時期を決めた。", "target_word": "計算", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は利益[りえき]が出[で]るまでの期間[きかん]を計算[けいさん]して、新[あたら]しい店[みせ]を開[ひら]く時期[じき]を決[き]めた。", "sentence_source": "generated"}, {"text": "あの監督は、試合の流れまで計算して選手を交代させた。", "target_word": "計算", "complexity_tier": "T3", "furigana": "あの監督[かんとく]は、試合[しあい]の流[なが]れまで計算[けいさん]して選手[せんしゅ]を交代[こうたい]させた。", "sentence_source": "generated"}, {"text": "彼がわざと負けたのは計算の上で、相手を油断させるためだった。", "target_word": "計算", "complexity_tier": "T3", "furigana": "彼[かれ]がわざと負[ま]けたのは計算[けいさん]の上[うえ]で、相手[あいて]を油断[ゆだん]させるためだった。", "sentence_source": "generated"}, {"text": "将来の費用を計算して、今から少しずつ貯金を始めた。", "target_word": "計算", "complexity_tier": "T3", "furigana": "将来[しょうらい]の費用[ひよう]を計算[けいさん]して、今[いま]から少[すこ]しずつ貯金[ちょきん]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "計算し尽くされた構図の写真は、見る人に強い印象を残す。", "target_word": "計算", "complexity_tier": "T3", "furigana": "計算[けいさん]し尽[つ]くされた構図[こうず]の写真[しゃしん]は、見[み]る人[ひと]に強[つよ]い印象[いんしょう]を残[のこ]す。", "sentence_source": "generated"}], "morphological_forms": [{"form": "計算する", "label": "サ変動詞・終止形"}, {"form": "計算した", "label": "過去形"}, {"form": "計算して", "label": "て形"}, {"form": "計算される", "label": "受身形"}, {"form": "計算された", "label": "受身・過去形"}], "register": "中立", "sense_fingerprint": "損得や結果を見通して先を読むこと(計算して行動する・計算どおり)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e1d13d0-4a75-4ad6-af0d-7ff5a6956501') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37711, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "計算", "is_correct": true, "explanation": "「計算された論理」は、結果を見通して組み立てた論理という意味で、この文の文脈に合う。"}, {"text": "感情", "is_correct": false, "explanation": "「感情された論理」とは言えない。論理は感情から組み立てるものではないので、ここでは合わない。"}, {"text": "偶然", "is_correct": false, "explanation": "「偶然された論理」は不自然。偶然は起きたことを表し、意図して組み立てる論理とは結びつかない。"}, {"text": "慣習", "is_correct": false, "explanation": "「慣習された論理」は不自然。既存のしきたりではなく、意図的に組んだ論理を述べる文脈に合わない。"}], "explanations": {"計算": "「計算された論理」は、結果を見通して組み立てた論理という意味で、この文の文脈に合う。", "感情": "「感情された論理」とは言えない。論理は感情から組み立てるものではないので、ここでは合わない。", "偶然": "「偶然された論理」は不自然。偶然は起きたことを表し、意図して組み立てる論理とは結びつかない。", "慣習": "「慣習された論理」は不自然。既存のしきたりではなく、意図的に組んだ論理を述べる文脈に合わない。"}, "sentence_index": 0, "correct_answer": "計算"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は計算をふくらませて、将来の夢を語った。", "explanation": "〈想像をふくらませる〉の〈想像〉の代わりに〈計算〉を置いた誤用。計算は数字や論理で結果を出す行為で、空想のように広げることはできない。"}, {"text": "朝から嫌な計算を感じて、外出をやめた。", "explanation": "〈嫌な予感を感じる〉の〈予感〉の代わりに〈計算〉を置いた誤用。計算は数字や論理で結果を出す行為で、感覚として感じるものではない。"}, {"text": "彼は夜中に計算をかき鳴らして、近所の人に怒られた。", "explanation": "〈ギターをかき鳴らす〉の〈ギター〉の代わりに〈計算〉を置いた誤用。計算は数を出す作業で、楽器のように音を鳴らすものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37711, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "計算", "is_correct": true, "explanation": "「試合の流れまで計算して」は、流れを見通して判断したという意味で、交代させた理由として合う。"}, {"text": "挨拶", "is_correct": false, "explanation": "「挨拶して選手を交代させた」は意味がつながらない。挨拶は交代の判断の根拠にならない。"}, {"text": "拍手", "is_correct": false, "explanation": "「拍手して選手を交代させた」は不自然。拍手は交代の判断を表さない。"}, {"text": "注文", "is_correct": false, "explanation": "「注文して選手を交代させた」は交代の判断の根拠にならず、流れを読む文脈に合わない。"}], "explanations": {"計算": "「試合の流れまで計算して」は、流れを見通して判断したという意味で、交代させた理由として合う。", "挨拶": "「挨拶して選手を交代させた」は意味がつながらない。挨拶は交代の判断の根拠にならない。", "拍手": "「拍手して選手を交代させた」は不自然。拍手は交代の判断を表さない。", "注文": "「注文して選手を交代させた」は交代の判断の根拠にならず、流れを読む文脈に合わない。"}, "sentence_index": 6, "correct_answer": "計算"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "玄関で計算が鳴って、客が来た。", "explanation": "〈ベルが鳴る〉の〈ベル〉の代わりに〈計算〉を置いた誤用。計算は数や論理で答えを出す行為で、音を立てて鳴るものではない。"}, {"text": "彼女は同僚に計算を寄せている。", "explanation": "〈好意を寄せる〉の代わりに〈計算〉を置いた誤用。計算は相手に向ける気持ちとしては使わない。"}, {"text": "その知らせを聞いて、計算がこみ上げてきた。", "explanation": "〈怒りがこみ上げる〉の代わりに〈計算〉を置いた誤用。込み上げるのは感情で、数や論理の計算は感情として湧かない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37711, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "将来の費用を計算に、予算を立てた。", "corrected_sentence": "将来の費用を計算して、予算を立てた。", "error_description": "「計算に」は誤り。計算は「計算して」と動詞の連用形で続け、後ろの「予算を立てた」につなぐ。「計算に」では文の成分がつながらない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37711, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は失敗を計算に入って、予備の計画を立てた。", "corrected_sentence": "彼は失敗を計算に入れて、予備の計画を立てた。", "error_description": "「計算に入る」は自動詞で、目的語の「失敗を」と合わない。「計算に入れる」と他動詞にして、「失敗を計算に入れる」の形にする必要がある。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
