INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37714, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "「CFD」は、コンピューターを使って空気や水の流れを調べる方法のことです。飛行機の形を考えるときに使います。", "primary_collocate": null, "pronunciation": "しーえふでぃー", "ipa": "ɕiːefudiː", "syllable_count": 6, "sentences": [{"text": "CFD を使えば、飛行機のまわりの空気の流れが分かる。", "target_word": "CFD", "complexity_tier": "T3", "furigana": "CFD を使[つか]えば、飛行機[ひこうき]のまわりの空気[くうき]の流[なが]れが分[わ]かる。", "sentence_source": "generated"}, {"text": "CFD は、コンピューターで水の流れを調べる方法だ。", "target_word": "CFD", "complexity_tier": "T3", "furigana": "CFD は、コンピューターで水[みず]の流[なが]れを調[しら]べる方法[ほうほう]だ。", "sentence_source": "generated"}, {"text": "新しい翼の形を考えるために、CFD で計算した。", "target_word": "CFD", "complexity_tier": "T3", "furigana": "新[あたら]しい翼[つばさ]の形[かたち]を考[かんが]えるために、CFD で計算[けいさん]した。", "sentence_source": "generated"}, {"text": "CFD のおかげで、風洞実験の回数を減らせた。", "target_word": "CFD", "complexity_tier": "T3", "furigana": "CFD のおかげで、風洞実験[ふうどうじっけん]の回数[かいすう]を減[へ]らせた。", "sentence_source": "generated"}, {"text": "車の形を変えて、CFD で空気の通り方を比べた。", "target_word": "CFD", "complexity_tier": "T3", "furigana": "車[くるま]の形[かたち]を変[か]えて、CFD で空気[くうき]の通[とお]り方[かた]を比[くら]べた。", "sentence_source": "generated"}, {"text": "この会社は、CFD を使って船の設計をしている。", "target_word": "CFD", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、CFD を使[つか]って船[ふね]の設計[せっけい]をしている。", "sentence_source": "generated"}, {"text": "CFD の結果を見ると、翼の後ろで風が乱れている。", "target_word": "CFD", "complexity_tier": "T3", "furigana": "CFD の結果[けっか]を見[み]ると、翼[つばさ]の後[うし]ろで風[かぜ]が乱[みだ]れている。", "sentence_source": "generated"}, {"text": "大学の授業で、CFD の使い方を習った。", "target_word": "CFD", "complexity_tier": "T3", "furigana": "大学[だいがく]の授業[じゅぎょう]で、CFD の使[つか]い方[かた]を習[なら]った。", "sentence_source": "generated"}, {"text": "CFD は、実際に飛ばさなくても流れを調べられる。", "target_word": "CFD", "complexity_tier": "T3", "furigana": "CFD は、実際[じっさい]に飛[と]ばさなくても流[なが]れを調[しら]べられる。", "sentence_source": "generated"}, {"text": "ビルのまわりの風を調べるのにも、CFD が使われる。", "target_word": "CFD", "complexity_tier": "T3", "furigana": "ビルのまわりの風[かぜ]を調[しら]べるのにも、CFD が使[つか]われる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "CFD", "label": "基本形"}], "register": "一般", "sense_fingerprint": "コンピューターで空気や水の流れを調べる方法（飛行機の形の設計など）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '755579f7-4a87-4e7f-897a-270cbb3c668d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37714, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "CFD", "is_correct": true, "explanation": "ここには〈CFD〉（空気の流れを計算で調べる方法）が入る。「CFD を使えば」で手法を指す。"}, {"text": "電池", "is_correct": false, "explanation": "電池は電気を蓄える部品で、空気の流れを調べる手段にはならないので合わない。"}, {"text": "座席", "is_correct": false, "explanation": "座席は人が座る場所で、空気の流れを調べる手段として「を使えば」に続かない。"}, {"text": "燃料", "is_correct": false, "explanation": "燃料は動力に使うもので、空気の流れを知るための手段にはならない。"}], "explanations": {"CFD": "ここには〈CFD〉（空気の流れを計算で調べる方法）が入る。「CFD を使えば」で手法を指す。", "電池": "電池は電気を蓄える部品で、空気の流れを調べる手段にはならないので合わない。", "座席": "座席は人が座る場所で、空気の流れを調べる手段として「を使えば」に続かない。", "燃料": "燃料は動力に使うもので、空気の流れを知るための手段にはならない。"}, "sentence_index": 0, "correct_answer": "CFD"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "CFD では、翼を風洞に入れて実際に風を当てて調べる。", "explanation": "ここは〈風洞実験〉の意味。CFD は計算で流れを調べる方法なので、実物の翼を風洞に入れて風を当てる場面には合わない。"}, {"text": "CFD は、新しい機体を実際に空へ飛ばして確かめる。", "explanation": "ここは〈試験飛行〉の意味。CFD は計算による解析で、機体を実際に空へ飛ばすことはできないので合わない。"}, {"text": "CFD で、翼の重さを量った。", "explanation": "ここは〈はかり〉（重さを測る道具）の意味。CFD は流れを計算する方法で、重さを量る道具ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37714, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "CFD", "is_correct": true, "explanation": "ここには〈CFD〉（計算で流れを調べる方法）が入る。「CFD の結果」として自然に続く。"}, {"text": "滑走路", "is_correct": false, "explanation": "滑走路は飛行機が離着陸する場所で、風の計算結果とは結びつかない。"}, {"text": "燃費", "is_correct": false, "explanation": "燃費は燃料の効率を指し、風の乱れを見る対象にはならない。"}, {"text": "管制塔", "is_correct": false, "explanation": "管制塔は空港の施設で、翼の後ろの風の乱れを示す対象ではない。"}], "explanations": {"CFD": "ここには〈CFD〉（計算で流れを調べる方法）が入る。「CFD の結果」として自然に続く。", "滑走路": "滑走路は飛行機が離着陸する場所で、風の計算結果とは結びつかない。", "燃費": "燃費は燃料の効率を指し、風の乱れを見る対象にはならない。", "管制塔": "管制塔は空港の施設で、翼の後ろの風の乱れを示す対象ではない。"}, "sentence_index": 6, "correct_answer": "CFD"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ビルの周りの風を、CFD で観測した。", "explanation": "ここは〈計測〉（機器で実際の風を測る）の意味。CFD は計算で流れを解析する方法なので、現実の風を測るとは言えない。"}, {"text": "CFD で、室内の空気を送り出す。", "explanation": "ここは〈換気扇〉（空気を送る機械）の意味。CFD は空気の流れを計算する方法で、室内の空気を送る機械ではないので合わない。"}, {"text": "CFD で、床のほこりを吸い取った。", "explanation": "ここは〈掃除機〉（ほこりを取る機械）の意味。CFD は計算の方法で、ほこりを吸い取る機械ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37714, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "CFD が使えば、翼のまわりの気流が分かる。", "corrected_sentence": "CFD を使えば、翼のまわりの気流が分かる。", "error_description": "「使う」は目的語に「を」を取る他動詞。「CFD が使えば」は主語の「が」になっていて誤り。正しくは「CFD を使えば」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37714, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "CFD を使ると、翼の後ろの乱れが分かる。", "corrected_sentence": "CFD を使うと、翼の後ろの乱れが分かる。", "error_description": "「使う」の条件形は「使うと」。「使ると」は動詞の活用が誤った形で、日本語として存在しない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
