INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37715, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "CFD（数値流体力学）とは、コンピューターを用いて流体の流れを数値的に解析・シミュレーションする手法で、特に航空機の設計などで翼周りの気流を計算するために用いられます。", "primary_collocate": null, "pronunciation": "しーえふでぃー", "ipa": "ɕiːefudiː", "syllable_count": 6, "sentences": [{"text": "翼周りの気流を求めるため、CFD による解析を行った。", "target_word": "CFD", "complexity_tier": "T3", "furigana": "翼周[つばさまわ]りの気流[きりゅう]を求[もと]めるため、CFD による解析[かいせき]を行[おこな]った。", "sentence_source": "generated"}, {"text": "CFD の計算格子を細かくすると、精度は上がるが時間がかかる。", "target_word": "CFD", "complexity_tier": "T3", "furigana": "CFD の計算格子[けいさんこうし]を細[こま]かくすると、精度[せいど]は上[あ]がるが時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "設計の初期段階で CFD を用いれば、試作の費用を抑えられる。", "target_word": "CFD", "complexity_tier": "T3", "furigana": "設計[せっけい]の初期段階[しょきだんかい]で CFD を用[もち]いれば、試作[しさく]の費用[ひよう]を抑[おさ]えられる。", "sentence_source": "generated"}, {"text": "CFD で得た圧力分布を、風洞試験の結果と照らし合わせた。", "target_word": "CFD", "complexity_tier": "T3", "furigana": "CFD で得[え]た圧力分布[あつりょくぶんぷ]を、風洞試験[ふうどうしけん]の結果[けっか]と照[て]らし合[あ]わせた。", "sentence_source": "generated"}, {"text": "乱流モデルの選び方によって、CFD の結果は大きく変わる。", "target_word": "CFD", "complexity_tier": "T3", "furigana": "乱流[らんりゅう]モデルの選[えら]び方[かた]によって、CFD の結果[けっか]は大[おお]きく変[か]わる。", "sentence_source": "generated"}, {"text": "機体の抵抗を減らすため、CFD で形状を最適化した。", "target_word": "CFD", "complexity_tier": "T3", "furigana": "機体[きたい]の抵抗[ていこう]を減[へ]らすため、CFD で形状[けいじょう]を最適化[さいてきか]した。", "sentence_source": "generated"}, {"text": "CFD は流体の運動を数値的にシミュレーションする手法である。", "target_word": "CFD", "complexity_tier": "T3", "furigana": "CFD は流体[りゅうたい]の運動[うんどう]を数値的[すうちてき]にシミュレーションする手法[しゅほう]である。", "sentence_source": "generated"}, {"text": "エンジンの冷却空気の流れも、CFD で評価できる。", "target_word": "CFD", "complexity_tier": "T3", "furigana": "エンジンの冷却空気[れいきゃくくうき]の流[なが]れも、CFD で評価[ひょうか]できる。", "sentence_source": "generated"}, {"text": "計算機の性能が上がり、CFD は設計現場で広く使われている。", "target_word": "CFD", "complexity_tier": "T3", "furigana": "計算機[けいさんき]の性能[せいのう]が上[あ]がり、CFD は設計現場[せっけいげんば]で広[ひろ]く使[つか]われている。", "sentence_source": "generated"}, {"text": "CFD の解析結果から、翼の上面で剥離が起きると分かった。", "target_word": "CFD", "complexity_tier": "T3", "furigana": "CFD の解析結果[かいせきけっか]から、翼[つばさ]の上面[じょうめん]で剥離[はくり]が起[お]きると分[わ]かった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "CFD", "label": "基本形"}], "register": "専門", "sense_fingerprint": "数値流体力学：流体の流れを数値計算で解析する手法（翼周りの気流の計算など）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '755579f7-4a87-4e7f-897a-270cbb3c668d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37715, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "CFD", "is_correct": true, "explanation": "ここには〈CFD〉（数値流体力学）が入る。「CFD による解析」として手法を表す。"}, {"text": "燃料", "is_correct": false, "explanation": "燃料は解析の手段にならず、「による解析」の手段として合わない。"}, {"text": "翼", "is_correct": false, "explanation": "翼は物体で、解析の手法を表さないので「による解析」に入らない。"}, {"text": "機首", "is_correct": false, "explanation": "機首は機体の先端部で、解析の手段としては成り立たない。"}], "explanations": {"CFD": "ここには〈CFD〉（数値流体力学）が入る。「CFD による解析」として手法を表す。", "燃料": "燃料は解析の手段にならず、「による解析」の手段として合わない。", "翼": "翼は物体で、解析の手法を表さないので「による解析」に入らない。", "機首": "機首は機体の先端部で、解析の手段としては成り立たない。"}, "sentence_index": 0, "correct_answer": "CFD"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "CFD で、模型に風を当てて圧力を測った。", "explanation": "ここは〈風洞試験〉の意味。CFD は計算による解析で、模型に実際に風を当てて圧力を測るのは風洞試験なので合わない。"}, {"text": "CFD を翼の表面に貼り付けた。", "explanation": "ここは〈圧力センサー〉の意味。CFD は解析の方法で、翼の表面に貼り付けるモノではないので合わない。"}, {"text": "CFD で翼の色を調べた。", "explanation": "ここは〈分光器〉の意味。CFD は流体の流れを計算する方法で、物体の色を調べる道具ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37715, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "CFD", "is_correct": true, "explanation": "ここは手法の名前として〈CFD〉が入る。「である」で手法を定義する文になる。"}, {"text": "乱流", "is_correct": false, "explanation": "乱流は流れの状態を指し、シミュレーションの手法ではないので合わない。"}, {"text": "圧力", "is_correct": false, "explanation": "圧力は物理量で、手法を表さないので「である」の主語として合わない。"}, {"text": "境界層", "is_correct": false, "explanation": "境界層は壁の近くの流れの層で、手法を指さないので合わない。"}], "explanations": {"CFD": "ここは手法の名前として〈CFD〉が入る。「である」で手法を定義する文になる。", "乱流": "乱流は流れの状態を指し、シミュレーションの手法ではないので合わない。", "圧力": "圧力は物理量で、手法を表さないので「である」の主語として合わない。", "境界層": "境界層は壁の近くの流れの層で、手法を指さないので合わない。"}, "sentence_index": 6, "correct_answer": "CFD"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "CFD で、円の面積を求めた。", "explanation": "ここは〈数値計算〉の意味。CFD は流体の流れを解析する手法なので、円の面積のような数学の計算には使わない。"}, {"text": "翼に繰り返し荷重をかける CFD を行った。", "explanation": "ここは〈耐久試験〉の意味。CFD は流体の流れの計算で、翼に荷重をかけて壊れるまで試すことはできないので合わない。"}, {"text": "上空から、翼の全体を CFD で撮った。", "explanation": "ここは〈カメラ〉（映像を記録する機械）の意味。CFD は流れを計算する方法で、翼を写し取る機械ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37715, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "CFD に計算格子を細かくすれば、精度は上がるが時間が長くなる。", "corrected_sentence": "CFD の計算格子を細かくすれば、精度は上がるが時間が長くなる。", "error_description": "「計算格子」は CFD に属するので、つなぐ助詞は「の」。「に」は相手や方向を示し、ここでは合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37715, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "翼の上面の剥離を、CFD に調べた。", "corrected_sentence": "翼の上面の剥離を、CFD で調べた。", "error_description": "「調べる」は「で」で手段を示す。「CFD に」は誤りで、正しくは「CFD で」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37717, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「検査の数値が正常」は、主語の数値が正常だという意味で自然。"}, {"text": "を", "is_correct": false, "explanation": "「検査の数値を正常だったので」は目的語の形が文に合わず、正常さを述べられない。"}, {"text": "に", "is_correct": false, "explanation": "「検査の数値に正常だったので」は名詞に状態を続ける形が不自然。"}, {"text": "と", "is_correct": false, "explanation": "「検査の数値と正常だったので」は並列の形が意味を成さない。"}], "correct_answer": "が", "explanations": {"が": "「検査の数値が正常」は、主語の数値が正常だという意味で自然。", "を": "「検査の数値を正常だったので」は目的語の形が文に合わず、正常さを述べられない。", "に": "「検査の数値に正常だったので」は名詞に状態を続ける形が不自然。", "と": "「検査の数値と正常だったので」は並列の形が意味を成さない。"}, "error_tags": {"を": "目的語の誤用", "に": "位置・対象の誤用", "と": "並列の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37717, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「数値が基準を超えた」は、数値が基準を上回ったという主語と述語の関係で自然。"}, {"text": "へ", "is_correct": false, "explanation": "「数値へ基準を超えた」は方向の関係が成り立たず、意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「数値より基準を超えた」は比較の形が文に合わず、不自然。"}, {"text": "から", "is_correct": false, "explanation": "「数値から基準を超えた」は起点を表す語として意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「数値が基準を超えた」は、数値が基準を上回ったという主語と述語の関係で自然。", "へ": "「数値へ基準を超えた」は方向の関係が成り立たず、意味が通らない。", "より": "「数値より基準を超えた」は比較の形が文に合わず、不自然。", "から": "「数値から基準を超えた」は起点を表す語として意味が通らない。"}, "error_tags": {"へ": "方向の誤用", "より": "比較の誤用", "から": "起点の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37717, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物の量や大きさを数字で表したもの。", "primary_collocate": null, "pronunciation": "すうち", "ipa": "sɯːtɕi", "syllable_count": 3, "sentences": [{"text": "部屋の温度を示す数値が、二十度から二十五度に上がりました。", "target_word": "数値", "complexity_tier": "T3", "furigana": "部屋[へや]の温度[おんど]を示[しめ]す数値[すうち]が、二十度[にじゅうど]から二十五度[にじゅうごど]に上[あ]がりました。", "sentence_source": "generated"}, {"text": "検査の数値が正常だったので、医者は安心した顔をしました。", "target_word": "数値", "complexity_tier": "T3", "furigana": "検査[けんさ]の数値[すうち]が正常[せいじょう]だったので、医者[いしゃ]は安心[あんしん]した顔[かお]をしました。", "sentence_source": "generated"}, {"text": "雨の量を表す数値は、今年は去年よりずっと低いです。", "target_word": "数値", "complexity_tier": "T3", "furigana": "雨[あめ]の量[りょう]を表[あらわ]す数値[すうち]は、今年[ことし]は去年[きょねん]よりずっと低[ひく]いです。", "sentence_source": "generated"}, {"text": "新しい車の燃費の数値は、ほかの車より良いです。", "target_word": "数値", "complexity_tier": "T3", "furigana": "新[あたら]しい車[くるま]の燃費[ねんぴ]の数値[すうち]は、ほかの車[くるま]より良[よ]いです。", "sentence_source": "generated"}, {"text": "机の大きさの数値を確かめて、紙にメモしました。", "target_word": "数値", "complexity_tier": "T3", "furigana": "机[つくえ]の大[おお]きさの数値[すうち]を確[たし]かめて、紙[かみ]にメモしました。", "sentence_source": "generated"}, {"text": "川の水の量の数値が高くなると、町に注意が出ます。", "target_word": "数値", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]の量[りょう]の数値[すうち]が高[たか]くなると、町[まち]に注意[ちゅうい]が出[で]ます。", "sentence_source": "generated"}, {"text": "画面の明るさを数値で決めると、毎回同じ明るさにできます。", "target_word": "数値", "complexity_tier": "T3", "furigana": "画面[がめん]の明[あか]るさを数値[すうち]で決[き]めると、毎回[まいかい]同[おな]じ明[あか]るさにできます。", "sentence_source": "generated"}, {"text": "数値が基準を超えたので、工場は作業を止めました。", "target_word": "数値", "complexity_tier": "T3", "furigana": "数値[すうち]が基準[きじゅん]を超[こ]えたので、工場[こうじょう]は作業[さぎょう]を止[と]めました。", "sentence_source": "generated"}, {"text": "体重の数値を毎朝記録して、健康に気をつけています。", "target_word": "数値", "complexity_tier": "T3", "furigana": "体重[たいじゅう]の数値[すうち]を毎朝[まいあさ]記録[きろく]して、健康[けんこう]に気[き]をつけています。", "sentence_source": "generated"}, {"text": "気温の数値は同じでも、風が強いと体感はもっと寒いです。", "target_word": "数値", "complexity_tier": "T3", "furigana": "気温[きおん]の数値[すうち]は同[おな]じでも、風[かぜ]が強[つよ]いと体感[たいかん]はもっと寒[さむ]いです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "数値", "label": "基本形"}], "register": "標準（中立的な書き言葉・話し言葉）", "sense_fingerprint": "測定した量や大きさを表す数字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8506ed3a-c0bb-4ca9-9f47-86feb09e3786') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37717, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "数値", "is_correct": true, "explanation": "「温度を示す数値」は測った値を表し、二十度から二十五度に上がったという文に合う。"}, {"text": "愛情", "is_correct": false, "explanation": "「温度を示す愛情」は意味が通らず、温度の変化の主語にならない。"}, {"text": "自由", "is_correct": false, "explanation": "「温度を示す自由」は温度を示せず、文が成り立たない。"}, {"text": "平和", "is_correct": false, "explanation": "「温度を示す平和」は数値を表せず、温度の変化を述べられない。"}], "explanations": {"数値": "「温度を示す数値」は測った値を表し、二十度から二十五度に上がったという文に合う。", "愛情": "「温度を示す愛情」は意味が通らず、温度の変化の主語にならない。", "自由": "「温度を示す自由」は温度を示せず、文が成り立たない。", "平和": "「温度を示す平和」は数値を表せず、温度の変化を述べられない。"}, "sentence_index": 0, "correct_answer": "数値"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい数値を運転して、海まで行きました。", "explanation": "ここは〈車〉の置き換え。数値は運転できないので、運転する対象にならない。"}, {"text": "新しい車の数値は、とても明るい青です。", "explanation": "ここは〈色〉の置き換え。数値には色がないので、明るい青だとは言えない。"}, {"text": "数値と一緒に、公園で遊びました。", "explanation": "ここは〈友だち〉の置き換え。数値は人ではないので、一緒に遊ぶ相手にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37717, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数値", "is_correct": true, "explanation": "「数値で決める」は数字で明るさを指定する意味で、毎回同じ明るさにできるという文に合う。"}, {"text": "誠実", "is_correct": false, "explanation": "「誠実で決める」は明るさを決める手段にならず、意味が通らない。"}, {"text": "感謝", "is_correct": false, "explanation": "「感謝で決める」は手段として不自然で、明るさの設定にならない。"}, {"text": "友情", "is_correct": false, "explanation": "「友情で決める」は明るさを決める方法として成り立たない。"}], "explanations": {"数値": "「数値で決める」は数字で明るさを指定する意味で、毎回同じ明るさにできるという文に合う。", "誠実": "「誠実で決める」は明るさを決める手段にならず、意味が通らない。", "感謝": "「感謝で決める」は手段として不自然で、明るさの設定にならない。", "友情": "「友情で決める」は明るさを決める方法として成り立たない。"}, "sentence_index": 6, "correct_answer": "数値"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "数値が強く降って、道がぬれました。", "explanation": "ここは〈雨〉の置き換え。数値は降るものではないので、降る主語にならない。"}, {"text": "数値をかけて、ぐっすり眠りました。", "explanation": "ここは〈布団〉の置き換え。数値は布団のようにかけられるものではないので、かける対象にならない。"}, {"text": "数値になると、川が凍ります。", "explanation": "ここは〈冬〉の置き換え。数値は季節ではないので、季節として「〜になる」とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37717, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "温度の数値を、二十度から二十五度に上がりました。", "corrected_sentence": "温度の数値が、二十度から二十五度に上がりました。", "error_description": "「上がる」は自動詞なので、主語は「が」で示す。「を」を付けると「数値」が目的語になり、「上がりました」とつながらない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37717, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "数値な基準を超えると、警報が鳴ります。", "corrected_sentence": "数値の基準を超えると、警報が鳴ります。", "error_description": "「数値」は名詞なので、名詞を修飾するには「の」を使う。「な」は形容動詞の語尾で、名詞の「数値」には付かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37718, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す。流体を話題に置き、後の文で形が変わることを述べる。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す。流体で容器に入れると道具の意味になり不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。流体へ容器に入れると、対象の方向がずれる。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を示す。流体と容器に入れると二つを並べる意味になり、文意が崩れる。"}], "correct_answer": "は", "explanations": {"は": "主題を示す。流体を話題に置き、後の文で形が変わることを述べる。", "で": "手段や場所を示す。流体で容器に入れると道具の意味になり不自然。", "へ": "方向を示す。流体へ容器に入れると、対象の方向がずれる。", "と": "相手や並列を示す。流体と容器に入れると二つを並べる意味になり、文意が崩れる。"}, "error_tags": {"で": "手段・場所", "へ": "方向", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37718, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "連体修飾で「流体の量」を作る。"}, {"text": "が", "is_correct": false, "explanation": "主格。流体が量をはかるとなり、装置の用途が合わない。"}, {"text": "を", "is_correct": false, "explanation": "目的語。「流体を量を」と目的語が二つ並び、不自然になる。"}, {"text": "より", "is_correct": false, "explanation": "比較。流体より量をはかるとなり、比べる意味になって文意が崩れる。"}], "correct_answer": "の", "explanations": {"の": "連体修飾で「流体の量」を作る。", "が": "主格。流体が量をはかるとなり、装置の用途が合わない。", "を": "目的語。「流体を量を」と目的語が二つ並び、不自然になる。", "より": "比較。流体より量をはかるとなり、比べる意味になって文意が崩れる。"}, "error_tags": {"が": "主格", "を": "目的格", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37718, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "液体や気体のように、形がなくて流れるもの。", "primary_collocate": null, "pronunciation": "りゅうたい", "ipa": "ɾʲɯːtai", "syllable_count": 4, "sentences": [{"text": "水や空気は、形を持たない流体だ。", "target_word": "流体", "complexity_tier": "T3", "furigana": "水[みず]や空気[くうき]は、形[かたち]を持[も]たない流体[りゅうたい]だ。", "sentence_source": "generated"}, {"text": "流体は容器に入れると、容器の形になる。", "target_word": "流体", "complexity_tier": "T3", "furigana": "流体[りゅうたい]は容器[ようき]に入[い]れると、容器[ようき]の形[かたち]になる。", "sentence_source": "generated"}, {"text": "流体は固体とちがって、手でつかめない。", "target_word": "流体", "complexity_tier": "T3", "furigana": "流体[りゅうたい]は固体[こたい]とちがって、手[て]でつかめない。", "sentence_source": "generated"}, {"text": "水も油も流体の仲間だ。", "target_word": "流体", "complexity_tier": "T3", "furigana": "水[みず]も油[あぶら]も流体[りゅうたい]の仲間[なかま]だ。", "sentence_source": "generated"}, {"text": "パイプの中を流体が流れて、工場へ運ばれる。", "target_word": "流体", "complexity_tier": "T3", "furigana": "パイプの中[なか]を流体[りゅうたい]が流[なが]れて、工場[こうじょう]へ運[はこ]ばれる。", "sentence_source": "generated"}, {"text": "風は空気という流体の動きだ。", "target_word": "流体", "complexity_tier": "T3", "furigana": "風[かぜ]は空気[くうき]という流体[りゅうたい]の動[うご]きだ。", "sentence_source": "generated"}, {"text": "氷はかたいが、とけて水になれば流体として流れ出す。", "target_word": "流体", "complexity_tier": "T3", "furigana": "氷[こおり]はかたいが、とけて水[みず]になれば流体[りゅうたい]として流[なが]れ出[だ]す。", "sentence_source": "generated"}, {"text": "この装置は流体の量をはかるために使う。", "target_word": "流体", "complexity_tier": "T3", "furigana": "この装置[そうち]は流体[りゅうたい]の量[りょう]をはかるために使[つか]う。", "sentence_source": "generated"}, {"text": "ガスも流体なので、管を通って家に届く。", "target_word": "流体", "complexity_tier": "T3", "furigana": "ガスも流体[りゅうたい]なので、管[くだ]を通[とお]って家[いえ]に届[とど]く。", "sentence_source": "generated"}, {"text": "流体は力を加えると、すぐに形を変える。", "target_word": "流体", "complexity_tier": "T3", "furigana": "流体[りゅうたい]は力[ちから]を加[くわ]えると、すぐに形[かたち]を変[か]える。", "sentence_source": "generated"}], "morphological_forms": [{"form": "流体", "label": "基本形"}], "register": "標準", "sense_fingerprint": "水や空気など、決まった形がなく流れるもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04de0b4-b7c5-4a40-b388-094939d08f82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37718, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "流体", "is_correct": true, "explanation": "空欄に入る語。形がなく流れる物質の総称で、水や空気を指す。"}, {"text": "太陽", "is_correct": false, "explanation": "天体の一つで、形を持たない物質の説明には合わない。"}, {"text": "機械", "is_correct": false, "explanation": "人が作る道具で、水や空気には当てはまらない。"}, {"text": "教室", "is_correct": false, "explanation": "建物の一室で、物質の性質の説明には使えない。"}], "explanations": {"流体": "空欄に入る語。形がなく流れる物質の総称で、水や空気を指す。", "太陽": "天体の一つで、形を持たない物質の説明には合わない。", "機械": "人が作る道具で、水や空気には当てはまらない。", "教室": "建物の一室で、物質の性質の説明には使えない。"}, "sentence_index": 0, "correct_answer": "流体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この小説は流体の場面が多い。", "explanation": "流体は液体や気体の総称で、血が流れる場面の意味は持たない。"}, {"text": "今年は黒い服が流体になっている。", "explanation": "流体は物質の分類で、服のはやりを表す語ではない。"}, {"text": "彼は流体の剣術を習った。", "explanation": "流体は液体や気体の総称で、武道の系統は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37718, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流体", "is_correct": true, "explanation": "空欄に入る語。とけて流れる状態の物質として、水を指す。"}, {"text": "天体", "is_correct": false, "explanation": "星や惑星のことで、とけて流れる物には使えない。"}, {"text": "食品", "is_correct": false, "explanation": "食べ物の総称で、流れ出す状態の説明には合わない。"}, {"text": "楽器", "is_correct": false, "explanation": "音を出す道具で、とけて流れる物には当てはまらない。"}], "explanations": {"流体": "空欄に入る語。とけて流れる状態の物質として、水を指す。", "天体": "星や惑星のことで、とけて流れる物には使えない。", "食品": "食べ物の総称で、流れ出す状態の説明には合わない。", "楽器": "音を出す道具で、とけて流れる物には当てはまらない。"}, "sentence_index": 6, "correct_answer": "流体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は流体のやり方で仕事をする。", "explanation": "流体は物質の分類で、仕事のやり方は表せない。"}, {"text": "選手は流体のように滑らかにパスをつないだ。", "explanation": "流体は物質の分類で、動きの滑らかさには使わない。"}, {"text": "この商品は流体が盛んだ。", "explanation": "流体は物質の分類で、商品の出回りの盛んさは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37718, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "流体で風船の中に入り、形が変わる。", "corrected_sentence": "流体は風船の中に入り、形が変わる。", "error_description": "「流体」に続く助詞が誤り。主語を示す「は」が正しく、「で」だと手段の意味になり文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37718, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冬の雪もとけて水になれば流体で流れ出す。", "corrected_sentence": "冬の雪もとけて水になれば流体として流れ出す。", "error_description": "「流体」に続く「で」は手段を示すので、状態を表す「として」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
