INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37719, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "連体修飾で「流体の流れ方」を作る。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所。研究者で流れ方を調べるでは、道具の意味になって不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向。研究者へ流れ方を調べるでは、対象の方向がずれる。"}, {"text": "より", "is_correct": false, "explanation": "比較。流体より流れ方を調べるでは、比べる意味になって文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "連体修飾で「流体の流れ方」を作る。", "で": "手段・場所。研究者で流れ方を調べるでは、道具の意味になって不自然。", "へ": "方向。研究者へ流れ方を調べるでは、対象の方向がずれる。", "より": "比較。流体より流れ方を調べるでは、比べる意味になって文が成り立たない。"}, "error_tags": {"で": "手段・場所", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37719, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "液体や気体など、形を変えて自由に流れる性質を持つ物質の総称。", "primary_collocate": null, "pronunciation": "りゅうたい", "ipa": "ɾʲɯːtai", "syllable_count": 4, "sentences": [{"text": "液体と気体をまとめて流体と呼ぶ。", "target_word": "流体", "complexity_tier": "T3", "furigana": "液体[えきたい]と気体[きたい]をまとめて流体[りゅうたい]と呼[よ]ぶ。", "sentence_source": "generated"}, {"text": "理科の授業で、流体の性質について学んだ。", "target_word": "流体", "complexity_tier": "T3", "furigana": "理科[りか]の授業[じゅぎょう]で、流体[りゅうたい]の性質[せいしつ]について学[まな]んだ。", "sentence_source": "generated"}, {"text": "流体の中では、物体が受ける抵抗が大きくなる。", "target_word": "流体", "complexity_tier": "T3", "furigana": "流体[りゅうたい]の中[なか]では、物体[ぶったい]が受[う]ける抵抗[ていこう]が大[おお]きくなる。", "sentence_source": "generated"}, {"text": "飛行機は、空気という流体の中を進む。", "target_word": "流体", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]は、空気[くうき]という流体[りゅうたい]の中[なか]を進[すす]む。", "sentence_source": "generated"}, {"text": "川の水も大気も、広い意味では流体だ。", "target_word": "流体", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]も大気[たいき]も、広[ひろ]い意味[いみ]では流体[りゅうたい]だ。", "sentence_source": "generated"}, {"text": "流体の圧力は、深いところほど大きい。", "target_word": "流体", "complexity_tier": "T3", "furigana": "流体[りゅうたい]の圧力[あつりょく]は、深[ふか]いところほど大[おお]きい。", "sentence_source": "generated"}, {"text": "血液も流体の一つで、体の中をめぐっている。", "target_word": "流体", "complexity_tier": "T3", "furigana": "血液[けつえき]も流体[りゅうたい]の一[ひと]つで、体[からだ]の中[なか]をめぐっている。", "sentence_source": "generated"}, {"text": "研究者は、流体の流れ方を調べている。", "target_word": "流体", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、流体[りゅうたい]の流[なが]れ方[かた]を調[しら]べている。", "sentence_source": "generated"}, {"text": "はちみつのように、ゆっくり流れる流体もある。", "target_word": "流体", "complexity_tier": "T3", "furigana": "はちみつのように、ゆっくり流[なが]れる流体[りゅうたい]もある。", "sentence_source": "generated"}, {"text": "船の設計では、流体が船に与える力を計算する。", "target_word": "流体", "complexity_tier": "T3", "furigana": "船[ふね]の設計[せっけい]では、流体[りゅうたい]が船[ふね]に与[あた]える力[ちから]を計算[けいさん]する。", "sentence_source": "generated"}], "morphological_forms": [{"form": "流体", "label": "基本形"}], "register": "標準", "sense_fingerprint": "液体と気体をまとめて指す理科の用語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04de0b4-b7c5-4a40-b388-094939d08f82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37719, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "流体", "is_correct": true, "explanation": "空欄に入る語。液体と気体を総称する理科の語。"}, {"text": "固体", "is_correct": false, "explanation": "形を保つ物質の状態で、液体と気体をまとめる語にはならない。"}, {"text": "植物", "is_correct": false, "explanation": "生き物の分類で、液体と気体には当てはまらない。"}, {"text": "楽器", "is_correct": false, "explanation": "音を出す道具で、物質の総称には使えない。"}], "explanations": {"流体": "空欄に入る語。液体と気体を総称する理科の語。", "固体": "形を保つ物質の状態で、液体と気体をまとめる語にはならない。", "植物": "生き物の分類で、液体と気体には当てはまらない。", "楽器": "音を出す道具で、物質の総称には使えない。"}, "sentence_index": 0, "correct_answer": "流体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "群れの流体を一つずつ数えた。", "explanation": "流体は液体や気体の総称で、一つ一つ数える個体の意味は持たない。"}, {"text": "この川は広い流体を流れる。", "explanation": "流体は物質の分類で、川の地域の広さを表す語ではない。"}, {"text": "この道場では、流体の型を教えている。", "explanation": "流体は液体や気体の総称で、武道の系統は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37719, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流体", "is_correct": true, "explanation": "空欄に入る語。体内をめぐる流れる物質の総称で、血液を含む。"}, {"text": "小物", "is_correct": false, "explanation": "持ち物の小さなもので、血液の分類には合わない。"}, {"text": "地図", "is_correct": false, "explanation": "場所や道を示す図で、体の中をめぐるものには使わない。"}, {"text": "絵画", "is_correct": false, "explanation": "描かれた絵で、体の中を流れるものには当てはまらない。"}], "explanations": {"流体": "空欄に入る語。体内をめぐる流れる物質の総称で、血液を含む。", "小物": "持ち物の小さなもので、血液の分類には合わない。", "地図": "場所や道を示す図で、体の中をめぐるものには使わない。", "絵画": "描かれた絵で、体の中を流れるものには当てはまらない。"}, "sentence_index": 6, "correct_answer": "流体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この言葉は今年の流体語だ。", "explanation": "流体は物質の分類で、言葉のはやりは表せない。"}, {"text": "彼は流体に英語を話した。", "explanation": "流体は液体や気体の総称で、話し方の上手さは表せない。"}, {"text": "事故で流体が出て、救急車を呼んだ。", "explanation": "流体は物質の総称で、血が流れ出る様子は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37719, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "理科では、この物質を流体に呼ぶ。", "corrected_sentence": "理科では、この物質を流体と呼ぶ。", "error_description": "「呼ぶ」は名称を表す「と」を取るので、「流体に」の「に」は誤り。「流体と呼ぶ」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37719, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "海水も流体を一つで、船の周りを流れている。", "corrected_sentence": "海水も流体の一つで、船の周りを流れている。", "error_description": "「流体」の後の「を」が誤り。「の一つ」と続けて同格にするのが正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37720, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「勉強する」の対象を示す格助詞で、力学が勉強の対象になるので合う。"}, {"text": "が", "is_correct": false, "explanation": "「力学が勉強する」では主語になり、勉強の対象を示す語が欠けて文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や相手を示すので、「力学に勉強する」は勉強の対象を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、勉強の対象を表す文には合わない。"}], "correct_answer": "を", "explanations": {"を": "「勉強する」の対象を示す格助詞で、力学が勉強の対象になるので合う。", "が": "「力学が勉強する」では主語になり、勉強の対象を示す語が欠けて文が成り立たない。", "に": "「に」は方向や相手を示すので、「力学に勉強する」は勉強の対象を表せない。", "へ": "「へ」は方向を示すので、勉強の対象を表す文には合わない。"}, "error_tags": {"が": "主語と目的語の取り違え", "に": "格の誤り", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37720, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「苦手」の対象を示す格助詞で、「力学が苦手」の形になるので合う。"}, {"text": "で", "is_correct": false, "explanation": "「力学で苦手」は手段や場所の意味になり、苦手な対象を表せない。"}, {"text": "と", "is_correct": false, "explanation": "「力学と苦手」は並列を示すが、「苦手」の対象にはならない。"}, {"text": "から", "is_correct": false, "explanation": "「力学から苦手」は起点を示すので、苦手の対象を表す文には合わない。"}], "correct_answer": "が", "explanations": {"が": "「苦手」の対象を示す格助詞で、「力学が苦手」の形になるので合う。", "で": "「力学で苦手」は手段や場所の意味になり、苦手な対象を表せない。", "と": "「力学と苦手」は並列を示すが、「苦手」の対象にはならない。", "から": "「力学から苦手」は起点を示すので、苦手の対象を表す文には合わない。"}, "error_tags": {"で": "手段・場所", "と": "並列", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37720, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物が動いたり、止まったりするときの、力の動きを考える学問です。", "primary_collocate": null, "pronunciation": "りきがく", "ipa": "ɾikiɡakɯ", "syllable_count": 4, "sentences": [{"text": "力学では、物が動く理由を力から考えます。", "target_word": "力学", "complexity_tier": "T3", "furigana": "力学[りきがく]では、物[もの]が動[うご]く理由[りゆう]を力[ちから]から考[かんが]えます。", "sentence_source": "generated"}, {"text": "力学を勉強すると、ボールが飛ぶ道すじがわかります。", "target_word": "力学", "complexity_tier": "T3", "furigana": "力学[りきがく]を勉強[べんきょう]すると、ボールが飛[と]ぶ道[みち]すじがわかります。", "sentence_source": "generated"}, {"text": "兄は大学で力学の授業を受けています。", "target_word": "力学", "complexity_tier": "T3", "furigana": "兄[あに]は大学[だいがく]で力学[りきがく]の授業[じゅぎょう]を受[う]けています。", "sentence_source": "generated"}, {"text": "橋を作る人は、力学を使って丈夫な形を考えます。", "target_word": "力学", "complexity_tier": "T3", "furigana": "橋[はし]を作[つく]る人[ひと]は、力学[りきがく]を使[つか]って丈夫[じょうぶ]な形[かたち]を考[かんが]えます。", "sentence_source": "generated"}, {"text": "力学の問題は、図をかくととても解きやすくなります。", "target_word": "力学", "complexity_tier": "T3", "furigana": "力学[りきがく]の問題[もんだい]は、図[ず]をかくととても解[と]きやすくなります。", "sentence_source": "generated"}, {"text": "先生は、力学の例として、坂を転がる玉を見せました。", "target_word": "力学", "complexity_tier": "T3", "furigana": "先生[せんせい]は、力学[りきがく]の例[れい]として、坂[さか]を転[ころ]がる玉[たま]を見[み]せました。", "sentence_source": "generated"}, {"text": "自転車が止まる理由も、力学で説明できます。", "target_word": "力学", "complexity_tier": "T3", "furigana": "自転車[じてんしゃ]が止[と]まる理由[りゆう]も、力学[りきがく]で説明[せつめい]できます。", "sentence_source": "generated"}, {"text": "力学が苦手なので、毎週の練習問題を二回ずつ解いています。", "target_word": "力学", "complexity_tier": "T3", "furigana": "力学[りきがく]が苦手[にがて]なので、毎週[まいしゅう]の練習問題[れんしゅうもんだい]を二回[にかい]ずつ解[と]いています。", "sentence_source": "generated"}, {"text": "力学の本を読んで、物が落ちる仕組みを知りました。", "target_word": "力学", "complexity_tier": "T3", "furigana": "力学[りきがく]の本[ほん]を読[よ]んで、物[もの]が落[お]ちる仕組[しく]みを知[し]りました。", "sentence_source": "generated"}, {"text": "高い建物は、風の力を考えた力学の計算をして建てます。", "target_word": "力学", "complexity_tier": "T3", "furigana": "高[たか]い建物[たてもの]は、風[かぜ]の力[ちから]を考[かんが]えた力学[りきがく]の計算[けいさん]をして建[た]てます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "力学", "label": "基本形"}], "register": "標準（学問的だが中立的）", "sense_fingerprint": "物の動きと止まりを力から考える学問", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T4: contains vocabulary far above tier T4: 道すじ (Zipf 1.43)']::text[], '8506ed3a-c0bb-4ca9-9f47-86feb09e3786') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37720, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "力学", "is_correct": true, "explanation": "物の動きと止まりを力から考える学問の名称で、文の内容と合う。"}, {"text": "料理", "is_correct": false, "explanation": "調理の分野なので、物が動く理由を力から考える文には合わない。"}, {"text": "文学", "is_correct": false, "explanation": "言葉や物語を扱う分野なので、力の働きを説明する文には合わない。"}, {"text": "音楽", "is_correct": false, "explanation": "音や演奏を扱う分野なので、物の動きと力の関係を述べる文には合わない。"}], "explanations": {"力学": "物の動きと止まりを力から考える学問の名称で、文の内容と合う。", "料理": "調理の分野なので、物が動く理由を力から考える文には合わない。", "文学": "言葉や物語を扱う分野なので、力の働きを説明する文には合わない。", "音楽": "音や演奏を扱う分野なので、物の動きと力の関係を述べる文には合わない。"}, "sentence_index": 0, "correct_answer": "力学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "電気が流れる仕組みを、力学で一から習った。", "explanation": "ここは〈電磁気学〉の内容を指している。力学は物体の運動と力を扱うので、電気の流れは対象にならない。"}, {"text": "細胞が分かれる仕組みを、力学で顕微鏡を使って調べた。", "explanation": "ここは〈生物学〉の内容を指している。力学は物の動きと力の学問なので、細胞の分裂は扱わない。"}, {"text": "人がうそをつく仕組みを、力学で研究している。", "explanation": "ここは〈心理学〉の内容を指している。力学は物体の運動を扱うので、人の心の働きには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37720, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "力学", "is_correct": true, "explanation": "学問の名称で、自転車の止まる理由を説明する文と合う。"}, {"text": "絵画", "is_correct": false, "explanation": "描く芸術の分野なので、自転車が止まる理由の説明には合わない。"}, {"text": "歴史", "is_correct": false, "explanation": "過去の出来事を扱う分野なので、止まる理由の説明には合わない。"}, {"text": "漢字", "is_correct": false, "explanation": "文字の学習内容なので、物理的な止まる理由の説明には合わない。"}], "explanations": {"力学": "学問の名称で、自転車の止まる理由を説明する文と合う。", "絵画": "描く芸術の分野なので、自転車が止まる理由の説明には合わない。", "歴史": "過去の出来事を扱う分野なので、止まる理由の説明には合わない。", "漢字": "文字の学習内容なので、物理的な止まる理由の説明には合わない。"}, "sentence_index": 6, "correct_answer": "力学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "物の値段が上がる仕組みを、力学で説明した。", "explanation": "ここは〈経済学〉の内容を指している。力学は物体の運動と力を扱うので、値段の仕組みは対象にならない。"}, {"text": "昔の戦いの流れを、力学で年表にまとめた。", "explanation": "ここは〈歴史学〉の内容を指している。力学は運動と力の学問なので、過去の出来事は扱わない。"}, {"text": "外国語の文法の仕組みを、力学で研究している。", "explanation": "ここは〈言語学〉の内容を指している。力学は物体の運動を扱うので、文法の研究には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37720, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は毎日、力学を本を読んでいます。", "corrected_sentence": "私は毎日、力学の本を読んでいます。", "error_description": "「力学の本」の「の」が「を」になっている。「力学」は「本」を修飾する名詞なので「の」が正しい。「を」を続けると目的語が二つ並んで不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37720, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもたちは力学を授業で、ふりこを作った。", "corrected_sentence": "子どもたちは力学の授業で、ふりこを作った。", "error_description": "「力学の授業」の「の」が「を」になっている。「力学」は「授業」を修飾するので「の」が正しい。「を」だと「授業で」との関係が崩れて不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37721, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「力学の基本」と名詞を修飾する「の」で、文の意味が通る。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「基本になる」を続けると目的語の形が崩れて文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「力学に基本になる」は意味が通らず、名詞の修飾関係を作れない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、基本の内容を修飾する文には合わない。"}], "correct_answer": "の", "explanations": {"の": "「力学の基本」と名詞を修飾する「の」で、文の意味が通る。", "を": "「を」は目的語を示すが、「基本になる」を続けると目的語の形が崩れて文が成り立たない。", "に": "「力学に基本になる」は意味が通らず、名詞の修飾関係を作れない。", "へ": "「へ」は方向を示すので、基本の内容を修飾する文には合わない。"}, "error_tags": {"を": "目的語と修飾の取り違え", "に": "格の誤り", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37721, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「ふつうの力学では」と範囲を示し、説明できない範囲として文が成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "「力学がは」となり、「が」の後に「は」が続かず文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「力学のは」となり、「の」の後に「は」が続かず文が成り立たない。"}, {"text": "も", "is_correct": false, "explanation": "「力学もは」となり、「も」と「は」が重なって文が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「ふつうの力学では」と範囲を示し、説明できない範囲として文が成り立つ。", "が": "「力学がは」となり、「が」の後に「は」が続かず文が成り立たない。", "の": "「力学のは」となり、「の」の後に「は」が続かず文が成り立たない。", "も": "「力学もは」となり、「も」と「は」が重なって文が成り立たない。"}, "error_tags": {"が": "格の誤り", "の": "修飾の誤り", "も": "助詞の重なり"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37721, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物体の運動と、それに働く力の関係を研究する物理学の一分野。", "primary_collocate": null, "pronunciation": "りきがく", "ipa": "ɾikiɡakɯ", "syllable_count": 4, "sentences": [{"text": "高校の物理では、まず力学から習います。", "target_word": "力学", "complexity_tier": "T3", "furigana": "高校[こうこう]の物理[ぶつり]では、まず力学[りきがく]から習[なら]います。", "sentence_source": "generated"}, {"text": "ニュートンは、力学の基本になる法則を見つけました。", "target_word": "力学", "complexity_tier": "T3", "furigana": "ニュートンは、力学[りきがく]の基本[きほん]になる法則[ほうそく]を見[み]つけました。", "sentence_source": "generated"}, {"text": "力学は、物体の運動と力の関係を研究する物理学の一分野です。", "target_word": "力学", "complexity_tier": "T3", "furigana": "力学[りきがく]は、物体[ぶったい]の運動[うんどう]と力[ちから]の関係[かんけい]を研究[けんきゅう]する物理学[ぶつりがく]の一分野[いちぶんや]です。", "sentence_source": "generated"}, {"text": "力学の試験では、物体の速さと力を使って計算する問題が出ました。", "target_word": "力学", "complexity_tier": "T3", "furigana": "力学[りきがく]の試験[しけん]では、物体[ぶったい]の速[はや]さと力[ちから]を使[つか]って計算[けいさん]する問題[もんだい]が出[で]ました。", "sentence_source": "generated"}, {"text": "宇宙船の動きは、力学の法則で予想できます。", "target_word": "力学", "complexity_tier": "T3", "furigana": "宇宙船[うちゅうせん]の動[うご]きは、力学[りきがく]の法則[ほうそく]で予想[よそう]できます。", "sentence_source": "generated"}, {"text": "彼女は物理学者で、力学を専門に研究しています。", "target_word": "力学", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は物理学者[ぶつりがくしゃ]で、力学[りきがく]を専門[せんもん]に研究[けんきゅう]しています。", "sentence_source": "generated"}, {"text": "力学の式を使えば、物体が落ちる時間を計算できます。", "target_word": "力学", "complexity_tier": "T3", "furigana": "力学[りきがく]の式[しき]を使[つか]えば、物体[ぶったい]が落[お]ちる時間[じかん]を計算[けいさん]できます。", "sentence_source": "generated"}, {"text": "とても小さい粒の動きは、ふつうの力学では説明できません。", "target_word": "力学", "complexity_tier": "T3", "furigana": "とても小[ちい]さい粒[つぶ]の動[うご]きは、ふつうの力学[りきがく]では説明[せつめい]できません。", "sentence_source": "generated"}, {"text": "力学の法則によると、力を加えない物体は同じ速さで動き続けます。", "target_word": "力学", "complexity_tier": "T3", "furigana": "力学[りきがく]の法則[ほうそく]によると、力[ちから]を加[くわ]えない物体[ぶったい]は同[おな]じ速[はや]さで動[うご]き続[つづ]けます。", "sentence_source": "generated"}, {"text": "この教科書は、力学の基礎を図でやさしく説明しています。", "target_word": "力学", "complexity_tier": "T3", "furigana": "この教科書[きょうかしょ]は、力学[りきがく]の基礎[きそ]を図[ず]でやさしく説明[せつめい]しています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "力学", "label": "基本形"}], "register": "標準（学問的・やや硬い）", "sense_fingerprint": "物理学の一分野で、運動と力の関係を扱う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8506ed3a-c0bb-4ca9-9f47-86feb09e3786') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37721, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "力学", "is_correct": true, "explanation": "物体の運動と力の関係を研究する物理学の分野で、高校物理の最初に習う内容と合う。"}, {"text": "歴史", "is_correct": false, "explanation": "人類の過去を扱う分野で、物理の授業で最初に習う内容ではない。"}, {"text": "文法", "is_correct": false, "explanation": "言語の決まりを扱う分野で、物理の授業の内容ではない。"}, {"text": "漢字", "is_correct": false, "explanation": "文字の学習内容で、物理の授業の出発点としては合わない。"}], "explanations": {"力学": "物体の運動と力の関係を研究する物理学の分野で、高校物理の最初に習う内容と合う。", "歴史": "人類の過去を扱う分野で、物理の授業で最初に習う内容ではない。", "文法": "言語の決まりを扱う分野で、物理の授業の内容ではない。", "漢字": "文字の学習内容で、物理の授業の出発点としては合わない。"}, "sentence_index": 0, "correct_answer": "力学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "薬品どうしが反応する仕組みを、力学で一から習った。", "explanation": "ここは〈化学〉の内容を指している。力学は物体の運動と力を扱うので、薬品の反応は対象にならない。"}, {"text": "植物が光に向かって伸びる仕組みを、力学で調べた。", "explanation": "ここは〈生物学〉の内容を指している。力学は運動と力の学問なので、植物の生長は扱わない。"}, {"text": "人が緊張する仕組みを、力学で研究している。", "explanation": "ここは〈心理学〉の内容を指している。力学は物体の運動を扱うので、人の心の働きには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37721, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "力学", "is_correct": true, "explanation": "運動と力の関係を扱う分野で、物体が落ちる時間を計算する式と合う。"}, {"text": "料理", "is_correct": false, "explanation": "調理の分野なので、落ちる時間を計算する式には結びつかない。"}, {"text": "音楽", "is_correct": false, "explanation": "音や演奏の分野なので、物体の落下を計算する式には合わない。"}, {"text": "文学", "is_correct": false, "explanation": "言葉や物語の分野なので、落下時間を計算する式には合わない。"}], "explanations": {"力学": "運動と力の関係を扱う分野で、物体が落ちる時間を計算する式と合う。", "料理": "調理の分野なので、落ちる時間を計算する式には結びつかない。", "音楽": "音や演奏の分野なので、物体の落下を計算する式には合わない。", "文学": "言葉や物語の分野なので、落下時間を計算する式には合わない。"}, "sentence_index": 6, "correct_answer": "力学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会社が利益を増やす仕組みを、力学で説明した。", "explanation": "ここは〈経済学〉の内容を指している。力学は物体の運動と力を扱うので、会社の利益の仕組みは対象にならない。"}, {"text": "江戸時代の政治の流れを、力学で年表にまとめた。", "explanation": "ここは〈歴史学〉の内容を指している。力学は運動と力の学問なので、過去の政治は扱わない。"}, {"text": "日本語の敬語の仕組みを、力学で研究している。", "explanation": "ここは〈言語学〉の内容を指している。力学は物体の運動を扱うので、敬語の研究には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37721, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹は大学で力学が学んでいます。", "corrected_sentence": "妹は大学で力学を学んでいます。", "error_description": "「学ぶ」の目的語を示す「が」が「を」になるべき箇所。「が」だと「力学が」が主語になり、「学んでいます」の目的語がなくなって不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37721, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "宇宙船の動きを、力学を法則で予想した。", "corrected_sentence": "宇宙船の動きを、力学の法則で予想した。", "error_description": "「力学の法則」の「の」が「を」になっている。「力学」は「法則」を修飾するので「の」が正しい。「を」を続けると「法則で」との関係が崩れて不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37722, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「用いる」の目的語を示す格助詞で、図を使うという意味になる。"}, {"text": "が", "is_correct": false, "explanation": "「図が用いて」は図が主語になり、用いる目的語が欠けて文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、使う対象を表す文には合わない。"}, {"text": "と", "is_correct": false, "explanation": "「図と用いて」は並列を示し、使う対象の関係を作れない。"}], "correct_answer": "を", "explanations": {"を": "「用いる」の目的語を示す格助詞で、図を使うという意味になる。", "が": "「図が用いて」は図が主語になり、用いる目的語が欠けて文が成り立たない。", "へ": "「へ」は方向を示すので、使う対象を表す文には合わない。", "と": "「図と用いて」は並列を示し、使う対象の関係を作れない。"}, "error_tags": {"が": "主語と目的語の取り違え", "へ": "方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37722, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「用いる」の目的語を示す格助詞で、ていねいな表現を使うという意味になる。"}, {"text": "から", "is_correct": false, "explanation": "「表現から用いる」は起点の意味になり、使う対象を表せない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は「表現よりも用いる」の意味になり、目的語の役割を果たさない。"}, {"text": "で", "is_correct": false, "explanation": "「表現で用いる」は手段の意味になり、表現が手段ではなく対象なので不自然。"}], "correct_answer": "を", "explanations": {"を": "「用いる」の目的語を示す格助詞で、ていねいな表現を使うという意味になる。", "から": "「表現から用いる」は起点の意味になり、使う対象を表せない。", "より": "比較の「より」は「表現よりも用いる」の意味になり、目的語の役割を果たさない。", "で": "「表現で用いる」は手段の意味になり、表現が手段ではなく対象なので不自然。"}, "error_tags": {"から": "起点", "より": "比較", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37722, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "道具や方法、言葉などを目的のために使う。", "primary_collocate": null, "pronunciation": "もちいる", "ipa": "mot͡ɕiiɾɯ", "syllable_count": 4, "sentences": [{"text": "この実験では、特別な薬品を用いる。", "target_word": "用いる", "complexity_tier": "T3", "furigana": "この実験(じっけん)では、特別(とくべつ)な薬品(やくひん)を用(もち)いる。", "sentence_source": "generated"}, {"text": "先生は説明のために、図を用いて話した。", "target_word": "用いて", "complexity_tier": "T3", "furigana": "先生(せんせい)は説明(せつめい)のために、図(ず)を用(もち)いて話(はな)した。", "sentence_source": "generated"}, {"text": "昔の人は、火をおこすのに石を用いた。", "target_word": "用いた", "complexity_tier": "T3", "furigana": "昔(むかし)の人(ひと)は、火(ひ)をおこすのに石(いし)を用(もち)いた。", "sentence_source": "generated"}, {"text": "文章を書くときは、やさしい言葉を用いるようにしている。", "target_word": "用いる", "complexity_tier": "T3", "furigana": "文章(ぶんしょう)を書(か)くときは、やさしい言葉(ことば)を用(もち)いるようにしている。", "sentence_source": "generated"}, {"text": "会議では、専門用語を用いない方がわかりやすい。", "target_word": "用いない", "complexity_tier": "T3", "furigana": "会議(かいぎ)では、専門用語(せんもんようご)を用(もち)いない方(ほう)がわかりやすい。", "sentence_source": "generated"}, {"text": "この方法は、多くの学校で用いられている。", "target_word": "用いられている", "complexity_tier": "T3", "furigana": "この方法(ほうほう)は、多(おお)くの学校(がっこう)で用(もち)いられている。", "sentence_source": "generated"}, {"text": "彼は新しい技術を用いて、安い家具を作った。", "target_word": "用いて", "complexity_tier": "T3", "furigana": "彼(かれ)は新(あたら)しい技術(ぎじゅつ)を用(もち)いて、安(やす)い家具(かぐ)を作(つく)った。", "sentence_source": "generated"}, {"text": "手紙では、ていねいな表現を用いるのが礼儀だ。", "target_word": "用いる", "complexity_tier": "T3", "furigana": "手紙(てがみ)では、ていねいな表現(ひょうげん)を用(もち)いるのが礼儀(れいぎ)だ。", "sentence_source": "generated"}, {"text": "この料理人は古い鍋を用いて、昔の味を出している。", "target_word": "用いて", "complexity_tier": "T3", "furigana": "この料理人(りょうりにん)は古(ふる)い鍋(なべ)を用(もち)いて、昔(むかし)の味(あじ)を出(だ)している。", "sentence_source": "generated"}, {"text": "山の地図を作るために、空からの写真を用いた。", "target_word": "用いた", "complexity_tier": "T3", "furigana": "山(やま)の地図(ちず)を作(つく)るために、空(そら)からの写真(しゃしん)を用(もち)いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "用いない", "label": "否定形"}, {"form": "用いた", "label": "過去形"}, {"form": "用いて", "label": "て形"}, {"form": "用います", "label": "丁寧形"}, {"form": "用いれば", "label": "仮定形"}, {"form": "用いられる", "label": "受身形"}, {"form": "用いる", "label": "基本形"}], "register": "やや硬い標準語", "sense_fingerprint": "道具・方法・言葉などを目的のために使う（「使う」より硬い）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8506ed3a-c0bb-4ca9-9f47-86feb09e3786') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37722, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "用いる", "is_correct": true, "explanation": "「使って目的を果たす」意味で、特別な薬品を使う文と合う。"}, {"text": "洗う", "is_correct": false, "explanation": "「薬品を洗う」は意味が通らず、道具や方法を使う文には合わない。"}, {"text": "切る", "is_correct": false, "explanation": "「薬品を切る」は意味が通らず、使用の意味にならない。"}, {"text": "折る", "is_correct": false, "explanation": "「薬品を折る」は意味が通らず、使用の意味にならない。"}], "explanations": {"用いる": "「使って目的を果たす」意味で、特別な薬品を使う文と合う。", "洗う": "「薬品を洗う」は意味が通らず、道具や方法を使う文には合わない。", "切る": "「薬品を切る」は意味が通らず、使用の意味にならない。", "折る": "「薬品を折る」は意味が通らず、使用の意味にならない。"}, "sentence_index": 0, "correct_answer": "用いる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "お腹がすいたので、おにぎりを用いた。", "explanation": "ここは〈食べる〉の意味。用いるは何かを目的のために使う語で、食べる動作には使わない。"}, {"text": "来客のために、おいしいお菓子を用いた。", "explanation": "ここは〈用意する〉の意味。用いるは物を目的のために使うことで、前もって準備する意味にはならない。"}, {"text": "のどが渇いたので、冷たい水を用いた。", "explanation": "ここは〈飲む〉の意味。用いるは使うことを表す語で、飲む動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37722, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "用いて", "is_correct": true, "explanation": "て形で、「技術を使って家具を作った」と文脈に合う。"}, {"text": "叩いて", "is_correct": false, "explanation": "「技術を叩いて」は意味が通らず、使う意味にならない。"}, {"text": "眠って", "is_correct": false, "explanation": "「技術を眠って」は意味が通らず、道具や方法を使う意味にならない。"}, {"text": "怒って", "is_correct": false, "explanation": "「技術を怒って」は意味が通らず、使う意味にならない。"}], "explanations": {"用いて": "て形で、「技術を使って家具を作った」と文脈に合う。", "叩いて": "「技術を叩いて」は意味が通らず、使う意味にならない。", "眠って": "「技術を眠って」は意味が通らず、道具や方法を使う意味にならない。", "怒って": "「技術を怒って」は意味が通らず、使う意味にならない。"}, "sentence_index": 6, "correct_answer": "用いて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "眠くなったので、やわらかいふとんを用いた。", "explanation": "ここは〈寝る〉の意味。用いるは物を目的のために使う語で、眠る動作には使わない。"}, {"text": "友達から、大事な手紙を用いた。", "explanation": "ここは〈受け取る〉の意味。用いるは使うことを表し、受け取る動作には使わない。"}, {"text": "電車の中で、大事な財布を用いて落とした。", "explanation": "ここは〈落とす〉の意味。用いるは使う意味で、物を誤って手放す出来事には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37722, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古い道具を用いる、家を直した。", "corrected_sentence": "古い道具を用いて、家を直した。", "error_description": "「用いる」は終止形で、文を「、」で続けるには連用の「用いて」が必要。終止形のままだと「用いる、家を直した」となり文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "用いて", "is_correct": true, "explanation": "て形で、「図を使って話した」と後ろの文へ続く形になり、文の流れに合う。"}, {"text": "用いない", "is_correct": false, "explanation": "否定形なので「使わずに話した」という意味になり、文の内容と合わない。"}, {"text": "用いられる", "is_correct": false, "explanation": "受身形なので「図が使われる」の意味になり、先生が使う主語の文と合わない。"}, {"text": "用います", "is_correct": false, "explanation": "丁寧形なので、普通体の「話した」と文体が合わない。"}], "correct_form": "用いて", "base_form": "用いる", "form_label": "て形", "sentence_index": 1, "explanations": {"用いて": "て形で、「図を使って話した」と後ろの文へ続く形になり、文の流れに合う。", "用いない": "否定形なので「使わずに話した」という意味になり、文の内容と合わない。", "用いられる": "受身形なので「図が使われる」の意味になり、先生が使う主語の文と合わない。", "用います": "丁寧形なので、普通体の「話した」と文体が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37722, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもたちは、絵の具が用いて、きれいな花を描いた。", "corrected_sentence": "子どもたちは、絵の具を用いて、きれいな花を描いた。", "error_description": "「用いる」の目的語を示す「が」が「を」になるべき箇所。「が」だと「絵の具が」が主語になり、「用いて」の目的語がなくなって不自然になる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "用いる", "is_correct": true, "explanation": "基本形で、「のが礼儀だ」の前に来て一般論を述べる形と合う。"}, {"text": "用います", "is_correct": false, "explanation": "丁寧形なので「のが礼儀」の前に続かず、文が成り立たない。"}, {"text": "用いれば", "is_correct": false, "explanation": "仮定形なので、条件の意味が入り、「礼儀だ」の文と合わない。"}, {"text": "用いられて", "is_correct": false, "explanation": "受身のて形なので、表現が受身になり、能動の文の意味と合わない。"}], "correct_form": "用いる", "base_form": "用いる", "form_label": "基本形", "sentence_index": 7, "explanations": {"用いる": "基本形で、「のが礼儀だ」の前に来て一般論を述べる形と合う。", "用います": "丁寧形なので「のが礼儀」の前に続かず、文が成り立たない。", "用いれば": "仮定形なので、条件の意味が入り、「礼儀だ」の文と合わない。", "用いられて": "受身のて形なので、表現が受身になり、能動の文の意味と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37724, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「する」の目的語を示す「を」。「シミュレーションをすると」で正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「シミュレーションがすると」では意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「シミュレーションへすると」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐので、「シミュレーションのすると」は動詞とつながらない。"}], "correct_answer": "を", "explanations": {"を": "「する」の目的語を示す「を」。「シミュレーションをすると」で正しい。", "が": "「が」は主語を示すので、「シミュレーションがすると」では意味が通らない。", "へ": "「へ」は方向を示すので、「シミュレーションへすると」は成り立たない。", "の": "「の」は名詞をつなぐので、「シミュレーションのすると」は動詞とつながらない。"}, "error_tags": {"が": "主語", "へ": "方向", "の": "名詞つなぎ"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37724, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37724, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "コンピューターの中で、本当にあったらどうなるかをためしてみることです。", "primary_collocate": null, "pronunciation": "しみゅれーしょん", "ipa": "ɕimʲɯɾeːɕoɴ", "syllable_count": 6, "sentences": [{"text": "パイロットは、本物の飛行機に乗る前にシミュレーションで練習する。", "target_word": "シミュレーション", "complexity_tier": "T3", "furigana": "パイロットは、本物[ほんもの]の飛行機[ひこうき]に乗[の]る前[まえ]にシミュレーションで練習[れんしゅう]する。", "sentence_source": "generated"}, {"text": "コンピューターでシミュレーションをすると、地震のときの建物の動きがわかる。", "target_word": "シミュレーション", "complexity_tier": "T3", "furigana": "コンピューターでシミュレーションをすると、地震[じしん]のときの建物[たてもの]の動[うご]きがわかる。", "sentence_source": "generated"}, {"text": "実際に火事を起こすことはできないので、シミュレーションで避難の方法を調べた。", "target_word": "シミュレーション", "complexity_tier": "T3", "furigana": "実際[じっさい]に火事[かじ]を起[お]こすことはできないので、シミュレーションで避難[ひなん]の方法[ほうほう]を調[しら]べた。", "sentence_source": "generated"}, {"text": "授業で、天気の変化をシミュレーションして結果を発表した。", "target_word": "シミュレーション", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]で、天気[てんき]の変化[へんか]をシミュレーションして結果[けっか]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "シミュレーションの結果、このままでは川の水があふれることがわかった。", "target_word": "シミュレーション", "complexity_tier": "T3", "furigana": "シミュレーションの結果[けっか]、このままでは川[かわ]の水[みず]があふれることがわかった。", "sentence_source": "generated"}, {"text": "失敗したら危ないので、まずシミュレーションで試してみよう。", "target_word": "シミュレーション", "complexity_tier": "T3", "furigana": "失敗[しっぱい]したら危[あぶ]ないので、まずシミュレーションで試[ため]してみよう。", "sentence_source": "generated"}, {"text": "先生は、シミュレーションを使って星の動きを見せてくれた。", "target_word": "シミュレーション", "complexity_tier": "T3", "furigana": "先生[せんせい]は、シミュレーションを使[つか]って星[ほし]の動[うご]きを見[み]せてくれた。", "sentence_source": "generated"}, {"text": "彼は新しい車の安全性を、シミュレーションで何度も確かめた。", "target_word": "シミュレーション", "complexity_tier": "T3", "furigana": "彼[かれ]は新[あたら]しい車[くるま]の安全性[あんぜんせい]を、シミュレーションで何度[なんど]も確[たし]かめた。", "sentence_source": "generated"}, {"text": "シミュレーションでは問題がなかったが、本番では雨で計画が変わった。", "target_word": "シミュレーション", "complexity_tier": "T3", "furigana": "シミュレーションでは問題[もんだい]がなかったが、本番[ほんばん]では雨[あめ]で計画[けいかく]が変[か]わった。", "sentence_source": "generated"}, {"text": "買い物の前に、ローンの支払いをシミュレーションしておくと安心だ。", "target_word": "シミュレーション", "complexity_tier": "T3", "furigana": "買[か]い物[もの]の前[まえ]に、ローンの支払[しはら]いをシミュレーションしておくと安心[あんしん]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "シミュレーション", "label": "基本形"}, {"form": "シミュレーションする", "label": "サ変動詞形"}], "register": "中立", "sense_fingerprint": "実際には起こせないことを、コンピューターで試して結果を見ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f06b4680-4fa3-4940-ae92-665bd01dff19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37724, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "シミュレーション", "is_correct": true, "explanation": "「で練習する」の手段を指し、模擬的な練習として文が成り立つ。"}, {"text": "機内食", "is_correct": false, "explanation": "機内食は練習の手段にならないので、「機内食で練習する」は成り立たない。"}, {"text": "航空券", "is_correct": false, "explanation": "航空券は練習の道具ではないので、文の意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は練習の手段にならないので、「天気で練習する」は成り立たない。"}], "explanations": {"シミュレーション": "「で練習する」の手段を指し、模擬的な練習として文が成り立つ。", "機内食": "機内食は練習の手段にならないので、「機内食で練習する」は成り立たない。", "航空券": "航空券は練習の道具ではないので、文の意味が通らない。", "天気": "天気は練習の手段にならないので、「天気で練習する」は成り立たない。"}, "sentence_index": 0, "correct_answer": "シミュレーション"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "段ボールで作った船のシミュレーションを、プールに浮かべて遊んだ。", "explanation": "ここは〈模型〉の意味。シミュレーションは計算による再現で、プールに浮かべられる物ではないので合わない。"}, {"text": "先生は黒板に、花のシミュレーションを描いて説明した。", "explanation": "ここは〈絵〉の意味。シミュレーションは描くものではなく計算で再現することなので合わない。"}, {"text": "妹はシミュレーションを抱いて、昼寝をしていた。", "explanation": "ここは〈人形〉の意味。シミュレーションは抱けるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37724, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "シミュレーション", "is_correct": true, "explanation": "「を使って」の対象で、星の動きを再現する手段として文に合う。"}, {"text": "雑談", "is_correct": false, "explanation": "雑談は手段ではないので、「雑談を使って」は成り立たない。"}, {"text": "感想", "is_correct": false, "explanation": "感想は手段として使うものではないので、「感想を使って」は意味が通らない。"}, {"text": "勇気", "is_correct": false, "explanation": "勇気は道具ではないので、「勇気を使って星の動きを見せた」は成り立たない。"}], "explanations": {"シミュレーション": "「を使って」の対象で、星の動きを再現する手段として文に合う。", "雑談": "雑談は手段ではないので、「雑談を使って」は成り立たない。", "感想": "感想は手段として使うものではないので、「感想を使って」は意味が通らない。", "勇気": "勇気は道具ではないので、「勇気を使って星の動きを見せた」は成り立たない。"}, "sentence_index": 6, "correct_answer": "シミュレーション"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖母は、シミュレーションの糸を編んで、マフラーを作った。", "explanation": "ここは〈毛糸〉の意味。シミュレーションは編める素材ではないので合わない。"}, {"text": "店の前に、大きなシミュレーションを立てた。", "explanation": "ここは〈看板〉の意味。シミュレーションは立てられる物ではないので合わない。"}, {"text": "寒い夜は、シミュレーションを干して、ふかふかにした。", "explanation": "ここは〈ふとん〉の意味。シミュレーションは干せる物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37724, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は、シミュレーションが使って台風の進路を生徒に見せた。", "corrected_sentence": "先生は、シミュレーションを使って台風の進路を生徒に見せた。", "error_description": "「使う」の道具を示すのは「を」。「が」は主語を示すので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37724, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "避難の訓練の前に、シミュレーションを起こしておくと安心だ。", "corrected_sentence": "避難の訓練の前に、シミュレーションをしておくと安心だ。", "error_description": "「する」が正しい。「起こす」は事故や火事など起きる出来事に使うので、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
