INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37725, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "手段を示す「で」。「シミュレーションで条件をしぼった」で正しい。"}, {"text": "に", "is_correct": false, "explanation": "「に」は位置や相手を示すので、「シミュレーションに条件をしぼった」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、ここでは意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「条件を」がすでにあるため、「を」が重なって文が崩れる。"}], "correct_answer": "で", "explanations": {"で": "手段を示す「で」。「シミュレーションで条件をしぼった」で正しい。", "に": "「に」は位置や相手を示すので、「シミュレーションに条件をしぼった」は成り立たない。", "へ": "「へ」は方向を示すので、ここでは意味が通らない。", "を": "「条件を」がすでにあるため、「を」が重なって文が崩れる。"}, "error_tags": {"に": "位置・相手", "へ": "方向", "を": "目的語（重複）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37725, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "現実の現象やシステムを、コンピューターなどを使って模擬的に再現すること。", "primary_collocate": null, "pronunciation": "しみゅれーしょん", "ipa": "ɕimʲɯɾeːɕoɴ", "syllable_count": 6, "sentences": [{"text": "研究者は、気候変動の影響を大規模なシミュレーションで再現した。", "target_word": "シミュレーション", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、気候変動[きこうへんどう]の影響[えいきょう]を大規模[だいきぼ]なシミュレーションで再現[さいげん]した。", "sentence_source": "generated"}, {"text": "シミュレーションによって、翼の周りの空気の流れを解析した。", "target_word": "シミュレーション", "complexity_tier": "T3", "furigana": "シミュレーションによって、翼[つばさ]の周[まわ]りの空気[くうき]の流[なが]れを解析[かいせき]した。", "sentence_source": "generated"}, {"text": "この会社は、工場の生産ラインのシミュレーションを行って無駄を減らした。", "target_word": "シミュレーション", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、工場[こうじょう]の生産[せいさん]ラインのシミュレーションを行[おこな]って無駄[むだ]を減[へ]らした。", "sentence_source": "generated"}, {"text": "シミュレーションの精度を上げるには、実際のデータが多く必要になる。", "target_word": "シミュレーション", "complexity_tier": "T3", "furigana": "シミュレーションの精度[せいど]を上[あ]げるには、実際[じっさい]のデータが多[おお]く必要[ひつよう]になる。", "sentence_source": "generated"}, {"text": "医学の分野でも、薬が体に与える影響をシミュレーションで予測する。", "target_word": "シミュレーション", "complexity_tier": "T3", "furigana": "医学[いがく]の分野[ぶんや]でも、薬[くすり]が体[からだ]に与[あた]える影響[えいきょう]をシミュレーションで予測[よそく]する。", "sentence_source": "generated"}, {"text": "津波のシミュレーションをもとに、新しい避難計画が作られた。", "target_word": "シミュレーション", "complexity_tier": "T3", "furigana": "津波[つなみ]のシミュレーションをもとに、新[あたら]しい避難計画[ひなんけいかく]が作[つく]られた。", "sentence_source": "generated"}, {"text": "計算に時間がかかるため、このシミュレーションは一晩かけて実行された。", "target_word": "シミュレーション", "complexity_tier": "T3", "furigana": "計算[けいさん]に時間[じかん]がかかるため、このシミュレーションは一晩[ひとばん]かけて実行[じっこう]された。", "sentence_source": "generated"}, {"text": "実験は費用が高いので、まずシミュレーションで条件をしぼった。", "target_word": "シミュレーション", "complexity_tier": "T3", "furigana": "実験[じっけん]は費用[ひよう]が高[たか]いので、まずシミュレーションで条件[じょうけん]をしぼった。", "sentence_source": "generated"}, {"text": "シミュレーションの結果は実際の観測と大きく違わなかった。", "target_word": "シミュレーション", "complexity_tier": "T3", "furigana": "シミュレーションの結果[けっか]は実際[じっさい]の観測[かんそく]と大[おお]きく違[ちが]わなかった。", "sentence_source": "generated"}, {"text": "設計者は、橋に重さがかかったときの変形をシミュレーションで調べた。", "target_word": "シミュレーション", "complexity_tier": "T3", "furigana": "設計者[せっけいしゃ]は、橋[はし]に重[おも]さがかかったときの変形[へんけい]をシミュレーションで調[しら]べた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "シミュレーション", "label": "基本形"}, {"form": "シミュレーションする", "label": "サ変動詞形"}], "register": "硬い(専門的)", "sense_fingerprint": "現象やシステムを計算機などで模擬的に再現し、予測や検証に使うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f06b4680-4fa3-4940-ae92-665bd01dff19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37725, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "シミュレーション", "is_correct": true, "explanation": "「で再現した」の手段を指し、計算による再現として文が成り立つ。"}, {"text": "素粒子", "is_correct": false, "explanation": "素粒子は再現の手段にならないので、「大規模な素粒子で再現した」は成り立たない。"}, {"text": "合唱", "is_correct": false, "explanation": "合唱は再現の手段にならないので、文の意味が通らない。"}, {"text": "作文", "is_correct": false, "explanation": "作文は現象を再現する手段ではないので、「作文で再現した」は成り立たない。"}], "explanations": {"シミュレーション": "「で再現した」の手段を指し、計算による再現として文が成り立つ。", "素粒子": "素粒子は再現の手段にならないので、「大規模な素粒子で再現した」は成り立たない。", "合唱": "合唱は再現の手段にならないので、文の意味が通らない。", "作文": "作文は現象を再現する手段ではないので、「作文で再現した」は成り立たない。"}, "sentence_index": 0, "correct_answer": "シミュレーション"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、シミュレーションで熱を測って、体調を記録している。", "explanation": "ここは〈体温計〉の意味。シミュレーションは体の温度を測る器具ではないので合わない。"}, {"text": "妹は、お気に入りのシミュレーションを鍋で煮て食べた。", "explanation": "ここは〈食材〉の意味。シミュレーションは食べ物ではないので合わない。"}, {"text": "毎晩、今日あったことをシミュレーションに書いている。", "explanation": "ここは〈日記〉の意味。シミュレーションは文章を書く帳面ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37725, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "シミュレーション", "is_correct": true, "explanation": "主語の「このシミュレーション」として、一晩かけて実行されるものに合う。"}, {"text": "論文", "is_correct": false, "explanation": "論文は実行されるものではないので、「この論文は一晩かけて実行された」は成り立たない。"}, {"text": "料理", "is_correct": false, "explanation": "料理は実行されるものではないので、「この料理は一晩かけて実行された」は意味が通らない。"}, {"text": "手芸", "is_correct": false, "explanation": "手芸は実行されるものではないので、文として成り立たない。"}], "explanations": {"シミュレーション": "主語の「このシミュレーション」として、一晩かけて実行されるものに合う。", "論文": "論文は実行されるものではないので、「この論文は一晩かけて実行された」は成り立たない。", "料理": "料理は実行されるものではないので、「この料理は一晩かけて実行された」は意味が通らない。", "手芸": "手芸は実行されるものではないので、文として成り立たない。"}, "sentence_index": 6, "correct_answer": "シミュレーション"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅行の前にシミュレーションを広げて、道順を確かめた。", "explanation": "ここは〈地図〉の意味。シミュレーションは広げて見られる紙ではないので合わない。"}, {"text": "友達にシミュレーションを書いて、近況を伝えた。", "explanation": "ここは〈手紙〉の意味。シミュレーションは書いて送る文章ではないので合わない。"}, {"text": "子どもが公園でシミュレーションを投げて遊んだ。", "explanation": "ここは〈ボール〉の意味。シミュレーションは投げられる物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37725, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究者は、新しい薬の効果をシミュレーションに確かめた。", "corrected_sentence": "研究者は、新しい薬の効果をシミュレーションで確かめた。", "error_description": "「確かめる」の手段を示すのは「で」。「に」は場所や方向を示すので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37725, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "まず、大雨の場合のシミュレーションを起こした。", "corrected_sentence": "まず、大雨の場合のシミュレーションを行った。", "error_description": "「行う」が正しい。「起こす」は事故や火事など出来事に使うので、シミュレーションには合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37726, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「理由」を示す「で」で、多用が原因で読みにくいという文の流れに合う。"}, {"text": "を", "is_correct": false, "explanation": "「漢字の多用を、この文章は読みにくい」は述語に目的語を続ける形になり、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐ形で、名詞の後に続かず文の骨組みが成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、読みにくさの原因を表す文には合わない。"}], "correct_answer": "で", "explanations": {"で": "「理由」を示す「で」で、多用が原因で読みにくいという文の流れに合う。", "を": "「漢字の多用を、この文章は読みにくい」は述語に目的語を続ける形になり、文が成り立たない。", "の": "「の」は名詞どうしをつなぐ形で、名詞の後に続かず文の骨組みが成り立たない。", "へ": "「へ」は方向を示すので、読みにくさの原因を表す文には合わない。"}, "error_tags": {"を": "目的語と述語の取り違え", "へ": "方向", "の": "名詞の接続の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37726, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「多用する」の目的語を示す格助詞で、たぶんという言葉を多く使う意味になる。"}, {"text": "が", "is_correct": false, "explanation": "「「たぶん」が多用する学生」は主語と動詞がずれ、意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「「たぶん」と多用する」は並列の意味になり、目的語の役割を果たさない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、使う対象を表す文には合わない。"}], "correct_answer": "を", "explanations": {"を": "「多用する」の目的語を示す格助詞で、たぶんという言葉を多く使う意味になる。", "が": "「「たぶん」が多用する学生」は主語と動詞がずれ、意味が通らない。", "と": "「「たぶん」と多用する」は並列の意味になり、目的語の役割を果たさない。", "から": "「から」は起点を示すので、使う対象を表す文には合わない。"}, "error_tags": {"が": "主語と目的語の取り違え", "と": "並列", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37726, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何度も何度も使うことです。", "primary_collocate": null, "pronunciation": "たよう", "ipa": "tajoː", "syllable_count": 3, "sentences": [{"text": "敬語の多用は、かえって不自然に聞こえる。", "target_word": "多用", "complexity_tier": "T3", "furigana": "敬語(けいご)の多用(たよう)は、かえって不自然(ふしぜん)に聞(き)こえる。", "sentence_source": "generated"}, {"text": "漢字の多用で、この文章は読みにくい。", "target_word": "多用", "complexity_tier": "T3", "furigana": "漢字(かんじ)の多用(たよう)で、この文章(ぶんしょう)は読(よ)みにくい。", "sentence_source": "generated"}, {"text": "薬の多用は体によくないと、医者が注意した。", "target_word": "多用", "complexity_tier": "T3", "furigana": "薬(くすり)の多用(たよう)は体(からだ)によくないと、医者(いしゃ)が注意(ちゅうい)した。", "sentence_source": "generated"}, {"text": "彼の話はカタカナ語の多用が目立つ。", "target_word": "多用", "complexity_tier": "T3", "furigana": "彼(かれ)の話(はなし)はカタカナ語(ご)の多用(たよう)が目立(めだ)つ。", "sentence_source": "generated"}, {"text": "絵文字の多用を避けて、ていねいなメールを書いた。", "target_word": "多用", "complexity_tier": "T3", "furigana": "絵文字(えもじ)の多用(たよう)を避(さ)けて、ていねいなメールを書(か)いた。", "sentence_source": "generated"}, {"text": "たとえ話の多用は、説明をわかりにくくする。", "target_word": "多用", "complexity_tier": "T3", "furigana": "たとえ話(ばなし)の多用(たよう)は、説明(せつめい)をわかりにくくする。", "sentence_source": "generated"}, {"text": "同じ言葉を多用しすぎると、文章が単調になる。", "target_word": "多用", "complexity_tier": "T3", "furigana": "同(おな)じ言葉(ことば)を多用(たよう)しすぎると、文章(ぶんしょう)が単調(たんちょう)になる。", "sentence_source": "generated"}, {"text": "授業で「たぶん」を多用する学生に、先生が注意した。", "target_word": "多用", "complexity_tier": "T3", "furigana": "授業(じゅぎょう)で「たぶん」を多用(たよう)する学生(がくせい)に、先生(せんせい)が注意(ちゅうい)した。", "sentence_source": "generated"}, {"text": "農薬の多用が、川の魚を減らす原因になっている。", "target_word": "多用", "complexity_tier": "T3", "furigana": "農薬(のうやく)の多用(たよう)が、川(かわ)の魚(さかな)を減(へ)らす原因(げんいん)になっている。", "sentence_source": "generated"}, {"text": "電気を多用する生活は、毎月の費用が高くなる。", "target_word": "多用", "complexity_tier": "T3", "furigana": "電気(でんき)を多用(たよう)する生活(せいかつ)は、毎月(まいつき)の費用(ひよう)が高(たか)くなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "多用する", "label": "する動詞"}, {"form": "多用した", "label": "過去形"}, {"form": "多用して", "label": "て形"}, {"form": "多用しない", "label": "否定形"}, {"form": "多用される", "label": "受身形"}], "register": "やや硬い標準語", "sense_fingerprint": "同じものを何度も繰り返して使うこと（回数の多さ）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8506ed3a-c0bb-4ca9-9f47-86feb09e3786') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37726, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多用", "is_correct": true, "explanation": "「何度も使う」意味で、敬語を何度も使うことを表し、文の内容と合う。"}, {"text": "掃除", "is_correct": false, "explanation": "「敬語の掃除」は意味が通らず、何度も使う意味にならない。"}, {"text": "作曲", "is_correct": false, "explanation": "「敬語の作曲」は意味が通らず、使用の回数を表す語として合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "「敬語の散歩」は意味が通らず、使用の回数を表す語として合わない。"}], "explanations": {"多用": "「何度も使う」意味で、敬語を何度も使うことを表し、文の内容と合う。", "掃除": "「敬語の掃除」は意味が通らず、何度も使う意味にならない。", "作曲": "「敬語の作曲」は意味が通らず、使用の回数を表す語として合わない。", "散歩": "「敬語の散歩」は意味が通らず、使用の回数を表す語として合わない。"}, "sentence_index": 0, "correct_answer": "多用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店は料理の多用が自慢で、和食も洋食も選べる。", "explanation": "ここは〈多様〉の意味。多用は同じものを何度も使うことで、種類の豊かさを表す語ではないので、料理の種類の多さには使えない。"}, {"text": "この町では、事故が多用している。", "explanation": "ここは〈多発〉の意味。多用は道具や言葉などを何度も使うことなので、事故が重なって起きる出来事の意味では使わない。"}, {"text": "彼は遅刻の多用で、いつも先生に叱られる。", "explanation": "ここは〈遅刻が多い〉の意味。多用は道具や言葉など使うものに使い、出来事には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37726, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多用", "is_correct": true, "explanation": "「多用しすぎる」の形で、同じ言葉を何度も使う文脈と合う。"}, {"text": "洗濯", "is_correct": false, "explanation": "「同じ言葉を洗濯しすぎる」は意味が通らず、使用の回数の意味にならない。"}, {"text": "登山", "is_correct": false, "explanation": "「同じ言葉を登山しすぎる」は意味が通らず、使用の回数の意味にならない。"}, {"text": "買い物", "is_correct": false, "explanation": "「同じ言葉を買い物しすぎる」は意味が通らず、使用の回数の意味にならない。"}], "explanations": {"多用": "「多用しすぎる」の形で、同じ言葉を何度も使う文脈と合う。", "洗濯": "「同じ言葉を洗濯しすぎる」は意味が通らず、使用の回数の意味にならない。", "登山": "「同じ言葉を登山しすぎる」は意味が通らず、使用の回数の意味にならない。", "買い物": "「同じ言葉を買い物しすぎる」は意味が通らず、使用の回数の意味にならない。"}, "sentence_index": 6, "correct_answer": "多用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この事業には多用のお金がかかる。", "explanation": "ここは〈多額〉の意味。多用は何かを何度も使うことで、金額の大きさを表す語ではないので、多額と取り違えた使い方は合わない。"}, {"text": "この薬は、子どもには多用の量で十分だ。", "explanation": "ここは〈少しの〉の意味（多少）。多用は何かを何度も使うことで、量の少なさを表す語ではないので、多少と取り違えた使い方は合わない。"}, {"text": "出血が多用だったので、病院へ行った。", "explanation": "ここは〈多量〉の意味。多用は何かを何度も使うことで、血の量の多さを表す語ではないので、多量と取り違えた使い方は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37726, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は、カタカナ語を多用を控えるように言われた。", "corrected_sentence": "彼は、カタカナ語の多用を控えるように言われた。", "error_description": "「多用」の前の「の」が「を」になっている。「カタカナ語の多用」と名詞を修飾する形が正しい。「を」を続けると「多用を控える」と目的語が二つ並んで不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37726, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は、説明に比喩が多用する。", "corrected_sentence": "彼は、説明に比喩を多用する。", "error_description": "「多用する」の目的語を示す「が」が「を」になるべき箇所。「が」だと「比喩が」が主語になり、「多用する」の目的語がなくなって文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37727, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『記号を多用する』で、多用の目的語を示す格助詞。"}, {"text": "が", "is_correct": false, "explanation": "『記号が多用する』では記号が主語になり、多用の対象にならない。"}, {"text": "に", "is_correct": false, "explanation": "『記号に多用する』とは言えず、多用は目的語に『を』を取る。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を表すので、多用の対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "『記号を多用する』で、多用の目的語を示す格助詞。", "が": "『記号が多用する』では記号が主語になり、多用の対象にならない。", "に": "『記号に多用する』とは言えず、多用は目的語に『を』を取る。", "へ": "『へ』は方向を表すので、多用の対象にはならない。"}, "error_tags": {"が": "主語", "に": "位置", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37727, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『「すごい」を多用する』で、多用の目的語を示す格助詞。"}, {"text": "で", "is_correct": false, "explanation": "『で』は手段などを表し、『「すごい」で多用する』は目的語の形にならない。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列や相手を示すので、『「すごい」と多用する』は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "『の』は名詞につく助詞で、動詞『多用する』の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "『「すごい」を多用する』で、多用の目的語を示す格助詞。", "で": "『で』は手段などを表し、『「すごい」で多用する』は目的語の形にならない。", "と": "『と』は並列や相手を示すので、『「すごい」と多用する』は成り立たない。", "の": "『の』は名詞につく助詞で、動詞『多用する』の目的語にはならない。"}, "error_tags": {"で": "手段", "と": "並列", "の": "連体"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37727, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "あることを、何回も、またはたくさんの場面で使うこと。", "primary_collocate": null, "pronunciation": "たよう", "ipa": "tajoː", "syllable_count": 3, "sentences": [{"text": "この小説は、受け身の表現を多用している。", "target_word": "多用", "complexity_tier": "T3", "furigana": "この小説(しょうせつ)は、受(う)け身(み)の表現(ひょうげん)を多用(たよう)している。", "sentence_source": "generated"}, {"text": "彼女はハートの記号を多用するので、メールがにぎやかだ。", "target_word": "多用", "complexity_tier": "T3", "furigana": "彼女(かのじょ)はハートの記号(きごう)を多用(たよう)するので、メールがにぎやかだ。", "sentence_source": "generated"}, {"text": "暗い色の多用が、この絵に重い雰囲気を与えている。", "target_word": "多用", "complexity_tier": "T3", "furigana": "暗(くら)い色(いろ)の多用(たよう)が、この絵(え)に重(おも)い雰囲気(ふんいき)を与(あた)えている。", "sentence_source": "generated"}, {"text": "専門用語の多用で、新入社員には資料が難しかった。", "target_word": "多用", "complexity_tier": "T3", "furigana": "専門用語(せんもんようご)の多用(たよう)で、新入社員(しんにゅうしゃいん)には資料(しりょう)が難(むずか)しかった。", "sentence_source": "generated"}, {"text": "この機械は、多用すると故障しやすいので注意が必要だ。", "target_word": "多用", "complexity_tier": "T3", "furigana": "この機械(きかい)は、多用(たよう)すると故障(こしょう)しやすいので注意(ちゅうい)が必要(ひつよう)だ。", "sentence_source": "generated"}, {"text": "広告では、短くて強い言葉が多用されることが多い。", "target_word": "多用", "complexity_tier": "T3", "furigana": "広告(こうこく)では、短(みじか)くて強(つよ)い言葉(ことば)が多用(たよう)されることが多(おお)い。", "sentence_source": "generated"}, {"text": "ゴム手袋は、掃除から料理まで多用される便利な道具だ。", "target_word": "多用", "complexity_tier": "T3", "furigana": "ゴム手袋(てぶくろ)は、掃除(そうじ)から料理(りょうり)まで多用(たよう)される便利(べんり)な道具(どうぐ)だ。", "sentence_source": "generated"}, {"text": "彼は「すごい」を多用するため、感想がいつも同じに聞こえる。", "target_word": "多用", "complexity_tier": "T3", "furigana": "彼(かれ)は「すごい」を多用(たよう)するため、感想(かんそう)がいつも同(おな)じに聞(き)こえる。", "sentence_source": "generated"}, {"text": "警告音の多用は、人をかえって不安にさせる。", "target_word": "多用", "complexity_tier": "T3", "furigana": "警告音(けいこくおん)の多用(たよう)は、人(ひと)をかえって不安(ふあん)にさせる。", "sentence_source": "generated"}, {"text": "敬語を多用した手紙は、ていねいだが少し固い。", "target_word": "多用", "complexity_tier": "T3", "furigana": "敬語(けいご)を多用(たよう)した手紙(てがみ)は、ていねいだが少(すこ)し固(かた)い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "多用する", "label": "する動詞"}, {"form": "多用した", "label": "過去形"}, {"form": "多用して", "label": "て形"}, {"form": "多用される", "label": "受身形"}, {"form": "多用しない", "label": "否定形"}], "register": "やや硬い標準語", "sense_fingerprint": "表現・手段などを繰り返し、またいろいろな場面で使うこと（使用範囲の広さ）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8506ed3a-c0bb-4ca9-9f47-86feb09e3786') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37727, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多用", "is_correct": true, "explanation": "『受け身の表現を多用している』で、同じ表現を何度も使うという意味に合う。"}, {"text": "多数", "is_correct": false, "explanation": "『多数している』は数の多さを言うだけで、表現を使うことを表せない。"}, {"text": "過多", "is_correct": false, "explanation": "『過多している』は量が多すぎる状態を表す名詞で、『している』と続けても使用の意味にならない。"}, {"text": "多額", "is_correct": false, "explanation": "金額の大きさを表す語なので、表現を使う行為には合わない。"}], "explanations": {"多用": "『受け身の表現を多用している』で、同じ表現を何度も使うという意味に合う。", "多数": "『多数している』は数の多さを言うだけで、表現を使うことを表せない。", "過多": "『過多している』は量が多すぎる状態を表す名詞で、『している』と続けても使用の意味にならない。", "多額": "金額の大きさを表す語なので、表現を使う行為には合わない。"}, "sentence_index": 0, "correct_answer": "多用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このレストランは、多用な料理を出すので人気だ。", "explanation": "ここは〈いろいろな〉の意味の『多様』。多用は同じことを何度も使う、または用事が多いという意味なので、料理の種類の多さには使わない。"}, {"text": "この道具は一度だけ多用して、すぐに捨てた。", "explanation": "ここは〈使用〉の意味。多用は何度も繰り返し使うことなので、一度だけ使った場合には合わない。"}, {"text": "団体は、個人から多用な寄付を受けた。", "explanation": "ここは〈多額〉の意味。多用は回数や場面の多さを言い、寄付の金額の大きさには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37727, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多用", "is_correct": true, "explanation": "『掃除から料理まで多用される』で、道具が多くの場面で使われるという意味に合う。"}, {"text": "多種", "is_correct": false, "explanation": "種類の多さを表す語で、『多種される』は動詞の形として成り立たない。"}, {"text": "多人数", "is_correct": false, "explanation": "人数を表す語で、道具を主語にしては使えない。"}, {"text": "多少", "is_correct": false, "explanation": "数量の程度を表す語で、『多少される』とは続かない。"}], "explanations": {"多用": "『掃除から料理まで多用される』で、道具が多くの場面で使われるという意味に合う。", "多種": "種類の多さを表す語で、『多種される』は動詞の形として成り立たない。", "多人数": "人数を表す語で、道具を主語にしては使えない。", "多少": "数量の程度を表す語で、『多少される』とは続かない。"}, "sentence_index": 6, "correct_answer": "多用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は毎日、猫を多用している。", "explanation": "ここは〈使う〉の意味で、生き物を目的語にしている。多用は道具や表現を繰り返し使うことに言い、猫には使わないので合わない。"}, {"text": "彼女は夏休みに田舎を多用している。", "explanation": "ここは〈過ごす〉の意味で、場所を目的語にしている。多用は道具や表現に使い、場所を過ごす意味では使わないので合わない。"}, {"text": "二人は長年かけて友情を多用してきた。", "explanation": "ここは〈育む〉の意味で、友情を目的語にしている。多用は道具や表現に使い、関係や感情には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37727, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しいアプリは、通知に多用しすぎて使いにくい。", "corrected_sentence": "新しいアプリは、通知を多用しすぎて使いにくい。", "error_description": "『多用する』は目的語に『を』を取る。『通知に多用』は助詞の誤りで、正しくは『通知を多用しすぎて』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37727, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "チームは速攻を多用せて、守りが崩れた。", "corrected_sentence": "チームは速攻を多用して、守りが崩れた。", "error_description": "『多用する』のて形は『多用して』。『多用せて』は活用の誤りで、正しくは『多用して』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37728, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『数万の星』で、数量と名詞をつなぐ格助詞。"}, {"text": "が", "is_correct": false, "explanation": "『数万が星』では名詞が二つ並び、『の』の役割を果たさない。"}, {"text": "を", "is_correct": false, "explanation": "『数万を星』では目的語の形にならず、光っている星とつながらない。"}, {"text": "に", "is_correct": false, "explanation": "『数万に星』では場所や相手を表せず、星につながらない。"}], "correct_answer": "の", "explanations": {"の": "『数万の星』で、数量と名詞をつなぐ格助詞。", "が": "『数万が星』では名詞が二つ並び、『の』の役割を果たさない。", "を": "『数万を星』では目的語の形にならず、光っている星とつながらない。", "に": "『数万に星』では場所や相手を表せず、星につながらない。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "位置"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37728, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『三万の小さな町』で、数量と名詞をつなぐ格助詞。"}, {"text": "で", "is_correct": false, "explanation": "『三万で小さな町』は成り立たず、手段や場所を表すが、数量と名詞をつなげない。"}, {"text": "と", "is_correct": false, "explanation": "『三万と小さな町』は並列の形になり、数量と町の修飾関係が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "『三万へ小さな町』は方向を表すが、町を修飾する形にはならない。"}], "correct_answer": "の", "explanations": {"の": "『三万の小さな町』で、数量と名詞をつなぐ格助詞。", "で": "『三万で小さな町』は成り立たず、手段や場所を表すが、数量と名詞をつなげない。", "と": "『三万と小さな町』は並列の形になり、数量と町の修飾関係が成り立たない。", "へ": "『三万へ小さな町』は方向を表すが、町を修飾する形にはならない。"}, "error_tags": {"で": "手段", "と": "並列", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37728, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "「万」は、10000を表す数の単位です。", "primary_collocate": null, "pronunciation": "まん", "ipa": "maɴ", "syllable_count": 2, "sentences": [{"text": "町の人口は、五万に近い。", "target_word": "万", "complexity_tier": "T3", "furigana": "町(まち)の人口(じんこう)は、五万(ごまん)に近(ちか)い。", "sentence_source": "generated"}, {"text": "空には、数万の星が光っていた。", "target_word": "万", "complexity_tier": "T3", "furigana": "空(そら)には、数万(すうまん)の星(ほし)が光(ひか)っていた。", "sentence_source": "generated"}, {"text": "祭りには、十万もの人が集まった。", "target_word": "万", "complexity_tier": "T3", "furigana": "祭(まつ)りには、十万(じゅうまん)もの人(ひと)が集(あつ)まった。", "sentence_source": "generated"}, {"text": "この動画は、百万回も見られている。", "target_word": "万", "complexity_tier": "T3", "furigana": "この動画(どうが)は、百万回(ひゃくまんかい)も見(み)られている。", "sentence_source": "generated"}, {"text": "川には、何万という小さな魚が泳いでいた。", "target_word": "万", "complexity_tier": "T3", "furigana": "川(かわ)には、何万(なんまん)という小(ちい)さな魚(さかな)が泳(およ)いでいた。", "sentence_source": "generated"}, {"text": "参加者が一万を超えて、会場に入れない人も出た。", "target_word": "万", "complexity_tier": "T3", "furigana": "参加者(さんかしゃ)が一万(いちまん)を超(こ)えて、会場(かいじょう)に入(はい)れない人(ひと)も出(で)た。", "sentence_source": "generated"}, {"text": "工場では毎日、二万の部品が作られている。", "target_word": "万", "complexity_tier": "T3", "furigana": "工場(こうじょう)では毎日(まいにち)、二万(にまん)の部品(ぶひん)が作(つく)られている。", "sentence_source": "generated"}, {"text": "人口が三万の小さな町に、新しい駅ができた。", "target_word": "万", "complexity_tier": "T3", "furigana": "人口(じんこう)が三万(さんまん)の小(ちい)さな町(まち)に、新(あたら)しい駅(えき)ができた。", "sentence_source": "generated"}, {"text": "桜の花が数万も咲いて、山がピンク色になった。", "target_word": "万", "complexity_tier": "T3", "furigana": "桜(さくら)の花(はな)が数万(すうまん)も咲(さ)いて、山(やま)がピンク色(いろ)になった。", "sentence_source": "generated"}, {"text": "祭りの客は去年より二万ふえて、道がこんだ。", "target_word": "万", "complexity_tier": "T3", "furigana": "祭(まつ)りの客(きゃく)は去年(きょねん)より二万(にまん)ふえて、道(みち)がこんだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "万", "label": "基本形"}, {"form": "数万", "label": "数万（複合）"}, {"form": "何万", "label": "疑問・不定数"}, {"form": "万の", "label": "連体用法"}], "register": "中立（日常語）", "sense_fingerprint": "人・物・生き物などの多さを示す数の単位（一万＝10000）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8506ed3a-c0bb-4ca9-9f47-86feb09e3786') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37728, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "万", "is_correct": true, "explanation": "『五万』は五万を表す数の単位で、『町の人口は五万に近い』と人口の規模を示す。"}, {"text": "円", "is_correct": false, "explanation": "『五円』は金額の単位で、町の人口の数としては規模が合わない。"}, {"text": "回", "is_correct": false, "explanation": "『五回』は回数の単位で、人口の規模を表せない。"}, {"text": "人", "is_correct": false, "explanation": "『五人』は人数だが、町の人口が五人に近いとすると規模が合わない。"}], "explanations": {"万": "『五万』は五万を表す数の単位で、『町の人口は五万に近い』と人口の規模を示す。", "円": "『五円』は金額の単位で、町の人口の数としては規模が合わない。", "回": "『五回』は回数の単位で、人口の規模を表せない。", "人": "『五人』は人数だが、町の人口が五人に近いとすると規模が合わない。"}, "sentence_index": 0, "correct_answer": "万"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会場には、万人が集まった。", "explanation": "ここは〈すべての人〉の意味の『万人』。数の一万の意味なら『一万人』と言うので、人数としては合わない。"}, {"text": "町の祭りには、万の屋台が並んだ。", "explanation": "ここは数字を付けずに『万』だけで数量を表した使い方。数の一万は『一万の』『数万の』のように言うので、ここでは合わない。"}, {"text": "来場者は、万人にのぼった。", "explanation": "ここは〈すべての人〉の意味の『万人』。数の一万の意味で人数を言うなら『一万人』になるので、ここでは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37728, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "万", "is_correct": true, "explanation": "『二万』は一万の二倍の数の単位で、毎日二万個規模で部品が作られるという数量を表す。"}, {"text": "時間", "is_correct": false, "explanation": "時間の長さを表す語で、部品の数には合わない。"}, {"text": "週", "is_correct": false, "explanation": "期間の単位で、毎日作る部品の数量を表さない。"}, {"text": "日", "is_correct": false, "explanation": "期間の単位で、『毎日二日の部品』は数量として成り立たない。"}], "explanations": {"万": "『二万』は一万の二倍の数の単位で、毎日二万個規模で部品が作られるという数量を表す。", "時間": "時間の長さを表す語で、部品の数には合わない。", "週": "期間の単位で、毎日作る部品の数量を表さない。", "日": "期間の単位で、『毎日二日の部品』は数量として成り立たない。"}, "sentence_index": 6, "correct_answer": "万"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "町の人口は、万人を超えた。", "explanation": "ここは〈すべての人〉の意味の『万人』。人口の数としては『一万人』と言うので、ここでは合わない。"}, {"text": "この店の売上は、万円に届いた。", "explanation": "ここは数字を付けずに『万』だけで金額を表した使い方。金額の一万は『一万円』と言うので、ここでは合わない。"}, {"text": "主催者は、万が一の事故に備えた。", "explanation": "ここは『万が一』という慣用句で、数の一万の意味ではない。数量を表す『万』としては使えないので、ここでは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37728, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会場には、十万が集まった。", "corrected_sentence": "会場には、十万人が集まった。", "error_description": "人数を数える『人』が抜けている。『十万』だけでは人数として数えられず、正しくは『十万人』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37728, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町の祭りは、来場者が一万に超えて、混雑した。", "corrected_sentence": "町の祭りは、来場者が一万を超えて、混雑した。", "error_description": "『超える』は目的語に『を』を取る。『一万に超えて』は助詞の誤りで、正しくは『一万を超えて』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aca32133-f907-4af6-b136-59f2bbb66e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37730, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「多すぎる」は数量が多い対象を「が」で示すので正しい。"}, {"text": "を", "is_correct": false, "explanation": "「多すぎる」は「を」を取らないので不可。"}, {"text": "に", "is_correct": false, "explanation": "「パターンに多すぎて」は意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「パターンで多すぎて」は手段を表し、ここでは合わない。"}], "correct_answer": "が", "explanations": {"が": "「多すぎる」は数量が多い対象を「が」で示すので正しい。", "を": "「多すぎる」は「を」を取らないので不可。", "に": "「パターンに多すぎて」は意味が通らない。", "で": "「パターンで多すぎて」は手段を表し、ここでは合わない。"}, "error_tags": {"を": "目的語", "に": "位置・対象", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37730, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「覚える」は覚える対象を目的語として「を」で取るので正しい。"}, {"text": "が", "is_correct": false, "explanation": "「三つのパターンが覚えれば」は主語になり、覚える対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「パターンと覚えれば」は並列を表し、目的語を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「パターンへ覚えれば」は方向を表し、意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「覚える」は覚える対象を目的語として「を」で取るので正しい。", "が": "「三つのパターンが覚えれば」は主語になり、覚える対象を示せない。", "と": "「パターンと覚えれば」は並列を表し、目的語を示せない。", "へ": "「パターンへ覚えれば」は方向を表し、意味が通らない。"}, "error_tags": {"が": "主語", "と": "並列・相手", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37730, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "形や動き方の決まった種類のこと。", "primary_collocate": null, "pronunciation": "ぱたーん", "ipa": "pataːɴ", "syllable_count": 4, "sentences": [{"text": "敵の動きには三つのパターンがあり、順番に覚えると倒しやすい。", "target_word": "パターン", "complexity_tier": "T3", "furigana": "敵[てき]の動[うご]きには三[みっ]つのパターンがあり、順番[じゅんばん]に覚[おぼ]えると倒[たお]しやすい。", "sentence_source": "generated"}, {"text": "髪型のパターンが多すぎて、どれにするか決められない。", "target_word": "パターン", "complexity_tier": "T3", "furigana": "髪型[かみがた]のパターンが多[おお]すぎて、どれにするか決[き]められない。", "sentence_source": "generated"}, {"text": "旅行の日程は、二つのパターンを考えてあります。", "target_word": "パターン", "complexity_tier": "T3", "furigana": "旅行[りょこう]の日程[にってい]は、二[ふた]つのパターンを考[かんが]えてあります。", "sentence_source": "generated"}, {"text": "申し込みの方法は、ネットと電話の二つのパターンがある。", "target_word": "パターン", "complexity_tier": "T3", "furigana": "申[もう]し込[こ]みの方法[ほうほう]は、ネットと電話[でんわ]の二[ふた]つのパターンがある。", "sentence_source": "generated"}, {"text": "このシャツは袖の形のパターンが豊富で、選ぶのが楽しい。", "target_word": "パターン", "complexity_tier": "T3", "furigana": "この シャツは 袖[そで]の 形[かたち]の パターン[ぱたーん]が 豊富[ほうふ]で、選[えら]ぶのが 楽[たの]しい。", "sentence_source": "generated"}, {"text": "ダンスの動きのパターンは四つだけなので、初心者でもすぐ覚えられる。", "target_word": "パターン", "complexity_tier": "T3", "furigana": "ダンスの動[うご]きのパターンは四[よっ]つだけなので、初心者[しょしんしゃ]でもすぐ覚[おぼ]えられる。", "sentence_source": "generated"}, {"text": "書道では、筆の運び方のパターンを何度も練習して、字の形を安定させる。", "target_word": "パターン", "complexity_tier": "T3", "furigana": "書道[しょどう]では、筆[ふで]の運[はこ]び方[かた]のパターン[ぱたーん]を何度[なんど]も練習[れんしゅう]して、字[じ]の形[かたち]を安定[あんてい]させる。", "sentence_source": "generated"}, {"text": "料理は、炒める・煮る・焼くの三つのパターンを覚えれば作りやすい。", "target_word": "パターン", "complexity_tier": "T3", "furigana": "料理[りょうり]は、炒[いた]める・煮[に]る・焼[や]くの三[みっ]つのパターンを覚[おぼ]えれば作[つく]りやすい。", "sentence_source": "generated"}, {"text": "相手チームは攻め方のパターンを変えてきた。", "target_word": "パターン", "complexity_tier": "T3", "furigana": "相手[あいて]チームは攻[せ]め方[かた]のパターンを変[か]えてきた。", "sentence_source": "generated"}, {"text": "この問題集は解き方のパターンごとに章が分かれている。", "target_word": "パターン", "complexity_tier": "T3", "furigana": "この問題集[もんだいしゅう]は解[と]き方[かた]のパターンごとに章[しょう]が分[わ]かれている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "パターン", "label": "基本形"}], "register": "中立", "sense_fingerprint": "形や動き方などの、決まった型や種類", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T2: contains vocabulary far above tier T2: 解き方 (Zipf 2.48)']::text[], '30f189a2-d0da-4e3f-9dc8-fbca6dc3d32d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
